!----------------------------------------------------
! Declare single instance of array of decomposition cascade constant types
!----------------------------------------------------
type(decomp_cascade_type), public, target, save :: decomp_cascade_con

!#if (defined CNDV)
!----------------------------------------------------
! Declare single instance of array of CNDV ecophysiological constant types
!----------------------------------------------------
type(pft_dgvepc_type), public, target, save :: dgv_pftcon
!#endif

character(len=16), parameter, public :: grlnd  = 'lndgrid'      ! name of lndgrid
character(len=16), parameter, public :: namea  = 'gridcellatm'  ! name of atmgrid
character(len=16), parameter, public :: nameg  = 'gridcell'     ! name of gridcells
character(len=16), parameter, public :: namel  = 'landunit'     ! name of landunits
character(len=16), parameter, public :: namec  = 'column'       ! name of columns
character(len=16), parameter, public :: namep  = 'pft'          ! name of pfts

!
!EOP
!----------------------------------------------------------------------- 
 contains
   subroutine clmtype45_mod
   end subroutine clmtype45_mod


end module clmtype45

module clm_varpar45

!-----------------------------------------------------------------------
!BOP
!
! !MODULE: clm_varpar45
!
! !DESCRIPTION:
! Module containing CLM parameters
!
! !USES:
  use shr_kind_mod, only: r8 => shr_kind_r8
!
! !PUBLIC TYPES:
  implicit none
  save
!KC parameters defined in ACASA-CN
  logical, public :: more_vertlayers = .false. ! true => run with more vertical soil layers
  integer, parameter :: nlev_equalspace   = 15
  integer, parameter :: toplev_equalspace =  6
  integer,parameter :: nlevsoifl =  10
  integer,parameter ::  nlevsoi     =  10
  integer,parameter ::  nlevgrnd    =  10
  integer, parameter :: nlevlak     =  10     ! number of lake layers
  integer, parameter :: nlevsno     =   5     ! maximum number of snow layers
  ! For CH4 code
  integer, parameter :: ngases = 3 ! CH4, O2, & CO2
  integer, parameter :: nlevcan     =   1     ! number of leaf layers in canopy
  integer, parameter :: numwat      =   5     ! number of water types (soil, ice, 2 lakes, wetland)
  integer, parameter :: numrad      =   2     ! number of solar radiation bands: vis, nir
  integer, parameter :: ivis        =   1     ! index for visible band
  integer, parameter :: inir        =   2     ! index for near-infrared band
  integer, parameter :: numsolar    =   2     ! number of solar type bands: direct, diffuse
  integer, parameter :: ndst        =   4     ! number of dust size classes (BGC only)
  integer, parameter :: dst_src_nbr =   3     ! number of size distns in src soil (BGC only)
  integer, parameter :: sz_nbr      = 200     ! number of sub-grid bins in large bin of dust size distribution (BGC only)
  integer, parameter :: mxpft       =  24     ! maximum number of PFT's for any mode; might we set some of these automatically from reading pft-physiology?
  integer, parameter :: numveg      =  16     ! number of veg types (without specific crop)
  integer, parameter :: numpft      = numveg  ! actual # of pfts (without bare)
  integer, parameter :: numcft      =   2     ! actual # of crops
  integer, parameter :: maxpatch_pft= 4  !MAXPATCH_PFT ! max number of plant functional types in naturally vegetated landunit
  integer, parameter :: numurbl     = 3       ! number of urban landunits
  integer, parameter :: ndecomp_pools = 7
  integer, parameter :: ndecomp_cascade_transitions = 10
  integer, parameter :: i_met_lit = 1
  integer, parameter :: i_cel_lit = 2
  integer, parameter :: i_lig_lit = 3
  integer, parameter :: i_cwd = 4
  integer, parameter :: nsompools = 3
  integer,parameter :: maxpatch_glcmec = 1   ! max number of elevation classes
  integer,parameter :: maxpatch_urb = 1       ! max number of urban pfts (columns) in urban landunit
  integer :: npatch_urban       ! number of urban pfts (columns) in urban landunit
  integer,parameter :: npatch_urban_tbd = maxpatch_pft + 1
  integer,parameter :: npatch_urban_hd = npatch_urban_tbd + maxpatch_urb
  integer,parameter :: npatch_urban_md = npatch_urban_hd + maxpatch_urb
!  integer, parameter :: npatch_urban   = maxpatch_pft + 1
  integer,parameter :: npatch_lake = npatch_urban_md + maxpatch_urb
  integer,parameter :: npatch_wet  = npatch_lake  + 1
  integer,parameter :: npatch_glacier  = npatch_wet   + 1
  integer,parameter :: npatch_glacier_mec = npatch_glacier + maxpatch_glcmec
  integer,parameter :: maxpatch = npatch_glacier_mec
  real(r8),parameter :: mach_eps = epsilon(1.0_r8)           ! machine epsilon
!  integer,parameter :: max_pft_per_gcell = numpft+1 + 3 + maxpatch_urb*numurbl + maxpatch_glcmec
!  integer,parameter :: max_pft_per_lu    = max(numpft+1, numcft, maxpatch_urb)
!  integer,parameter :: max_pft_per_col   = max(numpft+1, numcft, maxpatch_urb)
  integer,parameter ::  nlevdecomp      = nlevsoi
  integer,parameter ::  nlevdecomp_full = nlevgrnd
!KC end
!
! Define land surface 2-d grid. This sets the model resolution according
! to cpp directives LSMLON and LSMLAT in preproc.h.
!
!  integer, parameter :: lsmlon = LSMLON     ! maximum number of longitude points on lsm grid
!  integer, parameter :: lsmlat = LSMLAT     ! number of latitude points on lsm grid
! tcx make it dynamic, read from surface dataset

  integer, parameter :: lsmlon   = 1           ! maximum number of longitude points on lsm grid
  integer, parameter :: lsmlat   = 1        ! number of latitude points on lsm grid

! Define number of levels

!  integer, parameter :: nlevsoi     =  10   ! number of soil layers
!  integer, parameter :: nlevlak     =  10   ! number of lake layers
!  integer, parameter :: nlevsno     =   5   ! maximum number of snow layers
!ylu add
!  integer, parameter :: nlevgrnd    =  10 ! 10 ! 10 ! 10 ! 10 ! 10 ! 10 ! 10 ! 10 ! 10 ! 15     ! number of ground layers (includes lower layers that are hydrologically inactive)
  integer, parameter :: nlevurb     = nlevgrnd! number of urban layers (must equal nlevgrnd right now)
!ylu end
! Define miscellaneous parameters

!  integer, parameter :: numwat      =   5   ! number of water types (soil, ice, 2 lakes, wetland)
 ! integer, parameter :: npftpar     =  32   ! number of pft parameters (in LPJ - CNDV only)
!  integer, parameter :: numrad      =   2   ! number of solar radiation bands: vis, nir
!ylu add 
!  integer, parameter :: numsolar    =   2   ! number of solar type bands: direct, diffuse
!ylu end
!  integer, parameter :: ndst        =   4   ! number of dust size classes (BGC only)
!  integer, parameter :: dst_src_nbr =   3   ! number of size distns in src soil (BGC only)
!  integer, parameter :: sz_nbr      = 200   ! number of sub-grid bins in large bin of dust size distribution (BGC only)
  integer, parameter :: nvoc        =   5   ! number of voc categories (BGC only)
!Not found in CLM3.5, putting back in from CLM3
!ylu remove
  integer, parameter :: numcol      =   8   !number of soil color types

! Define parameters for RTM river routing model

  integer, parameter :: rtmlon = 720  !number of rtm longitudes
  integer, parameter :: rtmlat = 360  !number of rtm latitudes

! Define indices used in surface file read
! maxpatch_pft  = max number of vegetated pfts in naturally vegetated landunit
! maxpatch_crop = max number of crop pfts in crop landunit
!ylu add 10/15/10
!#if (defined CROP)
!  integer, parameter :: numpft         = 20  ! number of plant types
!  integer, parameter :: numcft         =  6     ! actual # of crops
!  integer, parameter :: numveg         = 16     ! number of veg types (without specific crop)
!#else
!  integer, parameter :: numpft         = 16     ! actual # of pfts (without bare)
!  integer, parameter :: numcft         =  2     ! actual # of crops
!  integer, parameter :: numveg         = numpft ! number of veg types (without specific crop)
!#endif
!  integer, parameter :: maxpatch_urb   = 1  !  5  ! the current coupling not include urban. 
#ifdef CROP
  integer, parameter :: maxpatch_cft   = 4    !YL changed from 2 to 4
#else
  integer, parameter :: maxpatch_cft   = 1
#endif

!  integer, parameter :: maxpatch_pft   = 4
!  integer, parameter :: npatch_urban   = maxpatch_pft + 1
!  integer, parameter :: npatch_lake    = npatch_urban + maxpatch_urb
!  integer, parameter :: npatch_wet     = npatch_lake  + 1
!  integer, parameter :: npatch_glacier = npatch_wet   + 1
  integer, parameter :: npatch_crop    = npatch_glacier + maxpatch_cft
!  integer, parameter :: maxpatch       = npatch_crop

!ylu add
#if (defined CROP)
  integer, parameter :: max_pft_per_gcell = numpft+1 + 3 + maxpatch_urb
#else
  integer, parameter :: max_pft_per_gcell = numpft+1 + 3 + maxpatch_urb + numcft
#endif
 integer, parameter :: max_pft_per_lu    = max(numpft+1, numcft, maxpatch_urb)
  integer, parameter :: max_pft_per_col   = max(numpft+1, numcft, maxpatch_urb)
  integer  :: num_landcover_types 


!Are these constants used?  I don't see max_col_per_lunit referenced anywhere.
!ylu remove
!  integer, parameter :: max_pft_per_gcell = numpft+1 + 4 + maxpatch_cft
!  integer, parameter :: max_pft_per_lu    = max(numpft+1, maxpatch_cft)
!  integer, parameter :: max_pft_per_col   = numpft+1

!  integer, parameter :: max_pft_per_col     = maxpatch_pft
!#if (defined NOCOMPETE)
!  integer, parameter :: max_col_per_lunit   = maxpatch_pft
!#else
!  integer, parameter :: max_col_per_lunit   = 1
!#endif
!Shouldn't this be 1?
!  integer, parameter :: max_lunit_per_gcell = 5            !(soil,urban,lake,wetland,glacier)

contains
	subroutine clm_varpar45_mod(nlcat)
          integer,intent(in)  :: nlcat 

          num_landcover_types = nlcat ! land use type

	end subroutine clm_varpar45_mod
!------------------------------------------------------------------------------
end module clm_varpar45

module clm_varcon45
!----------------------------------------------------------------------- 
!BOP
!
! !MODULE: clm_varcon45
!
! !DESCRIPTION: 
! Module containing various model constants 
!
! !USES:
  use shr_kind_mod, only: r8 => shr_kind_r8
  use clm_varpar45, only : numcol,numrad,nlevlak,&
                         maxpatch_pft,numpft,nlevgrnd,&
                         num_landcover_types,nlevdecomp_full,ngases
!
! !PUBLIC TYPES:
  implicit none
  save
!
! !REVISION HISTORY:
! Created by Mariana Vertenstein
!
!EOP
!----------------------------------------------------------------------- 
!KC parameters in ACASA-CN
  real(r8) :: rpi    = 3.14159265358979323846

  !------------------------------------------------------------------
  ! Initialize physical constants
  !------------------------------------------------------------------

  real(r8), parameter :: n_melt=0.7     !fsca shape parameter
  real(r8), parameter :: e_ice=6.0      !soil ice impedance factor
  real(r8), parameter :: pc = 0.4       !threshold probability
  real(r8), parameter :: mu = 0.13889   !connectivity exponent
  real(r8) :: grav   = 9.80616      !gravity constant [m/s2]
  real(r8) :: sb     = 5.67e-8_r8 !stefan-boltzmann constant  [W/m2/K4]
  real(r8) :: vkc    = 0.4 !von Karman constant [-]
  real(r8) :: rgas   = 1.38065e-23_r8*6.02214e26_r8   !universal gas constant [J/K/kmole]
  real(r8) :: rwat   = 1.38065e-23_r8*6.02214e26_r8/18.016    !gas constant for water vapor [J/(kg K)]
  real(r8) :: rair   = 1.38065e-23_r8*6.02214e26_r8/28.966  !gas constant for dry air [J/kg/K]
  real(r8) :: roverg = 1.38065e-23_r8*6.02214e26_r8/18.016/9.80616*1000._r8 !Rw/g constant = (8.3144/0.018)/(9.80616)*1000. mm/K
  real(r8) :: cpliq  = 4.188e3_r8   !Specific heat of water [J/kg-K]
  real(r8) :: cpice  = 2.11727e3_r8  !Specific heat of ice [J/kg-K]
  real(r8) :: cpair  = 1.00464e3_r8 !specific heat of dry air [J/kg/K]
  real(r8) :: hvap   = 2.501e6_r8 !Latent heat of evap for water [J/kg]
  real(r8) :: hsub   = 3.337e5_r8+2.501e6_r8 !Latent heat of sublimation    [J/kg]
  real(r8) :: hfus   = 3.337e5_r8 !Latent heat of fusion for ice [J/kg]
  real(r8) :: denh2o = 1.000e3_r8  !density of liquid water [kg/m3]
  real(r8) :: denice = 0.917e3_r8 !density of ice [kg/m3]
  real(r8) :: tkair  = 0.023_r8     !thermal conductivity of air   [W/m/K]
  real(r8) :: tkice  = 2.290_r8     !thermal conductivity of ice   [W/m/K]
  real(r8) :: tkwat  = 0.57_r8       !thermal conductivity of water [W/m/K]
  real(r8) :: tfrz   = 273.15  !freezing temperature [K]
  real(r8) :: tcrit  = 2.5_r8       !critical temperature to determine rain or snow
  real(r8) :: o2_molar_const = 0.209_r8   !constant atmospheric O2 molar ratio (mol/mol)

  real(r8) :: bdsno = 250._r8       !bulk density snow (kg/m**3)
  real(r8) :: alpha_aero = 1.0_r8   !constant for aerodynamic parameter weighting
  real(r8) :: tlsai_crit = 2.0_r8   !critical value of elai+esai for which aerodynamic parameters are maximum
  real(r8) :: watmin = 0.01_r8      !minimum soil moisture (mm)

  real(r8) :: re = 6.37122e6_r8*0.001_r8 !radius of earth (km)

  real(r8), public, parameter :: degpsec = 15._r8/3600.0_r8 ! Degree's earth rotates per second

  real(r8), public, parameter ::  secspday= 86400.0  ! Seconds per day
  integer,  public, parameter :: isecspday= secspday        ! Integer seconds per day
  real(r8), public, parameter ::  spval = 1.e36_r8  ! special value for real data
  integer , public, parameter :: ispval = -9999     ! special value for int data

  ! These are tunable constants from clm2_3

  real(r8) :: zlnd = 0.01_r8      !Roughness length for soil [m]
  real(r8) :: zsno = 0.0024_r8    !Roughness length for snow [m]
  real(r8) :: csoilc = 0.004_r8   !Drag coefficient for soil under canopy [-]
  real(r8) :: capr   = 0.34_r8    !Tuning factor to turn first layer T into surface T
  real(r8) :: cnfac  = 0.5_r8     !Crank Nicholson factor between 0 and 1
  real(r8) :: ssi    = 0.033_r8   !Irreducible water saturation of snow
  real(r8) :: wimp   = 0.05_r8    !Water impremeable if porosity less than wimp
  real(r8) :: pondmx = 10.0_r8     !Ponding depth (mm)
  real(r8) :: pondmx_urban = 1.0_r8  !Ponding depth for urban roof and impervious road (mm)

  real(r8) :: thk_bedrock = 3.0_r8      ! thermal conductivity of 'typical' saturated granitic rock
                                        ! (Clauser and Huenges, 1995)(W/m/K)

  !!! C13
