  real(r8) :: zlak(1:nlevlak)         !lake z  (layers)
  real(r8) :: dzlak(1:nlevlak)        !lake dz (thickness)
  real(r8) :: zsoi(1:nlevgrnd)         !soil z  (layers)
  real(r8) :: dzsoi(1:nlevgrnd)        !soil dz (thickness)
