   ppsyns%ko(beg:end) = nan
   ppsyns%qe(beg:end) = nan
   ppsyns%tpu_z(beg:end,1:nlevcan) = nan
   ppsyns%kp_z(beg:end,1:nlevcan) = nan
   ppsyns%theta_cj(beg:end) = nan
