                    deadstemc_xfer(i,m,j)              = deadstemc_xfer_buf(m)
                    livecrootc(i,m,j)                  = livecrootc_buf(m)
                    livecrootc_storage(i,m,j)          = livecrootc_storage_buf(m)
                    livecrootc_xfer(i,m,j)             = livecrootc_xfer_buf(m)
                    deadcrootc(i,m,j)                  = deadcrootc_buf(m)
                    deadcrootc_storage(i,m,j)          = deadcrootc_storage_buf(m)
                    deadcrootc_xfer(i,m,j)             = deadcrootc_xfer_buf(m)
                    cpool(i,m,j)                       = cpool_buf(m)
                    pft_ctrunc(i,m,j)                  = pft_ctrunc_buf(m)
                    leafn(i,m,j)                       = leafn_buf(m)
                    leafn_storage(i,m,j)               = leafn_storage_buf(m)
                    leafn_xfer(i,m,j)                  = leafn_xfer_buf(m)
                    frootn(i,m,j)                      = frootn_buf(m)
                    frootn_storage(i,m,j)              = frootn_storage_buf(m)
                    frootn_xfer(i,m,j)                 = frootn_xfer_buf(m)
                    livestemn(i,m,j)                   = livestemn_buf(m)
                    livestemn_storage(i,m,j)           = livestemn_storage_buf(m)
                    livestemn_xfer(i,m,j)              = livestemn_xfer_buf(m)
                    deadstemn(i,m,j)                   = deadstemn_buf(m)
                    deadstemn_storage(i,m,j)           = deadstemn_storage_buf(m)
                    deadstemn_xfer(i,m,j)              = deadstemn_xfer_buf(m)
                    livecrootn(i,m,j)                  = livecrootn_buf(m)
                    livecrootn_storage(i,m,j)          = livecrootn_storage_buf(m)
                    livecrootn_xfer(i,m,j)             = livecrootn_xfer_buf(m)
                    deadcrootn(i,m,j)                  = deadcrootn_buf(m)
                    deadcrootn_storage(i,m,j)          = deadcrootn_storage_buf(m)
                    deadcrootn_xfer(i,m,j)             = deadcrootn_xfer_buf(m)
                    npool(i,m,j)                       = npool_buf(m)
                    pft_ntrunc(i,m,j)                  = pft_ntrunc_buf(m)
                    gresp_storage(i,m,j)               = gresp_storage_buf(m)
                    gresp_xfer(i,m,j)                  = gresp_xfer_buf(m) 
                    xsmrpool(i,m,j)                    = xsmrpool_buf(m)
                    annsum_counter(i,m,j)              = annsum_counter_buf(m)
                    cannsum_npp(i,m,j)                 = cannsum_npp_buf(m)
                    cannavg_t2m(i,m,j)                 = cannavg_t2m_buf(m)
                    wf(i,m,j)                          = wf_buf(m)
                    me(i,m,j)                          = me_buf(m)
                    mean_fire_prob(i,m,j)              = mean_fire_prob_buf(m)
                    cwdc(i,m,j)                        = cwdc_buf(m)
                    litr1c(i,m,j)                      = litr1c_buf(m)
                    litr2c(i,m,j)                      = litr2c_buf(m)
                    litr3c(i,m,j)                      = litr3c_buf(m) 
                    soil1c(i,m,j)                      = soil1c_buf(m)
                    soil2c(i,m,j)                      = soil2c_buf(m)
                    soil3c(i,m,j)                      = soil3c_buf(m)
                    soil4c(i,m,j)                      = soil4c_buf(m)
                    seedc(i,m,j)                       = seedc_buf(m)
                    col_ctrunc(i,m,j)                  = col_ctrunc_buf(m)
                    prod10c(i,m,j)                     = prod10c_buf(m)
                    prod100c(i,m,j)                    = prod100c_buf(m)
                    cwdn(i,m,j)                        = cwdn_buf(m)
                    litr1n(i,m,j)                      = litr1n_buf(m) 
                    litr2n(i,m,j)                      = litr2n_buf(m)
                    litr3n(i,m,j)                      = litr3n_buf(m) 
                    soil1n(i,m,j)                      = soil1n_buf(m)
                    soil2n(i,m,j)                      = soil2n_buf(m)
                    soil3n(i,m,j)                      = soil3n_buf(m)
                    soil4n(i,m,j)                      = soil4n_buf(m)
                    seedn(i,m,j)                       = seedn_buf(m)
                    col_ntrunc(i,m,j)                  = col_ntrunc_buf(m)
                    prod10n(i,m,j)                     = prod10n_buf(m)
                    prod100n(i,m,j)                    = prod100n_buf(m)
                    sminn(i,m,j)                       = sminn_buf(m) 
                    totlitc(i,m,j)                     = totlitc_buf(m)
                    dwt_seedc_to_leaf(i,m,j)           = dwt_seedc_to_leaf_buf(m)
                    dwt_seedc_to_deadstem(i,m,j)       = dwt_seedc_to_deadstem_buf(m)
                    dwt_conv_cflux(i,m,j)              = dwt_conv_cflux_buf(m)
                    dwt_prod10c_gain(i,m,j)            = dwt_prod10c_gain_buf(m)
                    dwt_prod100c_gain(i,m,j)           = dwt_prod100c_gain_buf(m)
                    prod100c_loss(i,m,j)               = prod100c_loss_buf(m)
                    dwt_frootc_to_litr1c(i,m,j)        = dwt_frootc_to_litr1c_buf(m)
                    dwt_frootc_to_litr2c(i,m,j)        = dwt_frootc_to_litr2c_buf(m)
                    dwt_frootc_to_litr3c(i,m,j)        = dwt_frootc_to_litr3c_buf(m)
                    dwt_livecrootc_to_cwdc(i,m,j)      = dwt_livecrootc_to_cwdc_buf(m)
                    dwt_deadcrootc_to_cwdc(i,m,j)      = dwt_deadcrootc_to_cwdc_buf(m)
                    dwt_seedn_to_leaf(i,m,j)           = dwt_seedn_to_leaf_buf(m)
                    dwt_seedn_to_deadstem(i,m,j)       = dwt_seedn_to_deadstem_buf(m)
                    dwt_conv_nflux(i,m,j)              = dwt_conv_nflux_buf(m)
                    dwt_prod10n_gain(i,m,j)            = dwt_prod10n_gain_buf(m)
                    dwt_prod100n_gain(i,m,j)           = dwt_prod100n_gain_buf(m)
                    prod100n_loss(i,m,j)               = prod100n_loss_buf(m)
                    dwt_frootn_to_litr1n(i,m,j)        = dwt_frootn_to_litr1n_buf(m)
                    dwt_frootn_to_litr2n(i,m,j)        = dwt_frootn_to_litr2n_buf(m)
                    dwt_frootn_to_litr3n(i,m,j)        = dwt_frootn_to_litr3n_buf(m)
                    dwt_livecrootn_to_cwdn(i,m,j)      =  dwt_livecrootn_to_cwdn_buf(m)
                    dwt_deadcrootn_to_cwdn(i,m,j)      = dwt_deadcrootn_to_cwdn_buf(m)
                    retransn(i,m,j)                    = retransn_buf(m)
#endif

      end if

!  print*,'debug 9',i,j
  end do ! of i loop
  end do ! of j loop
!  print*,'debug 10'
!        call clmdebug_ACASA('clmdrv() success finished')   !DEL 
end subroutine acasadrv
!------------------------------------------------------------------------
subroutine ACASAINIT(ids,ide, jds,jde, kds,kde,  &
                     ims,ime, jms,jme, kms,kme,  &
                     its,ite, jts,jte, kts,kte,  &
                     num_soil_layers,TSLB,sh2o,smois,restart,       &
!Shuhua
                     irr_rand_field,irr_ph,irr_freq,           &
                     xtime,sf_surf_irr_scheme,                 &
                     perc_SIFRACT,perc_MIFRACT,perc_FIFRACT,   &
                     SIFRACT,MIFRACT,FIFRACT,                  &
!Shuhua
                     T2M_acasa,Q2M_acasa,T2M_MAX_acasa,T2M_MIN_acasa, &
                     LAI_acasa,drip_height,                           & ! Shuhua
                     NEE_acasa,photosynthesis, &
                     infiltration,NPP_acasa,GPP_acasa,ustar_acasa,Resp_can,&
                     SMSTAV,SMSTOT,xland,xice)

   USE module_state_description, ONLY :      DRIP,                 &
                                             CHANNEL,              &
                                             SPRINKLER,            &
                                             ALL_IRR_METH
  implicit none
  REAL, DIMENSION( ims:ime, jms:jme )                     , &
            INTENT(IN)       ::                         XLAND,xice
  REAL,    DIMENSION( ims:ime, jms:jme )                     , &
            INTENT(INOUT)    ::SMSTAV,SMSTOT
  LOGICAL , INTENT(IN) :: restart
  INTEGER,  INTENT(IN   )   ::     ids,ide, jds,jde, kds,kde,  &
                                   ims,ime, jms,jme, kms,kme,  &
                                   its,ite, jts,jte, kts,kte
   REAL,    DIMENSION( ims:ime, jms:jme )                     , &
            INTENT(INOUT)    :: T2M_acasa,Q2M_acasa,T2M_MAX_acasa,T2M_MIN_acasa,NEE_acasa,photosynthesis, &
                                infiltration,NPP_acasa,GPP_acasa,ustar_acasa,Resp_can 
   REAL,    DIMENSION( ims:ime, jms:jme )                     , & ! Shuhua
            INTENT(INOUT)    :: LAI_acasa,drip_height
   INTEGER, INTENT(IN)       ::     num_soil_layers
   REAL,    DIMENSION( ims:ime, num_soil_layers, jms:jme )    , &
            INTENT(INOUT)    ::                          TSLB,sh2o,smois!,t_sois,q_sois
   INTEGER                   :: itf,jtf,j,i,k,m

!Shuhua
   INTEGER,DIMENSION(ims:ime, jms:jme ),INTENT(INOUT):: irr_rand_field
   INTEGER, OPTIONAL , INTENT(IN   ) :: sf_surf_irr_scheme
   REAL,    OPTIONAL , INTENT(IN   ) :: xtime
   REAL, DIMENSION( ims:ime, jms:jme ), INTENT(INOUT), &
                                        OPTIONAL::   perc_SIFRACT, &
                                                     perc_MIFRACT, &
                                                     perc_FIFRACT
   REAL, DIMENSION( ims:ime, jms:jme ), INTENT(INOUT),             &
                                        OPTIONAL::        SIFRACT, &
                                                          MIFRACT, &
                                                          FIFRACT
   REAL, DIMENSION( its:ite, jts:jte ) :: irr_sum
   REAL  :: adjust

   INTEGER , DIMENSION(jds:jde) :: my_seeds
   INTEGER :: irr_ph,irr_freq
   REAL,DIMENSION(ims:ime, jms:jme ) :: rand_tmp


 IF(restart) return
   itf=min0(ite,ide-1)
   jtf=min0(jte,jde-1)
       do i=its,itf
       do j=jts,jtf
           T2M_MAX_acasa(i,j) = tslb(i,1,j)
           T2M_MIN_acasa(i,j) = tslb(i,1,j)
           LAI_acasa(i,j) = 0.
           drip_height(i,j) = 2 ! layer
           NEE_acasa(i,j) = 0.0
           photosynthesis(i,j) = 0.0
           infiltration(i,j) = 0.0
           NPP_acasa(i,j) = 0.0
           GPP_acasa(i,j) = 0.0
           ustar_acasa(i,j) = 0.0
           Resp_can(i,j) = 0.0
       enddo
       enddo

          DO j = jts,jtf
          DO i = its,itf


          if((xland(i,j)-1.5).ge.0.)then

!             If(xice(i,j).eq.1)print*,' SEA-ICE AT WATER POINT, i=',i,'j=',j

              smstav(i,j)=1.0
              smstot(i,j)=1.0
              smois(i,:,j)=1.0
              tslb(i,:,j)=273.16
            else if(xice(i,j).eq.1.)then

              smstav(i,j)=1.0
              smstot(i,j)=1.0
              smois(i,:,j)=1.0
            endif


          ENDDO
          ENDDO

      do i=its,itf
      do j=jts,jtf
       do k=1, num_soil_layers
          if(tslb(i,k,j) >= tfrz )  then
            sh2o(i,k,j) = smois(i,k,j)
          else
            sh2o(i,k,j) = 0.0
          end if
!          t_sois(i,k,j) = smois(i,k,j)
!          q_sois(i,k,j) = tslb(i,k,j)
       end do
      end do
      end do

   IF (xtime .eq. 0. .or. restart .eq. .true. ) then
     IF (PRESENT(SIFRACT) .and. PRESENT(MIFRACT) .and. PRESENT(FIFRACT) ) then
          print*,'set up irrigation percentage for all four schemes'
! Readjust the sum of irrigation fractions to 100%
          DO i = its,ite
          DO j = jts,jte
             irr_sum(i,j)=SIFRACT(I,J)+MIFRACT(I,J)+FIFRACT(I,J)
             if (irr_sum(i,j) .gt. 0.5 .and. irr_sum(i,j) .lt. 1.) then
                adjust = 1.- irr_sum(i,j)
                if (SIFRACT(I,J) .gt. 0.) SIFRACT(I,J)=SIFRACT(I,J)+adjust*SIFRACT(I,J)/irr_sum(i,j)
                if (MIFRACT(I,J) .gt. 0.) MIFRACT(I,J)=MIFRACT(I,J)+adjust*MIFRACT(I,J)/irr_sum(i,j)
                if (FIFRACT(I,J) .gt. 0.) FIFRACT(I,J)=FIFRACT(I,J)+adjust*FIFRACT(I,J)/irr_sum(i,j)
                irr_sum(i,j)=1.
             endif
          ENDDO
          ENDDO

          irr_perc: SELECT CASE(sf_surf_irr_scheme)
          CASE(SPRINKLER)
            DO i = its,ite
            DO j = jts,jte
               if (irr_sum(i,j) .gt. 0.5) then
                  perc_SIFRACT(i,j)=1. ! 100%
               else
                  perc_SIFRACT(i,j)=0.
               endif
               perc_MIFRACT(i,j)=0.
               perc_FIFRACT(i,j)=0.
            ENDDO
            ENDDO
          CASE(DRIP)
            DO i = its,ite
            DO j = jts,jte
               perc_SIFRACT(i,j)=0.
               if (irr_sum(i,j) .gt. 0.5) then
                  perc_MIFRACT(i,j)=1. ! 100%
               else
                  perc_MIFRACT(i,j)=0.
               endif
               perc_FIFRACT(i,j)=0.
            ENDDO
            ENDDO
          CASE(CHANNEL)
            DO i = its,ite
            DO j = jts,jte
               perc_SIFRACT(i,j)=0.
               perc_MIFRACT(i,j)=0.
               if (irr_sum(i,j) .gt. 0.5) then
                  perc_FIFRACT(i,j)=1. ! 100%
               else
                  perc_FIFRACT(i,j)=0.
               endif
            ENDDO
            ENDDO
          CASE(ALL_IRR_METH)
            DO i = its,ite
            DO j = jts,jte
               perc_SIFRACT(i,j)=SIFRACT(I,J)
               perc_MIFRACT(i,j)=MIFRACT(I,J)
               perc_FIFRACT(i,j)=FIFRACT(I,J)
            ENDDO
            ENDDO
          CASE (0)
            DO i = its,ite
            DO j = jts,jte
               perc_SIFRACT(i,j)=0.
               perc_MIFRACT(i,j)=0.
               perc_FIFRACT(i,j)=0.
            ENDDO
            ENDDO
          CASE DEFAULT
            print*,'Choose a valid irrigation scheme'
            stop
          END SELECT irr_perc
     ELSE
       print*,'Use an irrigation fraction option in WPS'
       stop
     ENDIF
   ENDIF

#if ( EM_CORE==1 )
   IF (irr_ph.NE.0)THEN
   DO i = its,ite
    DO j=jts,jte
      my_seeds(j) =sqrt(ide*(real(j-1)**2))+sqrt(real(jde*i))
!      PRINT*,'myseed', my_seeds(j),j,jts,jds
    END DO
      CALL RANDOM_SEED ( PUT = my_seeds )
      CALL RANDOM_NUMBER ( rand_tmp(i,:) )
      CALL RANDOM_SEED ( GET = my_seeds )
      CALL RANDOM_NUMBER ( rand_tmp(i,:) )
      irr_rand_field(i,:)=int(modulo(rand_tmp(i,:)*100,real(irr_freq)))
   END DO
   END IF

#endif

end subroutine ACASAINIT
!------------------------------------------------------------------------------
END MODULE module_sf_acasa

module domainMod
!-----------------------------------------------------------------------
!BOP
!
! !MODULE: domainMod
!
! !DESCRIPTION:
! Module containing 2-d global surface boundary data information
!
! !USES:
  use shr_kind_mod, only : r8 => shr_kind_r8
  use nanmod_ACASA
!  use spmdMod     , only : masterproc
  use abortutils  , only : endrun
!  use clm_varctl  , only : iulog
!
! !PUBLIC TYPES:
  implicit none
  private
!
  public :: domain_type

  !--- this typically contains local domain info with arrays dim begg:endg ---
  type domain_type
     integer          :: ns         ! global size of domain
     integer          :: ni,nj      ! global axis if 2d (nj=1 if unstructured)
     logical          :: isgrid2d   ! true => global grid is lat/lon
     integer          :: nbeg,nend  ! local beg/end indices
     character(len=8) :: clmlevel   ! grid type
     integer ,pointer :: mask(:)    ! land mask: 1 = land, 0 = ocean
     real(r8),pointer :: frac(:)    ! fractional land
     real(r8),pointer :: topo(:)    ! topography
     real(r8),pointer :: latc(:)    ! latitude of grid cell (deg)
     real(r8),pointer :: lonc(:)    ! longitude of grid cell (deg)
     real(r8),pointer :: area(:)    ! grid cell area (km**2)
     integer ,pointer :: pftm(:)    ! pft mask: 1=real, 0=fake, -1=notset
     integer ,pointer :: glcmask(:) ! glc mask: 1=sfc mass balance required by GLC component
                                    ! 0=SMB not required (default)
     character*16     :: set        ! flag to check if domain is set
     logical          :: decomped   ! decomposed locally or global copy
  end type domain_type

  type(domain_type)    , public :: ldomain
!  real(r8), allocatable, public :: lon1d(:), lat1d(:) ! 1d lat/lons for 2d grids
!
! !PUBLIC MEMBER FUNCTIONS:
  public domain_init          ! allocates/nans domain types
  public domain_clean         ! deallocates domain types
  public domain_check         ! write out domain info
! !REVISION HISTORY:
! Originally clm_varsur by Mariana Vertenstein
! Migrated from clm_varsur to domainMod by T Craig
!
  character*16,parameter :: set   = 'domain_set      '
  character*16,parameter :: unset = 'NOdomain_unsetNO'
!
!EOP
!------------------------------------------------------------------------------

contains

!------------------------------------------------------------------------------
!BOP
!
! !IROUTINE: domain_init
!
! !INTERFACE:
  subroutine domain_init(domain,isgrid2d,ni,nj,nbeg,nend,clmlevel)
!
! !DESCRIPTION:
! This subroutine allocates and nans the domain type
!
! !USES:
!
! !ARGUMENTS:
    implicit none
    type(domain_type)   :: domain        ! domain datatype
    logical, intent(in) :: isgrid2d      ! true => global grid is lat/lon
    integer, intent(in) :: ni,nj         ! grid size, 2d
    integer         , intent(in), optional  :: nbeg,nend  ! beg/end indices
    character(len=*), intent(in), optional  :: clmlevel   ! grid type
!
! !REVISION HISTORY:
!   Created by T Craig
!
!
! !LOCAL VARIABLES:
!EOP
    integer ier
    integer nb,ne
!
!------------------------------------------------------------------------------

    nb = 1
    ne = ni*nj
    if (present(nbeg)) then
       if (present(nend)) then
          nb = nbeg
          ne = nend
       endif
    endif

    if (domain%set == set) then
       call domain_clean(domain)
    endif
    allocate(domain%mask(nb:ne),domain%frac(nb:ne),domain%latc(nb:ne), &
             domain%pftm(nb:ne),domain%area(nb:ne),domain%lonc(nb:ne), &
             domain%topo(nb:ne),domain%glcmask(nb:ne),stat=ier)
    if (ier /= 0) then
!       write(iulog,*) 'domain_init ERROR: allocate mask, frac, lat, lon, area '
       call endrun()
    endif

    if (present(clmlevel)) then
       domain%clmlevel = clmlevel
    endif

    domain%isgrid2d = isgrid2d
    domain%ns       = ni*nj
    domain%ni       = ni
    domain%nj       = nj
    domain%nbeg     = nb
    domain%nend     = ne
    domain%mask     = -9999
    domain%frac     = -1.0e36
    domain%topo     = 0._r8
    domain%latc     = nan
    domain%lonc     = nan
    domain%area     = nan

    domain%set      = set
    if (domain%nbeg == 1 .and. domain%nend == domain%ns) then
       domain%decomped = .false.
    else
       domain%decomped = .true.
    endif

    domain%pftm     = -9999
    domain%glcmask  = 0

end subroutine domain_init
!------------------------------------------------------------------------------
!BOP
!
! !IROUTINE: domain_clean
!
! !INTERFACE:
  subroutine domain_clean(domain)
!
! !DESCRIPTION:
! This subroutine deallocates the domain type
!
! !USES:
!
! !ARGUMENTS:
    implicit none
    type(domain_type) :: domain        ! domain datatype
!
! !REVISION HISTORY:
!   Created by T Craig
!
!
! !LOCAL VARIABLES:
!EOP
    integer ier
!
!------------------------------------------------------------------------------
    if (domain%set == set) then
!       if (masterproc) then
!          write(iulog,*) 'domain_clean: cleaning ',domain%ni,domain%nj
!       endif
       deallocate(domain%mask,domain%frac,domain%latc, &
                  domain%lonc,domain%area,domain%pftm, &
                  domain%topo,domain%glcmask,stat=ier)
       if (ier /= 0) then
!          write(iulog,*) 'domain_clean ERROR: deallocate mask, frac, lat, lon, area '
          call endrun()
       endif
    else
!       if (masterproc) then
!          write(iulog,*) 'domain_clean WARN: clean domain unecessary '
!       endif
    endif

    domain%clmlevel   = unset
    domain%ns         = bigint
    domain%ni         = bigint
    domain%nj         = bigint
    domain%nbeg       = bigint
    domain%nend       = bigint
    domain%set        = unset
    domain%decomped   = .true.
end subroutine domain_clean
!------------------------------------------------------------------------------
!BOP
!
! !IROUTINE: domain_check
!
! !INTERFACE:
  subroutine domain_check(domain)
!
! !DESCRIPTION:
! This subroutine write domain info
!
! !USES:
!
! !ARGUMENTS:
    implicit none
    type(domain_type),intent(in)  :: domain        ! domain datatype
!
! !REVISION HISTORY:
!   Created by T Craig
!
!
! !LOCAL VARIABLES:
!
!EOP
!------------------------------------------------------------------------------

!  if (masterproc) then
!    write(iulog,*) '  domain_check set       = ',trim(domain%set)
!    write(iulog,*) '  domain_check decomped  = ',domain%decomped
!    write(iulog,*) '  domain_check ns        = ',domain%ns
!    write(iulog,*) '  domain_check ni,nj     = ',domain%ni,domain%nj
!    write(iulog,*) '  domain_check clmlevel  = ',trim(domain%clmlevel)
!    write(iulog,*) '  domain_check nbeg,nend = ',domain%nbeg,domain%nend
!    write(iulog,*) '  domain_check lonc      = ',minval(domain%lonc),maxval(domain%lonc)
!    write(iulog,*) '  domain_check latc      = ',minval(domain%latc),maxval(domain%latc)
!    write(iulog,*) '  domain_check mask      = ',minval(domain%mask),maxval(domain%mask)
!    write(iulog,*) '  domain_check frac      = ',minval(domain%frac),maxval(domain%frac)
