!-----------------------------------------------------------------------
!BOP
!
! !IROUTINE: CNSetCps
!
! !INTERFACE:
subroutine CNSetCps(num, filter, val, cps)
!
! !DESCRIPTION:
! Set column physical state variables
!
! !ARGUMENTS:
    implicit none
    integer , intent(in) :: num
    integer , intent(in) :: filter(:)
    real(r8), intent(in) :: val
    type (column_pstate_type), intent(inout) :: cps
!
! !REVISION HISTORY:
! Created by Peter Thornton
!
! !LOCAL VARIABLES:
! local pointers to implicit in/out arrays
!
! !OTHER LOCAL VARIABLES:
   integer :: fi,i,j     ! loop index
!EOP
!------------------------------------------------------------------------

   do fi = 1,num
      i = filter(fi)
      cps%decl(i) = val
      cps%coszen(i) = val
      cps%fpi(i) = val
      cps%fpg(i) = val
      cps%annsum_counter(i) = val
      cps%cannsum_npp(i) = val
      cps%cannavg_t2m(i) = val

  ! fire related variables changed by F. Li and S. Levis
      cps%wf(i) = val
      cps%wf2(i) = val
      cps%nfire(i) = val
      cps%baf_crop(i) = val
      cps%baf_peatf(i) = val
      cps%fbac(i) = val
      cps%fbac1(i) = val
      cps%farea_burned(i) = val
   end do

   do j = 1,nlevdecomp_full
      do fi = 1,num
         i = filter(fi)
         cps%fpi_vr(i,j) = val
      end do
   end do

   do j = 1,nlevgrnd
      do fi = 1,num
         i = filter(fi)
         cps%soilpsi(i,j) = val
      end do
   end do
end subroutine CNSetCps
!-----------------------------------------------------------------------

!-----------------------------------------------------------------------
!BOP
!
! !IROUTINE: CNSetCcs
!
! !INTERFACE:
subroutine CNSetCcs(num, filter, val, ccs)
!
! !DESCRIPTION:
! Set column carbon state variables
!
! !ARGUMENTS:
    implicit none
    integer , intent(in) :: num
    integer , intent(in) :: filter(:)
    real(r8), intent(in) :: val
    type (column_cstate_type), intent(inout) :: ccs
!
! !REVISION HISTORY:
! Created by Peter Thornton
!
! !LOCAL VARIABLES:
! local pointers to implicit in/out arrays
!
! !OTHER LOCAL VARIABLES:
   integer :: fi,i,j,k     ! loop index
!EOP
!------------------------------------------------------------------------

   do fi = 1,num
      i = filter(fi)
      ccs%cwdc(i)  = val
      ccs%col_ctrunc(i) = val
      ccs%totlitc(i) = val
      ccs%totsomc(i) = val
      ccs%totecosysc(i) = val
      ccs%totcolc(i) = val
      ccs%rootc_col(i) = val
      ccs%totvegc_col(i) = val
      ccs%leafc_col(i) = val
      ccs%fuelc(i) = val
      ccs%fuelc_crop(i) = val
      ccs%totlitc_1m(i) = val
      ccs%totsomc_1m(i) = val
   end do

   ! column and levdecomp
   do j = 1,nlevdecomp_full
      do fi = 1,num
         i = filter(fi)
         ccs%col_ctrunc_vr(i,j) = val
      end do
   end do

   ! column and decomp_pools
   do k = 1, ndecomp_pools
      do fi = 1,num
         i = filter(fi)
         ccs%decomp_cpools(i,k) = val
         ccs%decomp_cpools_1m(i,k) = val
      end do
   end do

   ! column, levdecomp, and decomp_pools
   do j = 1,nlevdecomp_full
      do k = 1, ndecomp_pools
         do fi = 1,num
            i = filter(fi)
            ccs%decomp_cpools_vr(i,j,k) = val
         end do
      end do
   end do
end subroutine CNSetCcs
!-----------------------------------------------------------------------

!-----------------------------------------------------------------------
!BOP
!
! !IROUTINE: CNSetCns
!
! !INTERFACE:
subroutine CNSetCns(num, filter, val, cns)
!
! !DESCRIPTION:
! Set column nitrogen state variables
!
! !ARGUMENTS:
    implicit none
    integer , intent(in) :: num
    integer , intent(in) :: filter(:)
    real(r8), intent(in) :: val
    type (column_nstate_type), intent(inout) :: cns
!
! !REVISION HISTORY:
! Created by Peter Thornton
!
! !LOCAL VARIABLES:
! local pointers to implicit in/out arrays
!
! !OTHER LOCAL VARIABLES:
   integer :: fi,i,j,k     ! loop index
!EOP
!------------------------------------------------------------------------

   ! column only
   do fi = 1,num
      i = filter(fi)
      cns%sminn(i) = val
      cns%col_ntrunc(i) = val
      cns%cwdn(i) = val
!#ifdef NITRIF_DENITRIF
      cns%smin_no3(i) = val
      cns%smin_nh4(i) = val
!#endif
      cns%totlitn(i) = val
      cns%totsomn(i) = val
      cns%totecosysn(i) = val
      cns%totcoln(i) = val
      cns%totsomn_1m(i) = val
      cns%totlitn_1m(i) = val
   end do

   ! column and levdecomp
   do j = 1,nlevdecomp_full
      do fi = 1,num
         i = filter(fi)
         cns%sminn_vr(i,j) = val
         cns%col_ntrunc_vr(i,j) = val
!#ifdef NITRIF_DENITRIF
         cns%smin_no3_vr(i,j) = val
         cns%smin_nh4_vr(i,j) = val
!#endif
      end do
   end do

   ! column and decomp_pools
   do k = 1, ndecomp_pools
      do fi = 1,num
         i = filter(fi)
         cns%decomp_npools(i,k) = val
         cns%decomp_npools_1m(i,k) = val
      end do
   end do

   ! column levdecomp, and decomp_pools
   do j = 1,nlevdecomp_full
      do k = 1, ndecomp_pools
         do fi = 1,num
            i = filter(fi)
            cns%decomp_npools_vr(i,j,k) = val
         end do
      end do
   end do
end subroutine CNSetCns
!-----------------------------------------------------------------------

!-----------------------------------------------------------------------
!BOP
!
! !IROUTINE: CNSetCcf
!
! !INTERFACE:
subroutine CNSetCcf(num, filter, val, ccf)
!
! !DESCRIPTION:
! Set column carbon flux variables
!
! !ARGUMENTS:
    implicit none
    integer , intent(in) :: num
    integer , intent(in) :: filter(:)
    real(r8), intent(in) :: val
    type (column_cflux_type), intent(inout) :: ccf
!
! !REVISION HISTORY:
! Created by Peter Thornton
!
! !LOCAL VARIABLES:
! local pointers to implicit in/out arrays
!
! !OTHER LOCAL VARIABLES:
   integer :: fi,i,j,k,l     ! loop index
!EOP
!------------------------------------------------------------------------

   do j = 1, nlevdecomp_full
      do fi = 1,num
         i = filter(fi)
         ! phenology: litterfall and crop fluxes associated wit
         ccf%phenology_c_to_litr_met_c(i,j)                = val
         ccf%phenology_c_to_litr_cel_c(i,j)                = val
         ccf%phenology_c_to_litr_lig_c(i,j)                = val
         ! gap mortality
         ccf%gap_mortality_c_to_litr_met_c(i,j)                = val
         ccf%gap_mortality_c_to_litr_cel_c(i,j)                = val
         ccf%gap_mortality_c_to_litr_lig_c(i,j)                = val
         ccf%gap_mortality_c_to_cwdc(i,j)                      = val
         ! fire
         ccf%fire_mortality_c_to_cwdc(i,j)                 = val
         ccf%m_c_to_litr_met_fire(i,j)             = val
         ccf%m_c_to_litr_cel_fire(i,j)             = val
         ccf%m_c_to_litr_lig_fire(i,j)             = val
         ! harvest
         ccf%harvest_c_to_litr_met_c(i,j)                  = val
         ccf%harvest_c_to_litr_cel_c(i,j)                  = val
         ccf%harvest_c_to_litr_lig_c(i,j)                  = val
         ccf%harvest_c_to_cwdc(i,j)                        = val
         ! hr
         ccf%hr_vr(i,j) = val
      end do
   end do

   do k = 1, ndecomp_pools
      do j = 1, nlevdecomp_full
         do fi = 1,num
            i = filter(fi)
            ccf%m_decomp_cpools_to_fire_vr(i,j,k) = val
            ccf%decomp_cpools_sourcesink(i,j,k) = val
            ccf%decomp_cpools_transport_tendency(i,j,k) = val
         end do
      end do
   end do

   do l = 1, ndecomp_cascade_transitions
         do fi = 1,num
            i = filter(fi)
            ccf%decomp_cascade_hr(i,l) = val
            ccf%decomp_cascade_ctransfer(i,l) = val
         end do
   end do

   do l = 1, ndecomp_cascade_transitions
      do j = 1, nlevdecomp_full
         do fi = 1,num
            i = filter(fi)
            ccf%decomp_cascade_hr_vr(i,j,l) = val
            ccf%decomp_cascade_ctransfer_vr(i,j,l) = val
            ccf%decomp_k(i,j,l) = val
         end do
      end do
   end do

   do k = 1, ndecomp_pools
      do fi = 1,num
         i = filter(fi)
         ccf%decomp_cpools_leached(i,k) = val
         ccf%m_decomp_cpools_to_fire(i,k) = val
      end do
   end do

   do fi = 1,num
      i = filter(fi)
      ccf%hrv_deadstemc_to_prod10c(i)         = val
      ccf%hrv_deadstemc_to_prod100c(i)        = val
      ccf%somc_fire(i)                        = val     ! F. Li and S.Levis
      ccf%prod10c_loss(i)                     = val
      ccf%prod100c_loss(i)                    = val
      ccf%product_closs(i)                    = val
      ccf%somhr(i)                            = val
      ccf%lithr(i)                            = val
      ccf%hr(i)                               = val
      ccf%sr(i)                               = val
      ccf%er(i)                               = val
      ccf%litfire(i)                          = val
      ccf%somfire(i)                          = val
      ccf%totfire(i)                          = val
      ccf%nep(i)                              = val
      ccf%nbp(i)                              = val
      ccf%nee(i)                              = val
      ccf%col_cinputs(i)                      = val
      ccf%col_coutputs(i)                     = val
      ccf%col_fire_closs(i)                   = val
      ccf%cwdc_hr(i)                          = val
      ccf%cwdc_loss(i)                        = val
      ccf%litterc_loss(i)                     = val
      ccf%som_c_leached(i) = val
  end do
end subroutine CNSetCcf
!-----------------------------------------------------------------------

!-----------------------------------------------------------------------
!BOP
!
! !IROUTINE: CNSetCnf
!
! !INTERFACE:
subroutine CNSetCnf(num, filter, val, cnf)
!
! !DESCRIPTION:
! Set column nitrogen flux variables
!
! !ARGUMENTS:
    implicit none
    integer , intent(in) :: num
    integer , intent(in) :: filter(:)
    real(r8), intent(in) :: val
    type (column_nflux_type), intent(inout) :: cnf
!
! !REVISION HISTORY:
! Created by Peter Thornton
!
! !LOCAL VARIABLES:
! local pointers to implicit in/out arrays
!
! !OTHER LOCAL VARIABLES:
   integer :: fi,i,j,k,l     ! loop index
!EOP
!------------------------------------------------------------------------
   do j = 1, nlevdecomp_full
      do fi = 1,num
         i = filter(fi)
         ! phenology: litterfall and crop fluxes associated wit
         cnf%phenology_n_to_litr_met_n(i,j)                = val
         cnf%phenology_n_to_litr_cel_n(i,j)                = val
         cnf%phenology_n_to_litr_lig_n(i,j)                = val
         ! gap mortality
         cnf%gap_mortality_n_to_litr_met_n(i,j)                = val
         cnf%gap_mortality_n_to_litr_cel_n(i,j)                = val
         cnf%gap_mortality_n_to_litr_lig_n(i,j)                = val
         cnf%gap_mortality_n_to_cwdn(i,j)                      = val
         ! fire
         cnf%fire_mortality_n_to_cwdn(i,j)                 = val
         cnf%m_n_to_litr_met_fire(i,j)             = val
         cnf%m_n_to_litr_cel_fire(i,j)             = val
         cnf%m_n_to_litr_lig_fire(i,j)             = val
         ! harvest
         cnf%harvest_n_to_litr_met_n(i,j)                  = val
         cnf%harvest_n_to_litr_cel_n(i,j)                  = val
         cnf%harvest_n_to_litr_lig_n(i,j)                  = val
         cnf%harvest_n_to_cwdn(i,j)                        = val
!#ifndef NITRIF_DENITRIF
!         cnf%sminn_to_denit_excess_vr(i,j) = val
!         cnf%sminn_leached_vr(i,j) = val
!#else
         cnf%f_nit_vr(i,j) = val
         cnf%f_denit_vr(i,j) = val
         cnf%smin_no3_leached_vr(i,j) = val
         cnf%smin_no3_runoff_vr(i,j) = val
         cnf%n2_n2o_ratio_denit_vr(i,j) = val
         cnf%pot_f_nit_vr(i,j) = val
         cnf%pot_f_denit_vr(i,j) = val
         cnf%actual_immob_no3_vr(i,j) = val
         cnf%actual_immob_nh4_vr(i,j) = val
         cnf%smin_no3_to_plant_vr(i,j) = val
         cnf%smin_nh4_to_plant_vr(i,j) = val
         cnf%f_n2o_denit_vr(i,j)  = val
         cnf%f_n2o_nit_vr(i,j)  = val

         cnf%smin_no3_massdens_vr(i,j) = val
         cnf%k_nitr_t_vr(i,j) = val
         cnf%k_nitr_ph_vr(i,j) = val
         cnf%k_nitr_h2o_vr(i,j) = val
         cnf%k_nitr_vr(i,j) = val
         cnf%wfps_vr(i,j) = val
         cnf%fmax_denit_carbonsubstrate_vr(i,j) = val
         cnf%fmax_denit_nitrate_vr(i,j) = val
         cnf%f_denit_base_vr(i,j) = val

         cnf%diffus(i,j) = val
         cnf%ratio_k1(i,j) = val
         cnf%ratio_no3_co2(i,j) = val
         cnf%soil_co2_prod(i,j) = val
         cnf%fr_WFPS(i,j) = val
         cnf%soil_bulkdensity(i,j) = val

         cnf%r_psi(i,j) = val
         cnf%anaerobic_frac(i,j) = val
!#endif
         cnf%potential_immob_vr(i,j) = val
         cnf%actual_immob_vr(i,j) = val
         cnf%sminn_to_plant_vr(i,j) = val
         cnf%supplement_to_sminn_vr(i,j) = val
         cnf%gross_nmin_vr(i,j) = val
         cnf%net_nmin_vr(i,j) = val
      end do
   end do

   do fi = 1,num
      i = filter(fi)
      cnf%ndep_to_sminn(i) = val
      cnf%nfix_to_sminn(i) = val
      cnf%fert_to_sminn(i) = val
      cnf%soyfixn_to_sminn(i) = val
      cnf%hrv_deadstemn_to_prod10n(i) = val
      cnf%hrv_deadstemn_to_prod100n(i) = val
      cnf%prod10n_loss(i) = val
      cnf%prod100n_loss(i) = val
      cnf%product_nloss(i) = val
      cnf%potential_immob(i) = val
      cnf%actual_immob(i) = val
      cnf%sminn_to_plant(i) = val
      cnf%supplement_to_sminn(i) = val
      cnf%gross_nmin(i) = val
      cnf%net_nmin(i) = val
      cnf%denit(i) = val
!#ifdef NITRIF_DENITRIF
      cnf%f_nit(i) = val
      cnf%pot_f_nit(i) = val
      cnf%f_denit(i) = val
      cnf%pot_f_denit(i) = val
      cnf%f_n2o_denit(i) = val
      cnf%f_n2o_nit(i) = val
      cnf%smin_no3_leached(i) = val
      cnf%smin_no3_runoff(i) = val
!#else
!      cnf%sminn_to_denit_excess(i) = val
!      cnf%sminn_leached(i) = val
!#endif
      cnf%col_ninputs(i) = val
      cnf%col_noutputs(i) = val
      cnf%col_fire_nloss(i) = val
      cnf%som_n_leached(i) = val
   end do

   do k = 1, ndecomp_pools
      do fi = 1,num
         i = filter(fi)
         cnf%decomp_npools_leached(i,k) = val
         cnf%m_decomp_npools_to_fire(i,k) = val
      end do
   end do

   do k = 1, ndecomp_pools
      do j = 1, nlevdecomp_full
         do fi = 1,num
            i = filter(fi)
            cnf%m_decomp_npools_to_fire_vr(i,j,k) = val
            cnf%decomp_npools_sourcesink(i,j,k) = val
            cnf%decomp_npools_transport_tendency(i,j,k) = val
         end do
      end do
   end do

   do l = 1, ndecomp_cascade_transitions
         do fi = 1,num
            i = filter(fi)
            cnf%decomp_cascade_ntransfer(i,l) = val
            cnf%decomp_cascade_sminn_flux(i,l) = val
!#ifndef NITRIF_DENITRIF
!            cnf%sminn_to_denit_decomp_cascade(i,l) = val
!#endif
         end do
   end do

   do l = 1, ndecomp_cascade_transitions
      do j = 1, nlevdecomp_full
         do fi = 1,num
            i = filter(fi)
            cnf%decomp_cascade_ntransfer_vr(i,j,l) = val
            cnf%decomp_cascade_sminn_flux_vr(i,j,l) = val
!#ifndef NITRIF_DENITRIF
!            cnf%sminn_to_denit_decomp_cascade_vr(i,j,l) = val
!#endif
         end do
      end do
   end do


end subroutine CNSetCnf
!-----------------------------------------------------------------------

!#endif

end module cnsetvaluemod_ACASA

module subgridavemod_ACASA

!-----------------------------------------------------------------------
!BOP
!
! !MODULE: subgridavemod_ACASA
!
! !DESCRIPTION:
! Utilities to perfrom subgrid averaging
!
! !USES:
  use shr_kind_mod, only: r8 => shr_kind_r8
  use clmtype45
  use clm_varcon45, only : spval, isturb,  icol_roof, icol_sunwall, icol_shadewall, &
                         icol_road_perv, icol_road_imperv
!  use clm_varctl, only : iulog
  use abortutils, only : endrun

! !PUBLIC TYPES:
  implicit none
  save
!
! !PUBLIC MEMBER FUNCTIONS:
  public :: p2c   ! Perfrom an average from pfts to columns
  public :: p2l   ! Perfrom an average from pfts to landunits
  public :: p2g   ! Perfrom an average from pfts to gridcells
  public :: c2l   ! Perfrom an average from columns to landunits
  public :: c2g   ! Perfrom an average from columns to gridcells
  public :: l2g   ! Perfrom an average from landunits to gridcells

  interface p2c
     module procedure p2c_1d
     module procedure p2c_2d
     module procedure p2c_1d_filter
     module procedure p2c_2d_filter
  end interface
  interface p2l
     module procedure p2l_1d
     module procedure p2l_2d
  end interface
  interface p2g
     module procedure p2g_1d
     module procedure p2g_2d
  end interface
  interface c2l
     module procedure c2l_1d
     module procedure c2l_2d
  end interface
  interface c2g
     module procedure c2g_1d
     module procedure c2g_2d
  end interface
  interface l2g
     module procedure l2g_1d
     module procedure l2g_2d
  end interface
!
! !PRIVATE MEMBER FUNCTIONS:
  private :: build_scale_l2g
  private :: create_scale_l2g_lookup
!
! !REVISION HISTORY:
! Created by Mariana Vertenstein 12/03
!
!EOP

! WJS (10-14-11): TODO:
! 
! - I believe that scale_p2c, scale_c2l and scale_l2g should be included in the sumwt
! accumulations (e.g., sumwt = sumwt + wtgcell * scale_p2c * scale_c2l * scale_l2g), but
! that requires some more thought to (1) make sure that is correct, and (2) make sure it
! doesn't break the urban scaling. (See also my notes in create_scale_l2g_lookup.)
!   - Once that is done, you could use a scale of 0, avoiding the need for the use of
!   spval and the special checks that requires.
!
! - Currently, there is a lot of repeated code to calculate scale_c2l. This should be
! cleaned up.
!   - At a minimum, should collect the repeated code into a subroutine to eliminate this
!   repitition
!   - The best thing might be to use a lookup array, as is done for scale_l2g
! -----------------------------------------------------------------------

contains

!-----------------------------------------------------------------------
!BOP
!
! !IROUTINE: p2c_1d
!
! !INTERFACE:
  subroutine p2c_1d (lbp, ubp, lbc, ubc, parr, carr, p2c_scale_type)
!
! !DESCRIPTION:
! Perfrom subgrid-average from pfts to columns.
! Averaging is only done for points that are not equal to "spval".
!
! !USES:
    use clm_varpar45, only : max_pft_per_col
!
! !ARGUMENTS:
    implicit none
    integer , intent(in)  :: lbp, ubp              ! beginning and ending pft
    integer , intent(in)  :: lbc, ubc              ! beginning and ending column
    real(r8), intent(in)  :: parr(lbp:ubp)         ! pft array
    real(r8), intent(out) :: carr(lbc:ubc)         ! column array
    character(len=*), intent(in) :: p2c_scale_type ! scale type
!
! !REVISION HISTORY:
! Created by Mariana Vertenstein 12/03
!
!
! !LOCAL VARIABLES:
!EOP
    integer  :: pi,p,c,index           ! indices
    real(r8) :: scale_p2c(lbp:ubp)     ! scale factor for column->landunit mapping
    logical  :: found                  ! temporary for error check
    real(r8) :: sumwt(lbc:ubc)         ! sum of weights
    logical , pointer :: pactive(:)    ! true=>do computations on this pft (see reweightMod for details)
    real(r8), pointer  :: wtcol(:)      ! weight of pft relative to column
    integer , pointer :: pcolumn(:)    ! column index of corresponding pft
    integer , pointer :: npfts(:)      ! number of pfts in column
    integer , pointer :: pfti(:)       ! initial pft index in column
!------------------------------------------------------------------------

    pactive  => clm3%g%l%c%p%active
    wtcol    => clm3%g%l%c%p%wtcol
    pcolumn  => clm3%g%l%c%p%column
    npfts    => clm3%g%l%c%npfts
    pfti     => clm3%g%l%c%pfti

    if (p2c_scale_type == 'unity') then
       do p = lbp,ubp
          scale_p2c(p) = 1.0_r8
       end do
    else
!       write(iulog,*)'p2c_1d error: scale type ',p2c_scale_type,' not supported'
       call endrun()
    end if

    carr(lbc:ubc) = spval
    sumwt(lbc:ubc) = 0._r8
    do p = lbp,ubp
! KC
!    wtcol(p) = 1.0
! KC end

       if (pactive(p) .and. wtcol(p) /= 0._r8) then
          if (parr(p) /= spval) then
             c = pcolumn(p)
             if (sumwt(c) == 0._r8) carr(c) = 0._r8
             carr(c) = carr(c) + parr(p) * scale_p2c(p) * wtcol(p)
             sumwt(c) = sumwt(c) + wtcol(p)
          end if
       end if
    end do
    found = .false.
    do c = lbc,ubc
       if (sumwt(c) > 1.0_r8 + 1.e-6_r8) then
          found = .true.
          index = c
       else if (sumwt(c) /= 0._r8) then
          carr(c) = carr(c)/sumwt(c)
       end if
    end do
    if (found) then
!       write(iulog,*)'p2c error: sumwt is greater than 1.0 at c= ',index
       call endrun()
    end if

  end subroutine p2c_1d

!-----------------------------------------------------------------------
!BOP
!
! !IROUTINE: p2c_2d
!
! !INTERFACE:
  subroutine p2c_2d (lbp, ubp, lbc, ubc, num2d, parr, carr, p2c_scale_type)
!
! !DESCRIPTION:
! Perfrom subgrid-average from landunits to gridcells.
! Averaging is only done for points that are not equal to "spval".
!
! !USES:
    use clm_varpar45, only : max_pft_per_col
!
! !ARGUMENTS:
    implicit none
    integer , intent(in)  :: lbp, ubp              ! beginning and ending pft
    integer , intent(in)  :: lbc, ubc              ! beginning and ending column
    integer , intent(in)  :: num2d                 ! size of second dimension
    real(r8), intent(in)  :: parr(lbp:ubp,num2d)   ! pft array
    real(r8), intent(out) :: carr(lbc:ubc,num2d)   ! column array
    character(len=*), intent(in) :: p2c_scale_type ! scale type
!
! !REVISION HISTORY:
! Created by Mariana Vertenstein 12/03
!
!
! !LOCAL VARIABLES:
!EOP
    integer  :: j,pi,p,c,index         ! indices
    real(r8) :: scale_p2c(lbp:ubp)     ! scale factor for column->landunit mapping
    logical  :: found                  ! temporary for error check
    real(r8) :: sumwt(lbc:ubc)         ! sum of weights
    logical , pointer :: pactive(:)    ! true=>do computations on this pft (see reweightMod for details)
    real(r8) , pointer  :: wtcol(:)      ! weight of pft relative to column
    integer , pointer :: pcolumn(:)    ! column index of corresponding pft
    integer , pointer :: npfts(:)      ! number of pfts in column
    integer , pointer :: pfti(:)       ! initial pft index in column
!------------------------------------------------------------------------

    pactive  => clm3%g%l%c%p%active
    wtcol    => clm3%g%l%c%p%wtcol
    pcolumn  => clm3%g%l%c%p%column
    npfts    => clm3%g%l%c%npfts
    pfti     => clm3%g%l%c%pfti
! KC
!    wtcol = 1.0
! KC end

    if (p2c_scale_type == 'unity') then
       do p = lbp,ubp
          scale_p2c(p) = 1.0_r8
       end do
    else
!       write(iulog,*)'p2c_2d error: scale type ',p2c_scale_type,' not supported'
       call endrun()
    end if

    carr(:,:) = spval
    do j = 1,num2d
       sumwt(:) = 0._r8
       do p = lbp,ubp
! KC
    !wtcol(p) = 1.0
! KC end

          if (pactive(p) .and. wtcol(p) /= 0._r8) then
             if (parr(p,j) /= spval) then
                c = pcolumn(p)
                if (sumwt(c) == 0._r8) carr(c,j) = 0._r8
                carr(c,j) = carr(c,j) + parr(p,j) * scale_p2c(p) * wtcol(p)
                sumwt(c) = sumwt(c) + wtcol(p)
             end if
          end if
       end do
       found = .false.
       do c = lbc,ubc
          if (sumwt(c) > 1.0_r8 + 1.e-6_r8) then
             found = .true.
             index = c
          else if (sumwt(c) /= 0._r8) then
             carr(c,j) = carr(c,j)/sumwt(c)
          end if
       end do
       if (found) then
!          write(iulog,*)'p2c_2d error: sumwt is greater than 1.0 at c= ',index,' lev= ',j
          call endrun()
       end if
    end do 
  end subroutine p2c_2d

!-----------------------------------------------------------------------
!BOP
!
! !IROUTINE: p2c_1d_filter
!
! !INTERFACE:
  subroutine p2c_1d_filter (numfc, filterc, pftarr, colarr)
!
! !DESCRIPTION:
! perform pft to column averaging for single level pft arrays
!
! !USES:
    use clm_varpar45, only : max_pft_per_col
!
! !ARGUMENTS:
    implicit none
    integer , intent(in)  :: numfc
    integer , intent(in)  :: filterc(numfc)
    real(r8), pointer     :: pftarr(:)
    real(r8), pointer     :: colarr(:)
!
! !REVISION HISTORY:
! Created by Mariana Vertenstein 12/03
!
!
! !LOCAL VARIABLES:
!EOP
    integer :: fc,c,pi,p           ! indices
    logical , pointer :: pactive(:)! true=>do computations on this pft (see reweightMod for details)
    integer , pointer :: npfts(:)
    integer , pointer :: pfti(:)
    integer , pointer :: pftf(:)
    real(r8) , pointer  :: wtcol(:)
!-----------------------------------------------------------------------

    pactive => clm3%g%l%c%p%active
    npfts   => clm3%g%l%c%npfts
    pfti    => clm3%g%l%c%pfti
    pftf    => clm3%g%l%c%pftf
    wtcol   => clm3%g%l%c%p%wtcol
!KC 
!    wtcol = 1.0
!KC end
    do fc = 1,numfc
       c = filterc(fc)
       colarr(c) = 0._r8
       do p = pfti(c), pftf(c)
! KC
    !wtcol(p) = 1.0
! KC end

          if (pactive(p)) colarr(c) = colarr(c) + pftarr(p) * wtcol(p)
       end do
    end do

  end subroutine p2c_1d_filter

!-----------------------------------------------------------------------
!BOP
!
! !IROUTINE: p2c_2d_filter
!
! !INTERFACE:
  subroutine p2c_2d_filter (lev, numfc, filterc, pftarr, colarr)
!
! !DESCRIPTION:
! perform pft to column averaging for multi level pft arrays
!
! !USES:
    use clm_varpar45, only : max_pft_per_col

! !ARGUMENTS:
    implicit none
    integer , intent(in)  :: lev
    integer , intent(in)  :: numfc
    integer , intent(in)  :: filterc(numfc)
    real(r8), pointer     :: pftarr(:,:)
    real(r8), pointer     :: colarr(:,:)
!
! !REVISION HISTORY:
! Created by Mariana Vertenstein 12/03
!
!
! !LOCAL VARIABLES:
!EOP
    integer :: fc,c,pi,p,j    ! indices
    logical , pointer :: pactive(:)  ! true=>do computations on this pft (see reweightMod for details)
    integer , pointer :: npfts(:)
    integer , pointer :: pfti(:)
    integer , pointer :: pftf(:)
    real(r8), pointer  :: wtcol(:)
!-----------------------------------------------------------------------

    pactive => clm3%g%l%c%p%active
    npfts   => clm3%g%l%c%npfts
    pfti    => clm3%g%l%c%pfti
    pftf    => clm3%g%l%c%pftf
    wtcol   => clm3%g%l%c%p%wtcol
!KC 
!    wtcol = 1.0
!KC end
    do j = 1,lev
       do fc = 1,numfc
          c = filterc(fc)
          colarr(c,j) = 0._r8
          do p = pfti(c), pftf(c)
! KC
    !wtcol(p) = 1.0
! KC end
             if (pactive(p)) colarr(c,j) = colarr(c,j) + pftarr(p,j) * wtcol(p)
          end do
       end do
    end do

  end subroutine p2c_2d_filter

!-----------------------------------------------------------------------
!BOP
!
! !IROUTINE: p2l_1d
!
! !INTERFACE:
  subroutine p2l_1d (lbp, ubp, lbc, ubc, lbl, ubl, parr, larr, &
       p2c_scale_type, c2l_scale_type)
!
! !DESCRIPTION:
! Perfrom subgrid-average from pfts to landunits
! Averaging is only done for points that are not equal to "spval".
!
! !USES:
    use clm_varpar45, only : max_pft_per_lu
!
! !ARGUMENTS:
    implicit none
    integer , intent(in)  :: lbp, ubp              ! beginning and ending pft indices
    integer , intent(in)  :: lbc, ubc              ! beginning and ending column indices
    integer , intent(in)  :: lbl, ubl              ! beginning and ending landunit indices
    real(r8), intent(in)  :: parr(lbp:ubp)         ! input column array
    real(r8), intent(out) :: larr(lbl:ubl)         ! output landunit array
    character(len=*), intent(in) :: p2c_scale_type ! scale factor type for averaging
    character(len=*), intent(in) :: c2l_scale_type ! scale factor type for averaging
!
! !REVISION HISTORY:
! Created by Mariana Vertenstein 12/03
!
!
! !LOCAL VARIABLES:
!EOP
    integer  :: pi,p,c,l,index         ! indices
    logical  :: found                  ! temporary for error check
    real(r8) :: sumwt(lbl:ubl)         ! sum of weights
    real(r8) :: scale_p2c(lbc:ubc)     ! scale factor for pft->column mapping
    real(r8) :: scale_c2l(lbc:ubc)     ! scale factor for column->landunit mapping
    logical , pointer :: pactive(:)    ! true=>do computations on this pft (see reweightMod for details)
    real(r8), pointer :: wtlunit(:)    ! weight of pft relative to landunit
    integer , pointer :: pcolumn(:)    ! column of corresponding pft
    integer , pointer :: plandunit(:)  ! landunit of corresponding pft
    integer , pointer :: npfts(:)      ! number of pfts in landunit
    integer , pointer :: pfti(:)       ! initial pft index in landunit
    integer , pointer :: clandunit(:)  ! landunit of corresponding column
    integer , pointer :: ctype(:)      ! column type
    integer , pointer :: ltype(:)      ! landunit type
    real(r8), pointer :: canyon_hwr(:) ! urban canyon height to width ratio
!------------------------------------------------------------------------

    pactive    => clm3%g%l%c%p%active
    canyon_hwr => clm3%g%l%canyon_hwr
    ltype      => clm3%g%l%itype
    ctype      => clm3%g%l%c%itype
    clandunit  => clm3%g%l%c%landunit
    wtlunit    => clm3%g%l%c%p%wtlunit
    pcolumn    => clm3%g%l%c%p%column
    plandunit  => clm3%g%l%c%p%landunit
    npfts      => clm3%g%l%npfts
    pfti       => clm3%g%l%pfti

    if (c2l_scale_type == 'unity') then
       do c = lbc,ubc
          scale_c2l(c) = 1.0_r8
       end do
    else if (c2l_scale_type == 'urbanf') then
       do c = lbc,ubc
          l = clandunit(c) 
          if (ltype(l) == isturb) then
             if (ctype(c) == icol_sunwall) then
                scale_c2l(c) = 3.0 * canyon_hwr(l) 
             else if (ctype(c) == icol_shadewall) then
                scale_c2l(c) = 3.0 * canyon_hwr(l) 
             else if (ctype(c) == icol_road_perv .or. ctype(c) == icol_road_imperv) then
                scale_c2l(c) = 3.0_r8
             else if (ctype(c) == icol_roof) then
                scale_c2l(c) = 1.0_r8
             end if
          else
             scale_c2l(c) = 1.0_r8
          end if
       end do
    else if (c2l_scale_type == 'urbans') then
       do c = lbc,ubc
          l = clandunit(c) 
          if (ltype(l) == isturb) then
             if (ctype(c) == icol_sunwall) then
                scale_c2l(c) = (3.0 * canyon_hwr(l)) / (2.*canyon_hwr(l) + 1.)
             else if (ctype(c) == icol_shadewall) then
                scale_c2l(c) = (3.0 * canyon_hwr(l)) / (2.*canyon_hwr(l) + 1.)
             else if (ctype(c) == icol_road_perv .or. ctype(c) == icol_road_imperv) then
                scale_c2l(c) = 3.0 / (2.*canyon_hwr(l) + 1.)
             else if (ctype(c) == icol_roof) then
                scale_c2l(c) = 1.0_r8
             end if
          else
             scale_c2l(c) = 1.0_r8
          end if
       end do
    else
!       write(iulog,*)'p2l_1d error: scale type ',c2l_scale_type,' not supported'
       call endrun()
    end if

    if (p2c_scale_type == 'unity') then
       do p = lbp,ubp
          scale_p2c(p) = 1.0_r8
       end do
    else
!       write(iulog,*)'p2l_1d error: scale type ',p2c_scale_type,' not supported'
       call endrun()
    end if

    larr(:) = spval
    sumwt(:) = 0._r8
    do p = lbp,ubp
       if (pactive(p) .and. wtlunit(p) /= 0._r8) then
          c = pcolumn(p)
          if (parr(p) /= spval .and. scale_c2l(c) /= spval) then
             l = plandunit(p)
             if (sumwt(l) == 0._r8) larr(l) = 0._r8
             larr(l) = larr(l) + parr(p) * scale_p2c(p) * scale_c2l(c) * wtlunit(p)
             sumwt(l) = sumwt(l) + wtlunit(p)
          end if
       end if
    end do
    found = .false.
    do l = lbl,ubl
       if (sumwt(l) > 1.0_r8 + 1.e-6_r8) then
          found = .true.
          index = l
       else if (sumwt(l) /= 0._r8) then
          larr(l) = larr(l)/sumwt(l)
       end if
    end do
    if (found) then
!       write(iulog,*)'p2l_1d error: sumwt is greater than 1.0 at l= ',index
       call endrun()
    end if

  end subroutine p2l_1d

!-----------------------------------------------------------------------
!BOP
!
! !IROUTINE: p2l_2d
!
! !INTERFACE:
  subroutine p2l_2d(lbp, ubp, lbc, ubc, lbl, ubl, num2d, parr, larr, &
       p2c_scale_type, c2l_scale_type)
!
! !DESCRIPTION:
! Perfrom subgrid-average from pfts to landunits
! Averaging is only done for points that are not equal to "spval".
!
! !USES:
    use clm_varpar45, only : max_pft_per_lu
!
! !ARGUMENTS:
    implicit none
    integer , intent(in)  :: lbp, ubp              ! beginning and ending pft indices
    integer , intent(in)  :: lbc, ubc              ! beginning and ending column indices
    integer , intent(in)  :: lbl, ubl              ! beginning and ending landunit indices
    integer , intent(in)  :: num2d                 ! size of second dimension
    real(r8), intent(in)  :: parr(lbp:ubp,num2d)   ! input pft array
    real(r8), intent(out) :: larr(lbl:ubl,num2d)   ! output gridcell array
    character(len=*), intent(in) :: p2c_scale_type ! scale factor type for averaging
    character(len=*), intent(in) :: c2l_scale_type ! scale factor type for averaging
!
! !REVISION HISTORY:
! Created by Mariana Vertenstein 12/03
!
!
! !LOCAL VARIABLES:
!EOP
    integer  :: j,pi,p,c,l,index       ! indices
    logical  :: found                  ! temporary for error check
    real(r8) :: sumwt(lbl:ubl)         ! sum of weights
    real(r8) :: scale_p2c(lbc:ubc)     ! scale factor for pft->column mapping
    real(r8) :: scale_c2l(lbc:ubc)     ! scale factor for column->landunit mapping
    logical , pointer :: pactive(:)    ! true=>do computations on this pft (see reweightMod for details)
    real(r8), pointer :: wtlunit(:)    ! weight of pft relative to landunit
    integer , pointer :: pcolumn(:)    ! column of corresponding pft
    integer , pointer :: plandunit(:)  ! landunit of corresponding pft
    integer , pointer :: npfts(:)      ! number of pfts in landunit
    integer , pointer :: pfti(:)       ! initial pft index in landunit
    integer , pointer :: clandunit(:)  ! landunit of corresponding column
    integer , pointer :: ctype(:)      ! column type
    integer , pointer :: ltype(:)      ! landunit type
    real(r8), pointer :: canyon_hwr(:) ! urban canyon height to width ratio
!------------------------------------------------------------------------

    pactive    => clm3%g%l%c%p%active
    canyon_hwr => clm3%g%l%canyon_hwr
    ltype      => clm3%g%l%itype
    clandunit  => clm3%g%l%c%landunit
    ctype      => clm3%g%l%c%itype
    wtlunit   => clm3%g%l%c%p%wtlunit
    pcolumn   => clm3%g%l%c%p%column
    plandunit => clm3%g%l%c%p%landunit
    npfts     => clm3%g%l%npfts
    pfti      => clm3%g%l%pfti

    if (c2l_scale_type == 'unity') then
       do c = lbc,ubc
          scale_c2l(c) = 1.0_r8
       end do
    else if (c2l_scale_type == 'urbanf') then
       do c = lbc,ubc
          l = clandunit(c) 
          if (ltype(l) == isturb) then
             if (ctype(c) == icol_sunwall) then
                scale_c2l(c) = 3.0 * canyon_hwr(l) 
             else if (ctype(c) == icol_shadewall) then
                scale_c2l(c) = 3.0 * canyon_hwr(l) 
             else if (ctype(c) == icol_road_perv .or. ctype(c) == icol_road_imperv) then
                scale_c2l(c) = 3.0_r8
             else if (ctype(c) == icol_roof) then
                scale_c2l(c) = 1.0_r8
             end if
          else
             scale_c2l(c) = 1.0_r8
          end if
       end do
    else if (c2l_scale_type == 'urbans') then
       do c = lbc,ubc
          l = clandunit(c) 
          if (ltype(l) == isturb) then
             if (ctype(c) == icol_sunwall) then
                scale_c2l(c) = (3.0 * canyon_hwr(l)) / (2.*canyon_hwr(l) + 1.)
             else if (ctype(c) == icol_shadewall) then
                scale_c2l(c) = (3.0 * canyon_hwr(l)) / (2.*canyon_hwr(l) + 1.)
             else if (ctype(c) == icol_road_perv .or. ctype(c) == icol_road_imperv) then
                scale_c2l(c) = 3.0 / (2.*canyon_hwr(l) + 1.)
             else if (ctype(c) == icol_roof) then
                scale_c2l(c) = 1.0_r8
             end if
          else
             scale_c2l(c) = 1.0_r8
          end if
       end do
    else
!       write(iulog,*)'p2l_2d error: scale type ',c2l_scale_type,' not supported'
       call endrun()
    end if

    if (p2c_scale_type == 'unity') then
       do p = lbp,ubp
          scale_p2c(p) = 1.0_r8
       end do
    else
!       write(iulog,*)'p2l_2d error: scale type ',p2c_scale_type,' not supported'
       call endrun()
    end if

    larr(:,:) = spval
    do j = 1,num2d
       sumwt(:) = 0._r8
       do p = lbp,ubp
          if (pactive(p) .and. wtlunit(p) /= 0._r8) then
             c = pcolumn(p)
             if (parr(p,j) /= spval .and. scale_c2l(c) /= spval) then
                l = plandunit(p)
                if (sumwt(l) == 0._r8) larr(l,j) = 0._r8
                larr(l,j) = larr(l,j) + parr(p,j) * scale_p2c(p) * scale_c2l(c) * wtlunit(p)
                sumwt(l) = sumwt(l) + wtlunit(p)
             end if
          end if
       end do
       found = .false.
       do l = lbl,ubl
          if (sumwt(l) > 1.0_r8 + 1.e-6_r8) then
             found = .true.
             index = l
          else if (sumwt(l) /= 0._r8) then
             larr(l,j) = larr(l,j)/sumwt(l)
          end if
       end do
       if (found) then
!          write(iulog,*)'p2l_2d error: sumwt is greater than 1.0 at l= ',index,' j= ',j
          call endrun()
       end if
    end do

  end subroutine p2l_2d

