    real(r8) :: sumwt(lbg:ubg)         ! sum of weights
    logical , pointer :: pactive(:)    ! true=>do computations on this pft (see reweightMod for details)
    real(r8), pointer :: wtgcell(:)    ! weight of pfts relative to gridcells
