!    end if
!    ipfts = ipfts + npfts_per_lunit
!    if (present(nurban_hd )) nurban_hd  = npfts_per_lunit
!    if (present(wturban_hd)) wturban_hd = wtlunit

    ! Set urban medium density landunit

!    npfts_per_lunit = 0
