!            end if
!            
!            sminn_to_plant_vr(c,j) = (sminn_vr(c,j)/dt) - actual_immob_vr(c,j)
!         end if
!      end do
!   end do

   ! sum up N fluxes to plant
!   do j = 1, nlevdecomp
!      do fc=1,num_soilc
!         c = filter_soilc(fc)    
!         sminn_to_plant(c) = sminn_to_plant(c) + sminn_to_plant_vr(c,j) * dzsoi_decomp(j)
!      end do
