   ! sum up N fluxes to immobilization
!   do j = 1, nlevdecomp
!      do fc=1,num_soilc
!         c = filter_soilc(fc)    
!         actual_immob(c) = actual_immob(c) + actual_immob_vr(c,j) * dzsoi_decomp(j)
!         potential_immob(c) = potential_immob(c) + potential_immob_vr(c,j) * dzsoi_decomp(j)
!      end do
!   end do
!
!   do fc=1,num_soilc
!      c = filter_soilc(fc)    
!      ! calculate the fraction of potential growth that can be
!      ! acheived with the N available to plants      
!      if (col_plant_ndemand(c) > 0.0_r8) then
!         fpg(c) = sminn_to_plant(c) / col_plant_ndemand(c)
!      else
!i,         fpg(c) = 1.0_r8
!      end if
!      
!      ! calculate the fraction of immobilization realized (for diagnostic purposes)
!      if (potential_immob(c) > 0.0_r8) then
!         fpi(c) = actual_immob(c) / potential_immob(c)
!      else
!         fpi(c) = 1.0_r8
!      end if
!   end do

!#else  !----------NITRIF_DENITRIF-------------!
   ! column loops to resolve plant/heterotroph/nitrifier/denitrifier competition for mineral N

   ! init total mineral N pools
   do fc=1,num_soilc
      c = filter_soilc(fc)
      sminn_tot(c) = 0.
   end do

   ! sum up total mineral N pools
   do j = 1, nlevdecomp
      do fc=1,num_soilc
         c = filter_soilc(fc)
         sminn_tot(c) = sminn_tot(c) + (smin_no3_vr(c,j) + smin_nh4_vr(c,j)) * dzsoi_decomp(j)
      end do
   end do

   ! define N uptake profile for initial vertical distribution of plant N uptake, assuming plant seeks N from where it is most abundant
   do j = 1, nlevdecomp
      do fc=1,num_soilc
         c = filter_soilc(fc)
         if (sminn_tot(c) .gt. 0.) then
               nuptake_prof(c,j) = sminn_vr(c,j) / sminn_tot(c)
         else
               nuptake_prof(c,j) = nfixation_prof(c,j)
         endif
      end do
   end do

   ! main column/vertical loop
   do j = 1, nlevdecomp  
      do fc=1,num_soilc
         c = filter_soilc(fc)
         l = clandunit(c)

         !  first compete for nh4
         sum_nh4_demand(c,j) = col_plant_ndemand(c) * nuptake_prof(c,j) + potential_immob_vr(c,j) + pot_f_nit_vr(c,j)
         sum_nh4_demand_scaled(c,j) = col_plant_ndemand(c)* nuptake_prof(c,j) * compet_plant_nh4 + &
              potential_immob_vr(c,j)*compet_decomp_nh4 + pot_f_nit_vr(c,j)*compet_nit
         if (sum_nh4_demand(c,j)*dt < smin_nh4_vr(c,j)) then
            ! NH4 availability is not limiting immobilization or plant
            ! uptake, and all can proceed at their potential rates
           nlimit_nh4(c,j) = 0
            fpi_nh4_vr(c,j) = 1.0_r8
            actual_immob_nh4_vr(c,j) = potential_immob_vr(c,j)
            smin_nh4_to_plant_vr(c,j) = col_plant_ndemand(c) * nuptake_prof(c,j)
            
            f_nit_vr(c,j) = pot_f_nit_vr(c,j)
            
         else
            
            ! NH4 availability can not satisfy the sum of immobilization, nitrification, and
            ! plant growth demands, so these three demands compete for available
            ! soil mineral NH4 resource.
            nlimit_nh4(c,j) = 1
            if (sum_nh4_demand(c,j) > 0.0_r8) then
               actual_immob_nh4_vr(c,j) = min((smin_nh4_vr(c,j)/dt)*(potential_immob_vr(c,j)*compet_decomp_nh4 / sum_nh4_demand_scaled(c,j)), potential_immob_vr(c,j))
               smin_nh4_to_plant_vr(c,j) = min((smin_nh4_vr(c,j)/dt)*(col_plant_ndemand(c)*nuptake_prof(c,j)*compet_plant_nh4 / sum_nh4_demand_scaled(c,j)), col_plant_ndemand(c)*nuptake_prof(c,j))
               f_nit_vr(c,j) =  min((smin_nh4_vr(c,j)/dt)*(pot_f_nit_vr(c,j)*compet_nit / sum_nh4_demand_scaled(c,j)), pot_f_nit_vr(c,j))
            else
               actual_immob_nh4_vr(c,j) = 0.0_r8
               smin_nh4_to_plant_vr(c,j) = 0.0_r8
               f_nit_vr(c,j) = 0.0_r8
            end if
            
            if (potential_immob_vr(c,j) > 0.0_r8) then
               fpi_nh4_vr(c,j) = actual_immob_nh4_vr(c,j) / potential_immob_vr(c,j)
            else
               fpi_nh4_vr(c,j) = 0.0_r8
            end if
           
         end if

         ! next compete for no3
         sum_no3_demand(c,j) = (col_plant_ndemand(c)*nuptake_prof(c,j)-smin_nh4_to_plant_vr(c,j)) + (potential_immob_vr(c,j)-actual_immob_nh4_vr(c,j)) + pot_f_denit_vr(c,j)
         sum_no3_demand_scaled(c,j) = (col_plant_ndemand(c)*nuptake_prof(c,j)-smin_nh4_to_plant_vr(c,j))*compet_plant_no3 + &
              (potential_immob_vr(c,j)-actual_immob_nh4_vr(c,j))*compet_decomp_no3 + pot_f_denit_vr(c,j)*compet_denit

         if (sum_no3_demand(c,j)*dt < smin_no3_vr(c,j)) then
            ! NO3 availability is not limiting immobilization or plant
            ! uptake, and all can proceed at their potential rates
            nlimit_no3(c,j) = 1
            fpi_no3_vr(c,j) = 1.0_r8 -  fpi_nh4_vr(c,j)
            actual_immob_no3_vr(c,j) = (potential_immob_vr(c,j)-actual_immob_nh4_vr(c,j))
            smin_no3_to_plant_vr(c,j) = (col_plant_ndemand(c)*nuptake_prof(c,j)-smin_nh4_to_plant_vr(c,j))
            
            f_denit_vr(c,j) = pot_f_denit_vr(c,j)
            
         else 
            
            ! NO3 availability can not satisfy the sum of immobilization, denitrification, and
            ! plant growth demands, so these three demands compete for available
            ! soil mineral NO3 resource.
            nlimit_no3(c,j) = 1
            if (sum_no3_demand(c,j) > 0.0_r8) then
               actual_immob_no3_vr(c,j) = min((smin_no3_vr(c,j)/dt)*((potential_immob_vr(c,j)-actual_immob_nh4_vr(c,j))*compet_decomp_no3 / sum_no3_demand_scaled(c,j)), &
                    potential_immob_vr(c,j)-actual_immob_nh4_vr(c,j))
               smin_no3_to_plant_vr(c,j) = min((smin_no3_vr(c,j)/dt)*((col_plant_ndemand(c)*nuptake_prof(c,j)-smin_nh4_to_plant_vr(c,j))*compet_plant_no3 / sum_no3_demand_scaled(c,j)), &
                    col_plant_ndemand(c)*nuptake_prof(c,j)-smin_nh4_to_plant_vr(c,j))
               f_denit_vr(c,j) =  min((smin_no3_vr(c,j)/dt)*(pot_f_denit_vr(c,j)*compet_denit / sum_no3_demand_scaled(c,j)), pot_f_denit_vr(c,j))
            else
               actual_immob_no3_vr(c,j) = 0.0_r8
               smin_no3_to_plant_vr(c,j) = 0.0_r8
               f_denit_vr(c,j) = 0.0_r8
            end if
            
            if (potential_immob_vr(c,j) > 0.0_r8) then
              fpi_no3_vr(c,j) = actual_immob_no3_vr(c,j) / potential_immob_vr(c,j)
            else
               fpi_no3_vr(c,j) = 0.0_r8
            end if
            
         end if
         

         ! n2o emissions: n2o from nitr is const fraction, n2o from denitr is calculated in nitrif_denitrif
         f_n2o_nit_vr(c,j) = f_nit_vr(c,j) * nitrif_n2o_loss_frac
         f_n2o_denit_vr(c,j) = f_denit_vr(c,j) / (1._r8 + n2_n2o_ratio_denit_vr(c,j))
         
         
         ! this code block controls the addition of N to sminn pool
         ! to eliminate any N limitation, when Carbon_Only is set.  This lets the
         ! model behave essentially as a carbon-only model, but with the
         ! benefit of keeping track of the N additions needed to
         ! eliminate N limitations, so there is still a diagnostic quantity
         ! that describes the degree of N limitation at steady-state.
         
         if ( Carbon_only) then !.or. &
!              (crop_supln .and. (itypelun(l) == istcrop) .and. &
!               (ivt(pfti(c)) >= npcropmin))  then

            if ( fpi_no3_vr(c,j) + fpi_nh4_vr(c,j) .lt. 1._r8 ) then
               fpi_nh4_vr(c,j) = 1.0_r8 - fpi_no3_vr(c,j)
               supplement_to_sminn_vr(c,j) = (potential_immob_vr(c,j) -  actual_immob_no3_vr(c,j)) - actual_immob_nh4_vr(c,j) 
               ! update to new values that satisfy demand
               actual_immob_nh4_vr(c,j) = potential_immob_vr(c,j) -  actual_immob_no3_vr(c,j)   
            end if
            if ( smin_no3_to_plant_vr(c,j) + smin_nh4_to_plant_vr(c,j) .lt. col_plant_ndemand(c)*nuptake_prof(c,j) ) then
               supplement_to_sminn_vr(c,j) = supplement_to_sminn_vr(c,j) + &
                    (col_plant_ndemand(c)*nuptake_prof(c,j) - smin_no3_to_plant_vr(c,j)) - smin_nh4_to_plant_vr(c,j)  ! use old values
               smin_nh4_to_plant_vr(c,j) = col_plant_ndemand(c)*nuptake_prof(c,j) - smin_no3_to_plant_vr(c,j)
            end if
            sminn_to_plant_vr(c,j) = smin_no3_to_plant_vr(c,j) + smin_nh4_to_plant_vr(c,j)
         end if

         ! sum up no3 and nh4 fluxes
         fpi_vr(c,j) = fpi_no3_vr(c,j) + fpi_nh4_vr(c,j)
         sminn_to_plant_vr(c,j) = smin_no3_to_plant_vr(c,j) + smin_nh4_to_plant_vr(c,j)
         actual_immob_vr(c,j) = actual_immob_no3_vr(c,j) + actual_immob_nh4_vr(c,j)
      end do
   end do
   
   do fc=1,num_soilc
      c = filter_soilc(fc)
      ! sum up N fluxes to plant after initial competition
      sminn_to_plant(c) = 0._r8
   end do   
   do j = 1, nlevdecomp  
      do fc=1,num_soilc
         c = filter_soilc(fc)
         sminn_to_plant(c) = sminn_to_plant(c) + sminn_to_plant_vr(c,j) * dzsoi_decomp(j)
      end do
   end do

   ! give plants a second pass to see if there is any mineral N left over with which to satisfy residual N demand.
   ! first take frm nh4 pool; then take from no3 pool
   do fc=1,num_soilc
      c = filter_soilc(fc)
      residual_plant_ndemand(c) = col_plant_ndemand(c) - sminn_to_plant(c)
      residual_smin_nh4(c) = 0._r8
   end do
   do j = 1, nlevdecomp  
      do fc=1,num_soilc
         c = filter_soilc(fc)
         if (residual_plant_ndemand(c) .gt. 0._r8 ) then
            if (nlimit_nh4(c,j) .eq. 0) then
               residual_smin_nh4_vr(c,j) = max(smin_nh4_vr(c,j) - (actual_immob_vr(c,j) + smin_nh4_to_plant_vr(c,j) ) * dt, 0._r8)
               residual_smin_nh4(c) = residual_smin_nh4(c) + residual_smin_nh4_vr(c,j) * dzsoi_decomp(j)
            else
               residual_smin_nh4_vr(c,j)  = 0._r8
            endif
            
            if ( residual_smin_nh4(c) .gt. 0._r8 .and. nlimit_nh4(c,j) .eq. 0 ) then
               smin_nh4_to_plant_vr(c,j) = smin_nh4_to_plant_vr(c,j) + residual_smin_nh4_vr(c,j) * &
                    min(( residual_plant_ndemand(c) *  dt ) / residual_smin_nh4(c), 1._r8) / dt
            endif
         end if
      end do
   end do
   
   ! re-sum up N fluxes to plant after second pass for nh4
   do fc=1,num_soilc
      c = filter_soilc(fc)
      sminn_to_plant(c) = 0._r8
   end do
   do j = 1, nlevdecomp
      do fc=1,num_soilc
         c = filter_soilc(fc)
         sminn_to_plant_vr(c,j) = smin_nh4_to_plant_vr(c,j) + smin_no3_to_plant_vr(c,j)
         sminn_to_plant(c) = sminn_to_plant(c) + (sminn_to_plant_vr(c,j)) * dzsoi_decomp(j)
      end do
   end do
   
   !
   ! and now do second pass for no3
   do fc=1,num_soilc
      c = filter_soilc(fc)
      residual_plant_ndemand(c) = col_plant_ndemand(c) - sminn_to_plant(c)
      residual_smin_no3(c) = 0._r8
   end do
   
   do j = 1, nlevdecomp
      do fc=1,num_soilc
         c = filter_soilc(fc)
         if (residual_plant_ndemand(c) .gt. 0._r8 ) then
            if (nlimit_no3(c,j) .eq. 0) then
               residual_smin_no3_vr(c,j) = max(smin_no3_vr(c,j) - (actual_immob_vr(c,j) + smin_no3_to_plant_vr(c,j) ) * dt, 0._r8)
               residual_smin_no3(c) = residual_smin_no3(c) + residual_smin_no3_vr(c,j) * dzsoi_decomp(j)
            else
               residual_smin_no3_vr(c,j)  = 0._r8
            endif
            
            if ( residual_smin_no3(c) .gt. 0._r8 .and. nlimit_no3(c,j) .eq. 0) then
               smin_no3_to_plant_vr(c,j) = smin_no3_to_plant_vr(c,j) + residual_smin_no3_vr(c,j) * &
                    min(( residual_plant_ndemand(c) *  dt ) / residual_smin_no3(c), 1._r8) / dt
            endif
         endif
      end do
   end do
   
   ! re-sum up N fluxes to plant after second passes of both no3 and nh4
   do fc=1,num_soilc
      c = filter_soilc(fc)
      sminn_to_plant(c) = 0._r8
   end do
   do j = 1, nlevdecomp
      do fc=1,num_soilc
         c = filter_soilc(fc)
         sminn_to_plant_vr(c,j) = smin_nh4_to_plant_vr(c,j) + smin_no3_to_plant_vr(c,j)
         sminn_to_plant(c) = sminn_to_plant(c) + (sminn_to_plant_vr(c,j)) * dzsoi_decomp(j)
      end do
   end do
   
   ! sum up N fluxes to immobilization
   do fc=1,num_soilc
      c = filter_soilc(fc)
      actual_immob(c) = 0._r8
      potential_immob(c) = 0._r8
   end do
   do j = 1, nlevdecomp  
      do fc=1,num_soilc
         c = filter_soilc(fc)
         actual_immob(c) = actual_immob(c) + actual_immob_vr(c,j) * dzsoi_decomp(j)
         potential_immob(c) = potential_immob(c) + potential_immob_vr(c,j) * dzsoi_decomp(j)
      end do
   end do


   do fc=1,num_soilc
      c = filter_soilc(fc)   
      ! calculate the fraction of potential growth that can be
      ! acheived with the N available to plants
      if (col_plant_ndemand(c) > 0.0_r8) then
         fpg(c) = sminn_to_plant(c) / col_plant_ndemand(c)
      else
         fpg(c) = 1._r8
      end if
      
      ! calculate the fraction of immobilization realized (for diagnostic purposes)
      if (potential_immob(c) > 0.0_r8) then
         fpi(c) = actual_immob(c) / potential_immob(c)
      else
         fpi(c) = 1._r8
      end if
   end do ! end of column loops
!#endif


   
   ! start new pft loop to distribute the available N between the
   ! competing pfts on the basis of relative demand, and allocate C and N to
   ! new growth and storage
   
   do fp=1,num_soilp
      p = filter_soilp(fp)
      c = pcolumn(p)

      ! set some local allocation variables
      f1 = froot_leaf(ivt(p))
      f2 = croot_stem(ivt(p))
      
      ! modified wood allocation to be 2.2 at npp=800 gC/m2/yr, 0.2 at npp=0,
      ! constrained so that it does not go lower than 0.2 (under negative annsum_npp)
      ! There was an error in this formula in previous version, where the coefficient
      ! was 0.004 instead of 0.0025.
      ! This variable allocation is only for trees. Shrubs have a constant
      ! allocation as specified in the pft-physiology file.  The value is also used
      ! as a trigger here: -1.0 means to use the dynamic allocation (trees).
      if (stem_leaf(ivt(p)) == -1._r8) then
        f3 = (2.7/(1.0+exp(-0.004*(annsum_npp(p) - 300.0)))) - 0.4
      else
        f3 = stem_leaf(ivt(p))
      end if
      
      f4 = flivewd(ivt(p))
      g1 = grperc(ivt(p))
      g2 = grpnow(ivt(p))
      cnl = leafcn(ivt(p))
      cnfr = frootcn(ivt(p))
      cnlw = livewdcn(ivt(p))
      cndw = deadwdcn(ivt(p))
!      fcur2 = fcur(ivt(p))
      fcur = fcurcn(ivt(p))

      if (ivt(p) >= npcropmin) then ! skip 2 generic crops
         if (croplive(p)) then
            f1 = aroot(p) / aleaf(p)
            f3 = astem(p) / aleaf(p)
            f5 = arepr(p) / aleaf(p)
            g1 = 0.25_r8
         else
            f1 = 0._r8
            f3 = 0._r8
            f5 = 0._r8
            g1 = 0.25_r8
         end if
      end if

      ! increase fcur linearly with ndays_active, until fcur reaches 1.0 at
      ! ndays_active = days/year.  This prevents the continued storage of C and N.
      ! turning off this correction (PET, 12/11/03), instead using bgtr in
      ! phenology algorithm.
      !fcur = fcur + (1._r8 - fcur)*lgsf(p)
      sminn_to_npool(p) = plant_ndemand(p) * fpg(c)
      plant_nalloc(p) = sminn_to_npool(p) + retransn_to_npool(p)


      ! calculate the associated carbon allocation, and the excess
      ! carbon flux that must be accounted for through downregulation
      plant_calloc(p) = plant_nalloc(p) * (c_allometry(p)/n_allometry(p))
      excess_cflux(p) = availc(p) - plant_calloc(p)


      ! reduce gpp fluxes due to N limitation
      if (gpp(p) > 0.0_r8) then
         downreg(p) = excess_cflux(p)/gpp(p)
! KC
!         psnsun_to_cpool(p) = psnsun_to_cpool(p)*(1._r8 - downreg(p))
!         psnshade_to_cpool(p) = psnshade_to_cpool(p)*(1._r8 - downreg(p))
          gpp(p) = gpp(p)*(1._r8 - downreg(p))
!KC end
!         if ( use_c13 ) then
!            c13_psnsun_to_cpool(p) = c13_psnsun_to_cpool(p)*(1._r8 - downreg(p))
!            c13_psnshade_to_cpool(p) = c13_psnshade_to_cpool(p)*(1._r8 - downreg(p))
!         endif

!         if ( use_c14 ) then
!            c14_psnsun_to_cpool(p) = c14_psnsun_to_cpool(p)*(1._r8 - downreg(p))
!            c14_psnshade_to_cpool(p) = c14_psnshade_to_cpool(p)*(1._r8 - downreg(p))
!         endif
      end if

      ! calculate the amount of new leaf C dictated by these allocation
      ! decisions, and calculate the daily fluxes of C and N to current
      ! growth and storage pools

      ! fcur is the proportion of this day's growth that is displayed now,
      ! the remainder going into storage for display next year through the
      ! transfer pools

      nlc = plant_calloc(p) / c_allometry(p)
      cpool_to_leafc(p)          = nlc * fcur
      cpool_to_leafc_storage(p)  = nlc * (1._r8 - fcur)
      cpool_to_frootc(p)         = nlc * f1 * fcur
      cpool_to_frootc_storage(p) = nlc * f1 * (1._r8 - fcur)
      if (woody(ivt(p)) == 1._r8) then
         cpool_to_livestemc(p)          = nlc * f3 * f4 * fcur
         cpool_to_livestemc_storage(p)  = nlc * f3 * f4 * (1._r8 - fcur)
         cpool_to_deadstemc(p)          = nlc * f3 * (1._r8 - f4) * fcur
         cpool_to_deadstemc_storage(p)  = nlc * f3 * (1._r8 - f4) * (1._r8 - fcur)
         cpool_to_livecrootc(p)         = nlc * f2 * f3 * f4 * fcur
         cpool_to_livecrootc_storage(p) = nlc * f2 * f3 * f4 * (1._r8 - fcur)
         cpool_to_deadcrootc(p)         = nlc * f2 * f3 * (1._r8 - f4) * fcur
         cpool_to_deadcrootc_storage(p) = nlc * f2 * f3 * (1._r8 - f4) * (1._r8 - fcur)
      end if
      if (ivt(p) >= npcropmin) then ! skip 2 generic crops
         cpool_to_livestemc(p)          = nlc * f3 * f4 * fcur
         cpool_to_livestemc_storage(p)  = nlc * f3 * f4 * (1._r8 - fcur)
         cpool_to_deadstemc(p)          = nlc * f3 * (1._r8 - f4) * fcur
         cpool_to_deadstemc_storage(p)  = nlc * f3 * (1._r8 - f4) * (1._r8 - fcur)
         cpool_to_livecrootc(p)         = nlc * f2 * f3 * f4 * fcur
         cpool_to_livecrootc_storage(p) = nlc * f2 * f3 * f4 * (1._r8 - fcur)
         cpool_to_deadcrootc(p)         = nlc * f2 * f3 * (1._r8 - f4) * fcur
         cpool_to_deadcrootc_storage(p) = nlc * f2 * f3 * (1._r8 - f4) * (1._r8 - fcur)
         cpool_to_grainc(p)             = nlc * f5 * fcur
         cpool_to_grainc_storage(p)     = nlc * f5 * (1._r8 -fcur)
      end if

      ! corresponding N fluxes
      npool_to_leafn(p)          = (nlc / cnl) * fcur
      npool_to_leafn_storage(p)  = (nlc / cnl) * (1._r8 - fcur)
      npool_to_frootn(p)         = (nlc * f1 / cnfr) * fcur
      npool_to_frootn_storage(p) = (nlc * f1 / cnfr) * (1._r8 - fcur)
      if (woody(ivt(p)) == 1._r8) then
         npool_to_livestemn(p)          = (nlc * f3 * f4 / cnlw) * fcur
         npool_to_livestemn_storage(p)  = (nlc * f3 * f4 / cnlw) * (1._r8 - fcur)
         npool_to_deadstemn(p)          = (nlc * f3 * (1._r8 - f4) / cndw) * fcur
         npool_to_deadstemn_storage(p)  = (nlc * f3 * (1._r8 - f4) / cndw) * (1._r8 - fcur)
         npool_to_livecrootn(p)         = (nlc * f2 * f3 * f4 / cnlw) * fcur
         npool_to_livecrootn_storage(p) = (nlc * f2 * f3 * f4 / cnlw) * (1._r8 - fcur)
         npool_to_deadcrootn(p)         = (nlc * f2 * f3 * (1._r8 - f4) / cndw) * fcur
         npool_to_deadcrootn_storage(p) = (nlc * f2 * f3 * (1._r8 - f4) / cndw) * (1._r8 - fcur)
      end if
      if (ivt(p) >= npcropmin) then ! skip 2 generic crops
         cng = graincn(ivt(p))
         npool_to_livestemn(p)          = (nlc * f3 * f4 / cnlw) * fcur
         npool_to_livestemn_storage(p)  = (nlc * f3 * f4 / cnlw) * (1._r8 - fcur)
         npool_to_deadstemn(p)          = (nlc * f3 * (1._r8 - f4) / cndw) * fcur
         npool_to_deadstemn_storage(p)  = (nlc * f3 * (1._r8 - f4) / cndw) * (1._r8 - fcur)
         npool_to_livecrootn(p)         = (nlc * f2 * f3 * f4 / cnlw) * fcur
         npool_to_livecrootn_storage(p) = (nlc * f2 * f3 * f4 / cnlw) * (1._r8 - fcur)
         npool_to_deadcrootn(p)         = (nlc * f2 * f3 * (1._r8 - f4) / cndw) * fcur
         npool_to_deadcrootn_storage(p) = (nlc * f2 * f3 * (1._r8 - f4) / cndw) * (1._r8 - fcur)
         npool_to_grainn(p)             = (nlc * f5 / cng) * fcur
         npool_to_grainn_storage(p)     = (nlc * f5 / cng) * (1._r8 -fcur)
      end if

      ! Calculate the amount of carbon that needs to go into growth
      ! respiration storage to satisfy all of the storage growth demands.
      ! Allows for the fraction of growth respiration that is released at the
      ! time of fixation, versus the remaining fraction that is stored for
      ! release at the time of display. Note that all the growth respiration
      ! fluxes that get released on a given timestep are calculated in growth_resp(),
      ! but that the storage of C for growth resp during display of transferred
      ! growth is assigned here.

      gresp_storage = cpool_to_leafc_storage(p) + cpool_to_frootc_storage(p)
      if (woody(ivt(p)) == 1._r8) then
         gresp_storage = gresp_storage + cpool_to_livestemc_storage(p)
         gresp_storage = gresp_storage + cpool_to_deadstemc_storage(p)
         gresp_storage = gresp_storage + cpool_to_livecrootc_storage(p)
         gresp_storage = gresp_storage + cpool_to_deadcrootc_storage(p)
      end if
      if (ivt(p) >= npcropmin) then ! skip 2 generic crops
         gresp_storage = gresp_storage + cpool_to_livestemc_storage(p)
         gresp_storage = gresp_storage + cpool_to_grainc_storage(p)
      end if
      cpool_to_gresp_storage(p) = gresp_storage * g1 * (1._r8 - g2)

   end do ! end pft loop

   deallocate(col_plant_ndemand)
end subroutine CNAllocation

!#endif

end module cnallocationmod_ACASA


module cndecompmod_ACASA
!#ifdef CN

!-----------------------------------------------------------------------
!BOP
!
! !MODULE: cndecompmod_ACASA
!
! !DESCRIPTION:
! Module holding routines used in litter and soil decomposition model
! for coupled carbon-nitrogen code.
!
! !USES:
   use shr_kind_mod , only: r8 => shr_kind_r8
!   use shr_const_mod_ACASA, only: SHR_CONST_TKFRZ
!    use clm_varctl  , only: iulog
    use clm_varcon45, only: dzsoi_decomp
!#ifndef CENTURY_DECOMP
!    use CNDecompCascadeMod_BGC, only : decomp_rate_constants
!#else
    use CNDecompCascadeMod_CENTURY, only : decomp_rate_constants
!#endif
!#ifdef NITRIF_DENITRIF
    use CNNitrifDenitrifMod, only: nitrif_denitrif
!#endif
    use CNVerticalProfileMod, only: decomp_vertprofiles

   implicit none
   save
   private
! !PUBLIC MEMBER FUNCTIONS:
   public:: CNDecompAlloc
   
!
! !REVISION HISTORY:
! 8/15/03: Created by Peter Thornton
! 10/23/03, Peter Thornton: migrated to vector data structures
!
!EOP
!-----------------------------------------------------------------------

contains

!-----------------------------------------------------------------------
!BOP
!
! !IROUTINE: CNDecompAlloc
!
! !INTERFACE:
subroutine CNDecompAlloc (lbp, ubp, lbc, ubc, num_soilc, filter_soilc, &
   num_soilp, filter_soilp,nstep,yr,nsoil0,SH2O,dt,tphoto, &
   RUNOFF1,RUNOFF2,isoi3)
!
! !DESCRIPTION:
!
! !USES:
   use clmtype45
   use cnallocationmod_ACASA , only: CNAllocation
!   use clm_time_manager, only: get_step_size
   use clm_varpar45   , only: nlevsoi,nlevgrnd,nlevdecomp,ndecomp_cascade_transitions,ndecomp_pools
   use pft2colmod_ACASA      , only: p2c
   use CNDecompCascadeMod_CENTURY, only: init_decompcascade
!
! !ARGUMENTS:
   implicit none
   integer, intent(in) :: lbp, ubp        ! pft-index bounds
   integer, intent(in) :: lbc, ubc        ! column-index bounds
   integer, intent(in) :: num_soilc       ! number of soil columns in filter
   integer, intent(in) :: filter_soilc(ubc-lbc+1) ! filter for soil columns
   integer, intent(in) :: num_soilp       ! number of soil pfts in filter
   integer, intent(in) :: filter_soilp(ubp-lbp+1) ! filter for soil pfts
!
! !CALLED FROM:
! subroutine CNEcosystemDyn in module CNEcosystemDynMod.F90
!
! !REVISION HISTORY:
! 8/15/03: Created by Peter Thornton
!
! !LOCAL VARIABLES:
! local pointers to implicit in scalars
!
   ! all c pools involved in decomposition
   real(r8), pointer :: decomp_cpools_vr(:,:,:)    ! (gC/m3)  vertically-resolved decomposing (litter, cwd, soil) c pools
   ! all n pools involved in decomposition
   real(r8), pointer :: decomp_npools_vr(:,:,:)    ! (gC/m3)  vertically-resolved decomposing (litter, cwd, soil) N pools

   integer, pointer :: clandunit(:)      ! index into landunit level quantities
   integer , pointer :: itypelun(:)      ! landunit type
   ! pft level
   real(r8), pointer :: rootfr(:,:)      ! fraction of roots in each soil layer  (nlevgrnd)
!   real(r8) :: rootfr(:,:)      ! fraction of roots in each soil layer  (nlevgrnd)
!
! local pointers to implicit in/out scalars
!
   real(r8), pointer :: fpi_vr(:,:)                            ! fraction of potential immobilization (no units)
   real(r8), pointer :: decomp_cascade_hr_vr(:,:,:)            ! vertically-resolved het. resp. from decomposing C pools (gC/m3/s)
   real(r8), pointer :: decomp_cascade_ctransfer_vr(:,:,:)     ! vertically-resolved het. resp. from decomposing C pools (gC/m3/s)
   real(r8), pointer :: decomp_pools_hr(:,:)                   ! het. resp. from decomposing C pools (gC/m2/s)
   real(r8), pointer :: decomp_cascade_ctransfer(:,:)          ! vertically-resolved C transferred along deomposition cascade (gC/m3/s)
   real(r8), pointer :: decomp_cascade_ntransfer_vr(:,:,:)     ! vert-res transfer of N from donor to receiver pool along decomp. cascade (gN/m3/s)
   real(r8), pointer :: decomp_cascade_sminn_flux_vr(:,:,:)    ! vert-res mineral N flux for transition along decomposition cascade (gN/m3/s)

   real(r8), pointer :: potential_immob_vr(:,:)
!#ifndef NITRIF_DENITRIF
!   real(r8), pointer :: sminn_to_denit_decomp_cascade_vr(:,:,:)
!   real(r8), pointer :: sminn_to_denit_excess_vr(:,:)
!#endif
   real(r8), pointer :: gross_nmin_vr(:,:)
   real(r8), pointer :: net_nmin_vr(:,:)
   real(r8), pointer :: gross_nmin(:)            ! gross rate of N mineralization (gN/m2/s)
   real(r8), pointer :: net_nmin(:)              ! net rate of N mineralization (gN/m2/s)
   ! For methane code
!#ifdef LCH4
!   real(r8), pointer :: fphr(:,:)                ! fraction of potential SOM + LITTER heterotrophic respiration
!   real(r8), pointer :: w_scalar(:,:)            ! fraction by which decomposition is limited by moisture availability
!#endif
   real(r8), pointer :: decomp_k(:,:,:)                       ! rate constant for decomposition (1./sec)
   real(r8), pointer :: rf_decomp_cascade(:,:,:)              ! respired fraction in decomposition step (frac)
   integer,  pointer :: cascade_donor_pool(:)                 ! which pool is C taken from for a given decomposition step
   integer,  pointer :: cascade_receiver_pool(:)              ! which pool is C added to for a given decomposition step
   real(r8), pointer :: pathfrac_decomp_cascade(:,:,:)        ! what fraction of C leaving a given pool passes through a given transition (frac)
   logical,  pointer :: floating_cn_ratio_decomp_pools(:)     ! TRUE => pool has fixed C:N ratio

!
! local pointers to implicit out scalars
!
! !OTHER LOCAL VARIABLES:
   integer :: c,j,k,l,m          !indices
   integer :: fc           !lake filter column index
   real(r8):: p_decomp_cpool_loss(lbc:ubc,1:nlevdecomp,1:ndecomp_cascade_transitions) !potential C loss from one pool to another
   real(r8):: pmnf_decomp_cascade(lbc:ubc,1:nlevdecomp,1:ndecomp_cascade_transitions) !potential mineral N flux, from one pool to another
   real(r8):: immob(lbc:ubc,1:nlevdecomp)        !potential N immobilization
   real(r8):: ratio        !temporary variable
   real(r8):: dnp          !denitrification proportion
   real(r8):: cn_decomp_pools(lbc:ubc,1:nlevdecomp,1:ndecomp_pools)
   real(r8), pointer :: initial_cn_ratio(:)               ! c:n ratio for initialization of pools
   integer, parameter :: i_atm = 0
   integer, pointer :: altmax_indx(:)                  ! maximum annual depth of thaw
   integer, pointer :: altmax_lastyear_indx(:)         ! prior year maximum annual depth of thaw
! KC 
   integer :: nstep,nsoil0,yr,isoi3
   real(r8) :: dt,tphoto(num_soilp)
   real :: RUNOFF1,RUNOFF2,SH2O(nsoil0)

   ! For methane code
!#ifndef NITRIF_DENITRIF
!   real(r8):: phr_vr(lbc:ubc,1:nlevdecomp)       !potential HR (gC/m3/s)
!#else
   real(r8), pointer :: phr_vr(:,:)              !potential HR (gC/m3/s)
!#endif
   real(r8):: hrsum(lbc:ubc,1:nlevdecomp)        !sum of HR (gC/m2/s)
   integer, pointer:: pfti 
   !EOP
   !-----------------------------------------------------------------------
   
   decomp_cpools_vr              => clm3%g%l%c%ccs%decomp_cpools_vr
   decomp_cascade_hr_vr          => clm3%g%l%c%ccf%decomp_cascade_hr_vr
   decomp_cascade_ctransfer_vr   => clm3%g%l%c%ccf%decomp_cascade_ctransfer_vr
   decomp_npools_vr              => clm3%g%l%c%cns%decomp_npools_vr
   decomp_cascade_ntransfer_vr   => clm3%g%l%c%cnf%decomp_cascade_ntransfer_vr
   decomp_cascade_sminn_flux_vr  => clm3%g%l%c%cnf%decomp_cascade_sminn_flux_vr
   fpi_vr                => clm3%g%l%c%cps%fpi_vr
   potential_immob_vr    => clm3%g%l%c%cnf%potential_immob_vr
   
   decomp_k                        => clm3%g%l%c%ccf%decomp_k
   rf_decomp_cascade               => clm3%g%l%c%cps%rf_decomp_cascade
   cascade_donor_pool              => decomp_cascade_con%cascade_donor_pool
   cascade_receiver_pool           => decomp_cascade_con%cascade_receiver_pool
   pathfrac_decomp_cascade         => clm3%g%l%c%cps%pathfrac_decomp_cascade
   floating_cn_ratio_decomp_pools  => decomp_cascade_con%floating_cn_ratio_decomp_pools
   initial_cn_ratio                => decomp_cascade_con%initial_cn_ratio
   altmax_indx                     => clm3%g%l%c%cps%altmax_indx
   altmax_lastyear_indx            => clm3%g%l%c%cps%altmax_lastyear_indx
   
!#ifndef NITRIF_DENITRIF
!   sminn_to_denit_decomp_cascade_vr   => clm3%g%l%c%cnf%sminn_to_denit_decomp_cascade_vr
!   sminn_to_denit_excess_vr => clm3%g%l%c%cnf%sminn_to_denit_excess_vr
!#else
   phr_vr                   => clm3%g%l%c%ccf%phr_vr
!#endif
   gross_nmin_vr            => clm3%g%l%c%cnf%gross_nmin_vr
   net_nmin_vr              => clm3%g%l%c%cnf%net_nmin_vr
   gross_nmin               => clm3%g%l%c%cnf%gross_nmin
   net_nmin                 => clm3%g%l%c%cnf%net_nmin
   ! For methane code
!#ifdef LCH4
!   fphr               => clm3%g%l%c%cch4%fphr
!   w_scalar           => clm3%g%l%c%ccf%w_scalar
!#endif
   
   rootfr                => clm3%g%l%c%p%pps%rootfr
   clandunit             => clm3%g%l%c%landunit
   itypelun              => clm3%g%l%itype
   
   if (nstep .eq. 1) then
   call init_decompcascade(1, 1)
   end if
   
   call decomp_rate_constants(lbc, ubc, num_soilc, filter_soilc, &
              yr,nsoil0,SH2O,isoi3)
   
   
   ! set initial values for potential C and N fluxes
   p_decomp_cpool_loss(:,:,:) = 0._r8
   pmnf_decomp_cascade(:,:,:) = 0._r8
   
   ! column loop to calculate potential decomp rates and total immobilization
   ! demand.
   
   
!!! calculate c:n ratios of applicable pools
   do l = 1, ndecomp_pools  !ndecomp_pools=7 for now
      if ( floating_cn_ratio_decomp_pools(l) ) then
         do j = 1,nlevdecomp !nlevdecomp=1 for now
            do fc = 1,num_soilc
               c = filter_soilc(fc)
               if ( decomp_npools_vr(c,j,l) .gt. 0._r8 ) then
                  cn_decomp_pools(c,j,l) = decomp_cpools_vr(c,j,l) / decomp_npools_vr(c,j,l)
               end if
            end do
         end do
      else
         do j = 1,nlevdecomp
            do fc = 1,num_soilc
               c = filter_soilc(fc)
               cn_decomp_pools(c,j,l) = initial_cn_ratio(l)
            end do
         end do
      end if
   end do
   
   
   ! calculate the non-nitrogen-limited fluxes
   ! these fluxes include the  "/ dt" term to put them on a
   ! per second basis, since the rate constants have been
   ! calculated on a per timestep basis.
   
   do k = 1, ndecomp_cascade_transitions
      do j = 1,nlevdecomp
         do fc = 1,num_soilc
            c = filter_soilc(fc)
            
            if (decomp_cpools_vr(c,j,cascade_donor_pool(k)) > 0._r8 .and. decomp_k(c,j,cascade_donor_pool(k)) .gt. 0._r8 ) then
               p_decomp_cpool_loss(c,j,k) = decomp_cpools_vr(c,j,cascade_donor_pool(k)) * decomp_k(c,j,cascade_donor_pool(k))  * pathfrac_decomp_cascade(c,j,k)
               
               if ( .not. floating_cn_ratio_decomp_pools(cascade_receiver_pool(k)) ) then  !! not transition of cwd to litter
                  
                  if (cascade_receiver_pool(k) .ne. i_atm ) then  ! not 100% respiration
                     ratio = 0._r8
                     
                     if (decomp_npools_vr(c,j,cascade_donor_pool(k)) > 0._r8) then
                        ratio = cn_decomp_pools(c,j,cascade_receiver_pool(k))/cn_decomp_pools(c,j,cascade_donor_pool(k))
                     endif
                     
                     pmnf_decomp_cascade(c,j,k) = (p_decomp_cpool_loss(c,j,k) * (1.0_r8 - rf_decomp_cascade(c,j,k) - ratio) &
                          / cn_decomp_pools(c,j,cascade_receiver_pool(k)) )
                     
                  else   ! 100% respiration
                     pmnf_decomp_cascade(c,j,k) = - p_decomp_cpool_loss(c,j,k) / cn_decomp_pools(c,j,cascade_donor_pool(k))
                  endif
                  
               else   ! CWD -> litter
                  pmnf_decomp_cascade(c,j,k) = 0._r8
               end if
            end if
         end do
         
      end do
   end do
   
   ! Sum up all the potential immobilization fluxes (positive pmnf flux)
   ! and all the mineralization fluxes (negative pmnf flux)
   do j = 1,nlevdecomp
      do fc = 1,num_soilc
         c = filter_soilc(fc)
         immob(c,j) = 0._r8
      end do
   end do
   do k = 1, ndecomp_cascade_transitions
      do j = 1,nlevdecomp
         do fc = 1,num_soilc
            c = filter_soilc(fc)
            if (pmnf_decomp_cascade(c,j,k) > 0._r8) then
               immob(c,j) = immob(c,j) + pmnf_decomp_cascade(c,j,k)
            else
               gross_nmin_vr(c,j) = gross_nmin_vr(c,j) - pmnf_decomp_cascade(c,j,k)
            end if
         end do
      end do
   end do
   
   do j = 1,nlevdecomp
      do fc = 1,num_soilc
         c = filter_soilc(fc)
         potential_immob_vr(c,j) = immob(c,j)
      end do
   end do
   
   ! Add up potential hr for methane calculations
   do j = 1,nlevdecomp
      do fc = 1,num_soilc
         c = filter_soilc(fc)
         phr_vr(c,j) = 0._r8
      end do
   end do
   do k = 1, ndecomp_cascade_transitions
      do j = 1,nlevdecomp
         do fc = 1,num_soilc
            c = filter_soilc(fc)
            phr_vr(c,j) = phr_vr(c,j) + rf_decomp_cascade(c,j,k) * p_decomp_cpool_loss(c,j,k)
         end do
      end do
   end do
   
   call decomp_vertprofiles(lbp, ubp, lbc,ubc,num_soilc,filter_soilc,num_soilp,filter_soilp)
   
!#ifdef NITRIF_DENITRIF
   ! calculate nitrification and denitrification rates
   call nitrif_denitrif(lbc, ubc, num_soilc, filter_soilc,nsoil0)
!#endif
   
   
   ! now that potential N immobilization is known, call allocation
   ! to resolve the competition between plants and soil heterotrophs
   ! for available soil mineral N resource.
   
   call CNAllocation (lbp, ubp, lbc, ubc, &
       num_soilc, filter_soilc, num_soilp, filter_soilp ,&
       dt,tphoto)

   
   ! column loop to calculate actual immobilization and decomp rates, following
   ! resolution of plant/heterotroph  competition for mineral N
   
   dnp = 0.01_r8
   
   ! calculate c:n ratios of applicable pools
   do l = 1, ndecomp_pools
      if ( floating_cn_ratio_decomp_pools(l) ) then
         do j = 1,nlevdecomp
            do fc = 1,num_soilc
               c = filter_soilc(fc)
               if ( decomp_npools_vr(c,j,l) .gt. 0._r8 ) then
                  cn_decomp_pools(c,j,l) = decomp_cpools_vr(c,j,l) / decomp_npools_vr(c,j,l)
               end if
            end do
         end do
      else
         do j = 1,nlevdecomp
            do fc = 1,num_soilc
               c = filter_soilc(fc)
               cn_decomp_pools(c,j,l) = initial_cn_ratio(l)
            end do
         end do
      end if
   end do
   
   ! upon return from CNAllocation, the fraction of potential immobilization
   ! has been set (cps%fpi_vr). now finish the decomp calculations.
   ! Only the immobilization steps are limited by fpi_vr (pmnf > 0)
   ! Also calculate denitrification losses as a simple proportion
   ! of mineralization flux.
   do k = 1, ndecomp_cascade_transitions
      do j = 1,nlevdecomp
         do fc = 1,num_soilc
            c = filter_soilc(fc)
            
            if (decomp_cpools_vr(c,j,cascade_donor_pool(k)) .gt. 0._r8) then
               if ( pmnf_decomp_cascade(c,j,k) .gt. 0._r8 ) then
                  p_decomp_cpool_loss(c,j,k) = p_decomp_cpool_loss(c,j,k) * fpi_vr(c,j)
                  pmnf_decomp_cascade(c,j,k) = pmnf_decomp_cascade(c,j,k) * fpi_vr(c,j)
!#ifndef NITRIF_DENITRIF
!                  sminn_to_denit_decomp_cascade_vr(c,j,k) = 0._r8
!               else
!                  sminn_to_denit_decomp_cascade_vr(c,j,k) = -dnp * pmnf_decomp_cascade(c,j,k)
!#endif
               end if
               decomp_cascade_hr_vr(c,j,k) = rf_decomp_cascade(c,j,k) * p_decomp_cpool_loss(c,j,k)
               decomp_cascade_ctransfer_vr(c,j,k) = (1._r8 - rf_decomp_cascade(c,j,k)) * p_decomp_cpool_loss(c,j,k)
               if (decomp_npools_vr(c,j,cascade_donor_pool(k)) > 0._r8 .and. cascade_receiver_pool(k) .ne. i_atm) then
                  decomp_cascade_ntransfer_vr(c,j,k) = p_decomp_cpool_loss(c,j,k) / cn_decomp_pools(c,j,cascade_donor_pool(k))
               else
                  decomp_cascade_ntransfer_vr(c,j,k) = 0._r8
               endif
               if ( cascade_receiver_pool(k) .ne. 0 ) then
                  decomp_cascade_sminn_flux_vr(c,j,k) = pmnf_decomp_cascade(c,j,k)
               else  ! keep sign convention negative for terminal pools
                  decomp_cascade_sminn_flux_vr(c,j,k) = - pmnf_decomp_cascade(c,j,k)
               endif
               net_nmin_vr(c,j) = net_nmin_vr(c,j) - pmnf_decomp_cascade(c,j,k)
            else
               decomp_cascade_ntransfer_vr(c,j,k) = 0._r8
!#ifndef NITRIF_DENITRIF
!               sminn_to_denit_decomp_cascade_vr(c,j,k) = 0._r8
!#endif
               decomp_cascade_sminn_flux_vr(c,j,k) = 0._r8
            end if
            
         end do
      end do
   end do
!#ifdef LCH4
   ! Calculate total fraction of potential HR, for methane code
!   do j = 1,nlevdecomp
!      do fc = 1,num_soilc
!         c = filter_soilc(fc)
!         hrsum(c,j) = 0._r8
!      end do
!   end do
!   do k = 1, ndecomp_cascade_transitions
!      do j = 1,nlevdecomp
!         do fc = 1,num_soilc
!            c = filter_soilc(fc)
!            hrsum(c,j) = hrsum(c,j) + rf_decomp_cascade(c,j,k) * p_decomp_cpool_loss(c,j,k)
!         end do
!      end do
!   end do
   
   ! Nitrogen limitation / (low)-moisture limitation
!   do j = 1,nlevdecomp
!      do fc = 1,num_soilc
!         c = filter_soilc(fc)
!         if (phr_vr(c,j) > 0._r8) then
!            fphr(c,j) = hrsum(c,j) / phr_vr(c,j) * w_scalar(c,j)
!            fphr(c,j) = max(fphr(c,j), 0.01_r8) ! Prevent overflow errors for 0 respiration
!         else
!            fphr(c,j) = 1._r8
!         end if
!      end do
!   end do
!#endif
   
   ! vertically integrate net and gross mineralization fluxes for diagnostic output
   do j = 1,nlevdecomp
      do fc = 1,num_soilc
         c = filter_soilc(fc)
         net_nmin(c) = net_nmin(c) + net_nmin_vr(c,j) * dzsoi_decomp(j)
         gross_nmin(c) = gross_nmin(c) + gross_nmin_vr(c,j) * dzsoi_decomp(j)   
      end do
   end do
  
 
 end subroutine CNDecompAlloc
 
 
!#endif
 
end module cndecompmod_ACASA


module accumulmod_ACASA

!-----------------------------------------------------------------------
!BOP
!
! !MODULE: accumulmod_ACASA
!
! !DESCRIPTION:
! This module contains generic subroutines that can be used to
! define, accumulate and extract  user-specified fields over
! user-defined intervals. Each interval  and accumulation type is
! unique to each field processed.
! Subroutine [init_accumulator] defines the values of the accumulated
! field data structure. Subroutine [update_accum_field] does
! the actual accumulation for a given field.
! Four types of accumulations are possible:
! - Average over time interval. Time average fields are only
!   valid at the end of the averaging interval.
! - Running mean over time interval. Running means are valid once the
!   length of the simulation exceeds the
! - Running accumulation over time interval. Accumulated fields are
!   continuously accumulated. The trigger value "-99999." resets
!   the accumulation to zero.
!
! !USES:
  use shr_kind_mod, only: r8 => shr_kind_r8
  use clm_varpar45  , only: maxpatch
  use abortutils  , only: endrun
!
! !PUBLIC TYPES:
  implicit none
  save
!
! !PUBLIC MEMBER FUNCTIONS:
  public :: init_accum_field     ! Initialize an accumulator field
  public :: accum_dealloc
  public :: extract_accum_field  ! Extracts the current value of an accumulator field
  interface extract_accum_field
     module procedure extract_accum_field_sl ! Extract current val of single-level accumulator field
     module procedure extract_accum_field_ml ! Extract current val of multi-level accumulator field
  end interface
  public :: update_accum_field
  interface update_accum_field               ! Updates the current value of an accumulator field
     module procedure update_accum_field_sl  ! Update single-level accumulator field
     module procedure update_accum_field_ml  ! Update multi-level accumulator field
  end interface
!
! !REVISION HISTORY:
! Created by Sam Levis
! Updated to clm2.1 data structures by Mariana Vertenstein
! Updated to include all subgrid type and multilevel fields, M. Vertenstein 03/2003
!
!EOP
!
  private
!
! PRIVATE TYPES:
!
  type accum_field
     character(len=  8) :: name     !field name
     character(len=128) :: desc     !field description
     character(len=  8) :: units    !field units
     character(len=  8) :: acctype  !accumulation type: ["timeavg","runmean","runaccum"]
     character(len=  8) :: type1d   !subgrid type: ["gridcell","landunit","column" or "pft"]
     character(len=  8) :: type2d   !type2d ('','levsoi','numrad',..etc. )
     integer :: beg1d               !subgrid type beginning index
     integer :: end1d               !subgrid type ending index
     integer :: num1d               !total subgrid points
     integer :: numlev              !number of vertical levels in field
     real(r8):: initval             !initial value of accumulated field
!    real(r8), pointer :: val(:,:)  !accumulated field
     real(r8), allocatable :: val(:,:)  !accumulated field
     integer :: period              !field accumulation period (in model time steps)
  end type accum_field


  integer, parameter :: max_accum = 100    !maximum number of accumulated fields
  type (accum_field) :: accum(max_accum)   !array accumulated fields
  integer :: naccflds = 0 
!------------------------------------------------------------------------

contains

!------------------------------------------------------------------------
!BOP
!
! !IROUTINE: init_accum_field
!
! !INTERFACE:
  subroutine init_accum_field (name, units, desc, &
       accum_type, accum_period, numlev, subgrid_type, init_value,dtime,&
       begg, endg, begl, endl, begc, endc, begp, endp)


!
! !DESCRIPTION:
! Initialize accumulation fields. This subroutine sets:
! o name  of accumulated field
! o units of accumulated field
! o accumulation type of accumulated field
! o description of accumulated fields: accdes
! o accumulation period for accumulated field (in iterations)
! o initial value of accumulated field
!
! !USES:
!    use clm_varcon45,    only : cday
!    use globals_ACASA,       only : dtime
!    use decompmod_ACASA,     only : get_proc_bounds
!
! !ARGUMENTS:
    implicit none
    character(len=*), intent(in) :: name           !field name
    character(len=*), intent(in) :: units          !field units
    character(len=*), intent(in) :: desc           !field description
    character(len=*), intent(in) :: accum_type     !field type: tavg, runm, runa, ins
    integer , intent(in) :: accum_period           !field accumulation period
    character(len=*), intent(in)   :: subgrid_type !["gridcell","landunit","column" or "pft"]
    integer , intent(in) :: numlev                 !number of vertical levels
    real(r8), intent(in) :: init_value             !field initial or reset value
!    character(len=*), intent(in), optional :: type2d !level type (optional) - needed if numlev > 1
    real(r8) :: dtime
!
! !REVISION HISTORY:
! Created by Mariana Vertenstein 03/2003
!
!EOP
!
! LOCAL VARIABLES:
    integer :: nf           ! field index
    integer :: beg1d,end1d  ! beggining and end subgrid indices
    integer :: num1d        ! total number subgrid indices
    integer :: begp, endp   ! per-proc beginning and ending pft indices
    integer :: begc, endc   ! per-proc beginning and ending column indices
    integer :: begl, endl   ! per-proc beginning and ending landunit indices
    integer :: begg, endg   ! per-proc gridcell ending gridcell indices
    real(r8) :: cday
!------------------------------------------------------------------------

    ! Determine necessary indices

!    call get_proc_bounds(begg, endg, begl, endl, begc, endc, begp, endp)
!    begg=1
!    endg=1
!    begl=1
!    endl=1
!    begc=1
!    endc=1
!    begp=1
!    endp=1
    cday = 86400.0_r8
! IMPORTANT
! dtime is fixed at 1800
!    dtime = 1800.0_r8
    ! update field index
    ! Consistency check that number of accumulated does not exceed maximum.

! this needs to be changed

    naccflds = naccflds + 1


    if (naccflds > max_accum) then
!       write (6,*) 'INIT_ACCUM_FIELD error: user-defined accumulation fields ', &
!            'equal to ',naccflds,' exceeds max_accum'
       call endrun
    end if
    nf = naccflds

    ! Note accumulation period must be converted from days
    ! to number of iterations

    accum(nf)%name = trim(name)
    accum(nf)%units = trim(units)
    accum(nf)%desc = trim(desc)
    accum(nf)%acctype = trim(accum_type)
    accum(nf)%initval = init_value
    accum(nf)%period = accum_period
    if (accum(nf)%period < 0) then
       accum(nf)%period = -accum(nf)%period * nint(cday) / dtime
    end if

    select case (trim(subgrid_type))
    case ('gridcell')
       beg1d = begg
       end1d = endg
       num1d = endg - begg + 1
    case ('landunit')
       beg1d = begl
       end1d = endl
       num1d = endl - begl + 1
    case ('column')
       beg1d = begc
       end1d = endc
       num1d = endc - begc + 1
    case ('pft')
       beg1d = begp
       end1d = endp
       num1d = endp - begp + 1
    case default
!       write(6,*)'INIT_ACCUM_FIELD: unknown subgrid type ',subgrid_type
       call endrun ()
    end select

    accum(nf)%type1d = trim(subgrid_type)
    accum(nf)%beg1d = beg1d
    accum(nf)%end1d = end1d
    accum(nf)%num1d = num1d
    accum(nf)%numlev = numlev

!    if (present(type2d)) then
!       accum(nf)%type2d = type2d
!    else
!       accum(nf)%type2d = ' '
!    end if

    ! Allocate and initialize accumulation field

! Here numlev is always equal to 1 
    allocate(accum(nf)%val(beg1d:end1d,numlev))
    accum(nf)%val(beg1d:end1d,1) = init_value

  end subroutine init_accum_field

!------------------------------------------------------------------------
!BOP
!
! !IROUTINE: extract_accum_field_sl
!
! !INTERFACE:
  subroutine extract_accum_field_sl (name, field, nstep)
!
! !DESCRIPTION:
! Extract single-level accumulated field.
! This routine extracts the field values from the multi-level
! accumulation field. It extracts the current value except if
! the field type is a time average. In this case, an absurd value
! is assigned to  indicate the time average is not yet valid.
!
! !USES:
    use clm_varcon45, only : spval
!
! !ARGUMENTS:
    implicit none
    character(len=*), intent(in) :: name     !field name
    real(r8), pointer, dimension(:) :: field !field values for current time step
    integer , intent(in) :: nstep            !timestep index
!
! !REVISION HISTORY:
! Created by Sam Levis
! Updated to clm2.1 data structures by Mariana Vertenstein
! Updated to include all subgrid type and multilevel fields, Mariana Vertenstein 03-2003
!
!EOP
!
! LOCAL VARIABLES:
    integer :: i,k,nf        !indices
    integer :: beg,end         !subgrid beginning,ending indices
!------------------------------------------------------------------------

    ! find field index. return if "name" is not on list

    nf = 0
!dir$ concurrent
!cdir nodep
    do i = 1, naccflds
       if (name == accum(i)%name) nf = i
    end do
    if (nf == 0) then
!       write(6,*) 'EXTRACT_ACCUM_FIELD_SL error: field name ',name,' not found'
       call endrun
    endif

    ! error check

    beg = accum(nf)%beg1d
    end = accum(nf)%end1d
    if (size(field,dim=1) /= end-beg+1) then
!       write(6,*)'ERROR in extract_accum_field for field ',accum(nf)%name
!       write(6,*)'size of first dimension of field is ',&
!            size(field,dim=1),' and should be ',end-beg+1
       call endrun
    endif

    ! extract field

    if (accum(nf)%acctype == 'timeavg' .and. &
         mod(nstep,accum(nf)%period) /= 0) then
!dir$ concurrent
!cdir nodep
       do k = beg,end
          field(k) = spval  !assign absurd value when avg not ready
       end do
    else
!dir$ concurrent
!cdir nodep
       do k = beg,end
          field(k) = accum(nf)%val(k,1)
       end do
    end if

  end subroutine extract_accum_field_sl

!------------------------------------------------------------------------
!BOP
!
! !IROUTINE: extract_accum_field_ml
!
! !INTERFACE:
  subroutine extract_accum_field_ml (name, field, nstep)
!
! !DESCRIPTION:
! Extract mutli-level accumulated field.
! This routine extracts the field values from the multi-level
! accumulation field. It extracts the current value except if
! the field type is a time average. In this case, an absurd value
! is assigned to  indicate the time average is not yet valid.
!
! !USES:
    use clm_varcon45, only : spval
!
! !ARGUMENTS:
    implicit none
    character(len=*), intent(in) :: name       !field name
    real(r8), pointer, dimension(:,:) :: field !field values for current time step
    integer, intent(in) :: nstep               !timestep index
!
! !REVISION HISTORY:
! Created by Sam Levis
! Updated to clm2.1 data structures by Mariana Vertenstein
! Updated to include all subgrid type and multilevel fields, M. Vertenstein 03/2003
!
!EOP
!
! LOCAL VARIABLES:
    integer :: i,j,k,nf        !indices
    integer :: beg,end         !subgrid beginning,ending indices
    integer :: numlev          !number of vertical levels
!------------------------------------------------------------------------

    ! find field index. return if "name" is not on list

    nf = 0
    do i = 1, naccflds
       if (name == accum(i)%name) nf = i
    end do
    if (nf == 0) then
!       write(6,*) 'EXTRACT_ACCUM_FIELD_ML error: field name ',name,' not found'
       call endrun
    endif

    ! error check

    numlev = accum(nf)%numlev
    beg = accum(nf)%beg1d
    end = accum(nf)%end1d
    if (size(field,dim=1) /= end-beg+1) then
!       write(6,*)'ERROR in extract_accum_field for field ',accum(nf)%name
!       write(6,*)'size of first dimension of field is ',&
!            size(field,dim=1),' and should be ',end-beg+1
       call endrun
    else if (size(field,dim=2) /= numlev) then
!       write(6,*)'ERROR in extract_accum_field for field ',accum(nf)%name
!       write(6,*)'size of second dimension of field iis ',&
!            size(field,dim=2),' and should be ',numlev
       call endrun
    endif

    !extract field

    if (accum(nf)%acctype == 'timeavg' .and. &
         mod(nstep,accum(nf)%period) /= 0) then
       do j = 1,numlev
!dir$ concurrent
!cdir nodep
          do k = beg,end
             field(k,j) = spval  !assign absurd value when avg not ready
          end do
       end do
    else
       do j = 1,numlev
!dir$ concurrent
!cdir nodep
          do k = beg,end
             field(k,j) = accum(nf)%val(k,j)
          end do
       end do
    end if

  end subroutine extract_accum_field_ml

!------------------------------------------------------------------------
!BOP
!
! !IROUTINE: update_accum_field_sl
!
! !INTERFACE:
  subroutine update_accum_field_sl (name, field, nstep)
!
! !DESCRIPTION:
! Accumulate single level field over specified time interval.
! The appropriate field is accumulated in the array [accval].
!
! !ARGUMENTS:
    implicit none
    character(len=*), intent(in) :: name     !field name
    real(r8), pointer, dimension(:) :: field !field values for current time step
    integer , intent(in) :: nstep            !time step index
!
! !REVISION HISTORY:
! Created by Sam Levis
! Updated to clm2.1 data structures by Mariana Vertenstein
! Updated to include all subgrid type and multilevel fields by M. Vertenstein 03/2003
!
!EOP
!
! LOCAL VARIABLES:
    integer :: i,k,nf              !indices
    integer :: accper              !temporary accumulation period
    integer :: beg,end             !subgrid beginning,ending indices
!------------------------------------------------------------------------

    ! find field index. return if "name" is not on list

    nf = 0
    do i = 1, naccflds
       if (name == accum(i)%name) nf = i
    end do
    if (nf == 0) then
!       write(6,*) 'UPDATE_ACCUM_FIELD_SL error: field name ',name,' not found'
       call endrun
    endif

    ! error check

    beg = accum(nf)%beg1d
    end = accum(nf)%end1d
    if (size(field,dim=1) /= end-beg+1) then
!       write(6,*)'ERROR in UPDATE_ACCUM_FIELD_SL for field ',accum(nf)%name
!       write(6,*)'size of first dimension of field is ',size(field,dim=1),&
!            ' and should be ',end-beg+1
       call endrun
    endif

    ! accumulate field

    if (accum(nf)%acctype /= 'timeavg' .AND. &
        accum(nf)%acctype /= 'runmean' .AND. &
        accum(nf)%acctype /= 'runaccum') then
!       write(6,*) 'UPDATE_ACCUM_FIELD_SL error: incorrect accumulation type'
!       write(6,*) ' was specified for field ',name
!       write(6,*)' accumulation type specified is ',accum(nf)%acctype
!       write(6,*)' only [timeavg, runmean, runaccum] are currently acceptable'
       call endrun()
    end if


    ! reset accumulated field value if necessary and  update
    ! accumulation field
    ! running mean never reset

    if (accum(nf)%acctype == 'timeavg') then

       !time average field reset every accumulation period
       !normalize at end of accumulation period

       if ((mod(nstep,accum(nf)%period) == 1) .and. (nstep /= 0)) then
          accum(nf)%val(beg:end,1) = 0._r8
       end if
       accum(nf)%val(beg:end,1) =  accum(nf)%val(beg:end,1) + field(beg:end)
       if (mod(nstep,accum(nf)%period) == 0) then
          accum(nf)%val(beg:end,1) = accum(nf)%val(beg:end,1) / accum(nf)%period
       endif

    else if (accum(nf)%acctype == 'runmean') then

       !running mean - reset accumulation period until greater than nstep

       accper = min (nstep,accum(nf)%period)
       accum(nf)%val(beg:end,1) = ((accper-1)*accum(nf)%val(beg:end,1) + field(beg:end)) / accper

    else if (accum(nf)%acctype == 'runaccum') then

       !running accumulation field reset at trigger -99999

!dir$ concurrent
!cdir nodep
       do k = beg,end
          if (nint(field(k)) == -99999) then
             accum(nf)%val(k,1) = 0._r8
          end if
       end do
       accum(nf)%val(beg:end,1) = min(max(accum(nf)%val(beg:end,1) + field(beg:end), 0._r8), 99999._r8)

    end if

  end subroutine update_accum_field_sl

!------------------------------------------------------------------------
!BOP
!
! !IROUTINE: update_accum_field_ml
!
! !INTERFACE:
  subroutine update_accum_field_ml (name, field, nstep)
!
! !DESCRIPTION:
! Accumulate multi level field over specified time interval.
!
! !ARGUMENTS:
    implicit none
    character(len=*), intent(in) :: name       !field name
    real(r8), pointer, dimension(:,:) :: field !field values for current time step
    integer , intent(in) :: nstep              !time step index
!
! !REVISION HISTORY:
! Created by Sam Levis
! Updated to clm2.1 data structures by Mariana Vertenstein
! Updated to include all subgrid type and multilevel fields by M. Vertenstein 03/2003
!
!EOP
!
! LOCAL VARIABLES:
    integer :: i,j,k,nf            !indices
    integer :: accper              !temporary accumulation period
    integer :: beg,end             !subgrid beginning,ending indices
    integer :: numlev              !number of vertical levels
!------------------------------------------------------------------------

    ! find field index. return if "name" is not on list

    nf = 0
    do i = 1, naccflds
       if (name == accum(i)%name) nf = i
    end do
    if (nf == 0) then
!       write(6,*) 'UPDATE_ACCUM_FIELD_ML error: field name ',name,' not found'
       call endrun
    endif

    ! error check

    numlev = accum(nf)%numlev
    beg = accum(nf)%beg1d
    end = accum(nf)%end1d
    if (size(field,dim=1) /= end-beg+1) then
!       write(6,*)'ERROR in UPDATE_ACCUM_FIELD_ML for field ',accum(nf)%name
!       write(6,*)'size of first dimension of field is ',size(field,dim=1),&
!            ' and should be ',end-beg+1
       call endrun
    else if (size(field,dim=2) /= numlev) then
!       write(6,*)'ERROR in UPDATE_ACCUM_FIELD_ML for field ',accum(nf)%name
!       write(6,*)'size of second dimension of field is ',size(field,dim=2),&
!            ' and should be ',numlev
       call endrun
    endif

    ! accumulate field

    if (accum(nf)%acctype /= 'timeavg' .AND. &
        accum(nf)%acctype /= 'runmean' .AND. &
        accum(nf)%acctype /= 'runaccum') then
!       write(6,*) 'UPDATE_ACCUM_FIELD_ML error: incorrect accumulation type'
!       write(6,*) ' was specified for field ',name
!       write(6,*)' accumulation type specified is ',accum(nf)%acctype
!       write(6,*)' only [timeavg, runmean, runaccum] are currently acceptable'
       call endrun()
    end if

    ! accumulate field

    ! reset accumulated field value if necessary and  update
    ! accumulation field
    ! running mean never reset

    if (accum(nf)%acctype == 'timeavg') then

       !time average field reset every accumulation period
       !normalize at end of accumulation period

       if ((mod(nstep,accum(nf)%period) == 1) .and. (nstep /= 0)) then
          accum(nf)%val(beg:end,1:numlev) = 0._r8
       endif
       accum(nf)%val(beg:end,1:numlev) =  accum(nf)%val(beg:end,1:numlev) + field(beg:end,1:numlev)
       if (mod(nstep,accum(nf)%period) == 0) then
          accum(nf)%val(beg:end,1:numlev) = accum(nf)%val(beg:end,1:numlev) / accum(nf)%period
       endif

    else if (accum(nf)%acctype == 'runmean') then

       !running mean - reset accumulation period until greater than nstep

       accper = min (nstep,accum(nf)%period)
       accum(nf)%val(beg:end,1:numlev) = &
            ((accper-1)*accum(nf)%val(beg:end,1:numlev) + field(beg:end,1:numlev)) / accper

    else if (accum(nf)%acctype == 'runaccum') then

       !running accumulation field reset at trigger -99999

       do j = 1,numlev
!dir$ concurrent
!cdir nodep
          do k = beg,end
             if (nint(field(k,j)) == -99999) then
                accum(nf)%val(k,j) = 0._r8
             end if
          end do
       end do
       accum(nf)%val(beg:end,1:numlev) = &
            min(max(accum(nf)%val(beg:end,1:numlev) + field(beg:end,1:numlev), 0._r8), 99999._r8)

    end if

  end subroutine update_accum_field_ml

!-----------------------------------------------------------------------
!BOP
!
! !IROUTINE: accum_dealloc
!
! !INTERFACE:
  subroutine accum_dealloc
!
! !DESCRIPTION:
! Deallocate dynamic memory for module variables
!
! !ARGUMENTS:
    implicit none
    integer :: i
!EOP
!-----------------------------------------------------------------------

    do i = 1,naccflds
      if (allocated (accum(i)%val))deallocate (accum(i)%val) 
    end do
    naccflds = 0
!      deallocate (accum(:)%val)
  end subroutine accum_dealloc


end module accumulmod_ACASA
module accfldsmod_ACASA

!-----------------------------------------------------------------------
!BOP
!
! !MODULE: accfldsmod_ACASA
!
! !DESCRIPTION:
! This module contains subroutines that initialize, update and extract
! the user-specified fields over user-defined intervals. Each interval
! and accumulation type is unique to each field processed.
! Subroutine [initAccumFlds] defines the fields to be processed
! and the type of accumulation. Subroutine [updateAccumFlds] does
! the actual accumulation for a given field. Fields are accumulated
! by calls to subroutine [update_accum_field]. To accumulate a field,
! it must first be defined in subroutine [initAccumFlds] and then
! accumulated by calls to [updateAccumFlds].
! Four types of accumulations are possible:
!   o average over time interval
!   o running mean over time interval
!   o running accumulation over time interval
! Time average fields are only valid at the end of the averaging interval.
! Running means are valid once the length of the simulation exceeds the
! averaging interval. Accumulated fields are continuously accumulated.
! The trigger value "-99999." resets the accumulation to zero.
!
! !USES:
  use shr_kind_mod, only: r8 => shr_kind_r8
  use abortutils, only: endrun
!
! !PUBLIC TYPES:
  implicit none
  save
!
! !PUBLIC MEMBER FUNCTIONS:
  public :: initAccFlds     ! Initialization accumulator fields
  public :: initAccClmtype  ! Initialize clmtype45 variables obtained from accum fields
  public :: updateAccFlds   ! Update accumulator fields
!
! !REVISION HISTORY:
! Created by M. Vertenstein 03/2003
!
!EOP

contains

!------------------------------------------------------------------------
!BOP
!
! !IROUTINE: initAccFlds()
!
! !INTERFACE:
!#if (defined CNDV)
!  subroutine initAccFlds(t_ref2m  ,tda   ,t10    ,fnpsn10   ,prec365,&
!                         agdd0    ,agdd5 ,agddtw ,agdd)
!#else
  subroutine initAccFlds(dtime,nstep)
!#endif
!
! !DESCRIPTION:
! Initializes accumulator and sets up array of accumulated fields
!
! !USES:
    use decompmod_ACASA    , only : get_proc_bounds
    use accumulmod_ACASA   , only : init_accum_field
!    use globals_ACASA      , only : dtime, nstep
!    use clm_varcon45   , only : cday, tfrz
    use nanmod_ACASA       , only : bigint
    use clm_varpar45   , only : maxpatch
!    use shr_const_mod_ACASA, only : SHR_CONST_TKFRZ

!
! !ARGUMENTS:
    implicit none
!
! !REVISION HISTORY::
! Created by M. Vertenstein 03/2003
!
! LOCAL VARIABLES:
!
    integer :: nstep
    real(r8) :: dtime,cday,tfrz
    integer, parameter :: not_used = bigint
!KC
    integer :: begg, endg, begl, endl, begc, endc, begp, endp
!KC end
!------------------------------------------------------------------------
   cday   = 86400.0_r8
   tfrz   = 273.16_r8
   call get_proc_bounds(begg, endg, begl, endl, begc, endc, begp, endp)
   call init_accum_field('TREFAV', 'K', &
         'average over an hour of 2-m temperature', &
         'timeavg', nint(3600._r8/dtime), &
         1,'pft', 0._r8,dtime,begg, endg, begl, endl, begc, endc, begp, endp)

    ! Hourly average of Urban 2m temperature.

    call init_accum_field('TREFAV_U', 'K', &
         'average over an hour of urban 2-m temperature', &
         'timeavg', nint(3600._r8/dtime), &
         1,'pft', 0._r8,dtime,begg, endg, begl, endl, begc, endc, begp, endp)

    ! Hourly average of Rural 2m temperature.

    call init_accum_field('TREFAV_R', 'K', &
         'average over an hour of rural 2-m temperature', &
         'timeavg', nint(3600._r8/dtime), &
         1,'pft', 0._r8,dtime,begg, endg, begl, endl, begc, endc, begp, endp)

    ! 24hr average of vegetation temperature (heald, 04/06)
    call init_accum_field ('T_VEG24', 'K', &
         '24hr average of vegetation temperature', &
         'runmean', -1, &
         1,'pft', 0._r8,dtime,begg, endg, begl, endl, begc, endc, begp, endp)

    ! 240hr average of vegetation temperature (heald, 04/06)
    call init_accum_field ('T_VEG240', 'K', &
         '240hr average of vegetation temperature', &
         'runmean', -10, &
         1,'pft', 0._r8,dtime,begg, endg, begl, endl, begc, endc, begp, endp)

    ! 24hr average of direct solar radiation (heald, 04/06)
    call init_accum_field ('FSD24', 'W/m2', &
         '24hr average of direct solar radiation', &
         'runmean', -1, &
         1,'pft', 0._r8,dtime,begg, endg, begl, endl, begc, endc, begp, endp)

    ! 240hr average of direct solar radiation (heald, 04/06)
    call init_accum_field ('FSD240', 'W/m2', &
         '240hr average of direct solar radiation', &
         'runmean', -10, &
         1,'pft', 0._r8,dtime,begg, endg, begl, endl, begc, endc, begp, endp)

    ! 24hr average of diffuse solar radiation (heald, 04/06)
    call init_accum_field ('FSI24', 'W/m2', &
         '24hr average of diffuse solar radiation', &
         'runmean', -1, &
         1,'pft',0._r8,dtime,begg, endg, begl, endl, begc, endc, begp, endp)

    ! 240hr average of diffuse solar radiation (heald, 04/06)
    call init_accum_field ('FSI240', 'W/m2', &
         '240hr average of diffuse solar radiation', &
         'runmean', -10, &
         1,'pft',0._r8,dtime,begg, endg, begl, endl, begc, endc, begp, endp)

    ! 24hr average of fraction of canopy that is sunlit (heald, 04/06)
    call init_accum_field ('FSUN24','fraction', &
         '24hr average of diffuse solar radiation', &
         'runmean', -1, &
         1,'pft', 0._r8,dtime,begg, endg, begl, endl, begc, endc, begp, endp)

    ! 240hr average of fraction of canopy that is sunlit (heald, 04/06)
    call init_accum_field ('FSUN240', 'fraction', &
         '240hr average of diffuse solar radiation', &
         'runmean', -10, &
         1,'pft',0._r8,dtime,begg, endg, begl, endl, begc, endc, begp, endp)

    ! Average of LAI from previous and current timestep (heald, 04/06)
    call init_accum_field ('LAIP', 'm2/m2', &
         'leaf area index average over timestep', &
         'runmean', 1, &
         1,'pft',0._r8,dtime,begg, endg, begl, endl, begc, endc, begp, endp)

! KC, IMPORTANT, disable for now
!#if (defined CNDV)
    ! 30-day average of 2m temperature.

    call init_accum_field ('TDA', 'K', &
         '30-day average of 2-m temperature', &
         'timeavg', -30, 1,&
         'pft', 0._r8,dtime,begg, endg, begl, endl, begc, endc, begp, endp)

    ! The following are running means.
    ! The accumulation period is set to 10 days for a 10-day running mean.
    call init_accum_field ('T10', 'K', &
         '10-day running mean of 2-m temperature', &
         'runmean', -10, 1,&
         'pft',273.15_r8+20._r8,dtime,begg, endg, begl, endl, begc, endc, begp, endp)

    call init_accum_field ('PREC365', 'MM H2O/S', &
         '365-day running mean of total precipitation', &
         'runmean', -365, 1,&
         'pft', 0._r8,dtime,begg, endg, begl, endl, begc, endc, begp, endp)
!
    ! The following are accumulated fields.
    ! These types of fields are accumulated until a trigger value resets
    ! the accumulation to zero (see subroutine update_accum_field).
    ! Hence, [accper] is not valid.

    call init_accum_field ('AGDDTW', 'K', &
         'growing degree-days base twmax', &
         'runaccum', not_used, 1,&
         'pft', 0._r8,dtime,begg, endg, begl, endl, begc, endc, begp, endp)

    call init_accum_field ('AGDD', 'K', &
         'growing degree-days base 5C', &
         'runaccum', not_used, 1, &
         'pft', 0._r8,dtime,begg, endg, begl, endl, begc, endc, begp, endp)
!#endif
      call init_accum_field ('PREC60', 'MM H2O/S', &
         '60-day running mean of total precipitation', &
         'runmean', -60, 1,&
         'pft', 0._r8,dtime,begg, endg, begl, endl, begc, endc, begp, endp)

         call init_accum_field ('PREC10', 'MM H2O/S', &
         '10-day running mean of total precipitation', &
         'runmean', -10, 1,&
         'pft', 0._r8,dtime,begg, endg, begl, endl, begc, endc, begp, endp)
!#if (defined CROP)
    ! 10-day average of min 2m temperature.

!    call init_accum_field (name='TDM10', units='K', &
!         desc='10-day running mean of min 2-m temperature', &
!         accum_type='runmean', accum_period=-10, &
!         subgrid_type='pft', numlev=1, init_value=SHR_CONST_TKFRZ)

    ! 5-day average of min 2m temperature.

!    call init_accum_field (name='TDM5', units='K', &
!         desc='5-day running mean of min 2-m temperature', &
!         accum_type='runmean', accum_period=-5, &
!         subgrid_type='pft', numlev=1, init_value=SHR_CONST_TKFRZ)

    ! All GDD summations are relative to the planting date
    ! (Kucharik & Brye 2003)

!    call init_accum_field (name='GDD0', units='K', &
!         desc='growing degree-days base 0C from planting', &
!         accum_type='runaccum', accum_period=not_used, &
!         subgrid_type='pft', numlev=1, init_value=0._r8)

!    call init_accum_field (name='GDD8', units='K', &
!         desc='growing degree-days base 8C from planting', &
!         accum_type='runaccum', accum_period=not_used, &
!         subgrid_type='pft', numlev=1, init_value=0._r8)

!    call init_accum_field (name='GDD10', units='K', &
!         desc='growing degree-days base 10C from planting', &
!         accum_type='runaccum', accum_period=not_used,  &
!         subgrid_type='pft', numlev=1, init_value=0._r8)
!
!    call init_accum_field (name='GDDPLANT', units='K', &
!         desc='growing degree-days from planting', &
!         accum_type='runaccum', accum_period=not_used,  &
!         subgrid_type='pft', numlev=1, init_value=0._r8)
!    
!    call init_accum_field (name='GDDTSOI', units='K', &
!         desc='growing degree-days from planting (top two soil layers)', &
!         accum_type='runaccum', accum_period=not_used,  &
!         subgrid_type='pft', numlev=1, init_value=0._r8)
!#endif

    ! Print output of accumulated fields

!    call print_accum_fields()

  end subroutine initAccFlds

!------------------------------------------------------------------------
!BOP
!
! !IROUTINE: updateAccFlds
!
! !INTERFACE:
  subroutine updateAccFlds(yr,dtime,nstep,latdeg,T2ACASA,&
               forc_solad,forc_solai,fsun_clm,xlai7,t2o6,prc33,prc34, &
               kmo,kda,mcsec,begg, endg, begl, endl, begc, endc, begp, endp,t_veg_clm)
!
! !DESCRIPTION:
! Update and/or extract accumulated fields
!
! !USES:
    use clmtype45
!    use decompmod_ACASA    , only : get_proc_bounds
    use clm_varcon45   , only : spval
!    use shr_const_mod_ACASA, only : SHR_CONST_CDAY, SHR_CONST_TKFRZ
    use pftvarcon45    , only : ndllf_dcd_brl_tree 
!    use globals_ACASA      , only : dtime, nstep, secs,day,dayp1,month
    use accumulmod_ACASA   , only : update_accum_field, extract_accum_field
!#if (defined CROP)
!    use pftvarcon45    , only : nwwheat, mxtmp, baset
!    use clm_time_manager , only : get_start_date
!#endif
  use filtermod_ACASA           , only : filter
!
! !ARGUMENTS:
    implicit none
!
! !REVISION HISTORY:
! Created by M. Vertenstein 03/2003
!
! !LOCAL VARIABLES:
!
! local pointers to implicit in arguments
!
    integer , pointer :: itype(:)            ! pft vegetation
    integer , pointer :: pgridcell(:)        ! index into gridcell level quantities
!    real(r8), pointer :: forc_t(:)           ! atmospheric temperature (Kelvin)
!    real(r8), pointer :: forc_rain(:)        ! rain rate [mm/s]
!    real(r8), pointer :: forc_snow(:)        ! snow rate [mm/s]
    real(r8), pointer :: t_ref2m(:)          ! 2 m height surface air temperature (Kelvin)
    real(r8), pointer :: t_ref2m_u(:)        ! Urban 2 m height surface air temperature (Kelvin)
    real(r8), pointer :: t_ref2m_r(:)        ! Rural 2 m height surface air temperature (Kelvin)
    logical , pointer :: urbpoi(:)           ! true => landunit is an urban point
   logical , pointer :: ifspecial(:)        ! true => landunit is not vegetated
    integer , pointer :: plandunit(:)        ! landunit index associated with each pft
!#if (defined CROP)
!    real(r8), pointer :: vf(:)
!    real(r8), pointer :: t_soisno(:,:)
!    real(r8), pointer :: h2osoi_liq(:,:)
!    real(r8), pointer :: watsat(:,:)
!    real(r8), pointer :: dz(:,:)
!    real(r8), pointer :: latdeg(:)           ! latitude (radians)
!    integer , pointer :: croplive(:)
!    integer , pointer :: pcolumn(:)          ! index into column level quantities
!#endif


!
! local pointers to implicit out arguments
!
    ! heald (04/06): variables to be accumulated for VOC emissions
    real(r8), pointer :: t_veg(:)            ! pft vegetation temperature (Kelvin) 
!    real(r8), pointer :: forc_solad(:,:)     ! direct beam radiation (visible only)
!    real(r8), pointer :: forc_solai(:,:)     ! diffuse radiation     (visible only)
    real(r8), pointer :: fsun(:)             ! sunlit fraction of canopy 
    real(r8), pointer :: elai(:)             ! one-sided leaf area index with burying by snow 
    ! heald (04/06): accumulated variables for VOC emissions
    real(r8), pointer :: t_veg24(:)          ! 24hr average vegetation temperature (K)
    real(r8), pointer :: t_veg240(:)         ! 240hr average vegetation temperature (Kelvin)
    real(r8), pointer :: fsd24(:)            ! 24hr average of direct beam radiation 
    real(r8), pointer :: fsd240(:)           ! 240hr average of direct beam radiation 
    real(r8), pointer :: fsi24(:)            ! 24hr average of diffuse beam radiation 
    real(r8), pointer :: fsi240(:)           ! 240hr average of diffuse beam radiation 
    real(r8), pointer :: fsun24(:)           ! 24hr average of sunlit fraction of canopy 
    real(r8), pointer :: fsun240(:)          ! 240hr average of sunlit fraction of canopy
    real(r8), pointer :: elai_p(:)           ! leaf area index average over timestep 

    real(r8), pointer :: t_ref2m_min(:)      ! daily minimum of average 2 m height surface air temperature (K)
    real(r8), pointer :: t_ref2m_max(:)      ! daily maximum of average 2 m height surface air temperature (K)
    real(r8), pointer :: t_ref2m_min_inst(:) ! instantaneous daily min of average 2 m height surface air temp (K)
    real(r8), pointer :: t_ref2m_max_inst(:) ! instantaneous daily max of average 2 m height surface air temp (K)
    real(r8), pointer :: t_ref2m_min_u(:)    ! Urban daily minimum of average 2 m height surface air temperature (K)
    real(r8), pointer :: t_ref2m_min_r(:)    ! Rural daily minimum of average 2 m height surface air temperature (K)
    real(r8), pointer :: t_ref2m_max_u(:)    ! Urban daily maximum of average 2 m height surface air temperature (K)
    real(r8), pointer :: t_ref2m_max_r(:)    ! Rural daily maximum of average 2 m height surface air temperature (K)
    real(r8), pointer :: t_ref2m_min_inst_u(:) ! Urban instantaneous daily min of average 2 m height surface air temp (K)
    real(r8), pointer :: t_ref2m_min_inst_r(:) ! Rural instantaneous daily min of average 2 m height surface air temp (K)
    real(r8), pointer :: t_ref2m_max_inst_u(:) ! Urban instantaneous daily max of average 2 m height surface air temp (K)
    real(r8), pointer :: t_ref2m_max_inst_r(:) ! Rural instantaneous daily max of average 2 m height surface air temp (K)
!#if (defined CNDV)
    real(r8), pointer :: t10(:)              ! 10-day running mean of the 2 m temperature (K)
    real(r8), pointer :: t_mo(:)             ! 30-day average temperature (Kelvin)
    real(r8), pointer :: t_mo_min(:)         ! annual min of t_mo (Kelvin)
    real(r8), pointer :: prec365(:)          ! 365-day running mean of tot. precipitation
    real(r8), pointer :: agddtw(:)           ! accumulated growing degree days above twmax
    real(r8), pointer :: agdd(:)             ! accumulated growing degree days above 5
    real(r8), pointer :: twmax(:)            ! upper limit of temperature of the warmest month
!#endif
!#if (defined CROP)
!    real(r8), pointer :: gdd0(:)             ! growing degree-days base 0C'
!    real(r8), pointer :: gdd8(:)             ! growing degree-days base 8C from planting
!    real(r8), pointer :: gdd10(:)            ! growing degree-days base 10C from planting
!    real(r8), pointer :: gddplant(:)         ! growing degree-days from planting
!    real(r8), pointer :: gddtsoi(:)          ! growing degree-days from planting (top two soil layers)
!    real(r8), pointer :: a10tmin(:)          ! 10-day running mean of min 2-m temperature
!    real(r8), pointer :: a5tmin(:)           ! 5-day running mean of min 2-m temperature
!#endif
!
!   
! !OTHER LOCAL VARIABLES:
!EOP
    integer :: g,l,c,p                   ! indices
    integer :: itypveg                   ! vegetation type
!    integer :: dtime                     ! timestep size [seconds]
!    integer :: nstep                     ! timestep number
!    integer :: year                      ! year (0, ...) for nstep
!    integer :: month                     ! month (1, ..., 12) for nstep
!    integer :: day                       ! day of month (1, ..., 31) for nstep
!    integer :: secs                      ! seconds into current date for nstep
    logical :: end_cd                    ! temporary for is_end_curr_day() value
    integer :: ier                       ! error status
    integer :: begp, endp                !  per-proc beginning and ending pft indices
    integer :: begc, endc                !  per-proc beginning and ending column indices
    integer :: begl, endl                !  per-proc beginning and ending landunit indices
    integer :: begg, endg                !  per-proc gridcell ending gridcell indices
    real(r8), pointer :: rbufslp(:)      ! temporary single level - pft level
     real(r8), pointer :: prec10(:)          ! 10-day running mean of tot. precipitation
    real(r8), pointer :: prec60(:)          ! 60-day running mean of tot. precipitation
!KC 
    integer :: yr,nstep,kmo,kda,mcsec,dayspyr,stemp,temp(12),month(12)
    real(r8) :: dtime,latdeg,T2ACASA,temp2,fsun_clm(filter(1)%num_soilp),t_veg_clm(filter(1)%num_soilp)
    real(r8) :: forc_solad,forc_solai,xlai7,t2o6,prc33,prc34
!------------------------------------------------------------------------

    ! Determine necessary indices

!    call get_proc_bounds(begg, endg, begl, endl, begc, endc, begp, endp)
!    begg=1
!    endg=1
!    begl=1
!    endl=1
!    begc=1
!    endc=1
!    begp=1
!    endp=1

    ! Assign local pointers to derived subtypes components (gridcell-level)

!    forc_t => clm_a2l%forc_t
!    forc_rain => clm_a2l%forc_rain
!    forc_snow => clm_a2l%forc_snow

!    forc_solad => clm_a2l%forc_solad        ! (heald 04/06)
!    forc_solai => clm_a2l%forc_solai        ! (heald 04/06)

   ! Assign local pointers to derived subtypes components (landunit-level)
    ifspecial  => clm3%g%l%ifspecial
    urbpoi     => clm3%g%l%urbpoi


    ! Assign local pointers to derived subtypes components (pft-level)

    itype            => clm3%g%l%c%p%itype
    pgridcell        => clm3%g%l%c%p%gridcell
    t_ref2m          => clm3%g%l%c%p%pes%t_ref2m
!    t_ref2m = T2ACASA
    t_ref2m_max_inst => clm3%g%l%c%p%pes%t_ref2m_max_inst
    t_ref2m_min_inst => clm3%g%l%c%p%pes%t_ref2m_min_inst
    t_ref2m_max      => clm3%g%l%c%p%pes%t_ref2m_max
    t_ref2m_min      => clm3%g%l%c%p%pes%t_ref2m_min
    t_ref2m_u        => clm3%g%l%c%p%pes%t_ref2m_u
    t_ref2m_r        => clm3%g%l%c%p%pes%t_ref2m_r
    t_ref2m_max_u    => clm3%g%l%c%p%pes%t_ref2m_max_u
    t_ref2m_max_r    => clm3%g%l%c%p%pes%t_ref2m_max_r
    t_ref2m_min_u    => clm3%g%l%c%p%pes%t_ref2m_min_u
    t_ref2m_min_r    => clm3%g%l%c%p%pes%t_ref2m_min_r
    t_ref2m_max_inst_u => clm3%g%l%c%p%pes%t_ref2m_max_inst_u
    t_ref2m_max_inst_r => clm3%g%l%c%p%pes%t_ref2m_max_inst_r
    t_ref2m_min_inst_u => clm3%g%l%c%p%pes%t_ref2m_min_inst_u
    t_ref2m_min_inst_r => clm3%g%l%c%p%pes%t_ref2m_min_inst_r
    plandunit        => clm3%g%l%c%p%landunit
!#if (defined CNDV)
    t_mo             => clm3%g%l%c%p%pdgvs%t_mo
    t_mo_min         => clm3%g%l%c%p%pdgvs%t_mo_min
    t10              => clm3%g%l%c%p%pdgvs%t10
    prec365          => clm3%g%l%c%p%pdgvs%prec365
    agddtw           => clm3%g%l%c%p%pdgvs%agddtw
    agdd             => clm3%g%l%c%p%pdgvs%agdd
    twmax            => dgv_pftcon%twmax
!#endif
!#if (defined CROP)
!    gdd0             => clm3%g%l%c%p%pps%gdd0
!    gdd8             => clm3%g%l%c%p%pps%gdd8
!    gdd10            => clm3%g%l%c%p%pps%gdd10
!    gddplant         => clm3%g%l%c%p%pps%gddplant
!    gddtsoi          => clm3%g%l%c%p%pps%gddtsoi
!    a10tmin          => clm3%g%l%c%p%pps%a10tmin
!    a5tmin           => clm3%g%l%c%p%pps%a5tmin
!    vf               => clm3%g%l%c%p%pps%vf
!    t_soisno         => clm3%g%l%c%ces%t_soisno
!    h2osoi_liq       => clm3%g%l%c%cws%h2osoi_liq
!    watsat           => clm3%g%l%c%cps%watsat
!    dz               => clm3%g%l%c%cps%dz
!    latdeg           => clm3%g%latdeg
!    croplive         => clm3%g%l%c%p%pps%croplive
!    pcolumn          => clm3%g%l%c%p%column
!#endif
    t_veg24          => clm3%g%l%c%p%pvs%t_veg24           ! (heald 04/06)
    t_veg240         => clm3%g%l%c%p%pvs%t_veg240          ! (heald 04/06)
    fsd24            => clm3%g%l%c%p%pvs%fsd24             ! (heald 04/06)
    fsd240           => clm3%g%l%c%p%pvs%fsd240            ! (heald 04/06)
    fsi24            => clm3%g%l%c%p%pvs%fsi24             ! (heald 04/06)
    fsi240           => clm3%g%l%c%p%pvs%fsi240            ! (heald 04/06)
    fsun24           => clm3%g%l%c%p%pvs%fsun24            ! (heald 04/06)
    fsun240          => clm3%g%l%c%p%pvs%fsun240           ! (heald 04/06)
    elai_p           => clm3%g%l%c%p%pvs%elai_p            ! (heald 04/06)
    t_veg            => clm3%g%l%c%p%pes%t_veg             ! (heald 04/06)
    fsun             => clm3%g%l%c%p%pps%fsun              ! (heald 04/06)
    elai             => clm3%g%l%c%p%pps%elai              ! (heald 04/06)

    prec60           => clm3%g%l%c%p%pps%prec60
    prec10           => clm3%g%l%c%p%pps%prec10

    ! Don't do any accumulation if nstep is zero
    ! (only applies to coupled or cam mode)

    if (nstep == 0) return

!KC 022514
  ! set time steps

   if (mod(yr,4) .eq. 0) then
      dayspyr = 366
!      month = (/31, 29, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31 /)
   else
      dayspyr = 365
!      month = (/31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31 /)
   end if
!   temp(1) = 31
!   do p = 2,12
!      temp(p) = month(p)+temp(p-1)
!   end do

!KC 
! IMPORTANT, this algorithm can only valid when starting at 1/1 of a year
! get time info
!   stemp = dtime*nstep             !run time in sec
!   mcsec = mod(stemp,86400)
!   kda = (stemp - mcsec)/86400  !num of days
!   if (kda .le. 31) then
!      kmo = 1
!   elseif ((kda .gt. temp(1)) .and. (kda .le. temp(2))) then
!      kmo = 2
!      kda = kda - temp(1)
!   elseif (kda .gt. temp(2) .and. kda .le. temp(3)) then
!      kmo = 3
!      kda = kda - temp(2)
!   elseif (kda .gt. temp(3) .and. kda .le. temp(4)) then
!      kmo = 4
!      kda = kda - temp(3)
!   elseif (kda .gt. temp(4) .and. kda .le. temp(5)) then
!      kmo = 5
!      kda = kda - temp(4)
!   elseif (kda .gt. temp(5) .and. kda .le. temp(6)) then
!      kmo = 6
!      kda = kda - temp(5)
!   elseif (kda .gt. temp(6) .and. kda .le. temp(7)) then 
!      kmo = 7
!      kda = kda - temp(6)
!   elseif (kda .gt. temp(7) .and. kda .le. temp(8)) then
!      kmo = 8
!      kda = kda - temp(7)
!   elseif (kda .gt. temp(8) .and. kda .le. temp(9)) then
!      kmo = 9
!      kda = kda - temp(8)
!   elseif (kda .gt. temp(9) .and. kda .le. temp(10)) then
!      kmo = 10
!      kda = kda - temp(9)
!   elseif (kda .gt. temp(10) .and. kda .le. temp(11)) then
!      kmo = 11
!      kda = kda - temp(10)
!   else
!      kmo = 12
!      kda = kda - temp(11)
!   end if
!KC end

    ! NOTE: currently only single level pft fields are used below
    ! Variables are declared above that should make it easy to incorporate
    ! multi-level or single-level fields of any subgrid type

    ! Allocate needed dynamic memory for single level pft field

    allocate(rbufslp(begp:endp), stat=ier)
    if (ier/=0) then
!       write(6,*)'update_accum_hist allocation error for rbuf1dp'
       call endrun
    endif

    ! Accumulate and extract TREFAV - hourly average 2m air temperature
    ! Used to compute maximum and minimum of hourly averaged 2m reference
    ! temperature over a day. Note that "spval" is returned by the call to
    ! accext if the time step does not correspond to the end of an
    ! accumulation interval. First, initialize the necessary values for
    ! an initial run at the first time step the accumulator is called
!KC 0318e4
!    t_ref2m(:) = T2ACASA
    t_ref2m_u(:) = T2ACASA
    t_ref2m_r(:) = T2ACASA
!KC end
    call update_accum_field  ('TREFAV', t_ref2m, nstep)
    call extract_accum_field ('TREFAV', rbufslp, nstep)

    if(mcsec.eq.0) then
      end_cd =  .true.
    else
      end_cd =  .false.
    end if
!dir$ concurrent
!cdir nodep

!KC 111814, initialize t_ref2m_max_inst
    if (nstep .eq. 1) then
!       t_ref2m_max_inst(:) = T2ACASA
!       t_ref2m_min_inst(:) = T2ACASA
       t_ref2m_max_inst_u(:) = T2ACASA
       t_ref2m_min_inst_u(:) = T2ACASA
       t_ref2m_max_inst_r(:) = T2ACASA
       t_ref2m_min_inst_r(:) = T2ACASA
    endif
!KC end

    do p = begp,endp
       if (rbufslp(p) /= spval) then
          t_ref2m_max_inst(p) = max(rbufslp(p), t_ref2m_max_inst(p))
          t_ref2m_min_inst(p) = min(rbufslp(p), t_ref2m_min_inst(p))
       endif
       if (end_cd) then
          t_ref2m_max(p) = t_ref2m_max_inst(p)
          t_ref2m_min(p) = t_ref2m_min_inst(p)
          t_ref2m_max_inst(p) = -spval
          t_ref2m_min_inst(p) =  spval
!          t_ref2m_max_inst(:) = T2ACASA
!          t_ref2m_min_inst(:) = T2ACASA
       else if (mcsec == int(dtime)) then
          t_ref2m_max(p) = spval
          t_ref2m_min(p) = spval
       endif
    end do
    ! Accumulate and extract TREFAV_U - hourly average urban 2m air temperature
    ! Used to compute maximum and minimum of hourly averaged 2m reference
    ! temperature over a day. Note that "spval" is returned by the call to
    ! accext if the time step does not correspond to the end of an
    ! accumulation interval. First, initialize the necessary values for
    ! an initial run at the first time step the accumulator is called
    
    call update_accum_field  ('TREFAV_U', t_ref2m_u, nstep)
    call extract_accum_field ('TREFAV_U', rbufslp, nstep)
    do p = begp,endp
       l = plandunit(p)
       if (rbufslp(p) /= spval) then
          t_ref2m_max_inst_u(p) = max(rbufslp(p), t_ref2m_max_inst_u(p))
          t_ref2m_min_inst_u(p) = min(rbufslp(p), t_ref2m_min_inst_u(p))
       endif
       if (end_cd) then
         if (urbpoi(l)) then
          t_ref2m_max_u(p) = t_ref2m_max_inst_u(p)
          t_ref2m_min_u(p) = t_ref2m_min_inst_u(p)
!          t_ref2m_max_inst_u(p) = -spval
!          t_ref2m_min_inst_u(p) =  spval
          t_ref2m_max_inst_u(:) = T2ACASA
          t_ref2m_min_inst_u(:) = T2ACASA
         end if 
       else if (mcsec == int(dtime)) then
          t_ref2m_max_u(p) = spval
          t_ref2m_min_u(p) = spval
       endif
    end do
    
    ! Accumulate and extract TREFAV_R - hourly average rural 2m air temperature
    ! Used to compute maximum and minimum of hourly averaged 2m reference
    ! temperature over a day. Note that "spval" is returned by the call to
    ! accext if the time step does not correspond to the end of an
    ! accumulation interval. First, initialize the necessary values for
    ! an initial run at the first time step the accumulator is called
    
    call update_accum_field  ('TREFAV_R', t_ref2m_r, nstep)
    call extract_accum_field ('TREFAV_R', rbufslp, nstep)
    do p = begp,endp
       l = plandunit(p)
       if (rbufslp(p) /= spval) then
          t_ref2m_max_inst_r(p) = max(rbufslp(p), t_ref2m_max_inst_r(p))
          t_ref2m_min_inst_r(p) = min(rbufslp(p), t_ref2m_min_inst_r(p))
       endif
       if (end_cd) then
         if (.not.(ifspecial(l))) then
          t_ref2m_max_r(p) = t_ref2m_max_inst_r(p)
          t_ref2m_min_r(p) = t_ref2m_min_inst_r(p)
!          t_ref2m_max_inst_r(p) = -spval
!          t_ref2m_min_inst_r(p) =  spval
          t_ref2m_max_inst_r(:) = T2ACASA
          t_ref2m_min_inst_r(:) = T2ACASA
        end if
       else if (mcsec == int(dtime)) then
          t_ref2m_max_r(p) = spval
          t_ref2m_min_r(p) = spval
       endif
    end do

    ! Accumulate and extract T_VEG24 & T_VEG240 (heald 04/06)
!get t_veg
    do p = begp,endp
       t_veg(p) = t_veg_clm(1)
    end do
    do p = 1,filter(1)%num_soilp
           t_veg(filter(1)%soilp(p)) = t_veg_clm(p)
    enddo
    do p = begp,endp
       rbufslp(p) = t_veg(p)
    end do
    call update_accum_field  ('T_VEG24', rbufslp, nstep)
    call extract_accum_field ('T_VEG24', t_veg24, nstep)
    call update_accum_field  ('T_VEG240', rbufslp, nstep)
    call extract_accum_field ('T_VEG240', t_veg240, nstep)

    ! Accumulate and extract forc_solad24 & forc_solad240 (heald 04/06)
    do p = begp,endp
!       g = pgridcell(p)
!       rbufslp(p) = forc_solad(g,1)
       rbufslp(p) = forc_solad
    end do
    call update_accum_field  ('FSD240', rbufslp, nstep)
    call extract_accum_field ('FSD240', fsd240, nstep)
    call update_accum_field  ('FSD24', rbufslp, nstep)
    call extract_accum_field ('FSD24', fsd24, nstep)

    ! Accumulate and extract forc_solai24 & forc_solai240 (heald 04/06)
    do p = begp,endp
!       g = pgridcell(p)
!       rbufslp(p) = forc_solai(g,1)
       rbufslp(p) = forc_solai
    end do
    call update_accum_field  ('FSI24', rbufslp, nstep)
    call extract_accum_field ('FSI24', fsi24, nstep)
    call update_accum_field  ('FSI240', rbufslp, nstep)
    call extract_accum_field ('FSI240', fsi240, nstep)

    ! Accumulate and extract fsun24 & fsun240 (heald 04/06)
!    temp2 = 0.0_r8
!    do p = 1,11
!       do g = 1,9
!          temp2 = temp2+fsl(p)*lf(g)
!       end do
!    end do
    do p = begp,endp
!       rbufslp(p) = fsun(p)
       rbufslp(p) = fsun_clm(1)
    end do
    do p = 1,filter(1)%num_soilp
              rbufslp(filter(1)%soilp(p)) = fsun_clm(p)
    enddo
    call update_accum_field  ('FSUN24', rbufslp, nstep)
    call extract_accum_field ('FSUN24', fsun24, nstep)
    call update_accum_field  ('FSUN240', rbufslp, nstep)
    call extract_accum_field ('FSUN240', fsun240, nstep)

    ! Accumulate and extract elai_p (heald 04/06)
    do p = begp,endp
       rbufslp(p) = elai(p)
!       rbufslp(p) = xlai7
    end do
    call update_accum_field  ('LAIP', rbufslp, nstep)
    call extract_accum_field ('LAIP', elai_p, nstep)


!KC IMPORTANT, disable for now
!#if (defined CNDV)
    ! Accumulate and extract TDA
    ! (accumulates TBOT as 30-day average)
    ! Also determine t_mo_min

 !dir$ concurrent
 !cdir nodep
    do p = begp,endp
!       g = pgridcell(p)
!       rbufslp(p) = forc_t(g)
       rbufslp(p) = t2o6
    end do
    call update_accum_field  ('TDA', rbufslp, nstep)
    call extract_accum_field ('TDA', rbufslp, nstep)
 !dir$ concurrent
 !cdir nodep
    do p = begp,endp
       t_mo(p) = rbufslp(p)
       t_mo_min(p) = min(t_mo_min(p), rbufslp(p))
    end do

    ! Accumulate and extract T10
    !(acumulates TSA as 10-day running mean)

    call update_accum_field  ('T10', t_ref2m, nstep)
    call extract_accum_field ('T10', t10, nstep)

    ! Accumulate and extract FNPSN10
    !(accumulates fpsn-frmf as 10-day running mean)



 !dir$ concurrent
 !cdir nodep
!    do p = begp,endp
!       rbufslp(p) = fpsn(p) - frmf(p)
!    end do
!    call update_accum_field  ('FNPSN10', rbufslp, nstep)
!    call extract_accum_field ('FNPSN10', fnpsn10, nstep)

    ! Accumulate and extract PREC365
    ! (accumulates total precipitation as 365-day running mean)

!dir$ concurrent
!cdir nodep
    do p = begp,endp
!       g = pgridcell(p)
!       rbufslp(p) = forc_rain(g) + forc_snow(g)
       rbufslp(p) = prc33+prc34
    end do
    call update_accum_field  ('PREC365', rbufslp, nstep)
    call extract_accum_field ('PREC365', prec365, nstep)

    ! Accumulate growing degree days based on 10-day running mean temperature.
    ! The trigger to reset the accumulated values to zero is -99999.

    ! Accumulate and extract AGDDTW (gdd base twmax, which is 23 deg C
    ! for boreal woody pfts)
    do p = begp,endp
       rbufslp(p) = max(0._r8, (t10(p) - 273.16_r8 - twmax(ndllf_dcd_brl_tree)) &
                    * dtime/86400.0_r8)
       if (kmo==1 .and. kda==1 .and. mcsec==int(dtime)) rbufslp(p) = -99999._r8
    end do
    call update_accum_field  ('AGDDTW', rbufslp, nstep)
    call extract_accum_field ('AGDDTW', agddtw, nstep)
    ! Accumulate and extract AGDD

    do p = begp,endp
       rbufslp(p) = max(0.0_r8, (t_ref2m(p) - (273.16_r8 + 5.0_r8)) &
            * dtime/86400.0_r8)
    end do
    call update_accum_field  ('AGDD', rbufslp, nstep)
    call extract_accum_field ('AGDD', agdd, nstep)

     do p = begp,endp
!       g = pgridcell(p)
       rbufslp(p) = prc33+prc34!forc_rain(g) + forc_snow(g)
    end do
    call update_accum_field  ('PREC60', rbufslp, nstep)
    call extract_accum_field ('PREC60', prec60, nstep)

    ! Accumulate and extract PREC10
    ! (accumulates total precipitation as 10-day running mean)
     do p = begp,endp
!       g = pgridcell(p)
       rbufslp(p) = prc33+prc34!forc_rain(g) + forc_snow(g)
    end do
    call update_accum_field  ('PREC10', rbufslp, nstep)
    call extract_accum_field ('PREC10', prec10, nstep)

!    if ( crop_prog )then
       ! Accumulate and extract TDM10

!       do p = begp,endp
!          rbufslp(p) = min(t_ref2m_min(p),t_ref2m_min_inst(p)) !slevis: ok choice?
!          if (rbufslp(p) > 1.e30_r8) rbufslp(p) = SHR_CONST_TKFRZ !and were 'min'&
!       end do                                         !'min_inst' not initialized?
!       call update_accum_field  ('TDM10', rbufslp, nstep)
!       call extract_accum_field ('TDM10', a10tmin, nstep)

       ! Accumulate and extract TDM5

!       do p = begp,endp
!          rbufslp(p) = min(t_ref2m_min(p),t_ref2m_min_inst(p)) !slevis: ok choice?
!          if (rbufslp(p) > 1.e30_r8) rbufslp(p) = SHR_CONST_TKFRZ !and were 'min'&
!       end do                                         !'min_inst' not initialized?
!       call update_accum_field  ('TDM5', rbufslp, nstep)
!       call extract_accum_field ('TDM5', a5tmin, nstep)

       ! Accumulate and extract GDD0

!       do p = begp,endp
!          itypveg = itype(p)
!          g = pgridcell(p)
!          if (month==1 .and. day==1 .and. secs==int(dtime)) then
!             rbufslp(p) = -99999._r8 ! reset gdd
!          else if (( month > 3 .and. month < 10 .and. latdeg(g) >= 0._r8) .or. &
!                   ((month > 9 .or.  month < 4) .and. latdeg(g) <  0._r8)     ) then
!             rbufslp(p) = max(0._r8, min(26._r8, t_ref2m(p)-SHR_CONST_TKFRZ)) &
!                          * dtime/SHR_CONST_CDAY
!          else
!             rbufslp(p) = 0._r8      ! keeps gdd unchanged at other times (eg, through Dec in NH)
!          end if
!       end do
!       call update_accum_field  ('GDD0', rbufslp, nstep)
!       call extract_accum_field ('GDD0', gdd0, nstep)

       ! Accumulate and extract GDD8

!       do p = begp,endp
!          itypveg = itype(p)
!          g = pgridcell(p)
!          if (month==1 .and. day==1 .and. secs==int(dtime)) then
!             rbufslp(p) = -99999._r8 ! reset gdd
!          else if (( month > 3 .and. month < 10 .and. latdeg(g) >= 0._r8) .or. &
!                   ((month > 9 .or.  month < 4) .and. latdeg(g) <  0._r8)     ) then
!             rbufslp(p) = max(0._r8, min(30._r8, &
!                                         t_ref2m(p)-(SHR_CONST_TKFRZ + 8._r8))) &
!                          * dtime/SHR_CONST_CDAY
!          else
!             rbufslp(p) = 0._r8      ! keeps gdd unchanged at other times (eg, through Dec in NH)
!          end if
!       end do
!       call update_accum_field  ('GDD8', rbufslp, nstep)
!       call extract_accum_field ('GDD8', gdd8, nstep)

       ! Accumulate and extract GDD10

!       do p = begp,endp
!          itypveg = itype(p)
!          g = pgridcell(p)
!          if (month==1 .and. day==1 .and. secs==int(dtime)) then
!             rbufslp(p) = -99999._r8 ! reset gdd
!          else if (( month > 3 .and. month < 10 .and. latdeg(g) >= 0._r8) .or. &
!                   ((month > 9 .or.  month < 4) .and. latdeg(g) <  0._r8)     ) then
!             rbufslp(p) = max(0._r8, min(30._r8, &
!                                         t_ref2m(p)-(SHR_CONST_TKFRZ + 10._r8))) &
!                          * dtime/SHR_CONST_CDAY
!          else
!             rbufslp(p) = 0._r8      ! keeps gdd unchanged at other times (eg, through Dec in NH)
!          end if
!       end do
!       call update_accum_field  ('GDD10', rbufslp, nstep)
!       call extract_accum_field ('GDD10', gdd10, nstep)
!
!       ! Accumulate and extract GDDPLANT
!
!       do p = begp,endp
!          if (croplive(p)) then ! relative to planting date
!             itypveg = itype(p)
!             rbufslp(p) = max(0._r8, min(mxtmp(itypveg), &
!                                         t_ref2m(p)-(SHR_CONST_TKFRZ + baset(itypveg)))) &
!                          * dtime/SHR_CONST_CDAY
!             if (itypveg == nwcereal .or. itypveg == nwcerealirrig) rbufslp(p) = rbufslp(p)*vf(p)
!          else
