contains

!-----------------------------------------------------------------------
!BOP
!
! !IROUTINE: NStateUpdate1
!
! !INTERFACE:
subroutine NStateUpdate1(num_soilc, filter_soilc, num_soilp, filter_soilp,dt)
!
! !DESCRIPTION:
! On the radiation time step, update all the prognostic nitrogen state
! variables (except for gap-phase mortality and fire fluxes)
!
! !USES:
   use clmtype45
!   use clm_time_manager, only: get_step_size
    use clm_varpar45   , only: nlevdecomp, ndecomp_pools, ndecomp_cascade_transitions
!   use clm_varctl  , only: iulog
   use clm_varpar45   , only: i_met_lit, i_cel_lit, i_lig_lit, i_cwd
