             end if
             
             ! retransn  
             ptr => pptr%pns%retransn(p)
             init_state = ptr*wt_old
             change_state = ptr*dwt
             new_state = init_state+change_state
             if (wt_new /= 0._r8) then
                ptr = new_state/wt_new
                dwt_ptr1 = dwt_ptr1 + change_state
             else
                ptr = 0._r8
                dwt_ptr1 = dwt_ptr1 - init_state
             end if
             
             ! npool  
             ptr => pptr%pns%npool(p)
             init_state = ptr*wt_old
             change_state = ptr*dwt
             new_state = init_state+change_state
             if (wt_new /= 0._r8) then
                ptr = new_state/wt_new
                dwt_ptr1 = dwt_ptr1 + change_state
             else
                ptr = 0._r8
                dwt_ptr1 = dwt_ptr1 - init_state
             end if
             
             ! pft_ntrunc  
             ptr => pptr%pns%pft_ntrunc(p)
             init_state = ptr*wt_old
             change_state = ptr*dwt
             new_state = init_state+change_state
             if (wt_new /= 0._r8) then
                ptr = new_state/wt_new
                dwt_ptr1 = dwt_ptr1 + change_state
             else
                ptr = 0._r8
                dwt_ptr1 = dwt_ptr1 - init_state
             end if
          end if       ! weight decreasing
       end if           ! is soil
    end do               ! pft loop
    
    ! calculate column-level seeding fluxes
    do pi = 1,max_pft_per_col
       do c = begc, endc
          if ( pi <=  cptr%npfts(c) ) then
             p = cptr%pfti(c) + pi - 1
             
             ! C fluxes
             cptr%ccf%dwt_seedc_to_leaf(c) = cptr%ccf%dwt_seedc_to_leaf(c) + dwt_leafc_seed(p)/dt
             cptr%ccf%dwt_seedc_to_deadstem(c) = cptr%ccf%dwt_seedc_to_deadstem(c) &
                  + dwt_deadstemc_seed(p)/dt
             
!             if ( use_c13 ) then
!                cptr%cc13f%dwt_seedc_to_leaf(c) = cptr%cc13f%dwt_seedc_to_leaf(c) + dwt_leafc13_seed(p)/dt
!                cptr%cc13f%dwt_seedc_to_deadstem(c) = cptr%cc13f%dwt_seedc_to_deadstem(c) &
!                     + dwt_deadstemc13_seed(p)/dt
!             endif
             
!             if ( use_c14 ) then	
!                cptr%cc14f%dwt_seedc_to_leaf(c) = cptr%cc14f%dwt_seedc_to_leaf(c) + dwt_leafc14_seed(p)/dt
!                cptr%cc14f%dwt_seedc_to_deadstem(c) = cptr%cc14f%dwt_seedc_to_deadstem(c) &
!                     + dwt_deadstemc14_seed(p)/dt
!             endif
             
             ! N fluxes
             cptr%cnf%dwt_seedn_to_leaf(c) = cptr%cnf%dwt_seedn_to_leaf(c) + dwt_leafn_seed(p)/dt
             cptr%cnf%dwt_seedn_to_deadstem(c) = cptr%cnf%dwt_seedn_to_deadstem(c) &
                  + dwt_deadstemn_seed(p)/dt
          end if
       end do
    end do
    
    
    ! calculate pft-to-column for fluxes into litter and CWD pools
    do j = 1, nlevdecomp
       do pi = 1,max_pft_per_col
          do c = begc, endc
             if ( pi <=  cptr%npfts(c) ) then
                p = cptr%pfti(c) + pi - 1
                
                ! fine root litter carbon fluxes
                cptr%ccf%dwt_frootc_to_litr_met_c(c,j) = cptr%ccf%dwt_frootc_to_litr_met_c(c,j) + &
                     (dwt_frootc_to_litter(p)*fr_flab(ivt(p)))/dt * pptr%pps%froot_prof(p,j)
                cptr%ccf%dwt_frootc_to_litr_cel_c(c,j) = cptr%ccf%dwt_frootc_to_litr_cel_c(c,j) + &
                     (dwt_frootc_to_litter(p)*fr_fcel(ivt(p)))/dt * pptr%pps%froot_prof(p,j)
                cptr%ccf%dwt_frootc_to_litr_lig_c(c,j) = cptr%ccf%dwt_frootc_to_litr_lig_c(c,j) + &
                     (dwt_frootc_to_litter(p)*fr_flig(ivt(p)))/dt * pptr%pps%froot_prof(p,j)
                
                
                ! fine root litter nitrogen fluxes
                cptr%cnf%dwt_frootn_to_litr_met_n(c,j) = cptr%cnf%dwt_frootn_to_litr_met_n(c,j) + &
                     (dwt_frootn_to_litter(p)*fr_flab(ivt(p)))/dt * pptr%pps%froot_prof(p,j)
                cptr%cnf%dwt_frootn_to_litr_cel_n(c,j) = cptr%cnf%dwt_frootn_to_litr_cel_n(c,j) + &
                     (dwt_frootn_to_litter(p)*fr_fcel(ivt(p)))/dt * pptr%pps%froot_prof(p,j)
                cptr%cnf%dwt_frootn_to_litr_lig_n(c,j) = cptr%cnf%dwt_frootn_to_litr_lig_n(c,j) + &
                     (dwt_frootn_to_litter(p)*fr_flig(ivt(p)))/dt * pptr%pps%froot_prof(p,j)
                
                ! livecroot fluxes to cwd
                cptr%ccf%dwt_livecrootc_to_cwdc(c,j) = cptr%ccf%dwt_livecrootc_to_cwdc(c,j) + &
                     (dwt_livecrootc_to_litter(p))/dt * pptr%pps%croot_prof(p,j)
                cptr%cnf%dwt_livecrootn_to_cwdn(c,j) = cptr%cnf%dwt_livecrootn_to_cwdn(c,j) + &
                     (dwt_livecrootn_to_litter(p))/dt * pptr%pps%croot_prof(p,j)
                
                ! deadcroot fluxes to cwd
                cptr%ccf%dwt_deadcrootc_to_cwdc(c,j) = cptr%ccf%dwt_deadcrootc_to_cwdc(c,j) + &
                     (dwt_deadcrootc_to_litter(p))/dt * pptr%pps%croot_prof(p,j)
                cptr%cnf%dwt_deadcrootn_to_cwdn(c,j) = cptr%cnf%dwt_deadcrootn_to_cwdn(c,j) + &
                     (dwt_deadcrootn_to_litter(p))/dt * pptr%pps%croot_prof(p,j)
             
!                if ( use_c13 ) then
                   ! C13 fine root litter fluxes
!                   cptr%cc13f%dwt_frootc_to_litr_met_c(c,j) = cptr%cc13f%dwt_frootc_to_litr_met_c(c,j) + &
!!                        (dwt_frootc13_to_litter(p)*pftcon%fr_flab(pptr%itype(p)))/dt * pptr%pps%froot_prof(p,j)
!                   cptr%cc13f%dwt_frootc_to_litr_cel_c(c,j) = cptr%cc13f%dwt_frootc_to_litr_cel_c(c,j) + &
!                        (dwt_frootc13_to_litter(p)*pftcon%fr_fcel(pptr%itype(p)))/dt * pptr%pps%froot_prof(p,j)
!                   cptr%cc13f%dwt_frootc_to_litr_lig_c(c,j) = cptr%cc13f%dwt_frootc_to_litr_lig_c(c,j) + &
!                        (dwt_frootc13_to_litter(p)*pftcon%fr_flig(pptr%itype(p)))/dt * pptr%pps%froot_prof(p,j)
                   ! livecroot fluxes to cwd
!                   cptr%cc13f%dwt_livecrootc_to_cwdc(c,j) = cptr%cc13f%dwt_livecrootc_to_cwdc(c,j) + &
!                        (dwt_livecrootc13_to_litter(p))/dt * pptr%pps%croot_prof(p,j)
                   ! deadcroot fluxes to cwd
!                   cptr%cc13f%dwt_deadcrootc_to_cwdc(c,j) = cptr%cc13f%dwt_deadcrootc_to_cwdc(c,j) + &
!                        (dwt_deadcrootc13_to_litter(p))/dt * pptr%pps%croot_prof(p,j)
!                   
!                endif
                
!                if ( use_c14 ) then                   
                   ! C14 fine root litter fluxes
!                   cptr%cc14f%dwt_frootc_to_litr_met_c(c,j) = cptr%cc14f%dwt_frootc_to_litr_met_c(c,j) + &
!                        (dwt_frootc14_to_litter(p)*pftcon%fr_flab(pptr%itype(p)))/dt * pptr%pps%froot_prof(p,j)
!                   cptr%cc14f%dwt_frootc_to_litr_cel_c(c,j) = cptr%cc14f%dwt_frootc_to_litr_cel_c(c,j) + &
!                        (dwt_frootc14_to_litter(p)*pftcon%fr_fcel(pptr%itype(p)))/dt * pptr%pps%froot_prof(p,j)
!                   cptr%cc14f%dwt_frootc_to_litr_lig_c(c,j) = cptr%cc14f%dwt_frootc_to_litr_lig_c(c,j) + &
!                        (dwt_frootc14_to_litter(p)*pftcon%fr_flig(pptr%itype(p)))/dt * pptr%pps%froot_prof(p,j)
!                   ! livecroot fluxes to cwd
!                   cptr%cc14f%dwt_livecrootc_to_cwdc(c,j) = cptr%cc14f%dwt_livecrootc_to_cwdc(c,j) + &
!                        (dwt_livecrootc14_to_litter(p))/dt * pptr%pps%croot_prof(p,j)
!                   ! deadcroot fluxes to cwd
!                   cptr%cc14f%dwt_deadcrootc_to_cwdc(c,j) = cptr%cc14f%dwt_deadcrootc_to_cwdc(c,j) + &
!                        (dwt_deadcrootc14_to_litter(p))/dt * pptr%pps%croot_prof(p,j)
!                endif
                
             end if
          end do
       end do
    end do
    ! calculate pft-to-column for fluxes into product pools and conversion flux
    do pi = 1,max_pft_per_col
       do c = begc,endc
          if (pi <= cptr%npfts(c)) then
             p = cptr%pfti(c) + pi - 1
             
             ! column-level fluxes are accumulated as positive fluxes.
             ! column-level C flux updates
             cptr%ccf%dwt_conv_cflux(c) = cptr%ccf%dwt_conv_cflux(c) - conv_cflux(p)/dt
             cptr%ccf%dwt_prod10c_gain(c) = cptr%ccf%dwt_prod10c_gain(c) - prod10_cflux(p)/dt
             cptr%ccf%dwt_prod100c_gain(c) = cptr%ccf%dwt_prod100c_gain(c) - prod100_cflux(p)/dt

             ! These magic constants should be replaced with: nbrdlf_evr_trp_tree and nbrdlf_dcd_trp_tree
             if(ivt(p)==4.or.ivt(p)==6)then
                cptr%ccf%lf_conv_cflux(c) = cptr%ccf%lf_conv_cflux(c) - conv_cflux(p)/dt
             end if
             
!             if ( use_c13 ) then
                ! C13 column-level flux updates
!                cptr%cc13f%dwt_conv_cflux(c) = cptr%cc13f%dwt_conv_cflux(c) - conv_c13flux(p)/dt
!!                cptr%cc13f%dwt_prod10c_gain(c) = cptr%cc13f%dwt_prod10c_gain(c) - prod10_c13flux(p)/dt
!                cptr%cc13f%dwt_prod100c_gain(c) = cptr%cc13f%dwt_prod100c_gain(c) - prod100_c13flux(p)/dt
!             endif
             
!             if ( use_c14 ) then
                ! C14 column-level flux updates
!                cptr%cc14f%dwt_conv_cflux(c) = cptr%cc14f%dwt_conv_cflux(c) - conv_c14flux(p)/dt
!                cptr%cc14f%dwt_prod10c_gain(c) = cptr%cc14f%dwt_prod10c_gain(c) - prod10_c14flux(p)/dt
!                cptr%cc14f%dwt_prod100c_gain(c) = cptr%cc14f%dwt_prod100c_gain(c) - prod100_c14flux(p)/dt
!             endif
             
             ! column-level N flux updates
             cptr%cnf%dwt_conv_nflux(c) = cptr%cnf%dwt_conv_nflux(c) - conv_nflux(p)/dt
             cptr%cnf%dwt_prod10n_gain(c) = cptr%cnf%dwt_prod10n_gain(c) - prod10_nflux(p)/dt
             cptr%cnf%dwt_prod100n_gain(c) = cptr%cnf%dwt_prod100n_gain(c) - prod100_nflux(p)/dt
             
          end if
       end do
    end do
    
    ! Deallocate pft-level flux arrays
    deallocate(dwt_leafc_seed)
    deallocate(dwt_leafn_seed)
    deallocate(dwt_deadstemc_seed)
    deallocate(dwt_deadstemn_seed)
    deallocate(dwt_frootc_to_litter)
    deallocate(dwt_livecrootc_to_litter)
    deallocate(dwt_deadcrootc_to_litter)
    deallocate(dwt_frootn_to_litter)
    deallocate(dwt_livecrootn_to_litter)
    deallocate(dwt_deadcrootn_to_litter)
    deallocate(conv_cflux)
    deallocate(prod10_cflux)
    deallocate(prod100_cflux)
    deallocate(conv_nflux)
    deallocate(prod10_nflux)
    deallocate(prod100_nflux)
if(allocated(wtcol_old)) deallocate (wtcol_old)             


!    if ( use_c13 ) then
!       deallocate(dwt_leafc13_seed)
!       deallocate(dwt_deadstemc13_seed)
!       deallocate(dwt_frootc13_to_litter)
!       deallocate(dwt_livecrootc13_to_litter)
!       deallocate(dwt_deadcrootc13_to_litter)
!       deallocate(conv_c13flux)
!       deallocate(prod10_c13flux)
!       deallocate(prod100_c13flux)
!    endif
             
!    if ( use_c14 ) then
!       deallocate(dwt_leafc14_seed)
!!       deallocate(dwt_deadstemc14_seed)
!       deallocate(dwt_frootc14_to_litter)
!       deallocate(dwt_livecrootc14_to_litter)
!       deallocate(dwt_deadcrootc14_to_litter)
!       deallocate(conv_c14flux)
!       deallocate(prod10_c14flux)
!       deallocate(prod100_c14flux)
!    endif
  end subroutine pftdyn_cnbal
!#endif

!#if (defined CNDV)
!-----------------------------------------------------------------------
!BOP
!
! !ROUTINE: pftwt_init
!
! !INTERFACE:
  subroutine pftwt_init(begp,endp)
!
! !DESCRIPTION:
! Initialize time interpolation of cndv pft weights from annual to time step
!
! !USES:
!  use clm_varctl, only : nsrest, nsrStartup
!
! !ARGUMENTS:
    implicit none
!
!EOP
!
! !LOCAL VARIABLES:
    integer  :: ier, p                        ! error status, do-loop index
    integer  :: begp,endp                     ! beg/end indices for land pfts
    character(len=32) :: subname='pftwt_init' ! subroutine name
    type(pft_type), pointer :: pptr           ! ponter to pft derived subtype
!-----------------------------------------------------------------------

    pptr => clm3%g%l%c%p
ier=0
!    call get_proc_bounds(begp=begp,endp=endp)
if (.not. allocated(wtcol_old)) allocate(wtcol_old(begp:endp),stat=ier)
    if (ier /= 0) then
       call endrun( subname//'::ERROR: pftwt_init allocation error for wtcol_old')
    end if
!KC 081214
!    if (nsrest == nsrStartup) then
!the following codes are for initial runs
       do p = begp,endp
          pptr%pdgvs%fpcgrid(p) = pptr%wtcol(p)
          pptr%pdgvs%fpcgridold(p) = pptr%wtcol(p)
          wtcol_old(p) = pptr%wtcol(p)
       end do
!for the other cases
!    else
!       do p = begp,endp
!          wtcol_old(p) = pptr%wtcol(p)
!       end do
!    end if
!KC end
  end subroutine pftwt_init

!-----------------------------------------------------------------------
!BOP
!
! !ROUTINE: pftwt_interp
!
! !INTERFACE:
  subroutine pftwt_interp( begp, endp ,dtime,nstep,year,isoi3,mon,day,sec)
!
! !DESCRIPTION:
! Time interpolate cndv pft weights from annual to time step
!
! !USES:
!    use clm_time_manager, only : get_curr_calday, get_curr_date, &
!                                 get_days_per_year
!    use clm_time_manager, only : get_step_size, get_nstep
    use clm_varcon45      , only : istsoil ! CNDV incompatible with dynLU
!    use clm_varctl      , only : finidat
!
! !ARGUMENTS:
    implicit none
    integer, intent(IN)  :: begp,endp                ! beg/end indices for land pfts
!
!EOP
!
! !LOCAL VARIABLES:
    integer  :: c,g,l,p            ! indices
    real(r8) :: cday               ! current calendar day (1.0 = 0Z on Jan 1)
    real(r8) :: wt1                ! time interpolation weights
    real(r8) :: dtime              ! model time step
    real(r8) :: days_per_year      ! days per year
    integer  :: nstep              ! time step number
    integer  :: year               ! year (0, ...) at nstep + 1
    integer  :: mon                ! month (1, ..., 12) at nstep + 1
    integer  :: day                ! day of month (1, ..., 31) at nstep + 1
    integer  :: sec                ! seconds into current date at nstep + 1
    type(landunit_type), pointer :: lptr ! pointer to landunit derived subtype
    type(pft_type)     , pointer :: pptr ! ...     to pft derived subtype
    character(len=32) :: subname='pftwt_interp' ! subroutine name
!KC 070114
    integer  :: month(12),isoi3
    real(r8) :: stemp,dtemp
! !CALLED FROM:
!  subr. driver
!-----------------------------------------------------------------------

    ! Set pointers into derived type

    lptr => clm3%g%l
    pptr => clm3%g%l%c%p

    ! Interpolate pft weight to current time step
    ! Map interpolated pctpft to subgrid weights
    ! assumes maxpatch_pft = numpft + 1, each landunit has 1 column, 
    ! SCAM not defined and create_croplandunit = .false.

!    nstep         = get_nstep()
!    dtime         = get_step_size()
!!    cday          = get_curr_calday(offset=-int(dtime))
!    days_per_year = get_days_per_year()
! KC, calculate days_per_year
   if (mod(year,4) .eq. 0) then
       days_per_year = 366.0
!       stemp = days_per_year*24.0*3600.0/dtime
      month = (/31, 29, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31 /)
   else
       days_per_year = 365.0
!       stemp = days_per_year*24.0*3600.0/dtime
      month = (/31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31 /)
   endif

!KC do the cday calculation
    stemp = 0.0
    if (mon .gt. 1) then
    do p = 1,mon-1
       stemp = stemp+month(p)
    enddo
    endif
!if (mon==1 .and. day==1 .and. sec==0) then
!   cday = 365+(86400-dtime)/86400
!else
   cday = stemp + day + sec/86400.0 -real(dtime)/86400.0 !setup offset by minus dtime
!endif
!    cday = mod((real(nstep)-1.0),stemp)*1800.0/24.0/3600.0+1.0
!    dtemp = real(nstep) - 1.0
!    cday = mod(dtemp,stemp)*1800.0/24.0/3600.0+1.0
if (mon==1 .and. day==1 .and. sec==0) then
   wt1 = real(dtime)/86400.0/days_per_year
else
   wt1 = ((days_per_year + 1._r8) - cday)/days_per_year
endif
!    call get_curr_date(year, mon, day, sec, offset=int(dtime))
    do p = begp,endp
       g = pptr%gridcell(p)
       l = pptr%landunit(p)
!!
!       if (lptr%itype(l) == istsoil .and. lptr%wtgcell(l) > 0._r8) then ! CNDV incompatible with dynLU
        if (isoi3 .ne. 14 .and. lptr%wtgcell(l) > 0._r8) then
          wtcol_old(p)    = pptr%wtcol(p)
          pptr%wtcol(p)   = pptr%pdgvs%fpcgrid(p) + &
                     wt1 * (pptr%pdgvs%fpcgridold(p) - pptr%pdgvs%fpcgrid(p))
          pptr%wtlunit(p) = pptr%wtcol(p)
          pptr%wtgcell(p) = pptr%wtcol(p) * lptr%wtgcell(l)
          if (mon==1 .and. day==1 .and. sec==0 .and. nstep>0) then
             pptr%pdgvs%fpcgridold(p) = pptr%pdgvs%fpcgrid(p)
          end if
       end if
    end do
if(allocated(wtcol_old)) deallocate (wtcol_old)
  end subroutine pftwt_interp
!#endif

!#ifdef CN
!-----------------------------------------------------------------------
!BOP
!
! !IROUTINE: CNHarvest
!
! !INTERFACE:
subroutine CNHarvest (num_soilc, filter_soilc, num_soilp, filter_soilp,yr)
!
! !DESCRIPTION:
! Harvest mortality routine for coupled carbon-nitrogen code (CN)
!
! !USES:
   use clmtype45
   use pftvarcon45       , only : noveg, nbrdlf_evr_shrub, pprodharv10
   use clm_varcon45      , only : secspday
!   use clm_time_manager, only : get_days_per_year
!
! !ARGUMENTS:
   implicit none
   integer, intent(in) :: num_soilc       ! number of soil columns in filter
   integer, intent(in) :: filter_soilc(:) ! column filter for soil points
   integer, intent(in) :: num_soilp       ! number of soil pfts in filter
   integer, intent(in) :: filter_soilp(:) ! pft filter for soil points
!
! !CALLED FROM:
! subroutine CNEcosystemDyn
!
! !REVISION HISTORY:
! 3/29/04: Created by Peter Thornton
!
! !LOCAL VARIABLES:
!
! local pointers to implicit in arrays
   integer , pointer :: pgridcell(:)   ! pft-level index into gridcell-level quantities
   integer , pointer :: ivt(:)         ! pft vegetation type

   real(r8), pointer :: leafc(:)              ! (gC/m2) leaf C
   real(r8), pointer :: frootc(:)             ! (gC/m2) fine root C
   real(r8), pointer :: livestemc(:)          ! (gC/m2) live stem C
   real(r8), pointer :: deadstemc(:)          ! (gC/m2) dead stem C
   real(r8), pointer :: livecrootc(:)         ! (gC/m2) live coarse root C
   real(r8), pointer :: deadcrootc(:)         ! (gC/m2) dead coarse root C
   real(r8), pointer :: xsmrpool(:)           ! (gC/m2) abstract C pool to meet excess MR demand
   real(r8), pointer :: leafc_storage(:)      ! (gC/m2) leaf C storage
   real(r8), pointer :: frootc_storage(:)     ! (gC/m2) fine root C storage
   real(r8), pointer :: livestemc_storage(:)  ! (gC/m2) live stem C storage
   real(r8), pointer :: deadstemc_storage(:)  ! (gC/m2) dead stem C storage
   real(r8), pointer :: livecrootc_storage(:) ! (gC/m2) live coarse root C storage
   real(r8), pointer :: deadcrootc_storage(:) ! (gC/m2) dead coarse root C storage
   real(r8), pointer :: gresp_storage(:)      ! (gC/m2) growth respiration storage
   real(r8), pointer :: leafc_xfer(:)         ! (gC/m2) leaf C transfer
   real(r8), pointer :: frootc_xfer(:)        ! (gC/m2) fine root C transfer
   real(r8), pointer :: livestemc_xfer(:)     ! (gC/m2) live stem C transfer
   real(r8), pointer :: deadstemc_xfer(:)     ! (gC/m2) dead stem C transfer
   real(r8), pointer :: livecrootc_xfer(:)    ! (gC/m2) live coarse root C transfer
   real(r8), pointer :: deadcrootc_xfer(:)    ! (gC/m2) dead coarse root C transfer
   real(r8), pointer :: gresp_xfer(:)         ! (gC/m2) growth respiration transfer
   real(r8), pointer :: leafn(:)              ! (gN/m2) leaf N
   real(r8), pointer :: frootn(:)             ! (gN/m2) fine root N
   real(r8), pointer :: livestemn(:)          ! (gN/m2) live stem N
   real(r8), pointer :: deadstemn(:)          ! (gN/m2) dead stem N
   real(r8), pointer :: livecrootn(:)         ! (gN/m2) live coarse root N
   real(r8), pointer :: deadcrootn(:)         ! (gN/m2) dead coarse root N
   real(r8), pointer :: retransn(:)           ! (gN/m2) plant pool of retranslocated N
   real(r8), pointer :: leafn_storage(:)      ! (gN/m2) leaf N storage
   real(r8), pointer :: frootn_storage(:)     ! (gN/m2) fine root N storage
   real(r8), pointer :: livestemn_storage(:)  ! (gN/m2) live stem N storage
   real(r8), pointer :: deadstemn_storage(:)  ! (gN/m2) dead stem N storage
   real(r8), pointer :: livecrootn_storage(:) ! (gN/m2) live coarse root N storage
   real(r8), pointer :: deadcrootn_storage(:) ! (gN/m2) dead coarse root N storage
   real(r8), pointer :: leafn_xfer(:)         ! (gN/m2) leaf N transfer
   real(r8), pointer :: frootn_xfer(:)        ! (gN/m2) fine root N transfer
   real(r8), pointer :: livestemn_xfer(:)     ! (gN/m2) live stem N transfer
   real(r8), pointer :: deadstemn_xfer(:)     ! (gN/m2) dead stem N transfer
   real(r8), pointer :: livecrootn_xfer(:)    ! (gN/m2) live coarse root N transfer
   real(r8), pointer :: deadcrootn_xfer(:)    ! (gN/m2) dead coarse root N transfer
!
! local pointers to implicit in/out arrays
!
! local pointers to implicit out arrays
   real(r8), pointer :: hrv_leafc_to_litter(:)
   real(r8), pointer :: hrv_frootc_to_litter(:)
   real(r8), pointer :: hrv_livestemc_to_litter(:)
   real(r8), pointer :: hrv_deadstemc_to_prod10c(:)
   real(r8), pointer :: hrv_deadstemc_to_prod100c(:)
   real(r8), pointer :: hrv_livecrootc_to_litter(:)
   real(r8), pointer :: hrv_deadcrootc_to_litter(:)
   real(r8), pointer :: hrv_xsmrpool_to_atm(:)
   real(r8), pointer :: hrv_leafc_storage_to_litter(:)
   real(r8), pointer :: hrv_frootc_storage_to_litter(:)
   real(r8), pointer :: hrv_livestemc_storage_to_litter(:)
   real(r8), pointer :: hrv_deadstemc_storage_to_litter(:)
   real(r8), pointer :: hrv_livecrootc_storage_to_litter(:)
   real(r8), pointer :: hrv_deadcrootc_storage_to_litter(:)
   real(r8), pointer :: hrv_gresp_storage_to_litter(:)
   real(r8), pointer :: hrv_leafc_xfer_to_litter(:)
   real(r8), pointer :: hrv_frootc_xfer_to_litter(:)
   real(r8), pointer :: hrv_livestemc_xfer_to_litter(:)
   real(r8), pointer :: hrv_deadstemc_xfer_to_litter(:)
   real(r8), pointer :: hrv_livecrootc_xfer_to_litter(:)
   real(r8), pointer :: hrv_deadcrootc_xfer_to_litter(:)
   real(r8), pointer :: hrv_gresp_xfer_to_litter(:)
   real(r8), pointer :: hrv_leafn_to_litter(:)
   real(r8), pointer :: hrv_frootn_to_litter(:)
   real(r8), pointer :: hrv_livestemn_to_litter(:)
   real(r8), pointer :: hrv_deadstemn_to_prod10n(:)
   real(r8), pointer :: hrv_deadstemn_to_prod100n(:)
   real(r8), pointer :: hrv_livecrootn_to_litter(:)
   real(r8), pointer :: hrv_deadcrootn_to_litter(:)
   real(r8), pointer :: hrv_retransn_to_litter(:)
   real(r8), pointer :: hrv_leafn_storage_to_litter(:)
   real(r8), pointer :: hrv_frootn_storage_to_litter(:)
   real(r8), pointer :: hrv_livestemn_storage_to_litter(:)
   real(r8), pointer :: hrv_deadstemn_storage_to_litter(:)
   real(r8), pointer :: hrv_livecrootn_storage_to_litter(:)
   real(r8), pointer :: hrv_deadcrootn_storage_to_litter(:)
   real(r8), pointer :: hrv_leafn_xfer_to_litter(:)
   real(r8), pointer :: hrv_frootn_xfer_to_litter(:)
   real(r8), pointer :: hrv_livestemn_xfer_to_litter(:)
   real(r8), pointer :: hrv_deadstemn_xfer_to_litter(:)
   real(r8), pointer :: hrv_livecrootn_xfer_to_litter(:)
   real(r8), pointer :: hrv_deadcrootn_xfer_to_litter(:)
!
! !OTHER LOCAL VARIABLES:
   integer :: p                         ! pft index
   integer :: g                         ! gridcell index
   integer :: fp                        ! pft filter index
   real(r8):: am                        ! rate for fractional harvest mortality (1/yr)
   real(r8):: m                         ! rate for fractional harvest mortality (1/s)
   real(r8):: days_per_year             ! days per year
! KC new variables
   integer:: yr
!EOP
!-----------------------------------------------------------------------

   ! assign local pointers to pft-level arrays
   pgridcell                      => clm3%g%l%c%p%gridcell
   
   ivt                            => clm3%g%l%c%p%itype
   leafc                          => clm3%g%l%c%p%pcs%leafc
   frootc                         => clm3%g%l%c%p%pcs%frootc
   livestemc                      => clm3%g%l%c%p%pcs%livestemc
   deadstemc                      => clm3%g%l%c%p%pcs%deadstemc
   livecrootc                     => clm3%g%l%c%p%pcs%livecrootc
   deadcrootc                     => clm3%g%l%c%p%pcs%deadcrootc
   xsmrpool                       => clm3%g%l%c%p%pcs%xsmrpool
   leafc_storage                  => clm3%g%l%c%p%pcs%leafc_storage
   frootc_storage                 => clm3%g%l%c%p%pcs%frootc_storage
   livestemc_storage              => clm3%g%l%c%p%pcs%livestemc_storage
   deadstemc_storage              => clm3%g%l%c%p%pcs%deadstemc_storage
   livecrootc_storage             => clm3%g%l%c%p%pcs%livecrootc_storage
   deadcrootc_storage             => clm3%g%l%c%p%pcs%deadcrootc_storage
   gresp_storage                  => clm3%g%l%c%p%pcs%gresp_storage
   leafc_xfer                     => clm3%g%l%c%p%pcs%leafc_xfer
   frootc_xfer                    => clm3%g%l%c%p%pcs%frootc_xfer
   livestemc_xfer                 => clm3%g%l%c%p%pcs%livestemc_xfer
   deadstemc_xfer                 => clm3%g%l%c%p%pcs%deadstemc_xfer
   livecrootc_xfer                => clm3%g%l%c%p%pcs%livecrootc_xfer
   deadcrootc_xfer                => clm3%g%l%c%p%pcs%deadcrootc_xfer
   gresp_xfer                     => clm3%g%l%c%p%pcs%gresp_xfer
   leafn                          => clm3%g%l%c%p%pns%leafn
   frootn                         => clm3%g%l%c%p%pns%frootn
   livestemn                      => clm3%g%l%c%p%pns%livestemn
   deadstemn                      => clm3%g%l%c%p%pns%deadstemn
   livecrootn                     => clm3%g%l%c%p%pns%livecrootn
   deadcrootn                     => clm3%g%l%c%p%pns%deadcrootn
   retransn                       => clm3%g%l%c%p%pns%retransn
   leafn_storage                  => clm3%g%l%c%p%pns%leafn_storage
   frootn_storage                 => clm3%g%l%c%p%pns%frootn_storage
   livestemn_storage              => clm3%g%l%c%p%pns%livestemn_storage
   deadstemn_storage              => clm3%g%l%c%p%pns%deadstemn_storage
   livecrootn_storage             => clm3%g%l%c%p%pns%livecrootn_storage
   deadcrootn_storage             => clm3%g%l%c%p%pns%deadcrootn_storage
   leafn_xfer                     => clm3%g%l%c%p%pns%leafn_xfer
   frootn_xfer                    => clm3%g%l%c%p%pns%frootn_xfer
   livestemn_xfer                 => clm3%g%l%c%p%pns%livestemn_xfer
   deadstemn_xfer                 => clm3%g%l%c%p%pns%deadstemn_xfer
   livecrootn_xfer                => clm3%g%l%c%p%pns%livecrootn_xfer
   deadcrootn_xfer                => clm3%g%l%c%p%pns%deadcrootn_xfer
   hrv_leafc_to_litter              => clm3%g%l%c%p%pcf%hrv_leafc_to_litter
   hrv_frootc_to_litter             => clm3%g%l%c%p%pcf%hrv_frootc_to_litter
   hrv_livestemc_to_litter          => clm3%g%l%c%p%pcf%hrv_livestemc_to_litter
   hrv_deadstemc_to_prod10c         => clm3%g%l%c%p%pcf%hrv_deadstemc_to_prod10c
   hrv_deadstemc_to_prod100c        => clm3%g%l%c%p%pcf%hrv_deadstemc_to_prod100c
   hrv_livecrootc_to_litter         => clm3%g%l%c%p%pcf%hrv_livecrootc_to_litter
   hrv_deadcrootc_to_litter         => clm3%g%l%c%p%pcf%hrv_deadcrootc_to_litter
   hrv_xsmrpool_to_atm              => clm3%g%l%c%p%pcf%hrv_xsmrpool_to_atm
   hrv_leafc_storage_to_litter      => clm3%g%l%c%p%pcf%hrv_leafc_storage_to_litter
   hrv_frootc_storage_to_litter     => clm3%g%l%c%p%pcf%hrv_frootc_storage_to_litter
   hrv_livestemc_storage_to_litter  => clm3%g%l%c%p%pcf%hrv_livestemc_storage_to_litter
   hrv_deadstemc_storage_to_litter  => clm3%g%l%c%p%pcf%hrv_deadstemc_storage_to_litter
   hrv_livecrootc_storage_to_litter => clm3%g%l%c%p%pcf%hrv_livecrootc_storage_to_litter
   hrv_deadcrootc_storage_to_litter => clm3%g%l%c%p%pcf%hrv_deadcrootc_storage_to_litter
   hrv_gresp_storage_to_litter      => clm3%g%l%c%p%pcf%hrv_gresp_storage_to_litter
   hrv_leafc_xfer_to_litter         => clm3%g%l%c%p%pcf%hrv_leafc_xfer_to_litter
   hrv_frootc_xfer_to_litter        => clm3%g%l%c%p%pcf%hrv_frootc_xfer_to_litter
   hrv_livestemc_xfer_to_litter     => clm3%g%l%c%p%pcf%hrv_livestemc_xfer_to_litter
   hrv_deadstemc_xfer_to_litter     => clm3%g%l%c%p%pcf%hrv_deadstemc_xfer_to_litter
   hrv_livecrootc_xfer_to_litter    => clm3%g%l%c%p%pcf%hrv_livecrootc_xfer_to_litter
   hrv_deadcrootc_xfer_to_litter    => clm3%g%l%c%p%pcf%hrv_deadcrootc_xfer_to_litter
   hrv_gresp_xfer_to_litter         => clm3%g%l%c%p%pcf%hrv_gresp_xfer_to_litter
   hrv_leafn_to_litter              => clm3%g%l%c%p%pnf%hrv_leafn_to_litter
   hrv_frootn_to_litter             => clm3%g%l%c%p%pnf%hrv_frootn_to_litter
   hrv_livestemn_to_litter          => clm3%g%l%c%p%pnf%hrv_livestemn_to_litter
   hrv_deadstemn_to_prod10n         => clm3%g%l%c%p%pnf%hrv_deadstemn_to_prod10n
   hrv_deadstemn_to_prod100n        => clm3%g%l%c%p%pnf%hrv_deadstemn_to_prod100n
   hrv_livecrootn_to_litter         => clm3%g%l%c%p%pnf%hrv_livecrootn_to_litter
   hrv_deadcrootn_to_litter         => clm3%g%l%c%p%pnf%hrv_deadcrootn_to_litter
   hrv_retransn_to_litter           => clm3%g%l%c%p%pnf%hrv_retransn_to_litter
   hrv_leafn_storage_to_litter      => clm3%g%l%c%p%pnf%hrv_leafn_storage_to_litter
   hrv_frootn_storage_to_litter     => clm3%g%l%c%p%pnf%hrv_frootn_storage_to_litter
   hrv_livestemn_storage_to_litter  => clm3%g%l%c%p%pnf%hrv_livestemn_storage_to_litter
   hrv_deadstemn_storage_to_litter  => clm3%g%l%c%p%pnf%hrv_deadstemn_storage_to_litter
   hrv_livecrootn_storage_to_litter => clm3%g%l%c%p%pnf%hrv_livecrootn_storage_to_litter
   hrv_deadcrootn_storage_to_litter => clm3%g%l%c%p%pnf%hrv_deadcrootn_storage_to_litter
   hrv_leafn_xfer_to_litter         => clm3%g%l%c%p%pnf%hrv_leafn_xfer_to_litter
   hrv_frootn_xfer_to_litter        => clm3%g%l%c%p%pnf%hrv_frootn_xfer_to_litter
   hrv_livestemn_xfer_to_litter     => clm3%g%l%c%p%pnf%hrv_livestemn_xfer_to_litter
   hrv_deadstemn_xfer_to_litter     => clm3%g%l%c%p%pnf%hrv_deadstemn_xfer_to_litter
   hrv_livecrootn_xfer_to_litter    => clm3%g%l%c%p%pnf%hrv_livecrootn_xfer_to_litter
   hrv_deadcrootn_xfer_to_litter    => clm3%g%l%c%p%pnf%hrv_deadcrootn_xfer_to_litter


! KC, calculate dayspyr 1/29/14
   if (mod(yr,4) .eq. 0) then
       days_per_year = 366.
   else
       days_per_year = 365.
   endif

!   days_per_year = get_days_per_year()

! KC end

   ! pft loop
   do fp = 1,num_soilp
      p = filter_soilp(fp)
      g = pgridcell(p)
      
      ! If this is a tree pft, then
      ! get the annual harvest "mortality" rate (am) from harvest array
      ! and convert to rate per second
      if (ivt(p) > noveg .and. ivt(p) < nbrdlf_evr_shrub) then

         if (do_harvest) then
!KC 081114, neglect the effects from harvest for now
!            am = harvest(g)
!            m  = am/(days_per_year * secspday)
             m = 0._r8
!KC end
         else
            m = 0._r8
         end if   

         ! pft-level harvest carbon fluxes
         ! displayed pools
         hrv_leafc_to_litter(p)               = leafc(p)               * m
         hrv_frootc_to_litter(p)              = frootc(p)              * m
         hrv_livestemc_to_litter(p)           = livestemc(p)           * m
         hrv_deadstemc_to_prod10c(p)          = deadstemc(p)           * m * &
                                                pprodharv10(ivt(p))
         hrv_deadstemc_to_prod100c(p)         = deadstemc(p)           * m * &
                                                (1.0_r8 - pprodharv10(ivt(p)))
         hrv_livecrootc_to_litter(p)          = livecrootc(p)          * m
         hrv_deadcrootc_to_litter(p)          = deadcrootc(p)          * m
         hrv_xsmrpool_to_atm(p)               = xsmrpool(p)            * m

         ! storage pools
         hrv_leafc_storage_to_litter(p)       = leafc_storage(p)       * m
         hrv_frootc_storage_to_litter(p)      = frootc_storage(p)      * m
         hrv_livestemc_storage_to_litter(p)   = livestemc_storage(p)   * m
         hrv_deadstemc_storage_to_litter(p)   = deadstemc_storage(p)   * m
         hrv_livecrootc_storage_to_litter(p)  = livecrootc_storage(p)  * m
         hrv_deadcrootc_storage_to_litter(p)  = deadcrootc_storage(p)  * m
         hrv_gresp_storage_to_litter(p)       = gresp_storage(p)       * m

         ! transfer pools
         hrv_leafc_xfer_to_litter(p)          = leafc_xfer(p)          * m
         hrv_frootc_xfer_to_litter(p)         = frootc_xfer(p)         * m
         hrv_livestemc_xfer_to_litter(p)      = livestemc_xfer(p)      * m
         hrv_deadstemc_xfer_to_litter(p)      = deadstemc_xfer(p)      * m
         hrv_livecrootc_xfer_to_litter(p)     = livecrootc_xfer(p)     * m
         hrv_deadcrootc_xfer_to_litter(p)     = deadcrootc_xfer(p)     * m
         hrv_gresp_xfer_to_litter(p)          = gresp_xfer(p)          * m

         ! pft-level harvest mortality nitrogen fluxes
         ! displayed pools
         hrv_leafn_to_litter(p)               = leafn(p)               * m
         hrv_frootn_to_litter(p)              = frootn(p)              * m
         hrv_livestemn_to_litter(p)           = livestemn(p)           * m
         hrv_deadstemn_to_prod10n(p)          = deadstemn(p)           * m * &
                                                pprodharv10(ivt(p))
         hrv_deadstemn_to_prod100n(p)         = deadstemn(p)           * m * &
                                                (1.0_r8 - pprodharv10(ivt(p)))
         hrv_livecrootn_to_litter(p)          = livecrootn(p)          * m
         hrv_deadcrootn_to_litter(p)          = deadcrootn(p)          * m
         hrv_retransn_to_litter(p)            = retransn(p)            * m

         ! storage pools
         hrv_leafn_storage_to_litter(p)       = leafn_storage(p)       * m
         hrv_frootn_storage_to_litter(p)      = frootn_storage(p)      * m
         hrv_livestemn_storage_to_litter(p)   = livestemn_storage(p)   * m
         hrv_deadstemn_storage_to_litter(p)   = deadstemn_storage(p)   * m
         hrv_livecrootn_storage_to_litter(p)  = livecrootn_storage(p)  * m
         hrv_deadcrootn_storage_to_litter(p)  = deadcrootn_storage(p)  * m

         ! transfer pools
         hrv_leafn_xfer_to_litter(p)          = leafn_xfer(p)          * m
         hrv_frootn_xfer_to_litter(p)         = frootn_xfer(p)         * m
         hrv_livestemn_xfer_to_litter(p)      = livestemn_xfer(p)      * m
         hrv_deadstemn_xfer_to_litter(p)      = deadstemn_xfer(p)      * m
         hrv_livecrootn_xfer_to_litter(p)     = livecrootn_xfer(p)     * m
         hrv_deadcrootn_xfer_to_litter(p)     = deadcrootn_xfer(p)     * m
         
      end if  ! end tree block

   end do ! end of pft loop

   ! gather all pft-level litterfall fluxes from harvest to the column
   ! for litter C and N inputs

   call CNHarvestPftToColumn(num_soilc, filter_soilc)

end subroutine CNHarvest
!-----------------------------------------------------------------------

!-----------------------------------------------------------------------
!BOP
!
! !IROUTINE: CNHarvestPftToColumn
!
! !INTERFACE:
subroutine CNHarvestPftToColumn (num_soilc, filter_soilc)
!
! !DESCRIPTION:
! called at the end of CNHarvest to gather all pft-level harvest litterfall fluxes
! to the column level and assign them to the three litter pools
!
! !USES:
  use clmtype45
  use clm_varpar45, only : max_pft_per_col, maxpatch_pft, nlevdecomp
  use pftvarcon45 , only : lf_flab,lf_fcel,lf_flig,fr_flab,fr_fcel,fr_flig
!
! !ARGUMENTS:
  implicit none
  integer, intent(in) :: num_soilc       ! number of soil columns in filter
  integer, intent(in) :: filter_soilc(:) ! soil column filter
!
! !CALLED FROM:
! subroutine CNphenology
!
! !REVISION HISTORY:
! 9/8/03: Created by Peter Thornton
!
! !LOCAL VARIABLES:
!
! local pointers to implicit in scalars
   logical , pointer :: pactive(:)  ! true=>do computations on this pft (see reweightMod for details)
   integer , pointer :: ivt(:)      ! pft vegetation type
   real(r8), pointer :: wtcol(:)    ! pft weight relative to column (0-1)
!   real(r8), pointer :: lf_flab(:)  ! leaf litter labile fraction
!   real(r8), pointer :: lf_fcel(:)  ! leaf litter cellulose fraction
!   real(r8), pointer :: lf_flig(:)  ! leaf litter lignin fraction
!   real(r8), pointer :: fr_flab(:)  ! fine root litter labile fraction
!   real(r8), pointer :: fr_fcel(:)  ! fine root litter cellulose fraction
!   real(r8), pointer :: fr_flig(:)  ! fine root litter lignin fraction
   integer , pointer :: npfts(:)    ! number of pfts for each column
   integer , pointer :: pfti(:)     ! beginning pft index for each column
   real(r8), pointer :: hrv_leafc_to_litter(:)
   real(r8), pointer :: hrv_frootc_to_litter(:)
   real(r8), pointer :: hrv_livestemc_to_litter(:)
   real(r8), pointer :: phrv_deadstemc_to_prod10c(:)
   real(r8), pointer :: phrv_deadstemc_to_prod100c(:)
   real(r8), pointer :: hrv_livecrootc_to_litter(:)
   real(r8), pointer :: hrv_deadcrootc_to_litter(:)
   real(r8), pointer :: hrv_leafc_storage_to_litter(:)
   real(r8), pointer :: hrv_frootc_storage_to_litter(:)
   real(r8), pointer :: hrv_livestemc_storage_to_litter(:)
   real(r8), pointer :: hrv_deadstemc_storage_to_litter(:)
   real(r8), pointer :: hrv_livecrootc_storage_to_litter(:)
   real(r8), pointer :: hrv_deadcrootc_storage_to_litter(:)
   real(r8), pointer :: hrv_gresp_storage_to_litter(:)
   real(r8), pointer :: hrv_leafc_xfer_to_litter(:)
   real(r8), pointer :: hrv_frootc_xfer_to_litter(:)
   real(r8), pointer :: hrv_livestemc_xfer_to_litter(:)
   real(r8), pointer :: hrv_deadstemc_xfer_to_litter(:)
   real(r8), pointer :: hrv_livecrootc_xfer_to_litter(:)
   real(r8), pointer :: hrv_deadcrootc_xfer_to_litter(:)
   real(r8), pointer :: hrv_gresp_xfer_to_litter(:)
   real(r8), pointer :: hrv_leafn_to_litter(:)
   real(r8), pointer :: hrv_frootn_to_litter(:)
   real(r8), pointer :: hrv_livestemn_to_litter(:)
   real(r8), pointer :: phrv_deadstemn_to_prod10n(:)
   real(r8), pointer :: phrv_deadstemn_to_prod100n(:)
   real(r8), pointer :: hrv_livecrootn_to_litter(:)
   real(r8), pointer :: hrv_deadcrootn_to_litter(:)
   real(r8), pointer :: hrv_retransn_to_litter(:)
   real(r8), pointer :: hrv_leafn_storage_to_litter(:)
   real(r8), pointer :: hrv_frootn_storage_to_litter(:)
   real(r8), pointer :: hrv_livestemn_storage_to_litter(:)
   real(r8), pointer :: hrv_deadstemn_storage_to_litter(:)
   real(r8), pointer :: hrv_livecrootn_storage_to_litter(:)
   real(r8), pointer :: hrv_deadcrootn_storage_to_litter(:)
   real(r8), pointer :: hrv_leafn_xfer_to_litter(:)
   real(r8), pointer :: hrv_frootn_xfer_to_litter(:)
   real(r8), pointer :: hrv_livestemn_xfer_to_litter(:)
   real(r8), pointer :: hrv_deadstemn_xfer_to_litter(:)
   real(r8), pointer :: hrv_livecrootn_xfer_to_litter(:)
   real(r8), pointer :: hrv_deadcrootn_xfer_to_litter(:)
   real(r8), pointer :: harvest_c_to_litr_met_c(:,:)               ! C fluxes associated with harvest to litter metabolic pool (gC/m3/s)
   real(r8), pointer :: harvest_c_to_litr_cel_c(:,:)               ! C fluxes associated with harvest to litter cellulose pool (gC/m3/s)
   real(r8), pointer :: harvest_c_to_litr_lig_c(:,:)               ! C fluxes associated with harvest to litter lignin pool (gC/m3/s)
   real(r8), pointer :: harvest_c_to_cwdc(:,:)                     ! C fluxes associated with harvest to CWD pool (gC/m3/s)
   real(r8), pointer :: harvest_n_to_litr_met_n(:,:)               ! N fluxes associated with harvest to litter metabolic pool (gN/m3/s)
   real(r8), pointer :: harvest_n_to_litr_cel_n(:,:)               ! N fluxes associated with harvest to litter cellulose pool (gN/m3/s)
   real(r8), pointer :: harvest_n_to_litr_lig_n(:,:)               ! N fluxes associated with harvest to litter lignin pool (gN/m3/s)
   real(r8), pointer :: harvest_n_to_cwdn(:,:)                     ! N fluxes associated with harvest to CWD pool (gN/m3/s)
!
! local pointers to implicit in/out arrays
   real(r8), pointer :: chrv_deadstemc_to_prod10c(:)
   real(r8), pointer :: chrv_deadstemc_to_prod100c(:)
   real(r8), pointer :: chrv_deadstemn_to_prod10n(:)
   real(r8), pointer :: chrv_deadstemn_to_prod100n(:)
   real(r8), pointer :: leaf_prof(:,:)          ! (1/m) profile of leaves
   real(r8), pointer :: froot_prof(:,:)         ! (1/m) profile of fine roots
   real(r8), pointer :: croot_prof(:,:)         ! (1/m) profile of coarse roots
   real(r8), pointer :: stem_prof(:,:)          ! (1/m) profile of stems
!
! local pointers to implicit out arrays
!
!
! !OTHER LOCAL VARIABLES:
   integer :: fc,c,pi,p,j               ! indices
!EOP
!-----------------------------------------------------------------------

   ! assign local pointers
!   lf_flab                        => pftcon%lf_flab
!   lf_fcel                        => pftcon%lf_fcel
!   lf_flig                        => pftcon%lf_flig
!   fr_flab                        => pftcon%fr_flab
!   fr_fcel                        => pftcon%fr_fcel
!   fr_flig                        => pftcon%fr_flig

   ! assign local pointers to column-level arrays
   npfts                          => clm3%g%l%c%npfts
   pfti                           => clm3%g%l%c%pfti
   chrv_deadstemc_to_prod10c        => clm3%g%l%c%ccf%hrv_deadstemc_to_prod10c
   chrv_deadstemc_to_prod100c       => clm3%g%l%c%ccf%hrv_deadstemc_to_prod100c
   chrv_deadstemn_to_prod10n        => clm3%g%l%c%cnf%hrv_deadstemn_to_prod10n
   chrv_deadstemn_to_prod100n       => clm3%g%l%c%cnf%hrv_deadstemn_to_prod100n
   harvest_c_to_litr_met_c          => clm3%g%l%c%ccf%harvest_c_to_litr_met_c
   harvest_c_to_litr_cel_c          => clm3%g%l%c%ccf%harvest_c_to_litr_cel_c
   harvest_c_to_litr_lig_c          => clm3%g%l%c%ccf%harvest_c_to_litr_lig_c
   harvest_c_to_cwdc                => clm3%g%l%c%ccf%harvest_c_to_cwdc
   harvest_n_to_litr_met_n          => clm3%g%l%c%cnf%harvest_n_to_litr_met_n
   harvest_n_to_litr_cel_n          => clm3%g%l%c%cnf%harvest_n_to_litr_cel_n
   harvest_n_to_litr_lig_n          => clm3%g%l%c%cnf%harvest_n_to_litr_lig_n
   harvest_n_to_cwdn                => clm3%g%l%c%cnf%harvest_n_to_cwdn


   ! assign local pointers to pft-level arrays
   pactive                        => clm3%g%l%c%p%active
   ivt                            => clm3%g%l%c%p%itype
   wtcol                          => clm3%g%l%c%p%wtcol
   hrv_leafc_to_litter              => clm3%g%l%c%p%pcf%hrv_leafc_to_litter
   hrv_frootc_to_litter             => clm3%g%l%c%p%pcf%hrv_frootc_to_litter
   hrv_livestemc_to_litter          => clm3%g%l%c%p%pcf%hrv_livestemc_to_litter
   phrv_deadstemc_to_prod10c        => clm3%g%l%c%p%pcf%hrv_deadstemc_to_prod10c
   phrv_deadstemc_to_prod100c       => clm3%g%l%c%p%pcf%hrv_deadstemc_to_prod100c
   hrv_livecrootc_to_litter         => clm3%g%l%c%p%pcf%hrv_livecrootc_to_litter
   hrv_deadcrootc_to_litter         => clm3%g%l%c%p%pcf%hrv_deadcrootc_to_litter
   hrv_leafc_storage_to_litter      => clm3%g%l%c%p%pcf%hrv_leafc_storage_to_litter
   hrv_frootc_storage_to_litter     => clm3%g%l%c%p%pcf%hrv_frootc_storage_to_litter
   hrv_livestemc_storage_to_litter  => clm3%g%l%c%p%pcf%hrv_livestemc_storage_to_litter
   hrv_deadstemc_storage_to_litter  => clm3%g%l%c%p%pcf%hrv_deadstemc_storage_to_litter
   hrv_livecrootc_storage_to_litter => clm3%g%l%c%p%pcf%hrv_livecrootc_storage_to_litter
   hrv_deadcrootc_storage_to_litter => clm3%g%l%c%p%pcf%hrv_deadcrootc_storage_to_litter
   hrv_gresp_storage_to_litter      => clm3%g%l%c%p%pcf%hrv_gresp_storage_to_litter
   hrv_leafc_xfer_to_litter         => clm3%g%l%c%p%pcf%hrv_leafc_xfer_to_litter
   hrv_frootc_xfer_to_litter        => clm3%g%l%c%p%pcf%hrv_frootc_xfer_to_litter
   hrv_livestemc_xfer_to_litter     => clm3%g%l%c%p%pcf%hrv_livestemc_xfer_to_litter
   hrv_deadstemc_xfer_to_litter     => clm3%g%l%c%p%pcf%hrv_deadstemc_xfer_to_litter
   hrv_livecrootc_xfer_to_litter    => clm3%g%l%c%p%pcf%hrv_livecrootc_xfer_to_litter
   hrv_deadcrootc_xfer_to_litter    => clm3%g%l%c%p%pcf%hrv_deadcrootc_xfer_to_litter
   hrv_gresp_xfer_to_litter         => clm3%g%l%c%p%pcf%hrv_gresp_xfer_to_litter
   hrv_leafn_to_litter              => clm3%g%l%c%p%pnf%hrv_leafn_to_litter
   hrv_frootn_to_litter             => clm3%g%l%c%p%pnf%hrv_frootn_to_litter
   hrv_livestemn_to_litter          => clm3%g%l%c%p%pnf%hrv_livestemn_to_litter
   phrv_deadstemn_to_prod10n        => clm3%g%l%c%p%pnf%hrv_deadstemn_to_prod10n
   phrv_deadstemn_to_prod100n       => clm3%g%l%c%p%pnf%hrv_deadstemn_to_prod100n
   hrv_livecrootn_to_litter         => clm3%g%l%c%p%pnf%hrv_livecrootn_to_litter
   hrv_deadcrootn_to_litter         => clm3%g%l%c%p%pnf%hrv_deadcrootn_to_litter
   hrv_retransn_to_litter           => clm3%g%l%c%p%pnf%hrv_retransn_to_litter
   hrv_leafn_storage_to_litter      => clm3%g%l%c%p%pnf%hrv_leafn_storage_to_litter
   hrv_frootn_storage_to_litter     => clm3%g%l%c%p%pnf%hrv_frootn_storage_to_litter
   hrv_livestemn_storage_to_litter  => clm3%g%l%c%p%pnf%hrv_livestemn_storage_to_litter
   hrv_deadstemn_storage_to_litter  => clm3%g%l%c%p%pnf%hrv_deadstemn_storage_to_litter
   hrv_livecrootn_storage_to_litter => clm3%g%l%c%p%pnf%hrv_livecrootn_storage_to_litter
   hrv_deadcrootn_storage_to_litter => clm3%g%l%c%p%pnf%hrv_deadcrootn_storage_to_litter
   hrv_leafn_xfer_to_litter         => clm3%g%l%c%p%pnf%hrv_leafn_xfer_to_litter
   hrv_frootn_xfer_to_litter        => clm3%g%l%c%p%pnf%hrv_frootn_xfer_to_litter
   hrv_livestemn_xfer_to_litter     => clm3%g%l%c%p%pnf%hrv_livestemn_xfer_to_litter
   hrv_deadstemn_xfer_to_litter     => clm3%g%l%c%p%pnf%hrv_deadstemn_xfer_to_litter
   hrv_livecrootn_xfer_to_litter    => clm3%g%l%c%p%pnf%hrv_livecrootn_xfer_to_litter
   hrv_deadcrootn_xfer_to_litter    => clm3%g%l%c%p%pnf%hrv_deadcrootn_xfer_to_litter
   leaf_prof                      => clm3%g%l%c%p%pps%leaf_prof
   froot_prof                     => clm3%g%l%c%p%pps%froot_prof
   croot_prof                     => clm3%g%l%c%p%pps%croot_prof
   stem_prof                      => clm3%g%l%c%p%pps%stem_prof

   do j = 1, nlevdecomp
      do pi = 1,maxpatch_pft
         do fc = 1,num_soilc
            c = filter_soilc(fc)
            
            if (pi <=  npfts(c)) then
               p = pfti(c) + pi - 1
              ! KC
!    wtcol(p) = 1.0
              ! KC end
 
               if (pactive(p)) then
                  
                  
                  ! leaf harvest mortality carbon fluxes
                  harvest_c_to_litr_met_c(c,j) = harvest_c_to_litr_met_c(c,j) + &
                       hrv_leafc_to_litter(p) * lf_flab(ivt(p)) * wtcol(p) * leaf_prof(p,j)
                  harvest_c_to_litr_cel_c(c,j) = harvest_c_to_litr_cel_c(c,j) + &
                       hrv_leafc_to_litter(p) * lf_fcel(ivt(p)) * wtcol(p) * leaf_prof(p,j)
                  harvest_c_to_litr_lig_c(c,j) = harvest_c_to_litr_lig_c(c,j) + &
                       hrv_leafc_to_litter(p) * lf_flig(ivt(p)) * wtcol(p) * leaf_prof(p,j)
                  
                  ! fine root harvest mortality carbon fluxes
                  harvest_c_to_litr_met_c(c,j) = harvest_c_to_litr_met_c(c,j) + &
                       hrv_frootc_to_litter(p) * fr_flab(ivt(p)) * wtcol(p) * froot_prof(p,j)
                  harvest_c_to_litr_cel_c(c,j) = harvest_c_to_litr_cel_c(c,j) + &
                       hrv_frootc_to_litter(p) * fr_fcel(ivt(p)) * wtcol(p) * froot_prof(p,j)
                  harvest_c_to_litr_lig_c(c,j) = harvest_c_to_litr_lig_c(c,j) + &
                       hrv_frootc_to_litter(p) * fr_flig(ivt(p)) * wtcol(p) * froot_prof(p,j)
                  
                  ! wood harvest mortality carbon fluxes
                  harvest_c_to_cwdc(c,j)  = harvest_c_to_cwdc(c,j)  + &
                       hrv_livestemc_to_litter(p)  * wtcol(p) * stem_prof(p,j) 
                  harvest_c_to_cwdc(c,j) = harvest_c_to_cwdc(c,j) + &
                       hrv_livecrootc_to_litter(p) * wtcol(p) * croot_prof(p,j)
                  harvest_c_to_cwdc(c,j) = harvest_c_to_cwdc(c,j) + &
                       hrv_deadcrootc_to_litter(p) * wtcol(p) * croot_prof(p,j) 
                  
                  ! storage harvest mortality carbon fluxes
                  harvest_c_to_litr_met_c(c,j)      = harvest_c_to_litr_met_c(c,j)      + &
                       hrv_leafc_storage_to_litter(p)      * wtcol(p) * leaf_prof(p,j)
                  harvest_c_to_litr_met_c(c,j)     = harvest_c_to_litr_met_c(c,j)     + &
                       hrv_frootc_storage_to_litter(p)     * wtcol(p) * froot_prof(p,j)
                  harvest_c_to_litr_met_c(c,j)  = harvest_c_to_litr_met_c(c,j)  + &
                       hrv_livestemc_storage_to_litter(p)  * wtcol(p) * stem_prof(p,j)
                  harvest_c_to_litr_met_c(c,j)  = harvest_c_to_litr_met_c(c,j)  + &
                       hrv_deadstemc_storage_to_litter(p)  * wtcol(p) * stem_prof(p,j)
                  harvest_c_to_litr_met_c(c,j) = harvest_c_to_litr_met_c(c,j) + &
                       hrv_livecrootc_storage_to_litter(p) * wtcol(p) * croot_prof(p,j)
                  harvest_c_to_litr_met_c(c,j) = harvest_c_to_litr_met_c(c,j) + &
                       hrv_deadcrootc_storage_to_litter(p) * wtcol(p) * croot_prof(p,j)
                  harvest_c_to_litr_met_c(c,j)      = harvest_c_to_litr_met_c(c,j)      + &
                       hrv_gresp_storage_to_litter(p)      * wtcol(p) * leaf_prof(p,j)
                  
                  ! transfer harvest mortality carbon fluxes
                  harvest_c_to_litr_met_c(c,j)      = harvest_c_to_litr_met_c(c,j)      + &
                       hrv_leafc_xfer_to_litter(p)      * wtcol(p) * leaf_prof(p,j)
                  harvest_c_to_litr_met_c(c,j)     = harvest_c_to_litr_met_c(c,j)     + &
                       hrv_frootc_xfer_to_litter(p)     * wtcol(p) * froot_prof(p,j)
                  harvest_c_to_litr_met_c(c,j)  = harvest_c_to_litr_met_c(c,j)  + &
                       hrv_livestemc_xfer_to_litter(p)  * wtcol(p) * stem_prof(p,j)
                  harvest_c_to_litr_met_c(c,j)  = harvest_c_to_litr_met_c(c,j)  + &
                       hrv_deadstemc_xfer_to_litter(p)  * wtcol(p) * stem_prof(p,j)
                  harvest_c_to_litr_met_c(c,j) = harvest_c_to_litr_met_c(c,j) + &
                       hrv_livecrootc_xfer_to_litter(p) * wtcol(p) * croot_prof(p,j)
                  harvest_c_to_litr_met_c(c,j) = harvest_c_to_litr_met_c(c,j) + &
                       hrv_deadcrootc_xfer_to_litter(p) * wtcol(p) * croot_prof(p,j)
                  harvest_c_to_litr_met_c(c,j)      = harvest_c_to_litr_met_c(c,j)      + &
                       hrv_gresp_xfer_to_litter(p)      * wtcol(p) * leaf_prof(p,j)
                  
                  ! leaf harvest mortality nitrogen fluxes
                  harvest_n_to_litr_met_n(c,j) = harvest_n_to_litr_met_n(c,j) + &
                       hrv_leafn_to_litter(p) * lf_flab(ivt(p)) * wtcol(p) * leaf_prof(p,j)
                  harvest_n_to_litr_cel_n(c,j) = harvest_n_to_litr_cel_n(c,j) + &
                       hrv_leafn_to_litter(p) * lf_fcel(ivt(p)) * wtcol(p) * leaf_prof(p,j)
                  harvest_n_to_litr_lig_n(c,j) = harvest_n_to_litr_lig_n(c,j) + &
                       hrv_leafn_to_litter(p) * lf_flig(ivt(p)) * wtcol(p) * leaf_prof(p,j)
                  
                  ! fine root litter nitrogen fluxes
                  harvest_n_to_litr_met_n(c,j) = harvest_n_to_litr_met_n(c,j) + &
                       hrv_frootn_to_litter(p) * fr_flab(ivt(p)) * wtcol(p) * froot_prof(p,j)
                  harvest_n_to_litr_cel_n(c,j) = harvest_n_to_litr_cel_n(c,j) + &
                       hrv_frootn_to_litter(p) * fr_fcel(ivt(p)) * wtcol(p) * froot_prof(p,j)
                  harvest_n_to_litr_lig_n(c,j) = harvest_n_to_litr_lig_n(c,j) + &
                       hrv_frootn_to_litter(p) * fr_flig(ivt(p)) * wtcol(p) * froot_prof(p,j)
                  
                  ! wood harvest mortality nitrogen fluxes
                  harvest_n_to_cwdn(c,j)  = harvest_n_to_cwdn(c,j)  + &
                       hrv_livestemn_to_litter(p)  * wtcol(p) * stem_prof(p,j)
                  harvest_n_to_cwdn(c,j) = harvest_n_to_cwdn(c,j) + &
                       hrv_livecrootn_to_litter(p) * wtcol(p) * croot_prof(p,j)
                  harvest_n_to_cwdn(c,j) = harvest_n_to_cwdn(c,j) + &
                       hrv_deadcrootn_to_litter(p) * wtcol(p) * croot_prof(p,j)
                  
                  ! retranslocated N pool harvest mortality fluxes
                  harvest_n_to_litr_met_n(c,j) = harvest_n_to_litr_met_n(c,j) + &
                       hrv_retransn_to_litter(p) * wtcol(p) * leaf_prof(p,j)
                  
                  ! storage harvest mortality nitrogen fluxes
                  harvest_n_to_litr_met_n(c,j)      = harvest_n_to_litr_met_n(c,j)      + &
                       hrv_leafn_storage_to_litter(p)      * wtcol(p) * leaf_prof(p,j)
                  harvest_n_to_litr_met_n(c,j)     = harvest_n_to_litr_met_n(c,j)     + &
                       hrv_frootn_storage_to_litter(p)     * wtcol(p) * froot_prof(p,j)
                  harvest_n_to_litr_met_n(c,j)  = harvest_n_to_litr_met_n(c,j)  + &
                       hrv_livestemn_storage_to_litter(p)  * wtcol(p) * stem_prof(p,j)
                  harvest_n_to_litr_met_n(c,j)  = harvest_n_to_litr_met_n(c,j)  + &
                       hrv_deadstemn_storage_to_litter(p)  * wtcol(p) * stem_prof(p,j)
                  harvest_n_to_litr_met_n(c,j) = harvest_n_to_litr_met_n(c,j) + &
                       hrv_livecrootn_storage_to_litter(p) * wtcol(p) * croot_prof(p,j)
                  harvest_n_to_litr_met_n(c,j) = harvest_n_to_litr_met_n(c,j) + &
                       hrv_deadcrootn_storage_to_litter(p) * wtcol(p) * croot_prof(p,j)
                  
                  ! transfer harvest mortality nitrogen fluxes
                  harvest_n_to_litr_met_n(c,j)      = harvest_n_to_litr_met_n(c,j)      + &
                       hrv_leafn_xfer_to_litter(p)      * wtcol(p) * leaf_prof(p,j)
                  harvest_n_to_litr_met_n(c,j)     = harvest_n_to_litr_met_n(c,j)     + &
                       hrv_frootn_xfer_to_litter(p)     * wtcol(p) * froot_prof(p,j)
                  harvest_n_to_litr_met_n(c,j)  = harvest_n_to_litr_met_n(c,j)  + &
                       hrv_livestemn_xfer_to_litter(p)  * wtcol(p) * stem_prof(p,j)
                  harvest_n_to_litr_met_n(c,j)  = harvest_n_to_litr_met_n(c,j)  + &
                       hrv_deadstemn_xfer_to_litter(p)  * wtcol(p) * stem_prof(p,j)
                  harvest_n_to_litr_met_n(c,j) = harvest_n_to_litr_met_n(c,j) + &
                       hrv_livecrootn_xfer_to_litter(p) * wtcol(p) * croot_prof(p,j)
                  harvest_n_to_litr_met_n(c,j) = harvest_n_to_litr_met_n(c,j) + &
                       hrv_deadcrootn_xfer_to_litter(p) * wtcol(p) * croot_prof(p,j)
                  
               end if
            end if
            
         end do
         
      end do
   end do
   
   do pi = 1,maxpatch_pft
      do fc = 1,num_soilc
         c = filter_soilc(fc)
         
         if (pi <=  npfts(c)) then
            p = pfti(c) + pi - 1
           ! KC
!    wtcol(p) = 1.0
           ! KC end
 
            if (pactive(p)) then
               
               
               ! wood harvest mortality carbon fluxes to product pools
               chrv_deadstemc_to_prod10c(c)  = chrv_deadstemc_to_prod10c(c)  + &
                    phrv_deadstemc_to_prod10c(p)  * wtcol(p)
               chrv_deadstemc_to_prod100c(c)  = chrv_deadstemc_to_prod100c(c)  + &
                    phrv_deadstemc_to_prod100c(p)  * wtcol(p)
               
               
               ! wood harvest mortality nitrogen fluxes to product pools
               chrv_deadstemn_to_prod10n(c)  = chrv_deadstemn_to_prod10n(c)  + &
                    phrv_deadstemn_to_prod10n(p)  * wtcol(p)
               chrv_deadstemn_to_prod100n(c)  = chrv_deadstemn_to_prod100n(c)  + &
                    phrv_deadstemn_to_prod100n(p)  * wtcol(p)
            end if
         end if
         
      end do
      
   end do
   
 end subroutine CNHarvestPftToColumn
!-----------------------------------------------------------------------
!#endif

end module pftdynmod_ACASA

module tridiagonalmod_ACASA

!-----------------------------------------------------------------------
!BOP
!
! !MODULE: tridiagonalmod_ACASA
!
! !DESCRIPTION:
! Tridiagonal matrix solution
!
! !PUBLIC TYPES:
  implicit none
  save
!
! !PUBLIC MEMBER FUNCTIONS:
  public :: Tridiagonal
!
! !REVISION HISTORY:
! Created by Mariana Vertenstein
!
!EOP
!-----------------------------------------------------------------------

contains

!-----------------------------------------------------------------------
!BOP
!
! !IROUTINE: Tridiagonal
!
! !INTERFACE:
  subroutine Tridiagonal (lbc, ubc, lbj, ubj, jtop, numf, filter, &
                          a, b, c, r, u)
!
! !DESCRIPTION:
! Tridiagonal matrix solution
!
! !USES:
    use shr_kind_mod, only: r8 => shr_kind_r8
    use clmtype45
    use clm_varpar45    , only : nlevurb
    use clm_varcon45    , only : icol_roof, icol_sunwall, icol_shadewall
!    use clm_varctl    , only : iulog
!
! !ARGUMENTS:
    implicit none
    integer , intent(in)    :: lbc, ubc               ! lbinning and ubing column indices
    integer , intent(in)    :: lbj, ubj               ! lbinning and ubing level indices
    integer , intent(in)    :: jtop(lbc:ubc)          ! top level for each column
    integer , intent(in)    :: numf                   ! filter dimension
    integer , intent(in)    :: filter(1:numf)         ! filter
    real(r8), intent(in)    :: a(lbc:ubc, lbj:ubj)    ! "a" left off diagonal of tridiagonal matrix
    real(r8), intent(in)    :: b(lbc:ubc, lbj:ubj)    ! "b" diagonal column for tridiagonal matrix
    real(r8), intent(in)    :: c(lbc:ubc, lbj:ubj)    ! "c" right off diagonal tridiagonal matrix
    real(r8), intent(in)    :: r(lbc:ubc, lbj:ubj)    ! "r" forcing term of tridiagonal matrix
    real(r8), intent(inout) :: u(lbc:ubc, lbj:ubj)    ! solution
! local pointers to original implicit in arguments
!
    integer , pointer :: ctype(:)           ! column type

!
! !CALLED FROM:
! subroutine BiogeophysicsLake in module BiogeophysicsLakeMod
! subroutine SoilTemperature in module SoilTemperatureMod
! subroutine SoilWater in module HydrologyMod
!
! !REVISION HISTORY:
! 15 September 1999: Yongjiu Dai; Initial code
! 15 December 1999:  Paul Houser and Jon Radakovich; F90 Revision
!  1 July 2003: Mariana Vertenstein; modified for vectorization
!
!
! !OTHER LOCAL VARIABLES:
!EOP
!
    integer  :: j,ci,fc                   !indices
    real(r8) :: gam(lbc:ubc,lbj:ubj)      !temporary
    real(r8) :: bet(lbc:ubc)              !temporary
!-----------------------------------------------------------------------

    ! Assign local pointers to derived subtypes components (column-level)

    ctype          => clm3%g%l%c%itype

    ! Solve the matrix

    do fc = 1,numf
       ci = filter(fc)
       bet(ci) = b(ci,jtop(ci))
    end do

    do j = lbj, ubj
       do fc = 1,numf
          ci = filter(fc)
          if ((ctype(ci) == icol_sunwall .or. ctype(ci) == icol_shadewall &
              .or. ctype(ci) == icol_roof) .and. j <= nlevurb) then
             if (j >= jtop(ci)) then
                if (j == jtop(ci)) then
                   u(ci,j) = r(ci,j) / bet(ci)
                else
                   gam(ci,j) = c(ci,j-1) / bet(ci)
                   bet(ci) = b(ci,j) - a(ci,j) * gam(ci,j)
                   u(ci,j) = (r(ci,j) - a(ci,j)*u(ci,j-1)) / bet(ci)
                end if
             end if
          else if (ctype(ci) /= icol_sunwall .and. ctype(ci) /= icol_shadewall &
                   .and. ctype(ci) /= icol_roof) then
             if (j >= jtop(ci)) then
                if (j == jtop(ci)) then
                   u(ci,j) = r(ci,j) / bet(ci)
                else
                   gam(ci,j) = c(ci,j-1) / bet(ci)
                   bet(ci) = b(ci,j) - a(ci,j) * gam(ci,j)
                   u(ci,j) = (r(ci,j) - a(ci,j)*u(ci,j-1)) / bet(ci)
                end if
             end if
          end if
       end do
    end do

    do j = ubj-1,lbj,-1
       do fc = 1,numf
          ci = filter(fc)
          if ((ctype(ci) == icol_sunwall .or. ctype(ci) == icol_shadewall &
              .or. ctype(ci) == icol_roof) .and. j <= nlevurb-1) then
             if (j >= jtop(ci)) then
                u(ci,j) = u(ci,j) - gam(ci,j+1) * u(ci,j+1)
             end if
          else if (ctype(ci) /= icol_sunwall .and. ctype(ci) /= icol_shadewall &
                   .and. ctype(ci) /= icol_roof) then
             if (j >= jtop(ci)) then
                u(ci,j) = u(ci,j) - gam(ci,j+1) * u(ci,j+1)
             end if
          end if
       end do
    end do

  end subroutine Tridiagonal

end module tridiagonalmod_ACASA


module cnwoodproductsmod_ACASA
!#ifdef CN

!-----------------------------------------------------------------------
!BOP
!
! !MODULE: cnwoodproductsmod_ACASA
!
! !DESCRIPTION:
! Calculate loss fluxes from wood products pools, and update product pool state variables
!
! !USES:
!    use decompmod_ACASA   , only : get_proc_bounds
    use shr_kind_mod, only: r8 => shr_kind_r8
    use clm_varcon45  , only: istsoil
!    use spmdMod     , only: masterproc
    implicit none
    save
    private
! !PUBLIC MEMBER FUNCTIONS:
    public:: CNWoodProducts
!
! !REVISION HISTORY:
! 5/20/2009: Created by Peter Thornton
!
!EOP
!-----------------------------------------------------------------------

contains

!-----------------------------------------------------------------------
!BOP
!
! !IROUTINE: CNWoodProducts
!
! !INTERFACE:
subroutine CNWoodProducts(num_soilc, filter_soilc,dt)
!
! !DESCRIPTION:
! Update all loss fluxes from wood product pools, and update product pool state variables
! for both loss and gain terms.  Gain terms are calculated in pftdyn_cnbal() for gains associated
! with changes in landcover, and in CNHarvest(), for gains associated with wood harvest.
!
! !USES:
  use clmtype45
!  use clm_time_manager, only: get_step_size
!  use clm_varctl, only: use_c13, use_c14
!
! !ARGUMENTS:
  implicit none
  integer, intent(in) :: num_soilc       ! number of soil columns in filter
  integer, intent(in) :: filter_soilc(:) ! filter for soil columns
!
! !CALLED FROM:
! subroutine CNEcosystemDyn
!
! !REVISION HISTORY:
! 5/21/09: Created by Peter Thornton
!
! !LOCAL VARIABLES:

  integer :: fc        ! lake filter indices
  integer :: c         ! indices
  real(r8):: dt        ! time step (seconds)
  type(column_type),   pointer :: cptr         ! pointer to column derived subtype
  real(r8) :: kprod10       ! decay constant for 10-year product pool
  real(r8) :: kprod100      ! decay constant for 100-year product pool

!EOP
!-----------------------------------------------------------------------

  cptr => clm3%g%l%c
  
  ! calculate column-level losses from product pools
  ! the following (1/s) rate constants result in ~90% loss of initial state over 10 and 100 years,
  ! respectively, using a discrete-time fractional decay algorithm.
  kprod10 = 7.2e-9
  kprod100 = 7.2e-10
  
  do fc = 1,num_soilc
     c = filter_soilc(fc)
     
     ! calculate fluxes (1/sec)
     cptr%ccf%prod10c_loss(c)    = cptr%ccs%prod10c(c)    * kprod10
     cptr%ccf%prod100c_loss(c)   = cptr%ccs%prod100c(c)   * kprod100
     
!     if ( use_c13 ) then
!        cptr%cc13f%prod10c_loss(c)  = cptr%cc13s%prod10c(c)  * kprod10
!        cptr%cc13f%prod100c_loss(c) = cptr%cc13s%prod100c(c) * kprod100
!     endif
     
!     if ( use_c14 ) then
!        cptr%cc14f%prod10c_loss(c)  = cptr%cc14s%prod10c(c)  * kprod10
!        cptr%cc14f%prod100c_loss(c) = cptr%cc14s%prod100c(c) * kprod100
!     endif

     cptr%cnf%prod10n_loss(c)    = cptr%cns%prod10n(c)    * kprod10
     cptr%cnf%prod100n_loss(c)   = cptr%cns%prod100n(c)   * kprod100
  end do
  
  ! set time steps
!  dt = real( get_step_size(), r8 )
  
  ! update wood product state variables
  ! column loop
  do fc = 1,num_soilc
     c = filter_soilc(fc)
     
     ! column-level fluxes
     
     ! fluxes into wood product pools, from landcover change
     cptr%ccs%prod10c(c)    = cptr%ccs%prod10c(c)    + cptr%ccf%dwt_prod10c_gain(c)*dt
     cptr%ccs%prod100c(c)   = cptr%ccs%prod100c(c)   + cptr%ccf%dwt_prod100c_gain(c)*dt

!     if ( use_c13 ) then
!        cptr%cc13s%prod10c(c)  = cptr%cc13s%prod10c(c)  + cptr%cc13f%dwt_prod10c_gain(c)*dt
!        cptr%cc13s%prod100c(c) = cptr%cc13s%prod100c(c) + cptr%cc13f%dwt_prod100c_gain(c)*dt
!     endif

!     if ( use_c14 ) then
!        cptr%cc14s%prod10c(c)  = cptr%cc14s%prod10c(c)  + cptr%cc14f%dwt_prod10c_gain(c)*dt
!        cptr%cc14s%prod100c(c) = cptr%cc14s%prod100c(c) + cptr%cc14f%dwt_prod100c_gain(c)*dt
!     endif

     cptr%cns%prod10n(c)    = cptr%cns%prod10n(c)    + cptr%cnf%dwt_prod10n_gain(c)*dt
     cptr%cns%prod100n(c)   = cptr%cns%prod100n(c)   + cptr%cnf%dwt_prod100n_gain(c)*dt
     
     ! fluxes into wood product pools, from harvest
     cptr%ccs%prod10c(c)    = cptr%ccs%prod10c(c)    + cptr%ccf%hrv_deadstemc_to_prod10c(c)*dt
     cptr%ccs%prod100c(c)   = cptr%ccs%prod100c(c)   + cptr%ccf%hrv_deadstemc_to_prod100c(c)*dt

!     if ( use_c13 ) then
!        cptr%cc13s%prod10c(c)  = cptr%cc13s%prod10c(c)  + cptr%cc13f%hrv_deadstemc_to_prod10c(c)*dt
!        cptr%cc13s%prod100c(c) = cptr%cc13s%prod100c(c) + cptr%cc13f%hrv_deadstemc_to_prod100c(c)*dt
!     endif

!     if ( use_c14 ) then
!        cptr%cc14s%prod10c(c)  = cptr%cc14s%prod10c(c)  + cptr%cc14f%hrv_deadstemc_to_prod10c(c)*dt
!        cptr%cc14s%prod100c(c) = cptr%cc14s%prod100c(c) + cptr%cc14f%hrv_deadstemc_to_prod100c(c)*dt
!     endif

     cptr%cns%prod10n(c)    = cptr%cns%prod10n(c)    + cptr%cnf%hrv_deadstemn_to_prod10n(c)*dt
     cptr%cns%prod100n(c)   = cptr%cns%prod100n(c)   + cptr%cnf%hrv_deadstemn_to_prod100n(c)*dt
     
     ! fluxes out of wood product pools, from decomposition
     cptr%ccs%prod10c(c)    = cptr%ccs%prod10c(c)    - cptr%ccf%prod10c_loss(c)*dt
     cptr%ccs%prod100c(c)   = cptr%ccs%prod100c(c)   - cptr%ccf%prod100c_loss(c)*dt

!     if ( use_c13 ) then
!        cptr%cc13s%prod10c(c)  = cptr%cc13s%prod10c(c)  - cptr%cc13f%prod10c_loss(c)*dt
!        cptr%cc13s%prod100c(c) = cptr%cc13s%prod100c(c) - cptr%cc13f%prod100c_loss(c)*dt
!     endif

!     if ( use_c14 ) then
!        cptr%cc14s%prod10c(c)  = cptr%cc14s%prod10c(c)  - cptr%cc14f%prod10c_loss(c)*dt
!        cptr%cc14s%prod100c(c) = cptr%cc14s%prod100c(c) - cptr%cc14f%prod100c_loss(c)*dt
!     endif

     cptr%cns%prod10n(c)    = cptr%cns%prod10n(c)    - cptr%cnf%prod10n_loss(c)*dt
     cptr%cns%prod100n(c)   = cptr%cns%prod100n(c)   - cptr%cnf%prod100n_loss(c)*dt
     
  end do ! end of column loop
  
end subroutine CNWoodProducts
!-----------------------------------------------------------------------

!#endif

end module cnwoodproductsmod_ACASA



module CNSoilLittVertTranspMod
!#ifdef CN
  
  
!-----------------------------------------------------------------------
!BOP
!
! !MODULE: CNSoilLittVertTranspMod
!
! !DESCRIPTION:
! calculate vertical mixing of all decomposing C and N pools
!
! !USES:
  use shr_kind_mod, only : r8 => shr_kind_r8
!  use clm_varctl  , only : iulog, use_c13, use_c14, spinup_state
  use clm_varcon45  , only : secspday
!
! !PUBLIC TYPES:
  implicit none
  save
!
! !PUBLIC MEMBER FUNCTIONS:
  public :: CNSoilLittVertTransp   
!
! !PUBLIC DATA MEMBERS:
   real(r8), public :: som_diffus = 1e-4_r8 / (secspday * 365._r8)  ! [m^2/sec] = 1 cm^2 / yr
   real(r8), public :: som_adv_flux =  0._r8
   real(r8), public :: cryoturb_diffusion_k =  5e-4_r8 / (secspday * 365._r8)  ! [m^2/sec] = 5 cm^2 / yr = 1m^2 / 200 yr
   real(r8), public :: max_depth_cryoturb = 3._r8          ! (m) this is the maximum depth of cryoturbation
   real(r8), public :: max_altdepth_cryoturbation = 2._r8  ! (m) maximum active layer thickness for cryoturbation to occur
! !REVISION HISTORY:
!
!
! !PRIVATE MEMBER FUNCTIONS:
!
! !PRIVATE TYPES:
!EOP
!-----------------------------------------------------------------------

contains

!-----------------------------------------------------------------------
!BOP
!

!
! !IROUTINE: CNSoilLittVertTransp
!
! !INTERFACE:
subroutine CNSoilLittVertTransp(lbc, ubc, num_soilc, filter_soilc,dtime)
!
! !DESCRIPTION:
!
! Calculate vertical mixing of soil and litter pools.  Also reconcile sources and sinks of these pools 
! calculated in the CStateUpdate1 and NStateUpdate1 subroutines.
! Advection-diffusion code based on algorithm in Patankar (1980)
! Initial code by C. Koven and W. Riley
!
! !USES:
   use clmtype45
!   use clm_time_manager, only: get_step_size
   use clm_varpar45   , only: nlevdecomp, ndecomp_pools, nlevdecomp_full
   use clm_varcon45   , only: zsoi, dzsoi_decomp, zisoi
   use tridiagonalmod_ACASA  , only : Tridiagonal
   use abortutils   , only : endrun

! !ARGUMENTS:
   implicit none
   integer, intent(in) :: num_soilc       ! number of soil columns in filter
   integer, intent(in) :: filter_soilc(:) ! filter for soil columns
   integer, intent(in) :: lbc, ubc        ! column-index bounds

! !LOCAL VARIABLES:
!EOP
   ! real(r8) :: som_diffus_coef (lbc:ubc,1:nlevdecomp+1)     ! diffusivity (m2/s)  
   ! real(r8) :: som_adv_coef(lbc:ubc,1:nlevdecomp+1)         ! advective flux (m/s)
   real(r8), pointer :: som_adv_coef(:,:)                     ! SOM advective flux (m/s)
   real(r8), pointer :: som_diffus_coef(:,:)                  ! SOM diffusivity due to bio/cryo-turbation (m2/s)
   real(r8) :: diffus (lbc:ubc,1:nlevdecomp+1)                ! diffusivity (m2/s)  (includes spinup correction, if any)
   real(r8) :: adv_flux(lbc:ubc,1:nlevdecomp+1)               ! advective flux (m/s)  (includes spinup correction, if any)
!   real(r8) :: aaa                                            ! "A" function in Patankar
   real(r8) :: pe                                             ! Pe for "A" function in Patankar
   real(r8) :: w_m1, w_p1                                     ! Weights for calculating harmonic mean of diffusivity
   real(r8) :: d_m1, d_p1                                     ! Harmonic mean of diffusivity
   real(r8) :: a_tri (lbc:ubc,0:nlevdecomp+1)                 ! "a" vector for tridiagonal matrix
   real(r8) :: b_tri (lbc:ubc,0:nlevdecomp+1)                 ! "b" vector for tridiagonal matrix
   real(r8) :: c_tri (lbc:ubc,0:nlevdecomp+1)                 ! "c" vector for tridiagonal matrix
   real(r8) :: r_tri (lbc:ubc,0:nlevdecomp+1)                 ! "r" vector for tridiagonal solution
   real(r8) :: d_p1_zp1 (lbc:ubc,1:nlevdecomp+1)              ! diffusivity/delta_z for next j  
                                                              ! (set to zero for no diffusion)
   real(r8) :: d_m1_zm1 (lbc:ubc,1:nlevdecomp+1)              ! diffusivity/delta_z for previous j 
                                                              ! (set to zero for no diffusion)
   real(r8) :: f_p1     (lbc:ubc,1:nlevdecomp+1)              ! water flux for next j
   real(r8) :: f_m1     (lbc:ubc,1:nlevdecomp+1)              ! water flux for previous j
   real(r8) :: pe_p1     (lbc:ubc,1:nlevdecomp+1)             ! Peclet # for next j
   real(r8) :: pe_m1     (lbc:ubc,1:nlevdecomp+1)             ! Peclet # for previous j
   real(r8) :: dz_node(1:nlevdecomp+1)                        ! difference between nodes
   real(r8) :: epsilon_t (lbc:ubc,1:nlevdecomp+1,1:ndecomp_pools) !
   real(r8) :: conc_trcr(lbc:ubc,0:nlevdecomp+1)  
   real(r8), pointer :: conc_ptr(:,:,:)                       ! pointer for concentration state variable being transported
   real(r8), pointer :: source(:,:,:)                         ! pointer for source term
   logical, pointer  :: is_cwd(:)                             ! TRUE => pool is a cwd pool
   real(r8) :: a_p_0
   real(r8) :: deficit
   real(r8), pointer :: trcr_tendency_ptr(:,:,:)              ! pointer to store the vertical tendency 
                                                              ! (gain/loss due to vertical transport)
   real(r8), pointer :: altmax(:)                             ! maximum annual depth of thaw
   real(r8), pointer :: altmax_lastyear(:)                    ! prior year maximum annual depth of thaw


   integer :: ntype
   integer :: i_type,s,fc,c,j,l          ! indices
   integer :: jtop(lbc:ubc)              ! top level at each column
   real(r8) :: dtime                     ! land model time step (sec)
   integer :: zerolev_diffus
   real(r8), pointer :: spinup_factor(:) ! spinup accelerated decomposition factor, used to accelerate transport as well
   real(r8) :: spinup_term               ! spinup accelerated decomposition factor, used to accelerate transport as well
   real(r8) :: epsilon                   ! small number

!EOP
!-----------------------------------------------------------------------
   



   ! Set statement functions
!   aaa (pe) = max (0._r8, (1._r8 - 0.1_r8 * abs(pe))**5)  ! A function from Patankar, Table 5.2, pg 95
   
   is_cwd                                  => decomp_cascade_con%is_cwd
   spinup_factor                           => decomp_cascade_con%spinup_factor
   altmax                          => clm3%g%l%c%cps%altmax
   altmax_lastyear                 => clm3%g%l%c%cps%altmax_lastyear
   som_adv_coef                    => clm3%g%l%c%cps%som_adv_coef
   som_diffus_coef                 => clm3%g%l%c%cps%som_diffus_coef

   
!   dtime = get_step_size()
   
   ntype = 2
!   if ( use_c13 ) then
!      ntype = ntype+1
!   endif
!   if ( use_c14 ) then
!      ntype = ntype+1
!   endif
   spinup_term = 1._r8
   epsilon = 1.e-30
   
!#ifdef VERTSOILC
   !------ first get diffusivity / advection terms -------!
   ! use different mixing rates for bioturbation and cryoturbation, with fixed bioturbation and cryoturbation set to a maximum depth
   do fc = 1, num_soilc
      c = filter_soilc (fc)
      if  ( ( max(altmax(c), altmax_lastyear(c)) .le. max_altdepth_cryoturbation ) .and. ( max(altmax(c), altmax_lastyear(c)) .gt. 0._r8) ) then
         ! use mixing profile modified slightly from Koven et al. (2009): constant through active layer, linear decrease from base of active layer to zero at a fixed depth
         do j = 1,nlevdecomp+1
            if ( zisoi(j) .lt. max(altmax(c), altmax_lastyear(c)) ) then
               som_diffus_coef(c,j) = cryoturb_diffusion_k 
              som_adv_coef(c,j) = 0._r8
            else
               som_diffus_coef(c,j) = max(cryoturb_diffusion_k * ( 1._r8 - ( zisoi(j) - max(altmax(c), altmax_lastyear(c)) ) / &
                    ( max_depth_cryoturb - max(altmax(c), altmax_lastyear(c)) ) ), 0._r8)  ! go linearly to zero between ALT and max_depth_cryoturb
               som_adv_coef(c,j) = 0._r8
            endif
         end do
      elseif (  max(altmax(c), altmax_lastyear(c)) .gt. 0._r8 ) then
        ! constant advection, constant diffusion
         do j = 1,nlevdecomp+1
            som_adv_coef(c,j) = som_adv_flux 
            som_diffus_coef(c,j) = som_diffus
         end do
      else
         ! completely frozen soils--no mixing
         do j = 1,nlevdecomp+1
            som_adv_coef(c,j) = 0._r8
            som_diffus_coef(c,j) = 0._r8
        end do
      endif
   end do
   
   ! Set the distance between the node and the one ABOVE it   
   dz_node(1) = zsoi(1)
   do j = 2,nlevdecomp+1
      dz_node(j)= zsoi(j) - zsoi(j-1)
   enddo

!#endif
   
   !------ loop over litter/som types
   do i_type = 1, ntype
            
      select case (i_type)
      case (1)  ! C
         conc_ptr => clm3%g%l%c%ccs%decomp_cpools_vr
         source    => clm3%g%l%c%ccf%decomp_cpools_sourcesink
         trcr_tendency_ptr => clm3%g%l%c%ccf%decomp_cpools_transport_tendency
      case (2)  ! N
         conc_ptr => clm3%g%l%c%cns%decomp_npools_vr
         source    => clm3%g%l%c%cnf%decomp_npools_sourcesink
         trcr_tendency_ptr => clm3%g%l%c%cnf%decomp_npools_transport_tendency
!      case (3)
!         if ( use_c13 ) then
!            ! C13
!            conc_ptr => clm3%g%l%c%cc13s%decomp_cpools_vr
!            source    => clm3%g%l%c%cc13f%decomp_cpools_sourcesink
!            trcr_tendency_ptr => clm3%g%l%c%cc13f%decomp_cpools_transport_tendency
!         else
            ! C14
!            conc_ptr => clm3%g%l%c%cc14s%decomp_cpools_vr
!            source    => clm3%g%l%c%cc14f%decomp_cpools_sourcesink
!            trcr_tendency_ptr => clm3%g%l%c%cc14f%decomp_cpools_transport_tendency
!         endif
!      case (4)
!         if ( use_c14 .and. use_c13 ) then
            ! C14
!            conc_ptr => clm3%g%l%c%cc14s%decomp_cpools_vr
!            source    => clm3%g%l%c%cc14f%decomp_cpools_sourcesink
!            trcr_tendency_ptr => clm3%g%l%c%cc14f%decomp_cpools_transport_tendency
!         else
!            write(iulog,*) 'error.  ncase = 4, but c13 and c14 not both enabled.'
!            call endrun()
!         endif
      end select

!#ifdef VERTSOILC
      
      do s = 1, ndecomp_pools

!      if ( spinup_state .eq. 1 ) then
         ! increase transport (both advection and diffusion) by the same factor as accelerated decomposition for a given pool
         spinup_term = spinup_factor(s)
!      else
!         spinup_term = 1.
!      endif

         if ( .not. is_cwd(s) ) then

            do j = 1,nlevdecomp+1
               do fc = 1, num_soilc
                  c = filter_soilc (fc)
                  !
                  if ( abs(som_adv_coef(c,j)) * spinup_term .lt. epsilon ) then
                     adv_flux(c,j) = epsilon
                  else
                     adv_flux(c,j) = som_adv_coef(c,j) * spinup_term
                  endif
                 !
                  if ( abs(som_diffus_coef(c,j)) * spinup_term .lt. epsilon ) then
                     diffus(c,j) = epsilon
                  else
                     diffus(c,j) = som_diffus_coef(c,j) * spinup_term
                  endif
                 !
               end do
            end do
            
            ! Set Pe (Peclet #) and D/dz throughout column
            
            do fc = 1, num_soilc ! dummy terms here
               c = filter_soilc (fc)
               conc_trcr(c,0) = 0._r8
               conc_trcr(c,nlevdecomp+1) = 0._r8
            end do


            do j = 1,nlevdecomp+1
               do fc = 1, num_soilc
                 c = filter_soilc (fc)
                  
                  conc_trcr(c,j) = conc_ptr(c,j,s)
                  ! dz_tracer below is the difference between gridcell edges  (dzsoi_decomp)
                  ! dz_node_tracer is difference between cell centers 
                  
                  ! Calculate the D and F terms in the Patankar algorithm
                  if (j == 1) then
                     d_m1_zm1(c,j) = 0._r8
                     w_p1 = (zsoi(j+1) - zisoi(j)) / dz_node(j+1)
                     if ( diffus(c,j+1) .gt. 0._r8 .and. diffus(c,j) .gt. 0._r8) then
                        d_p1 = 1._r8 / ((1._r8 - w_p1) / diffus(c,j) + w_p1 / diffus(c,j+1)) ! Harmonic mean of diffus
                    else
                        d_p1 = 0._r8
                     endif
                     d_p1_zp1(c,j) = d_p1 / dz_node(j+1)
                     f_m1(c,j) = adv_flux(c,j)  ! Include infiltration here
                     f_p1(c,j) = adv_flux(c,j+1)
                     pe_m1(c,j) = 0._r8
                     pe_p1(c,j) = f_p1(c,j) / d_p1_zp1(c,j) ! Peclet #
                  elseif (j == nlevdecomp+1) then
                     ! At the bottom, assume no gradient in d_z (i.e., they're the same)
                    w_m1 = (zisoi(j-1) - zsoi(j-1)) / dz_node(j)
                     if ( diffus(c,j) .gt. 0._r8 .and. diffus(c,j-1) .gt. 0._r8) then
                        d_m1 = 1._r8 / ((1._r8 - w_m1) / diffus(c,j) + w_m1 / diffus(c,j-1)) ! Harmonic mean of diffus
                     else
                        d_m1 = 0._r8
                     endif
                     d_m1_zm1(c,j) = d_m1 / dz_node(j)
                     d_p1_zp1(c,j) = d_m1_zm1(c,j) ! Set to be the same
                     f_m1(c,j) = adv_flux(c,j)
                     !f_p1(c,j) = adv_flux(c,j+1)
                     f_p1(c,j) = 0._r8
                     pe_m1(c,j) = f_m1(c,j) / d_m1_zm1(c,j) ! Peclet #
                     pe_p1(c,j) = f_p1(c,j) / d_p1_zp1(c,j) ! Peclet #
                 else
                     ! Use distance from j-1 node to interface with j divided by distance between nodes
                     w_m1 = (zisoi(j-1) - zsoi(j-1)) / dz_node(j)
                     if ( diffus(c,j-1) .gt. 0._r8 .and. diffus(c,j) .gt. 0._r8) then
                        d_m1 = 1._r8 / ((1._r8 - w_m1) / diffus(c,j) + w_m1 / diffus(c,j-1)) ! Harmonic mean of diffus
                     else
                        d_m1 = 0._r8
                     endif
                     w_p1 = (zsoi(j+1) - zisoi(j)) / dz_node(j+1)
                     if ( diffus(c,j+1) .gt. 0._r8 .and. diffus(c,j) .gt. 0._r8) then
                        d_p1 = 1._r8 / ((1._r8 - w_p1) / diffus(c,j) + w_p1 / diffus(c,j+1)) ! Harmonic mean of diffus
                     else
                        d_p1 = (1._r8 - w_m1) * diffus(c,j) + w_p1 * diffus(c,j+1) ! Arithmetic mean of diffus
                     endif
                     d_m1_zm1(c,j) = d_m1 / dz_node(j)
                     d_p1_zp1(c,j) = d_p1 / dz_node(j+1)
                     f_m1(c,j) = adv_flux(c,j)
                     f_p1(c,j) = adv_flux(c,j+1)
                     pe_m1(c,j) = f_m1(c,j) / d_m1_zm1(c,j) ! Peclet #
                     pe_p1(c,j) = f_p1(c,j) / d_p1_zp1(c,j) ! Peclet #
                  end if
               enddo ! fc
            enddo ! j; nlevdecomp

            
            ! Calculate the tridiagonal coefficients
            do j = 0,nlevdecomp +1
               do fc = 1, num_soilc
                  c = filter_soilc (fc)
                  ! g = cgridcell(c)
                  
                  if (j > 0 .and. j < nlevdecomp+1) then
                     a_p_0 =  dzsoi_decomp(j) / dtime
                  endif
                  
                  if (j == 0) then ! top layer (atmosphere)
                     a_tri(c,j) = 0._r8
                     b_tri(c,j) = 1._r8
                     c_tri(c,j) = -1._r8
                     r_tri(c,j) = 0._r8
                  elseif (j == 1) then
                     a_tri(c,j) = -(d_m1_zm1(c,j) * max (0._r8, (1._r8 - 0.1_r8 * abs(pe_m1(c,j)))**5)) & 
                                  + max( f_m1(c,j), 0._r8) ! Eqn 5.47 Patankar
                     c_tri(c,j) = -(d_p1_zp1(c,j) * max (0._r8, (1._r8 - 0.1_r8 * abs(pe_p1(c,j)))**5)) &
                                  + max(-f_p1(c,j), 0._r8)
                     b_tri(c,j) = -a_tri(c,j) - c_tri(c,j) + a_p_0
                     r_tri(c,j) = source(c,j,s) * dzsoi_decomp(j) /dtime + (a_p_0 - adv_flux(c,j)) * conc_trcr(c,j) 
                  elseif (j .lt. nlevdecomp+1) then
                     a_tri(c,j) = -(d_m1_zm1(c,j) * max (0._r8, (1._r8 - 0.1_r8 * abs(pe_m1(c,j)))**5)) &
                                  + max( f_m1(c,j), 0._r8) ! Eqn 5.47 Patankar
                     c_tri(c,j) = -(d_p1_zp1(c,j) * max (0._r8, (1._r8 - 0.1_r8 * abs(pe_p1(c,j)))**5)) &
                                  + max(-f_p1(c,j), 0._r8)
                     b_tri(c,j) = -a_tri(c,j) - c_tri(c,j) + a_p_0
                     r_tri(c,j) = source(c,j,s) * dzsoi_decomp(j) /dtime + a_p_0 * conc_trcr(c,j)
                  else ! j==nlevdecomp+1; 0 concentration gradient at bottom
                     a_tri(c,j) = -1._r8
                     b_tri(c,j) = 1._r8
                     c_tri(c,j) = 0._r8 
                     r_tri(c,j) = 0._r8
                  endif
               enddo ! fc; column
            enddo ! j; nlevdecomp
           
            do fc = 1, num_soilc
               c = filter_soilc (fc)
               jtop(c) = 0
            enddo
           
            ! subtract initial concentration and source terms for tendency calculation
            do fc = 1, num_soilc
               c = filter_soilc (fc)
               do j = 1, nlevdecomp
                  trcr_tendency_ptr(c,j,s) = 0.-(conc_trcr(c,j) + source(c,j,s))
               end do
            end do

            ! Solve for the concentration profile for this time step
            call Tridiagonal(lbc, ubc, 0, nlevdecomp+1, jtop, num_soilc, filter_soilc, &
                 a_tri, b_tri, c_tri, r_tri, conc_trcr(lbc:ubc,0:nlevdecomp+1))
            
            
            ! add post-transport concentration to calculate tendency term
            do fc = 1, num_soilc
               c = filter_soilc (fc)
               do j = 1, nlevdecomp
                  trcr_tendency_ptr(c,j,s) = trcr_tendency_ptr(c,j,s) + conc_trcr(c,j)
                  trcr_tendency_ptr(c,j,s) = trcr_tendency_ptr(c,j,s) / dtime
               end do
            end do


         else
           ! for CWD pools, just add
            do j = 1,nlevdecomp
               do fc = 1, num_soilc
                  c = filter_soilc (fc)
                  conc_trcr(c,j) = conc_ptr(c,j,s) + source(c,j,s)
               end do
            end do
         end if ! not CWD
         do j = 1,nlevdecomp
            do fc = 1, num_soilc
               c = filter_soilc (fc)
              conc_ptr(c,j,s) = conc_trcr(c,j) 
            end do
         end do
      end do ! s (pool loop)

!if (i_type==1) then
!   write(66,*) 'conc_ptr',conc_ptr,'source',source,'conc_trcr',conc_trcr
!endif   
!#else
!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
      !! for single level case, no transport; just update the fluxes calculated in the StateUpdate1 subroutines
      
!      do l = 1, ndecomp_pools
!         do j = 1,nlevdecomp
!            do fc = 1, num_soilc
!!               c = filter_soilc (fc)
!               
!               conc_ptr(c,j,l) = conc_ptr(c,j,l) + source(c,j,l)
               
!               trcr_tendency_ptr(c,j,l) = 0._r8
!
!            end do
!         end do
!      end do
      
!#endif
      
   end do  ! i_type

   
end subroutine CNSoilLittVertTransp
 
!#endif
end module CNSoilLittVertTranspMod

module cnecosystemdynmod_ACASA
!#ifdef CN

!-----------------------------------------------------------------------
!BOP
!
! !MODULE: cnecosystemdynmod_ACASA
!
! !DESCRIPTION:
! Ecosystem dynamics: phenology, vegetation
!
! !USES:
  use shr_kind_mod, only: r8 => shr_kind_r8
!  use clm_varctl  , only: fpftdyn, use_c13, use_c14
!
! !PUBLIC TYPES:
  implicit none
  save
!
! !PUBLIC MEMBER FUNCTIONS:
  public :: EcosystemDynini      ! Dynamically allocate memory
  public :: CNEcosystemDynInit   ! Ecosystem dynamics initialization
  public :: CNEcosystemDyn       ! Ecosystem dynamics: phenology, vegetation
!
!
  real(r8), private, allocatable :: mlai2t(:,:) ! lai for interpolation (2 months)
  real(r8), private, allocatable :: msai2t(:,:) ! sai for interpolation (2 months)
  real(r8), private, allocatable :: mhvt2t(:,:) ! top vegetation height for interpolation (2 months)
  real(r8), private, allocatable :: mhvb2t(:,:) ! bottom vegetation height for interpolati
! !REVISION HISTORY:
! Created by Peter Thornton
! 19 May 2009: PET - modified to include call to harvest routine
!F. Li and S. Levis (11/06/12)
!
! !PRIVATE MEMBER FUNCTIONS:
!
! !PRIVATE TYPES:
!EOP
!-----------------------------------------------------------------------

contains

  subroutine EcosystemDynini ( )
!
! !DESCRIPTION:
! Dynamically allocate memory and set to signaling NaN.
!
! !USES:
    use nanmod_ACASA
    use abortutils, only: endrun
    use decompmod_ACASA, only : get_proc_bounds
!
! !ARGUMENTS:
    implicit none
!
! !REVISION HISTORY:
!
!
! !LOCAL VARIABLES:
!EOP
    integer :: ier    ! error code
    integer :: begp,endp  ! local beg and end p index
!-----------------------------------------------------------------------

!    InterpMonths1 = -999  ! saved month index
    call get_proc_bounds(begp=begp,endp=endp)

    ier = 0
    if(.not.allocated(mlai2t))allocate (mlai2t(begp:endp,2), &
              msai2t(begp:endp,2), &
              mhvt2t(begp:endp,2), &
              mhvb2t(begp:endp,2), stat=ier)
    if (ier /= 0) then
!       write(iulog,*) 'EcosystemDynini allocation error'
       call endrun
    end if

    mlai2t(:,:) = nan
    msai2t(:,:) = nan
    mhvt2t(:,:) = nan
    mhvb2t(:,:) = nan

  end subroutine EcosystemDynini

  subroutine EcosystemDyn_dealloc ()
!
    implicit none
!
!EOP
!-----------------------------------------------------------------------

    if(allocated(mlai2t)) deallocate (mlai2t)
    if(allocated(msai2t)) deallocate (msai2t)
    if(allocated(mhvt2t)) deallocate (mhvt2t)
    if(allocated(mhvb2t)) deallocate (mhvb2t)

  end subroutine EcosystemDyn_dealloc

!-----------------------------------------------------------------------

  subroutine CNEcosystemDynInit(lbg, ubg, lbc, ubc, lbp, ubp, dt)
!
! !DESCRIPTION:
! Initialzation of the CN Ecosystem dynamics.
!
! !USES:
    use cnallocationmod_ACASA, only : CNAllocationInit
    use cnphenologymod_ACASA , only : CNPhenologyInit
!    use cnfiremod_ACASA      , only : CNFireInit
!    use CNC14DecayMod  , only : C14_init_BombSpike
!
! !ARGUMENTS:
    implicit none
    integer, intent(in) :: lbg, ubg        ! gridcell bounds
    integer, intent(in) :: lbc, ubc        ! column bounds
    integer, intent(in) :: lbp, ubp        ! pft bounds
!
!KC 
    real(r8) :: dt
! !CALLED FROM:
!
! !REVISION HISTORY:
! 04/05/11, Erik Kluzek creation
!
! !LOCAL VARIABLES:
!EOP
!-----------------------------------------------------------------------
     call CNAllocationInit ( lbc, ubc, lbp, ubp ,dt)
     call CNPhenologyInit  ( lbp, ubp, dt)
!     call CNFireInit       ( lbg, ubg )

!     if ( use_c14 ) call C14_init_BombSpike()

  end subroutine CNEcosystemDynInit
!BOP
!
! !IROUTINE: CNEcosystemDyn
!
! !INTERFACE:
!  subroutine CNEcosystemDyn(lbc, ubc, lbp, ubp, num_soilc, filter_soilc, &
!                     num_soilp, filter_soilp, num_pcropp, filter_pcropp, &
!                     yr, &
!                   tsoiq,nsoil0,T2ACASA,dayl_factor,xlai7,pai,tessa_sun,tessa_sha,ivt, &
!                   nstep,zi,SH2O,deltat1,tphoto,decl,lat,prc33,prc34,relh,t2o6,mw6,popdens, &
!                   RUNOFF1,RUNOFF2,xlint,stei,domain_height,dt, &
!                   rweight,xsm)

  subroutine CNEcosystemDyn(lbc, ubc, lbp, ubp,  &
                     yr , &
                     tsoiq,nsoil0,T2_clm,dayl_factor, &
                     nstep,SH2O,dt,tphoto,decl,lat,prc33,prc34,&
                     relh,t2o6,mw6,popdens, &
                     RUNOFF1,RUNOFF2,domain_height, &
                     isoi3, &
                     kmo,kda,mcsec,lmr_sun,lmr_sha)

!
! !DESCRIPTION:
! The core CN code is executed here. Calculates fluxes for maintenance
! respiration, decomposition, allocation, phenology, and growth respiration.
! These routines happen on the radiation time step so that canopy structure
! stays synchronized with albedo calculations.
!
! !USES:
    use clmtype45
 !    use spmdMod              , only: masterproc
    use cnsetvaluemod_ACASA        , only: CNZeroFluxes
    use cnndynamicsmod_ACASA       , only: CNNDeposition,CNNFixation, CNNLeaching!, CNNFert, CNSoyfix
    use cnmrespmod_ACASA           , only: CNMResp
    use cndecompmod_ACASA          , only: CNDecompAlloc
    use cnphenologymod_ACASA       , only: CNPhenology
    use cngrespmod_ACASA           , only: CNGResp
    use cncstateupdate1mod_ACASA   , only: CStateUpdate1,CStateUpdate0
    use cnnstateupdate1mod_ACASA   , only: NStateUpdate1
    use cngapmortalitymod_ACASA    , only: CNGapMortality
    use cncstateupdate2mod_ACASA   , only: CStateUpdate2, CStateUpdate2h
    use cnnstateupdate2mod_ACASA   , only: NStateUpdate2, NStateUpdate2h
    use cnfiremod_ACASA            , only: CNFireArea, CNFireFluxes
    use cncstateupdate3mod_ACASA   , only: CStateUpdate3
    use cnnstateupdate3mod_ACASA   , only: NStateUpdate3
    use cnprecisioncontrolmod_ACASA, only: CNPrecisionControl
    use cnvegstructupdatemod_ACASA , only: CNVegStructUpdate
    use cnannualupdatemod_ACASA    , only: CNAnnualUpdate
    use cnsummarymod_ACASA         , only: CSummary, NSummary
 !   use CNCIsoFluxMod        , only: CIsoFlux1, CIsoFlux2, CIsoFlux2h, CIsoFlux3
 !   use CNC14DecayMod        , only: C14Decay, C14BombSpike
    use pftdynmod_ACASA              , only: CNHarvest
    use cnwoodproductsmod_ACASA      , only: CNWoodProducts
    use CNSoilLittVertTranspMod, only: CNSoilLittVertTransp
 !    use perf_mod               , only: t_startf, t_stopf
 !    use surfrdMod              , only: crop_prog
 !    use shr_sys_mod            , only: shr_sys_flush
  use filtermod_ACASA           , only : filter
!
! !ARGUMENTS:
    implicit none
    integer, intent(in) :: lbc, ubc        ! column bounds
    integer, intent(in) :: lbp, ubp        ! pft bounds
!    integer, intent(in) :: num_soilc       ! number of soil columns in filter
!    integer, intent(in) :: filter_soilc(ubc-lbc+1) ! filter for soil columns
!    integer, intent(in) :: num_soilp       ! number of soil pfts in filter
!    integer, intent(in) :: filter_soilp(ubp-lbp+1) ! filter for soil pfts
!    integer, intent(in) :: num_pcropp      ! number of prog. crop pfts in filter
!    integer, intent(in) :: filter_pcropp(ubc-lbc+1)! filter for prognostic crop pfts
!    logical, intent(in) :: doalb           ! true = surface albedo calculation time step
    integer, intent(in) :: nstep,nsoil0,yr,isoi3
    integer :: nc,np
    real(r8), intent(in) :: tsoiq(nsoil0),dayl_factor
    real(r8), intent(in) :: tphoto(filter(1)%num_soilp),decl,lat
    real(r8), intent(in) ::prc33,prc34,relh,t2o6,mw6,popdens
    real :: RUNOFF1,RUNOFF2,SH2O(nsoil0)
    real(r8), intent(in) :: domain_height,dt
!  real(r8) :: nee_out(num_soilc),gpp_out(num_soilp)
!  real(r8) :: nep_out(num_soilc),fire_out(num_soilc),dwt_out(num_soilc),product_out(num_soilc)
!  real(r8) :: hrv_out(num_soilc),col_gpp_out(num_soilc),leaf_resp(num_soilp),stem_resp(num_soilp)
   real(r8) :: lmr25top,nscaler,temp2(11),temp1
!   real(r8),pointer :: t10(:)
!   real(r8),pointer :: tlai(:)
!   real(r8),pointer :: htop(:)
!   integer,pointer :: ivt(:)
   integer :: i,kmo,kda,mcsec
   real(r8) :: xday,lmr_sun(filter(1)%num_soilp),lmr_sha(filter(1)%num_soilp),t2_clm(filter(1)%num_soilp)
!   real(r8) ::h2ocan_clm(filter(1)%num_soilp)
!   real(r8), pointer :: decomp_cpools_vr(:,:,:)

! !CALLED FROM:
!
! !REVISION HISTORY:
! 10/22/03, Peter Thornton: created from EcosystemDyn during migration to
!                           new vector code.
! 11/3/03, Peter Thornton: removed update of elai, esai, frac_veg_nosno_alb.
!     These are now done in CNVegStructUpdate(), which is called
!     prior to SurfaceAlbedo().
! 11/13/03, Peter Thornton: switched from nolake to soil filtering.
!
! !LOCAL VARIABLES:
!
! local pointers to implicit in arguments
!
! local pointers to implicit out arguments
!
! !OTHER LOCAL VARIABLES:
!
!EOP
!-----------------------------------------------------------------------
!    t10              => clm3%g%l%c%p%pes%t10
!    tlai                           => clm3%g%l%c%p%pps%tlai
!    htop                           => clm3%g%l%c%p%pps%htop
!   ivt                         => clm3%g%l%c%p%itype
!   decomp_cpools_vr              => clm3%g%l%c%ccs%decomp_cpools_vr
 !   if (doalb) then
   nc = ubc-lbc+1
   np = ubp-lbp+1
!filter(nc)%num_soilc,filter(nc)%soilc,filter(nc)%num_soilp,filter(nc)%soilp
       ! Call the main CN routines
       call CNZeroFluxes(filter(nc)%num_soilc,filter(nc)%soilc,filter(nc)%num_soilp,filter(nc)%soilp)
!write(*,*) 'CNZeroFluxes'
       call CNNDeposition(lbc, ubc)
!write(*,*) 'CNNDeposition'
       call CNNFixation(filter(nc)%num_soilc,filter(nc)%soilc,yr,nc)
!write(*,*) 'CNNFixation'
       call CNMResp(lbc, ubc, filter(nc)%num_soilc,filter(nc)%soilc,filter(nc)%num_soilp,filter(nc)%soilp, &
                   nsoil0,T2_clm,dayl_factor, &
                   lmr_sun,lmr_sha)
!write(*,*) 'CNMResp'
       call CNDecompAlloc(lbp, ubp, lbc, ubc, filter(nc)%num_soilc,filter(nc)%soilc,filter(nc)%num_soilp,filter(nc)%soilp, &
   nstep,yr,nsoil0,SH2O,dt,tphoto, &
   RUNOFF1,RUNOFF2,isoi3)

       ! CNphenology needs to be called after CNdecompAlloc, because it
       ! depends on current time-step fluxes to new growth on the last
       ! litterfall timestep in deciduous systems

       call CNPhenology(filter(nc)%num_soilc,filter(nc)%soilc,filter(nc)%num_soilp,filter(nc)%soilp, &
                        filter(nc)%num_pcropp,filter(nc)%pcropp,yr, &
                        lat,dt,nsoil0,decl,kmo,kda,mcsec)
!write(*,*) 'CNPhenology'

       call CNGResp(filter(nc)%num_soilp,filter(nc)%soilp)
!write(*,*) 'CNGResp'
       call CStateUpdate0(filter(nc)%num_soilp,filter(nc)%soilp, 'bulk',tphoto,dt)
!write(*,*) 'CStateUpdate0'
       call CStateUpdate1(filter(nc)%num_soilc,filter(nc)%soilc,filter(nc)%num_soilp,filter(nc)%soilp, 'bulk',dt)
!write(*,*) 'CStateUpdate1'
       call NStateUpdate1(filter(nc)%num_soilc,filter(nc)%soilc,filter(nc)%num_soilp,filter(nc)%soilp,dt)
!write(*,*) 'NStateUpdate1'
       call CNSoilLittVertTransp(lbc, ubc, filter(nc)%num_soilc,filter(nc)%soilc,dt)
!write(*,*) 'CNSoilLittVertTransp'
       call CNGapMortality(filter(nc)%num_soilc,filter(nc)%soilc,filter(nc)%num_soilp,filter(nc)%soilp,yr)
!write(*,*) 'CNGapMortality'
       call CStateUpdate2(filter(nc)%num_soilc,filter(nc)%soilc,filter(nc)%num_soilp,filter(nc)%soilp, 'bulk',dt)
!write(*,*) 'CStateUpdate2'
       call NStateUpdate2(filter(nc)%num_soilc,filter(nc)%soilc,filter(nc)%num_soilp,filter(nc)%soilp,dt)
!write(*,*) 'NStateUpdate2'      
       call CNHarvest(filter(nc)%num_soilc,filter(nc)%soilc,filter(nc)%num_soilp,filter(nc)%soilp,yr)
!write(*,*) 'CNHarvest'
       call CStateUpdate2h(filter(nc)%num_soilc,filter(nc)%soilc,filter(nc)%num_soilp,filter(nc)%soilp, 'bulk',dt)
!write(*,*) 'CStateUpdate2h'
       call NStateUpdate2h(filter(nc)%num_soilc,filter(nc)%soilc,filter(nc)%num_soilp,filter(nc)%soilp,dt)
!write(*,*) 'NStateUpdate2h'      
       call CNWoodProducts(filter(nc)%num_soilc,filter(nc)%soilc,dt)
!write(*,*) 'CNWoodProducts'      
       call CNFireArea(filter(nc)%num_soilc,filter(nc)%soilc,filter(nc)%num_soilp,filter(nc)%soilp,dt,yr,lat,nstep, &
                      prc33,prc34,relh,t2o6,mw6,popdens,tsoiq,kmo,kda,mcsec,nsoil0)
!write(*,*) 'CNFireArea'

       call CNFireFluxes(filter(nc)%num_soilc,filter(nc)%soilc,filter(nc)%num_soilp,filter(nc)%soilp, &
                         dt,yr,lat)
!write(*,*) 'CNFireFluxes'
       call CNNLeaching(lbc, ubc, filter(nc)%num_soilc,filter(nc)%soilc,dt,nsoil0,SH2O, &
            RUNOFF1,RUNOFF2)
!write(*,*) 'CNNLeaching'
       call CStateUpdate3(filter(nc)%num_soilc,filter(nc)%soilc,filter(nc)%num_soilp,filter(nc)%soilp, 'bulk',dt)
!write(*,*) 'CStateUpdate3'
       call NStateUpdate3(filter(nc)%num_soilc,filter(nc)%soilc,filter(nc)%num_soilp,filter(nc)%soilp,dt)
!write(*,*) 'NStateUpdate3'
       call CNPrecisionControl(filter(nc)%num_soilc,filter(nc)%soilc,filter(nc)%num_soilp,filter(nc)%soilp)
!write(*,*) 'CNPrecisionControl'
       call CNVegStructUpdate(filter(nc)%num_soilp,filter(nc)%soilp,dt, &
              domain_height)
!write(*,*) 'CNVegStructUpdate'
       call CSummary(filter(nc)%num_soilc,filter(nc)%soilc,filter(nc)%num_soilp,filter(nc)%soilp, 'bulk', &
                   dt,tphoto)
!write(*,*) 'CSummary'      
       call NSummary(filter(nc)%num_soilc,filter(nc)%soilc,filter(nc)%num_soilp,filter(nc)%soilp)
!write(*,*) 'NSummary'



  end subroutine CNEcosystemDyn
!#endif
!-----------------------------------------------------------------------

end  module cnecosystemdynmod_ACASA

module staticecosysdynmod_ACASA

!#if (!defined CNDV)
#if (!defined CN)
!-----------------------------------------------------------------------
!BOP
!
! !MODULE: staticecosysdynmod_ACASA
!
! !DESCRIPTION:
! Static Ecosystem dynamics: phenology, vegetation.
!
! !USES:
  use shr_kind_mod, only: r8 => shr_kind_r8
  use decompmod_ACASA    , only : get_proc_bounds
  use abortutils, only: endrun
!
! !PUBLIC TYPES:
  implicit none
  save
!
! !PUBLIC MEMBER FUNCTIONS:
  public :: EcosystemDyn       ! Ecosystem dynamics: phenology, vegetation
  public :: EcosystemDynini    ! Dynamically allocate memory
  public :: interpMonthlyVeg   ! interpolate monthly vegetation data

!
! !REVISION HISTORY:
! Created by Mariana Vertenstein
!
!EOP
!
! !PRIVATE MEMBER FUNCTIONS:
  private :: readMonthlyVegetation   ! read monthly vegetation data for two months
!
! PRIVATE TYPES:
  integer , private :: InterpMonths1         ! saved month index
  real(r8), private :: timwt(2)              ! time weights for month 1 and month 2
  real(r8),  allocatable :: mlai1(:) ! lai for interpolation (month 1)
  real(r8),  allocatable :: mlai2(:) ! lai for interpolation (month 2)
  real(r8),  allocatable :: msai1(:) ! sai for interpolation (month 1)
  real(r8),  allocatable :: msai2(:) ! sai for interpolation (month 2)
  real(r8),  allocatable :: mhvt1(:) ! top vegetation height for interpolation (month 1)
  real(r8),  allocatable :: mhvt2(:) ! top vegetation height for interpolation (month 2)
  real(r8),  allocatable :: mhvb1(:) ! bottom vegetation height for interpolation(month 1)
  real(r8),  allocatable :: mhvb2(:) ! bottom vegetation height for interpolation(month 2)
!-----------------------------------------------------------------------

contains

!-----------------------------------------------------------------------
!BOP
!
! !IROUTINE: EcosystemDynini
!
! !INTERFACE:
  subroutine EcosystemDynini ()
!
! !DESCRIPTION:
! Dynamically allocate memory and set to signaling NaN.
!
! !USES:
    use nanmod_ACASA
! !ARGUMENTS:
    implicit none
!
! !REVISION HISTORY:
!
!EOP
!
! LOCAL VARIABLES:
    integer :: ier    ! error code
    integer :: begg
    integer :: endg
    integer :: begl
    integer :: endl
    integer :: begc
    integer :: endc
    integer :: begp
    integer :: endp
!-----------------------------------------------------------------------

    InterpMonths1 = -999  ! saved month index
! begg,begl,begc,begp are all equal to 1
    call get_proc_bounds (begg, endg, begl, endl, begc, endc, begp, endp)
    ier = 0

    if(.not.allocated(mlai1)) allocate (mlai1(begp:endp))
    if(.not.allocated(mlai2)) allocate (mlai2(begp:endp))
    if(.not.allocated(msai1)) allocate (msai1(begp:endp))
    if(.not.allocated(msai2)) allocate (msai2(begp:endp))
    if(.not.allocated(mhvt1)) allocate (mhvt1(begp:endp))
    if(.not.allocated(mhvt2)) allocate (mhvt2(begp:endp))
    if(.not.allocated(mhvb1)) allocate (mhvb1(begp:endp))
    if(.not.allocated(mhvb2)) allocate (mhvb2(begp:endp))


!    if(.not.allocated(mlai1))allocate (mlai1(endp), mlai2(endp), &
!              msai1(endp), msai2(endp), &
!              mhvt1(endp), mhvt2(endp), &
!              mhvb1(endp), mhvb2(endp), stat=ier)

    if (ier /= 0) then
       write (6,*) 'EcosystemDynini allocation error'
       call endrun
    end if

!   call clmdebug_ACASA('EcosystemDynini mark1')

    mlai1(:) = nan
    mlai2(:) = nan
    msai1(:) = nan
    msai2(:) = nan
    mhvt1(:) = nan
    mhvt2(:) = nan
    mhvb1(:) = nan
    mhvb2(:) = nan




  end subroutine EcosystemDynini

!-----------------------------------------------------------------------

!
! !IROUTINE: EcosystemDyn
!
! !INTERFACE:
  subroutine EcosystemDyn(lbp, ubp, num_nolakep, filter_nolakep, doalb)
!
! !DESCRIPTION:
! Ecosystem dynamics: phenology, vegetation
! Calculates leaf areas (tlai, elai),  stem areas (tsai, esai) and
! height (htop).
!
! !USES:
    use clmtype45
!
! !ARGUMENTS:
    implicit none
    integer, intent(in) :: lbp, ubp                    ! pft bounds
    integer, intent(in) :: num_nolakep                 ! number of column non-lake points in pft filter
    integer, intent(in) :: filter_nolakep(ubp-lbp+1)   ! pft filter for non-lake points
    logical, intent(in) :: doalb                       ! true = surface albedo calculation time step
!
! !CALLED FROM:
!
! !REVISION HISTORY:
! Author: Gordon Bonan
! 2/1/02, Peter Thornton: Migrated to new data structure.
!
! !LOCAL VARIABLES:
!
! local pointers to implicit in arguments
!
    integer , pointer :: pcolumn(:)  ! column index associated with each pft
    real(r8), pointer :: snowdp(:)   ! snow height (m)
!
! local pointers to implicit out arguments
!
    real(r8), pointer :: tlai(:)     ! one-sided leaf area index, no burying by snow
    real(r8), pointer :: tsai(:)     ! one-sided stem area index, no burying by snow
    real(r8), pointer :: htop(:)     ! canopy top (m)
    real(r8), pointer :: hbot(:)     ! canopy bottom (m)
    real(r8), pointer :: elai(:)     ! one-sided leaf area index with burying by snow
    real(r8), pointer :: esai(:)     ! one-sided stem area index with burying by snow
    integer , pointer :: frac_veg_nosno_alb(:) ! frac of vegetation not covered by snow [-]
!
!EOP
!
! !OTHER LOCAL VARIABLES:
!
    integer  :: fp,p,c   ! indices
    real(r8) :: ol       ! thickness of canopy layer covered by snow (m)
    real(r8) :: fb       ! fraction of canopy layer covered by snow
!-----------------------------------------------------------------------

    if (doalb) then

       ! Assign local pointers to derived type scalar members (column-level)

       snowdp  => clm3%g%l%c%cps%snowdp

       ! Assign local pointers to derived type scalar members (pftlevel)

       pcolumn => clm3%g%l%c%p%column
       tlai    => clm3%g%l%c%p%pps%tlai
       tsai    => clm3%g%l%c%p%pps%tsai
       elai    => clm3%g%l%c%p%pps%elai
       esai    => clm3%g%l%c%p%pps%esai
       htop    => clm3%g%l%c%p%pps%htop
       hbot    => clm3%g%l%c%p%pps%hbot
       frac_veg_nosno_alb => clm3%g%l%c%p%pps%frac_veg_nosno_alb

!dir$ concurrent
!cdir nodep
       do fp = 1, num_nolakep
          p = filter_nolakep(fp)
          c = pcolumn(p)

          ! need to update elai and esai only every albedo time step so do not
          ! have any inconsistency in lai and sai between SurfaceAlbedo calls (i.e.,
          ! if albedos are not done every time step).
          ! leaf phenology
          ! Set leaf and stem areas based on day of year
          ! Interpolate leaf area index, stem area index, and vegetation heights
          ! between two monthly
          ! The weights below (timwt(1) and timwt(2)) were obtained by a call to
          ! routine InterpMonthlyVeg in subroutine NCARlsm.
          !                 Field   Monthly Values
          !                -------------------------
          ! leaf area index LAI  <- mlai1 and mlai2
          ! leaf area index SAI  <- msai1 and msai2
          ! top height      HTOP <- mhvt1 and mhvt2
          ! bottom height   HBOT <- mhvb1 and mhvb2

          tlai(p) = timwt(1)*mlai1(p) + timwt(2)*mlai2(p)
          tsai(p) = timwt(1)*msai1(p) + timwt(2)*msai2(p)
          htop(p) = timwt(1)*mhvt1(p) + timwt(2)*mhvt2(p)
          hbot(p) = timwt(1)*mhvb1(p) + timwt(2)*mhvb2(p)

          ! adjust lai and sai for burying by snow. if exposed lai and sai
          ! are less than 0.05, set equal to zero to prevent numerical
          ! problems associated with very small lai and sai.

          ol = min( max(snowdp(c)-hbot(p), 0._r8), htop(p)-hbot(p))
          fb = 1. - ol / max(1.e-06_r8, htop(p)-hbot(p))
          elai(p) = max(tlai(p)*fb, 0.0_r8)
          esai(p) = max(tsai(p)*fb, 0.0_r8)
          if (elai(p) < 0.05) elai(p) = 0._r8
          if (esai(p) < 0.05) esai(p) = 0._r8

          ! Fraction of vegetation free of snow

          if ((elai(p) + esai(p)) >= 0.05) then
             frac_veg_nosno_alb(p) = 1
          else
             frac_veg_nosno_alb(p) = 0
          end if

       end do ! end of pft loop

    end if  !end of if-doalb block

  end subroutine EcosystemDyn

!-----------------------------------------------------------------------
!BOP
!
! !IROUTINE: interpMonthlyVeg
!
! !INTERFACE:
  subroutine interpMonthlyVeg (kmo, kda)


!
! !DESCRIPTION:
! Determine if 2 new months of data are to be read.
!
! !USES:
! !ARGUMENTS:
    implicit none
!
! !REVISION HISTORY:
! Created by Mariana Vertenstein
!
!EOP
!
! LOCAL VARIABLES:
    integer :: kyr         ! year (0, ...) for nstep+1
    integer :: kmo         ! month (1, ..., 12)
    integer :: kda         ! day of month (1, ..., 31)
    integer :: ksec        ! seconds into current date for nstep+1
    real(r8):: dtime       ! land model time step (sec)
    real(r8):: t           ! a fraction: kda/ndaypm
    integer :: it(2)       ! month 1 and month 2 (step 1)
    integer :: months(2)   ! months to be interpolated (1 to 12)
    integer, dimension(12) :: ndaypm= &
         (/31,28,31,30,31,30,31,31,30,31,30,31/) !days per month
!-----------------------------------------------------------------------

    t = (kda-0.5) / ndaypm(kmo)
    it(1) = t + 0.5
    it(2) = it(1) + 1
    months(1) = kmo + it(1) - 1
    months(2) = kmo + it(2) - 1
    if (months(1) <  1) months(1) = 12
    if (months(2) > 12) months(2) = 1
    timwt(1) = (it(1)+0.5) - t
    timwt(2) = 1.-timwt(1)

     


!       call clmdebug_ACASA(' call readMonthlyVegetation')
       call readMonthlyVegetation(kmo, kda, months)

  end subroutine interpMonthlyVeg

!-----------------------------------------------------------------------
!BOP
!
! !IROUTINE: readMonthlyVegetation
!
! !INTERFACE:
!  subroutine readMonthlyVegetation (kmo, kda, months)

  subroutine readMonthlyVegetation(kmo, kda, months)
!
! !DESCRIPTION:
! Read monthly vegetation data for two consec. months.
!
! !USES:
    use clmtype45
    use clm_varpar45  , only : lsmlon, lsmlat, maxpatch_pft, maxpatch,  numpft
    use clm_varcon45 , only: hvt, hvb ,lai,sai
!
! !ARGUMENTS:
    implicit none
    integer, intent(in) :: kmo            ! month (1, ..., 12)
    integer, intent(in) :: kda            ! day of month (1, ..., 31)
    integer, intent(in) :: months(2)      ! months to be interpolated (1 to 12)

!
! !REVISION HISTORY:
! Created by Sam Levis
!
!EOP
!
! LOCAL VARIABLES:
    integer :: i,j,k,l,m,p,ivt            ! indices
    integer :: begg
    integer :: endg
    integer :: begl
    integer :: endl
    integer :: begc
    integer :: endc
    integer :: begp
    integer :: endp

    integer :: ier                        ! error code
!-----------------------------------------------------------------------

! begg,begl,begc,begp are all equal to 1
      call get_proc_bounds (begg, endg, begl, endl, begc, endc, begp, endp)
      do k=1,2
          do p = begp, endp
            ! i = clm3%g%l%c%p%ixy(p)
            ! j = clm3%g%l%c%p%jxy(p)
             m = clm3%g%l%c%p%mxy(p)
             ivt = clm3%g%l%c%p%itype(p)
!          call clmdebug_ACASA('mark1') 
             ! Assign lai/sai/hgtt/hgtb to the top [maxpatch_pft] pfts
             ! as determined in subroutine surfrd
                if((m <= maxpatch_pft.and.ivt/=0).or.ivt==15.or.ivt==16)then!vegetated pft
              !  if(ivt/=0.or.ivt==15.or.ivt==16)then!vegetated pft
 
                   if (k == 1) then
!                   call clmdebug_ACASA('if (k == 1) m1')
                      mlai1(p) = lai(ivt,months(k))
                   
                      msai1(p) = sai(ivt,months(k))
                      mhvt1(p) = hvt(ivt)
                      mhvb1(p) = hvb(ivt)
                   else !if (k == 2)
!                   call clmdebug_ACASA('else m1')
                      mlai2(p) = lai(ivt,months(k))
                      msai2(p) = sai(ivt,months(k))
                      mhvt2(p) = hvt(ivt)
                      mhvb2(p) = hvb(ivt)
                   end if
              else  
!                 call clmdebug_ACASA('non vegetated')                      ! non-vegetated pft
                    if (k == 1) then
!                     call clmdebug_ACASA('if (k == 1) m2')
!                     call clmdebug_ACASA('test')
                      mlai1(p) = 0_r8

                      msai1(p) = 0_r8
                      mhvt1(p) = 0_r8
!                      call clmdebug_ACASA('mhvb1(p)')
!                       mhvb1(p) = 0_r8

                   else !if (k == 2)
!                     call clmdebug_ACASA('else m2')
                      mlai2(p) = 0.
                      msai2(p) = 0.
                      mhvt2(p) = 0.
                      mhvb2(p) = 0.
                   end if
                end if

          end do   ! end of loop over pfts

       end do   ! end of loop over months
!do p = begp, endp
!          clm3%g%l%c%p%pps%tlai(p) = timwt(1)*mlai1(p) + timwt(2)*mlai2(p)
!          clm3%g%l%c%p%pps%tsai(p) = timwt(1)*msai1(p) + timwt(2)*msai2(p)
!          clm3%g%l%c%p%pps%htop(p) = timwt(1)*mhvt1(p) + timwt(2)*mhvt2(p)
!          clm3%g%l%c%p%pps%hbot(p) = timwt(1)*mhvb1(p) + timwt(2)*mhvb2(p) 
!enddo
!   call clmdebug_ACASA('done readMonthlyVegetation')

  end subroutine readMonthlyVegetation

!-----------------------------------------------------------------------
!BOP
!
! !IROUTINE: EcosystemDyn_dealloc
!
! !INTERFACE:
  subroutine EcosystemDyn_dealloc ()
!
    implicit none
!
!EOP
!-----------------------------------------------------------------------

    if(allocated(mlai1)) deallocate (mlai1)
    if(allocated(mlai2)) deallocate (mlai2)
    if(allocated(msai1)) deallocate (msai1)
    if(allocated(msai2)) deallocate (msai2)
    if(allocated(mhvt1)) deallocate (mhvt1)
    if(allocated(mhvt2)) deallocate (mhvt2)
    if(allocated(mhvb1)) deallocate (mhvb1)
    if(allocated(mhvb2)) deallocate (mhvb2)

  end subroutine EcosystemDyn_dealloc

#endif

end module staticecosysdynmod_ACASA


subroutine cninispecial_ACASA ( )

!#ifdef CN
!
! !DESCRIPTION:
! One-time initialization of CN variables for special landunits
!
! !USES:
   use shr_kind_mod, only: r8 => shr_kind_r8
   use pftvarcon45   , only: noveg
   use decompmod_ACASA   , only: get_proc_bounds
   use clm_varcon45  , only: spval, nlevdecomp_full
!   use clm_varctl  , only: iulog, use_c13, use_c14
   use clmtype45
   use cnsetvaluemod_ACASA
    use filtermod_ACASA, only: filter
!   use surfrdMod   , only: crop_prog
!
! !ARGUMENTS:
   implicit none
!
! !CALLED FROM:
! subroutine iniTimeConst in file iniTimeConst.F90
!
! !REVISION HISTORY:
! 11/13/03: Created by Peter Thornton
!F. Li and S. Levis (11/06/12)
!
! local pointers to implicit in arguments
!
  integer , pointer :: clandunit(:)    ! landunit index of corresponding column
  integer , pointer :: plandunit(:)    ! landunit index of corresponding pft
  logical , pointer :: ifspecial(:)    ! BOOL: true=>landunit is wetland,ice,lake, or urban
!
! local pointers to implicit out arguments
!
! !LOCAL VARIABLES:
!EOP
   integer :: fc,fp,l,c,p,j,np,nc ! indices
   integer :: begp, endp    ! per-clump/proc beginning and ending pft indices
   integer :: begc, endc    ! per-clump/proc beginning and ending column indices
   integer :: begl, endl    ! per-clump/proc beginning and ending landunit indices
   integer :: begg, endg    ! per-clump/proc gridcell ending gridcell indices
   integer :: num_specialc  ! number of good values in specialc filter
   integer :: num_specialp  ! number of good values in specialp filter
   integer, allocatable :: specialc(:) ! special landunit filter - columns
   integer, allocatable :: specialp(:) ! special landunit filter - pfts
!-----------------------------------------------------------------------
   ! assign local pointers at the landunit level
   ifspecial => clm3%g%l%ifspecial

   ! assign local pointers at the column level
   clandunit => clm3%g%l%c%landunit

   ! assign local pointers at the pft level
   plandunit => clm3%g%l%c%p%landunit

   ! Determine subgrid bounds on this processor
   call get_proc_bounds(begg, endg, begl, endl, begc, endc, begp, endp)
   ! allocate special landunit filters
   allocate(specialc(endc-begc+1))
   allocate(specialp(endp-begp+1))

   ! fill special landunit filters
   num_specialc = 0
   do c = begc, endc
      l = clandunit(c)
      if (ifspecial(l)) then
         num_specialc = num_specialc + 1
         specialc(num_specialc) = c
      end if
   end do

   num_specialp = 0
   do p = begp, endp
      l = plandunit(p)
      if (ifspecial(l)) then
         num_specialp = num_specialp + 1
         specialp(num_specialp) = p
      end if
   end do
   ! initialize column-level fields
   call CNSetCps(num_specialc, specialc, spval, clm3%g%l%c%cps)
   call CNSetCcs(num_specialc, specialc, 0._r8, clm3%g%l%c%ccs)
   call CNSetCns(num_specialc, specialc, 0._r8, clm3%g%l%c%cns)
   call CNSetCcf(num_specialc, specialc, 0._r8, clm3%g%l%c%ccf)
   call CNSetCnf(num_specialc, specialc, 0._r8, clm3%g%l%c%cnf)
!   if ( use_c13 ) then
!      call CNSetCcs(num_specialc, specialc, 0._r8, clm3%g%l%c%cc13s)
!      call CNSetCcf(num_specialc, specialc, 0._r8, clm3%g%l%c%cc13f)
!   endif

!   if ( use_c14 ) then
!      call CNSetCcs(num_specialc, specialc, 0._r8, clm3%g%l%c%cc14s)
!!      call CNSetCcf(num_specialc, specialc, 0._r8, clm3%g%l%c%cc14f)
!   endif

   ! initialize column-average pft fields
   call CNSetPps(num_specialc, specialc, spval, clm3%g%l%c%cps%pps_a)
   call CNSetPcs(num_specialc, specialc, 0._r8, clm3%g%l%c%ccs%pcs_a)
   call CNSetPns(num_specialc, specialc, 0._r8, clm3%g%l%c%cns%pns_a)
   call CNSetPcf(num_specialc, specialc, 0._r8, clm3%g%l%c%ccf%pcf_a)
   call CNSetPnf(num_specialc, specialc, 0._r8, clm3%g%l%c%cnf%pnf_a)

   ! initialize pft-level fields
   call CNSetPepv(num_specialp, specialp, spval, clm3%g%l%c%p%pepv)
   call CNSetPps(num_specialp, specialp, spval, clm3%g%l%c%p%pps)
   call CNSetPcs(num_specialp, specialp, 0._r8, clm3%g%l%c%p%pcs)
   call CNSetPns(num_specialp, specialp, 0._r8, clm3%g%l%c%p%pns)
   call CNSetPcf(num_specialp, specialp, 0._r8, clm3%g%l%c%p%pcf)
   call CNSetPnf(num_specialp, specialp, 0._r8, clm3%g%l%c%p%pnf)

!   if ( use_c13 ) then
!      call CNSetPcs(num_specialp, specialp, 0._r8, clm3%g%l%c%p%pc13s)
!      call CNSetPcf(num_specialp, specialp, 0._r8, clm3%g%l%c%p%pc13f)
!   endif

!   if ( use_c14 ) then
!      call CNSetPcs(num_specialp, specialp, 0._r8, clm3%g%l%c%p%pc14s)
!      call CNSetPcf(num_specialp, specialp, 0._r8, clm3%g%l%c%p%pc14f)
!   endif

   ! now loop through special filters and explicitly set the variables that
   ! have to be in place for SurfaceAlbedo and biogeophysics
   ! also set pcf%psnsun and pcf%psnsha to 0 (not included in CNSetPcf())

   do fp = 1,num_specialp
      p = specialp(fp)
      clm3%g%l%c%p%pps%tlai(p) = 0._r8
      clm3%g%l%c%p%pps%tsai(p) = 0._r8
      clm3%g%l%c%p%pps%elai(p) = 0._r8
      clm3%g%l%c%p%pps%esai(p) = 0._r8
      clm3%g%l%c%p%pps%htop(p) = 0._r8
      clm3%g%l%c%p%pps%hbot(p) = 0._r8
      clm3%g%l%c%p%pps%fwet(p) = 0._r8
      clm3%g%l%c%p%pps%fdry(p) = 0._r8
      clm3%g%l%c%p%pps%frac_veg_nosno_alb(p) = 0._r8
      clm3%g%l%c%p%pps%frac_veg_nosno(p) = 0._r8
      clm3%g%l%c%p%pcf%psnsun(p) = 0._r8
      clm3%g%l%c%p%pcf%psnsha(p) = 0._r8
!      if (crop_prog) clm3%g%l%c%p%pnf%fert(p)   = 0._r8

!     if ( use_c13 ) then
!        clm3%g%l%c%p%pc13f%psnsun(p) = 0._r8
!        clm3%g%l%c%p%pc13f%psnsha(p) = 0._r8
!     endif

!     if ( use_c14 ) then
!        clm3%g%l%c%p%pc14f%psnsun(p) = 0._r8
!        clm3%g%l%c%p%pc14f%psnsha(p) = 0._r8
!     endif
      
   end do

   do fc = 1,num_specialc
      c = specialc(fc)
      clm3%g%l%c%cwf%qflx_irrig(c) = 0._r8
      clm3%g%l%c%ccf%pcf_a%psnsun(c) = 0._r8
      clm3%g%l%c%ccf%pcf_a%psnsha(c) = 0._r8
      
!      if ( use_c13 ) then
!         clm3%g%l%c%cc13f%pcf_a%psnsun(c) = 0._r8
!         clm3%g%l%c%cc13f%pcf_a%psnsha(c) = 0._r8
!      endif
      
!      if ( use_c14 ) then
!         clm3%g%l%c%cc14f%pcf_a%psnsun(c) = 0._r8
!         clm3%g%l%c%cc14f%pcf_a%psnsha(c) = 0._r8
!      endif
      
      ! adding dynpft code
      clm3%g%l%c%ccs%seedc(c) = 0._r8
      clm3%g%l%c%ccs%prod10c(c) = 0._r8	  
      clm3%g%l%c%ccs%prod100c(c) = 0._r8	  
      clm3%g%l%c%ccs%totprodc(c) = 0._r8	  
      
!      if ( use_c13 ) then
!         clm3%g%l%c%cc13s%seedc(c) = 0._r8
!         clm3%g%l%c%cc13s%prod10c(c) = 0._r8	  
!!         clm3%g%l%c%cc13s%prod100c(c) = 0._r8	  
!         clm3%g%l%c%cc13s%totprodc(c) = 0._r8	  
!      endif
      
!      if ( use_c14 ) then
!         clm3%g%l%c%cc14s%seedc(c) = 0._r8
!         clm3%g%l%c%cc14s%prod10c(c) = 0._r8	  
!         clm3%g%l%c%cc14s%prod100c(c) = 0._r8	  
!         clm3%g%l%c%cc14s%totprodc(c) = 0._r8	  
!      endif
      
      clm3%g%l%c%cns%seedn(c) = 0._r8
      clm3%g%l%c%cns%prod10n(c) = 0._r8	  
      clm3%g%l%c%cns%prod100n(c) = 0._r8	  
      clm3%g%l%c%cns%totprodn(c) = 0._r8	  
      clm3%g%l%c%ccf%dwt_seedc_to_leaf(c) = 0._r8
      clm3%g%l%c%ccf%dwt_seedc_to_deadstem(c) = 0._r8
      clm3%g%l%c%ccf%dwt_conv_cflux(c) = 0._r8
      clm3%g%l%c%ccf%lf_conv_cflux(c) = 0._r8    ! F. Li and S. Levis
      clm3%g%l%c%ccf%dwt_prod10c_gain(c) = 0._r8
      clm3%g%l%c%ccf%prod10c_loss(c) = 0._r8
      clm3%g%l%c%ccf%dwt_prod100c_gain(c) = 0._r8
      clm3%g%l%c%ccf%prod100c_loss(c) = 0._r8
      clm3%g%l%c%ccf%dwt_closs(c) = 0._r8
      clm3%g%l%c%ccf%landuseflux(c) = 0._r8
      clm3%g%l%c%ccf%landuptake(c) = 0._r8
      do j = 1, nlevdecomp_full
         clm3%g%l%c%ccf%dwt_frootc_to_litr_met_c(c,j) = 0._r8
         clm3%g%l%c%ccf%dwt_frootc_to_litr_cel_c(c,j) = 0._r8
         clm3%g%l%c%ccf%dwt_frootc_to_litr_lig_c(c,j) = 0._r8
         clm3%g%l%c%ccf%dwt_livecrootc_to_cwdc(c,j) = 0._r8
         clm3%g%l%c%ccf%dwt_deadcrootc_to_cwdc(c,j) = 0._r8
      end do
!      if ( use_c13 ) then
!         clm3%g%l%c%cc13f%dwt_seedc_to_leaf(c) = 0._r8
!         clm3%g%l%c%cc13f%dwt_seedc_to_deadstem(c) = 0._r8
!         clm3%g%l%c%cc13f%dwt_conv_cflux(c) = 0._r8
!         clm3%g%l%c%cc13f%dwt_prod10c_gain(c) = 0._r8
!!         clm3%g%l%c%cc13f%prod10c_loss(c) = 0._r8
!         clm3%g%l%c%cc13f%dwt_prod100c_gain(c) = 0._r8
!         clm3%g%l%c%cc13f%prod100c_loss(c) = 0._r8
!         do j = 1, nlevdecomp_full
!            clm3%g%l%c%cc13f%dwt_frootc_to_litr_met_c(c,j) = 0._r8
!            clm3%g%l%c%cc13f%dwt_frootc_to_litr_cel_c(c,j) = 0._r8
!            clm3%g%l%c%cc13f%dwt_frootc_to_litr_lig_c(c,j) = 0._r8
!            clm3%g%l%c%cc13f%dwt_livecrootc_to_cwdc(c,j) = 0._r8
!            clm3%g%l%c%cc13f%dwt_deadcrootc_to_cwdc(c,j) = 0._r8
!         end do
!         clm3%g%l%c%cc13f%dwt_closs(c) = 0._r8
         
!      endif

!      if ( use_c14 ) then
!         clm3%g%l%c%cc14f%dwt_seedc_to_leaf(c) = 0._r8
!         clm3%g%l%c%cc14f%dwt_seedc_to_deadstem(c) = 0._r8
!         clm3%g%l%c%cc14f%dwt_conv_cflux(c) = 0._r8
!         clm3%g%l%c%cc14f%dwt_prod10c_gain(c) = 0._r8
!!         clm3%g%l%c%cc14f%prod10c_loss(c) = 0._r8
!         clm3%g%l%c%cc14f%dwt_prod100c_gain(c) = 0._r8
!         clm3%g%l%c%cc14f%prod100c_loss(c) = 0._r8
!         do j = 1, nlevdecomp_full
!            clm3%g%l%c%cc14f%dwt_frootc_to_litr_met_c(c,j) = 0._r8
!            clm3%g%l%c%cc14f%dwt_frootc_to_litr_cel_c(c,j) = 0._r8
!            clm3%g%l%c%cc14f%dwt_frootc_to_litr_lig_c(c,j) = 0._r8
!            clm3%g%l%c%cc14f%dwt_livecrootc_to_cwdc(c,j) = 0._r8
!            clm3%g%l%c%cc14f%dwt_deadcrootc_to_cwdc(c,j) = 0._r8
!         end do
!!         clm3%g%l%c%cc14f%dwt_closs(c) = 0._r8
!      endif
      
      clm3%g%l%c%cnf%dwt_seedn_to_leaf(c) = 0._r8
      clm3%g%l%c%cnf%dwt_seedn_to_deadstem(c) = 0._r8
      clm3%g%l%c%cnf%dwt_conv_nflux(c) = 0._r8
      clm3%g%l%c%cnf%dwt_prod10n_gain(c) = 0._r8
      clm3%g%l%c%cnf%prod10n_loss(c) = 0._r8
      clm3%g%l%c%cnf%dwt_prod100n_gain(c) = 0._r8
      clm3%g%l%c%cnf%prod100n_loss(c) = 0._r8
      do j = 1, nlevdecomp_full
         clm3%g%l%c%cnf%dwt_frootn_to_litr_met_n(c,j) = 0._r8
         clm3%g%l%c%cnf%dwt_frootn_to_litr_cel_n(c,j) = 0._r8
         clm3%g%l%c%cnf%dwt_frootn_to_litr_lig_n(c,j) = 0._r8
         clm3%g%l%c%cnf%dwt_livecrootn_to_cwdn(c,j) = 0._r8
         clm3%g%l%c%cnf%dwt_deadcrootn_to_cwdn(c,j) = 0._r8
      end do
      clm3%g%l%c%cnf%dwt_nloss(c) = 0._r8
      
   end do
   
   ! deallocate special landunit filters
   deallocate(specialc)
   deallocate(specialp)
   
!#endif
   
end subroutine cninispecial_ACASA

