!         write(s_logunit,F00) 'Either set: iyear_AD, OR [obliq, eccen, and mvelp]:'
!         write(s_logunit,F00) 'iyear_AD is the year to simulate orbit for (ie. 1950): '
!         write(s_logunit,F00) 'obliq, eccen, mvelp specify the orbit directly:'
!         write(s_logunit,F00) 'The AMIP II settings (for a 1995 orbit) are: '
!         write(s_logunit,F00) ' obliq =  23.4441'
!         write(s_logunit,F00) ' eccen =   0.016715'
!         write(s_logunit,F00) ' mvelp = 102.7'
!         call shr_sys_abort(subname//' ERROR: unreasonable obliq')
!      else if ( log_print ) then
!         write(s_logunit,F00) 'Use input orbital parameters: '
!      end if
!      if( (obliq < SHR_ORB_OBLIQ_MIN).or.(obliq > SHR_ORB_OBLIQ_MAX) ) then
!         write(s_logunit,F03) 'Input obliquity unreasonable: ', obliq
!         call shr_sys_abort(subname//' ERROR: unreasonable obliq')
!      end if
!      if( (eccen < SHR_ORB_ECCEN_MIN).or.(eccen > SHR_ORB_ECCEN_MAX) ) then
!         write(s_logunit,F03) 'Input eccentricity unreasonable: ', eccen
!         call shr_sys_abort(subname//' ERROR: unreasonable eccen')
!      end if
!      if( (mvelp < SHR_ORB_MVELP_MIN).or.(mvelp > SHR_ORB_MVELP_MAX) ) then
!         write(s_logunit,F03) 'Input mvelp unreasonable: ' , mvelp
!         call shr_sys_abort(subname//' ERROR: unreasonable mvelp')
!      end if
      eccen2 = eccen*eccen
      eccen3 = eccen2*eccen

   ELSE  ! Otherwise calculate based on years before present
 
!      if ( log_print .and. s_loglev > 0) then
!         write(s_logunit,F01) 'Calculate orbit for year: ' , iyear_AD
!      end if
      yb4_1950AD = 1950.0_SHR_KIND_R8 - real(iyear_AD,SHR_KIND_R8)
!      if ( abs(yb4_1950AD) .gt. 1000000.0_SHR_KIND_R8 )then
!         write(s_logunit,F00) 'orbit only valid for years+-1000000'
!         write(s_logunit,F00) 'Relative to 1950 AD'
!         write(s_logunit,F03) '# of years before 1950: ',yb4_1950AD
!         write(s_logunit,F01) 'Year to simulate was  : ',iyear_AD
!         call shr_sys_abort(subname//' ERROR: unreasonable year')
!      end if
 
      ! The following calculates the earths obliquity, orbital eccentricity
      ! (and various powers of it) and vernal equinox mean longitude of
      ! perihelion for years in the past (future = negative of years past),
      ! using constants (see parameter section) given in the program of:
      !
      ! Berger, Andre.  1978  A Simple Algorithm to Compute Long-Term Variations
      ! of Daily Insolation.  Contribution 18, Institute of Astronomy and
      ! Geophysics, Universite Catholique de Louvain, Louvain-la-Neuve, Belgium.
      !
      ! and formulas given in the paper (where less precise constants are also
      ! given):
      !
      ! Berger, Andre.  1978.  Long-Term Variations of Daily Insolation and
      ! Quaternary Climatic Changes.  J. of the Atmo. Sci. 35:2362-2367
      !
      ! The algorithm is valid only to 1,000,000 years past or hence.
      ! For a solution valid to 5-10 million years past see the above author.
      ! Algorithm below is better for years closer to present than is the
      ! 5-10 million year solution.
      !
      ! Years to time of interest must be negative of years before present
      ! (1950) in formulas that follow. 
 
      years = - yb4_1950AD
 
      ! In the summations below, cosine or sine arguments, which end up in
      ! degrees, must be converted to radians via multiplication by degrad.
      !
      ! Summation of cosine series for obliquity (epsilon in Berger 1978) in
      ! degrees. Convert the amplitudes and rates, which are in arc secs, into
      ! degrees via multiplication by psecdeg (arc seconds to degrees conversion
      ! factor).  For obliq, first term is Berger 1978 epsilon star; second
      ! term is series summation in degrees.
  
      obsum = 0.0_SHR_KIND_R8
      do i = 1, poblen
         obsum = obsum + obamp(i)*psecdeg*cos((obrate(i)*psecdeg*years + &
         &       obphas(i))*degrad)
      end do
      obliq = 23.320556_SHR_KIND_R8 + obsum
 
      ! Summation of cosine and sine series for computation of eccentricity 
      ! (eccen; e in Berger 1978) and fixed vernal equinox longitude of 
      ! perihelion (fvelp; pi in Berger 1978), which is used for computation 
      ! of moving vernal equinox longitude of perihelion.  Convert the rates, 
      ! which are in arc seconds, into degrees via multiplication by psecdeg.
 
      cossum = 0.0_SHR_KIND_R8
      do i = 1, pecclen
        cossum = cossum+ecamp(i)*cos((ecrate(i)*psecdeg*years+ecphas(i))*degrad)
      end do
 
      sinsum = 0.0_SHR_KIND_R8
      do i = 1, pecclen
        sinsum = sinsum+ecamp(i)*sin((ecrate(i)*psecdeg*years+ecphas(i))*degrad)
      end do
 
      ! Use summations to calculate eccentricity
 
      eccen2 = cossum*cossum + sinsum*sinsum
      eccen  = sqrt(eccen2)
      eccen3 = eccen2*eccen
 
      ! A series of cases for fvelp, which is in radians.
         
      if (abs(cossum) .le. 1.0E-8_SHR_KIND_R8) then
        if (sinsum .eq. 0.0_SHR_KIND_R8) then
          fvelp = 0.0_SHR_KIND_R8
        else if (sinsum .lt. 0.0_SHR_KIND_R8) then
          fvelp = 1.5_SHR_KIND_R8*pi
        else if (sinsum .gt. 0.0_SHR_KIND_R8) then
          fvelp = .5_SHR_KIND_R8*pi
        endif
      else if (cossum .lt. 0.0_SHR_KIND_R8) then
        fvelp = atan(sinsum/cossum) + pi
      else if (cossum .gt. 0.0_SHR_KIND_R8) then
        if (sinsum .lt. 0.0_SHR_KIND_R8) then
          fvelp = atan(sinsum/cossum) + 2.0_SHR_KIND_R8*pi
        else
          fvelp = atan(sinsum/cossum)
        endif
      endif
 
      ! Summation of sin series for computation of moving vernal equinox long
      ! of perihelion (mvelp; omega bar in Berger 1978) in degrees.  For mvelp,
      ! first term is fvelp in degrees; second term is Berger 1978 psi bar 
      ! times years and in degrees; third term is Berger 1978 zeta; fourth 
      ! term is series summation in degrees.  Convert the amplitudes and rates,
      ! which are in arc seconds, into degrees via multiplication by psecdeg.  
      ! Series summation plus second and third terms constitute Berger 1978
      ! psi, which is the general precession.
 
      mvsum = 0.0_SHR_KIND_R8
      do i = 1, pmvelen
        mvsum = mvsum + mvamp(i)*psecdeg*sin((mvrate(i)*psecdeg*years + &
        &       mvphas(i))*degrad)
      end do
      mvelp = fvelp/degrad + 50.439273_SHR_KIND_R8*psecdeg*years + 3.392506_SHR_KIND_R8 + mvsum
 
      ! Cases to make sure mvelp is between 0 and 360.
 
      do while (mvelp .lt. 0.0_SHR_KIND_R8)
        mvelp = mvelp + 360.0_SHR_KIND_R8
      end do
      do while (mvelp .ge. 360.0_SHR_KIND_R8)
        mvelp = mvelp - 360.0_SHR_KIND_R8
      end do

   END IF  ! end of test on whether to calculate or use input orbital params
 
   ! Orbit needs the obliquity in radians
 
   obliqr = obliq*degrad
 
   ! 180 degrees must be added to mvelp since observations are made from the
   ! earth and the sun is considered (wrongly for the algorithm) to go around
   ! the earth. For a more graphic explanation see Appendix B in:
   !
   ! A. Berger, M. Loutre and C. Tricot. 1993.  Insolation and Earth Orbital
   ! Periods.  J. of Geophysical Research 98:10,341-10,362.
   !
   ! Additionally, orbit will need this value in radians. So mvelp becomes
   ! mvelpp (mvelp plus pi)
 
   mvelpp = (mvelp + 180._SHR_KIND_R8)*degrad
 
   ! Set up an argument used several times in lambm0 calculation ahead.
 
   beta = sqrt(1._SHR_KIND_R8 - eccen2)
 
   ! The mean longitude at the vernal equinox (lambda m nought in Berger
   ! 1978; in radians) is calculated from the following formula given in 
   ! Berger 1978.  At the vernal equinox the true longitude (lambda in Berger
   ! 1978) is 0.

   lambm0 = 2._SHR_KIND_R8*((.5_SHR_KIND_R8*eccen + .125_SHR_KIND_R8*eccen3)*(1._SHR_KIND_R8 + beta)*sin(mvelpp)  &
   &      - .250_SHR_KIND_R8*eccen2*(.5_SHR_KIND_R8    + beta)*sin(2._SHR_KIND_R8*mvelpp)            &
   &      + .125_SHR_KIND_R8*eccen3*(1._SHR_KIND_R8/3._SHR_KIND_R8 + beta)*sin(3._SHR_KIND_R8*mvelpp))
 
!   if ( log_print ) then
!     write(s_logunit,F03) '------ Computed Orbital Parameters ------'
!     write(s_logunit,F03) 'Eccentricity      = ',eccen
!     write(s_logunit,F03) 'Obliquity (deg)   = ',obliq
!     write(s_logunit,F03) 'Obliquity (rad)   = ',obliqr
!     write(s_logunit,F03) 'Long of perh(deg) = ',mvelp
!     write(s_logunit,F03) 'Long of perh(rad) = ',mvelpp
!     write(s_logunit,F03) 'Long at v.e.(rad) = ',lambm0
!     write(s_logunit,F03) '-----------------------------------------'
!   end if
 
END SUBROUTINE shr_orb_params

!===============================================================================

SUBROUTINE shr_orb_decl(calday ,eccen ,mvelpp ,lambm0 ,obliqr ,delta ,eccf)

!-------------------------------------------------------------------------------
!
! Compute earth/orbit parameters using formula suggested by
! Duane Thresher.
!
!---------------------------Code history----------------------------------------
!
! Original version:  Erik Kluzek
! Date:              Oct/1997
!
!-------------------------------------------------------------------------------

   !------------------------------Arguments--------------------------------
   real   (SHR_KIND_R8),intent(in)  :: calday ! Calendar day, including fraction
   real   (SHR_KIND_R8),intent(in)  :: eccen  ! Eccentricity
   real   (SHR_KIND_R8),intent(in)  :: obliqr ! Earths obliquity in radians
   real   (SHR_KIND_R8),intent(in)  :: lambm0 ! Mean long of perihelion at the 
                                              ! vernal equinox (radians)
   real   (SHR_KIND_R8),intent(in)  :: mvelpp ! moving vernal equinox longitude
                                              ! of perihelion plus pi (radians)
   real   (SHR_KIND_R8),intent(out) :: delta  ! Solar declination angle in rad
   real   (SHR_KIND_R8),intent(out) :: eccf   ! Earth-sun distance factor (ie. (1/r)**2)
 
   !---------------------------Local variables-----------------------------
   real   (SHR_KIND_R8),parameter :: dayspy = 365.0_SHR_KIND_R8  ! days per year
   real   (SHR_KIND_R8),parameter :: ve     = 80.5_SHR_KIND_R8   ! Calday of vernal equinox
                                                     ! assumes Jan 1 = calday 1
 
   real   (SHR_KIND_R8) ::   lambm  ! Lambda m, mean long of perihelion (rad)
   real   (SHR_KIND_R8) ::   lmm    ! Intermediate argument involving lambm
   real   (SHR_KIND_R8) ::   lamb   ! Lambda, the earths long of perihelion
   real   (SHR_KIND_R8) ::   invrho ! Inverse normalized sun/earth distance
   real   (SHR_KIND_R8) ::   sinl   ! Sine of lmm
 
   ! Compute eccentricity factor and solar declination using
   ! day value where a round day (such as 213.0) refers to 0z at
   ! Greenwich longitude.
   !
   ! Use formulas from Berger, Andre 1978: Long-Term Variations of Daily
   ! Insolation and Quaternary Climatic Changes. J. of the Atmo. Sci.
   ! 35:2362-2367.
   !
   ! To get the earths true longitude (position in orbit; lambda in Berger 
   ! 1978) which is necessary to find the eccentricity factor and declination,
   ! must first calculate the mean longitude (lambda m in Berger 1978) at
   ! the present day.  This is done by adding to lambm0 (the mean longitude
   ! at the vernal equinox, set as March 21 at noon, when lambda=0; in radians)
   ! an increment (delta lambda m in Berger 1978) that is the number of
   ! days past or before (a negative increment) the vernal equinox divided by
   ! the days in a model year times the 2*pi radians in a complete orbit.
 
   lambm = lambm0 + (calday - ve)*2._SHR_KIND_R8*pi/dayspy
   lmm   = lambm  - mvelpp
 
   ! The earths true longitude, in radians, is then found from
   ! the formula in Berger 1978:
 
   sinl  = sin(lmm)
   lamb  = lambm  + eccen*(2._SHR_KIND_R8*sinl + eccen*(1.25_SHR_KIND_R8*sin(2._SHR_KIND_R8*lmm)  &
   &     + eccen*((13.0_SHR_KIND_R8/12.0_SHR_KIND_R8)*sin(3._SHR_KIND_R8*lmm) - 0.25_SHR_KIND_R8*sinl)))
 
   ! Using the obliquity, eccentricity, moving vernal equinox longitude of
   ! perihelion (plus), and earths true longitude, the declination (delta)
   ! and the normalized earth/sun distance (rho in Berger 1978; actually inverse
   ! rho will be used), and thus the eccentricity factor (eccf), can be 
   ! calculated from formulas given in Berger 1978.
 
   invrho = (1._SHR_KIND_R8 + eccen*cos(lamb - mvelpp)) / (1._SHR_KIND_R8 - eccen*eccen)
 
   ! Set solar declination and eccentricity factor
 
   delta  = asin(sin(obliqr)*sin(lamb))
   eccf   = invrho*invrho
 
   return
 
END SUBROUTINE shr_orb_decl

!===============================================================================

SUBROUTINE shr_orb_print( iyear_AD, eccen, obliq, mvelp )

!-------------------------------------------------------------------------------
!
! Print out the information on the Earths input orbital characteristics
!
!---------------------------Code history----------------------------------------
!
! Original version:  Erik Kluzek
! Date:              Oct/1997
!
!-------------------------------------------------------------------------------

   !---------------------------Arguments----------------------------------------
   integer(SHR_KIND_IN),intent(in) :: iyear_AD ! requested Year (AD)
   real   (SHR_KIND_R8),intent(in) :: eccen    ! eccentricity (unitless) 
                                               ! (typically 0 to 0.1)
   real   (SHR_KIND_R8),intent(in) :: obliq    ! obliquity (-90 to +90 degrees) 
                                               ! typically 22-26
   real   (SHR_KIND_R8),intent(in) :: mvelp    ! moving vernal equinox at perhel
                                               ! (0 to 360 degrees)
   !-------------------------- Formats -----------------------------------------
   character(len=*),parameter :: F00 = "('(shr_orb_print) ',4a)"
   character(len=*),parameter :: F01 = "('(shr_orb_print) ',a,i9.4)"
   character(len=*),parameter :: F02 = "('(shr_orb_print) ',a,f6.3)"
   character(len=*),parameter :: F03 = "('(shr_orb_print) ',a,es14.6)"
   !----------------------------------------------------------------------------
 
!   if (s_loglev > 0) then
!   if ( iyear_AD .ne. SHR_ORB_UNDEF_INT ) then
!     if ( iyear_AD > 0 ) then
!       write(s_logunit,F01) 'Orbital parameters calculated for year: AD ',iyear_AD
!     else
!       write(s_logunit,F01) 'Orbital parameters calculated for year: BC ',iyear_AD
!     end if
!   else if ( obliq /= SHR_ORB_UNDEF_REAL ) then
!     write(s_logunit,F03) 'Orbital parameters: '
!     write(s_logunit,F03) 'Obliquity (degree):              ', obliq
!     write(s_logunit,F03) 'Eccentricity (unitless):         ', eccen
!     write(s_logunit,F03) 'Long. of moving Perhelion (deg): ', mvelp
!   else
!     write(s_logunit,F03) 'Orbit parameters not set!'
!   end if
!   endif
 
END SUBROUTINE shr_orb_print
!===============================================================================

END MODULE shr_orb_mod_ACASA



module cnbalancecheckmod_ACASA
!#ifdef CN

!-----------------------------------------------------------------------
!BOP
!
! !MODULE: cnbalancecheckmod_ACASA
!
! !DESCRIPTION:
! Module for carbon mass balance checking.
!
! !USES:
    use abortutils  , only: endrun
    use shr_kind_mod, only: r8 => shr_kind_r8
!    use clm_varctl  , only: iulog
    implicit none
    save
    private
! !PUBLIC MEMBER FUNCTIONS:
    public :: BeginCBalance
    public :: BeginNBalance
    public :: CBalanceCheck
    public :: NBalanceCheck
!
! !REVISION HISTORY:
! 4/23/2004: Created by Peter Thornton
!
!EOP
!-----------------------------------------------------------------------

contains

!-----------------------------------------------------------------------
!BOP
!
! !IROUTINE: BeginCBalance
!
! !INTERFACE:
subroutine BeginCBalance(lbc, ubc, num_soilc, filter_soilc)
!
! !DESCRIPTION:
! On the radiation time step, calculate the beginning carbon balance for mass
! conservation checks.
!
! !USES:
   use clmtype45
!
! !ARGUMENTS:
   implicit none
   integer, intent(in) :: lbc, ubc        ! column bounds
   integer, intent(in) :: num_soilc       ! number of soil columns filter
   integer, intent(in) :: filter_soilc(ubc-lbc+1) ! filter for soil columns
!
! !CALLED FROM:
! subroutine clm_driver1
!
! !REVISION HISTORY:
! 2/4/05: Created by Peter Thornton
!
! !LOCAL VARIABLES:
! local pointers to implicit in arrays
   real(r8), pointer :: totcolc(:)            ! (gC/m2) total column carbon, incl veg and cpool
!
! local pointers to implicit out arrays
   real(r8), pointer :: col_begcb(:)   ! carbon mass, beginning of time step (gC/m**2)

!
! !OTHER LOCAL VARIABLES:
   integer :: c     ! indices
   integer :: fc   ! lake filter indices
!
!EOP
!-----------------------------------------------------------------------
   ! assign local pointers at the column level
   col_begcb                      => clm3%g%l%c%ccbal%begcb
   totcolc                        => clm3%g%l%c%ccs%totcolc

   ! column loop
   do fc = 1,num_soilc
      c = filter_soilc(fc)
 
      ! calculate beginning column-level carbon balance,
      ! for mass conservation check
 
      col_begcb(c) = totcolc(c)

   end do ! end of columns loop
 

end subroutine BeginCBalance
!-----------------------------------------------------------------------

!-----------------------------------------------------------------------
!BOP
!
! !IROUTINE: BeginNBalance
!
! !INTERFACE:
subroutine BeginNBalance(lbc, ubc, num_soilc, filter_soilc)
!
! !DESCRIPTION:
! On the radiation time step, calculate the beginning nitrogen balance for mass
! conservation checks.
!
! !USES:
   use clmtype45
!
! !ARGUMENTS:
   implicit none
   integer, intent(in) :: lbc, ubc        ! column bounds
   integer, intent(in) :: num_soilc       ! number of soil columns filter
   integer, intent(in) :: filter_soilc(ubc-lbc+1) ! filter for soil columns
!
! !CALLED FROM:
! subroutine clm_driver1
!
! !REVISION HISTORY:
! 2/4/05: Created by Peter Thornton
!
! !LOCAL VARIABLES:
! local pointers to implicit in arrays
   real(r8), pointer :: totcoln(:)            ! (gN/m2) total column nitrogen, incl veg
!
! local pointers to implicit out arrays
   real(r8), pointer :: col_begnb(:)   ! nitrogen mass, beginning of time step (gN/m**2)
!

! !OTHER LOCAL VARIABLES:
   integer :: c     ! indices
   integer :: fc   ! lake filter indices
!
!EOP
!-----------------------------------------------------------------------
   ! assign local pointers at the column level
   col_begnb                      => clm3%g%l%c%cnbal%begnb
   totcoln                        => clm3%g%l%c%cns%totcoln

   ! column loop
   do fc = 1,num_soilc
      c = filter_soilc(fc)
 
      ! calculate beginning column-level nitrogen balance,
      ! for mass conservation check
 
      col_begnb(c) = totcoln(c)

   end do ! end of columns loop
 
end subroutine BeginNBalance
!-----------------------------------------------------------------------

!-----------------------------------------------------------------------
!BOP
!
! !IROUTINE: CBalanceCheck
!
! !INTERFACE:
subroutine CBalanceCheck(lbc, ubc, num_soilc, filter_soilc,dt)
!
! !DESCRIPTION:
! On the radiation time step, perform carbon mass conservation check for column and pft
!
! !USES:
   use clmtype45
!   use clm_time_manager, only: get_step_size
!
! !ARGUMENTS:
   implicit none
   integer, intent(in) :: lbc, ubc        ! column bounds
   integer, intent(in) :: num_soilc       ! number of soil columns in filter
   integer, intent(in) :: filter_soilc(ubc-lbc+1) ! filter for soil columns
!
! !CALLED FROM:
! subroutine clm_driver1
!
! !REVISION HISTORY:
! 12/9/03: Created by Peter Thornton
!
! !LOCAL VARIABLES:
!
! local pointers to implicit in arrays
   real(r8), pointer :: totcolc(:)            ! (gC/m2) total column carbon, incl veg and cpool
   real(r8), pointer :: gpp(:)            ! (gC/m2/s) gross primary production 
   real(r8), pointer :: er(:)            ! (gC/m2/s) total ecosystem respiration, autotrophic + heterotrophic
   real(r8), pointer :: col_fire_closs(:) ! (gC/m2/s) total column-level fire C loss
   real(r8), pointer :: col_hrv_xsmrpool_to_atm(:)  ! excess MR pool harvest mortality (gC/m2/s)
   real(r8), pointer :: dwt_closs(:)              ! (gC/m2/s) total carbon loss from product pools and conversion
   real(r8), pointer :: product_closs(:)      ! (gC/m2/s) total wood product carbon loss
   real(r8), pointer :: som_c_leached(:)    ! total SOM C loss from vertical transport (gC/m^2/s)
!
! local pointers to implicit out arrays
   real(r8), pointer :: col_cinputs(:)  ! (gC/m2/s) total column-level carbon inputs (for balance check)
   real(r8), pointer :: col_coutputs(:) ! (gC/m2/s) total column-level carbon outputs (for balance check)
   real(r8), pointer :: col_begcb(:)    ! carbon mass, beginning of time step (gC/m**2)
   real(r8), pointer :: col_endcb(:)    ! carbon mass, end of time step (gC/m**2)
   real(r8), pointer :: col_errcb(:)    ! carbon balance error for the timestep (gC/m**2)
!
! !OTHER LOCAL VARIABLES:
   integer :: c,err_index  ! indices
   integer :: fc          ! lake filter indices
   logical :: err_found      ! error flag
   real(r8):: dt             ! radiation time step (seconds)
!EOP
!-----------------------------------------------------------------------

   ! assign local pointers to column-level arrays
   totcolc                        => clm3%g%l%c%ccs%totcolc
   gpp                            => clm3%g%l%c%ccf%pcf_a%gpp
   er                             => clm3%g%l%c%ccf%er
   col_fire_closs                 => clm3%g%l%c%ccf%col_fire_closs
   col_hrv_xsmrpool_to_atm        => clm3%g%l%c%ccf%pcf_a%hrv_xsmrpool_to_atm
   dwt_closs                      => clm3%g%l%c%ccf%dwt_closs
   product_closs                  => clm3%g%l%c%ccf%product_closs
   
   col_cinputs                    => clm3%g%l%c%ccf%col_cinputs
   col_coutputs                   => clm3%g%l%c%ccf%col_coutputs
   col_begcb                      => clm3%g%l%c%ccbal%begcb
   col_endcb                      => clm3%g%l%c%ccbal%endcb
   col_errcb                      => clm3%g%l%c%ccbal%errcb
   som_c_leached                  => clm3%g%l%c%ccf%som_c_leached
   
   
   ! set time steps
!   dt = real( get_step_size(), r8 )
   
   err_found = .false.
   ! column loop
   do fc = 1,num_soilc
      c = filter_soilc(fc)
      
      ! calculate the total column-level carbon storage, for mass conservation check
      
      col_endcb(c) = totcolc(c)
      
      ! calculate total column-level inputs
      
      col_cinputs(c) = gpp(c)
      
      ! calculate total column-level outputs
      ! er = ar + hr, col_fire_closs includes pft-level fire losses
      
      col_coutputs(c) = er(c) + col_fire_closs(c) + dwt_closs(c) + product_closs(c) + col_hrv_xsmrpool_to_atm(c)
      
      ! subtract leaching flux
      col_coutputs(c) = col_coutputs(c) - som_c_leached(c)
      
      ! calculate the total column-level carbon balance error for this time step
      col_errcb(c) = (col_cinputs(c) - col_coutputs(c))*dt - &
           (col_endcb(c) - col_begcb(c))
      
      ! check for significant errors
      if (abs(col_errcb(c)) > 1e-8_r8) then
         err_found = .true.
         err_index = c
      end if
      
   end do ! end of columns loop
   
   if (err_found) then
write(*,*) 'col_cinputs',col_cinputs,'col_coutputs',col_coutputs,'col_endcb',col_endcb,'col_begcb',col_begcb,&
           'er',er,'col_fire_closs',col_fire_closs,'dwt_closs',dwt_closs,'product_closs',product_closs,'col_hrv_xsmrpool_to_atm',col_hrv_xsmrpool_to_atm,&
           'som_c_leached',som_c_leached
!      c = err_index
	!      write(iulog,*)'column cbalance error = ', col_errcb(c), c
	!      write(iulog,*)'Latdeg,Londeg=',clm3%g%latdeg(clm3%g%l%c%gridcell(c)),clm3%g%londeg(clm3%g%l%c%gridcell(c))
	!      write(iulog,*)'begcb       = ',col_begcb(c)
	!      write(iulog,*)'endcb       = ',col_endcb(c)
	!      write(iulog,*)'delta store = ',col_endcb(c)-col_begcb(c)
	write(*,*) 'end in CBalanceCheck'      
	      call endrun
	   end if
	   

	end subroutine CBalanceCheck
	!-----------------------------------------------------------------------

	!-----------------------------------------------------------------------
	!BOP
	!
	! !IROUTINE: NBalanceCheck
	!
	! !INTERFACE:
	subroutine NBalanceCheck(lbc, ubc, num_soilc, filter_soilc,dt)
	!
	! !DESCRIPTION:
	! On the radiation time step, perform nitrogen mass conservation check
	! for column and pft
	!
	! !USES:
	   use clmtype45
	!   use clm_time_manager, only: get_step_size
	!   use surfrdMod       , only: crop_prog
	!
	! !ARGUMENTS:
	   implicit none
	   integer, intent(in) :: lbc, ubc        ! column bounds
	   integer, intent(in) :: num_soilc       ! number of soil columns in filter
	   integer, intent(in) :: filter_soilc(ubc-lbc+1) ! filter for soil columns
	!
	! !CALLED FROM:
	! subroutine clm_driver1
	!
	! !REVISION HISTORY:
	! 12/9/03: Created by Peter Thornton
	!
	! !LOCAL VARIABLES:
	!
	! local pointers to implicit in arrays
	   real(r8), pointer :: totcoln(:)               ! (gN/m2) total column nitrogen, incl veg
	   real(r8), pointer :: ndep_to_sminn(:)         ! atmospheric N deposition to soil mineral N (gN/m2/s)
	   real(r8), pointer :: nfix_to_sminn(:)         ! symbiotic/asymbiotic N fixation to soil mineral N (gN/m2/s) 
	   real(r8), pointer :: fert_to_sminn(:)
	   real(r8), pointer :: soyfixn_to_sminn(:)
	   real(r8), pointer :: supplement_to_sminn(:)   ! supplemental N supply (gN/m2/s)
	   real(r8), pointer :: denit(:)                 ! total rate of denitrification (gN/m2/s)
	!#ifndef NITRIF_DENITRIF
	!   real(r8), pointer :: sminn_leached(:)         ! soil mineral N pool loss to leaching (gN/m2/s)
	!#else
	   real(r8), pointer :: smin_no3_leached(:)      ! soil mineral NO3 pool loss to leaching (gN/m2/s)
	   real(r8), pointer :: smin_no3_runoff(:)       ! soil mineral NO3 pool loss to runoff (gN/m2/s)
	   real(r8), pointer :: f_n2o_nit(:)             ! flux of N2o from nitrification [gN/m^2/s]
	!#endif
	   real(r8), pointer :: col_fire_nloss(:)        ! total column-level fire N loss (gN/m2/s)
	   real(r8), pointer :: dwt_nloss(:)              ! (gN/m2/s) total nitrogen loss from product pools and conversion
	   real(r8), pointer :: product_nloss(:)          ! (gN/m2/s) total wood product nitrogen loss
	   real(r8), pointer :: som_n_leached(:)    ! total SOM N loss from vertical transport
	!
	! local pointers to implicit in/out arrays
	!
	! local pointers to implicit out arrays
	   real(r8), pointer :: col_ninputs(:)           ! column-level N inputs (gN/m2/s)
	   real(r8), pointer :: col_noutputs(:)          ! column-level N outputs (gN/m2/s)
	   real(r8), pointer :: col_begnb(:)             ! nitrogen mass, beginning of time step (gN/m**2)
	   real(r8), pointer :: col_endnb(:)             ! nitrogen mass, end of time step (gN/m**2)
	   real(r8), pointer :: col_errnb(:)             ! nitrogen balance error for the timestep (gN/m**2)

	! !OTHER LOCAL VARIABLES:
	   integer :: c,err_index,j    ! indices
	   integer :: fc             ! lake filter indices
	   logical :: err_found      ! error flag
	   real(r8):: dt             ! radiation time step (seconds)
	!EOP
	!-----------------------------------------------------------------------
	    ! assign local pointers to column-level arrays
	   
	   totcoln                        => clm3%g%l%c%cns%totcoln
	   ndep_to_sminn                  => clm3%g%l%c%cnf%ndep_to_sminn
	   nfix_to_sminn                  => clm3%g%l%c%cnf%nfix_to_sminn
	   fert_to_sminn                  => clm3%g%l%c%cnf%fert_to_sminn
	   soyfixn_to_sminn               => clm3%g%l%c%cnf%soyfixn_to_sminn
	   supplement_to_sminn            => clm3%g%l%c%cnf%supplement_to_sminn
	   denit                          => clm3%g%l%c%cnf%denit
	!#ifndef NITRIF_DENITRIF
	!   sminn_leached                  => clm3%g%l%c%cnf%sminn_leached
	!#else
	   smin_no3_leached               => clm3%g%l%c%cnf%smin_no3_leached
	   smin_no3_runoff                => clm3%g%l%c%cnf%smin_no3_runoff
	   f_n2o_nit                      => clm3%g%l%c%cnf%f_n2o_nit
	!#endif
	   col_fire_nloss                 => clm3%g%l%c%cnf%col_fire_nloss
	   dwt_nloss                      => clm3%g%l%c%cnf%dwt_nloss
	   product_nloss                  => clm3%g%l%c%cnf%product_nloss
	   som_n_leached                  => clm3%g%l%c%cnf%som_n_leached
	   
	   col_ninputs                    => clm3%g%l%c%cnf%col_ninputs
	   col_noutputs                   => clm3%g%l%c%cnf%col_noutputs
	   col_begnb                      => clm3%g%l%c%cnbal%begnb
	   col_endnb                      => clm3%g%l%c%cnbal%endnb
	   col_errnb                      => clm3%g%l%c%cnbal%errnb
	   
	   ! set time steps
	!   dt = real( get_step_size(), r8 )
	   
	   err_found = .false.
	   ! column loop
	   do fc = 1,num_soilc
	      c=filter_soilc(fc)
	      
	      ! calculate the total column-level nitrogen storage, for mass conservation check
	      
	      col_endnb(c) = totcoln(c)
	      
	      ! calculate total column-level inputs
	      
	      col_ninputs(c) = ndep_to_sminn(c) + nfix_to_sminn(c) + supplement_to_sminn(c)
	!      if (crop_prog) col_ninputs(c) = col_ninputs(c) + &
	!                       fert_to_sminn(c) + soyfixn_to_sminn(c)
	      
	      ! calculate total column-level outputs
	      
	      col_noutputs(c) = denit(c) + col_fire_nloss(c) + dwt_nloss(c) + product_nloss(c)
	      
	!#ifndef NITRIF_DENITRIF
	!      col_noutputs(c) = col_noutputs(c) + sminn_leached(c)
	!#else
	      col_noutputs(c) = col_noutputs(c) + f_n2o_nit(c)
	      
	      col_noutputs(c) = col_noutputs(c) + smin_no3_leached(c) + smin_no3_runoff(c)
	!#endif
	      
	      col_noutputs(c) = col_noutputs(c) - som_n_leached(c)
	      
	      ! calculate the total column-level nitrogen balance error for this time step
	      
	      col_errnb(c) = (col_ninputs(c) - col_noutputs(c))*dt - &
		   (col_endnb(c) - col_begnb(c))
	      
	      if (abs(col_errnb(c)) > 1e-8_r8) then
		 err_found = .true.
		 err_index = c
	      end if
	      
	   end do ! end of columns loop
	   
	   if (err_found) then
	!      c = err_index
	!      write(iulog,*)'column nbalance error = ', col_errnb(c), c
	!      write(iulog,*)'Latdeg,Londeg=',clm3%g%latdeg(clm3%g%l%c%gridcell(c)),clm3%g%londeg(clm3%g%l%c%gridcell(c))
	!!      write(iulog,*)'begnb       = ',col_begnb(c)
	!      write(iulog,*)'endnb       = ',col_endnb(c)
	!      write(iulog,*)'delta store = ',col_endnb(c)-col_begnb(c)
	!      write(iulog,*)'input mass  = ',col_ninputs(c)*dt
	!      write(iulog,*)'output mass = ',col_noutputs(c)*dt
	!      write(iulog,*)'net flux    = ',(col_ninputs(c)-col_noutputs(c))*dt
	write(*,*) 'end in NBalanceCheck'      
	      call endrun
	   end if
	   
	 end subroutine NBalanceCheck
	 !-----------------------------------------------------------------------
	!#endif
	 
	end module cnbalancecheckmod_ACASA


	module ActiveLayerMod
	  
	  
	!-----------------------------------------------------------------------
	!BOP
	!
	! !MODULE: ActiveLayerMod
	!
	! !DESCRIPTION:
	! Module holding routines for calculation of active layer dynamics
	!
	  ! !USES:
	  use shr_kind_mod , only: r8 => shr_kind_r8
	!  use shr_const_mod_ACASA, only: SHR_CONST_TKFRZ
	!  use clm_varctl  , only: iulog
	  
	  implicit none
	  save
	  private
	  ! !PUBLIC MEMBER FUNCTIONS:
	  public:: alt_calc
	  
	  !
	  ! !REVISION HISTORY:
	  ! 6/27/2011 Created by C. Koven
	  !
	  !EOP
	  !-----------------------------------------------------------------------
	  
	contains


	  subroutine alt_calc(lbc, ubc, num_soilc, filter_soilc,mon,day,sec,dtime,nsoil0,tsoiq)
	!
	! !DESCRIPTION:
	!
	!  define active layer thickness similarly to frost_table, except set as deepest thawed layer and define on nlevgrnd
	!  also update annual maxima, and keep track of prior year for rooting memory
	!
	! !USES:
	    use clmtype45
	    use clm_varpar45      , only : nlevgrnd,nlevsno
	!    use clm_time_manager    , only : get_curr_date, get_step_size
	!    use shr_const_mod_ACASA, only: SHR_CONST_TKFRZ
	!    use clm_varctl  , only: iulog
	    use clm_varcon45, only: zsoi
	    
	    
	!
	! !ARGUMENTS:
	    implicit none
	    integer, intent(in) :: lbc, ubc        ! column bounds
	    integer, intent(in) :: num_soilc       ! number of soil columns in filter
	    integer, intent(in) :: filter_soilc(:) ! filter for soil columns
	!
	! !CALLED FROM:
	! 
	!
	! !REVISION HISTORY:
	!
	! 6/27/2011 Created by C. Koven
	!
	! !LOCAL VARIABLES:
	! local pointers to implicit in scalars
	!
	! column level
	    real(r8), pointer :: t_soisno(:,:)          ! soil temperature (Kelvin)  (-nlevsno+1:nlevgrnd)
	    real(r8), pointer :: alt(:)                 ! current depth of thaw
	    real(r8), pointer :: altmax(:)              ! maximum annual depth of thaw
	    real(r8), pointer :: altmax_lastyear(:)     ! prior year maximum annual depth of thaw
	    integer, pointer :: alt_indx(:)             ! current depth of thaw
	    integer, pointer :: altmax_indx(:)          ! maximum annual depth of thaw
	    integer, pointer :: altmax_lastyear_indx(:) ! prior year maximum annual depth of thaw
	    real(r8), pointer :: lat(:)                 ! gridcell latitude (radians)
	    integer , pointer :: cgridcell(:)           ! gridcell index of column
	    
	    ! local variables
	    integer  :: c, j, fc, g                     ! counters
	    integer  :: alt_ind                         ! index of base of activel layer
	    integer  :: year                            ! year (0, ...) for nstep+1
	    integer  :: mon                             ! month (1, ..., 12) for nstep+1
	    integer  :: day                             ! day of month (1, ..., 31) for nstep+1
	    integer  :: sec                             ! seconds into current date for nstep+1
	    integer  :: dtime                           ! time step length in seconds
	    integer  :: k_frz                           ! index of first nonfrozen soil layer
	    logical  :: found_thawlayer                 ! used to break loop when first unfrozen layer reached
	    real(r8) :: t1, t2, z1, z2                  ! temporary variables
	    real(r8) :: SHR_CONST_TKFRZ    
	    integer  :: nsoil0
	    real(r8) :: tsoiq(nsoil0)
	    ! Assign local pointers to derived type arrays
	    t_soisno                               => clm3%g%l%c%ces%t_soisno
	    alt                                    => clm3%g%l%c%cps%alt
	    altmax                                 => clm3%g%l%c%cps%altmax
	    altmax_lastyear                        => clm3%g%l%c%cps%altmax_lastyear
	    alt_indx                               => clm3%g%l%c%cps%alt_indx
	    altmax_indx                            => clm3%g%l%c%cps%altmax_indx
	    altmax_lastyear_indx                   => clm3%g%l%c%cps%altmax_lastyear_indx
	    
	    ! Assign local pointers to derived subtypes components (gridcell-level and mapping)
	    lat             => clm3%g%lat
	    cgridcell       => clm3%g%l%c%gridcell
	    
	SHR_CONST_TKFRZ = 273.15_r8   

	do j = 1,nlevgrnd
	   t_soisno(:,j) = tsoiq(j)
	enddo
	do j = -nlevsno+1,0
	   t_soisno(:,j) = tsoiq(1)
	enddo
!	do j = nsoil0+1,nlevgrnd
!	   t_soisno(:,j) = tsoiq(nsoil0)
!	enddo
	    ! on a set annual timestep, update annual maxima
	    ! make this 1 January for NH columns, 1 July for SH columns
	!    call get_curr_date(year, mon, day, sec)
	!    dtime =  get_step_size()
	    if ( (mon .eq. 1) .and. (day .eq. 1) .and. ( sec / dtime .eq. 1) ) then
	       do fc = 1,num_soilc
		  c = filter_soilc(fc)
		  g = cgridcell(c)
		  if ( lat(g) .gt. 0. ) then 
		     altmax_lastyear(c) = altmax(c)
		     altmax_lastyear_indx(c) = altmax_indx(c)
		     altmax(c) = 0.
		     altmax_indx(c) = 0
		  endif
	       end do
	    endif
	    if ( (mon .eq. 7) .and. (day .eq. 1) .and. ( sec / dtime .eq. 1) ) then
	       do fc = 1,num_soilc
		  c = filter_soilc(fc)
		  g = cgridcell(c)
		  if ( lat(g) .le. 0. ) then 
		     altmax_lastyear(c) = altmax(c)
		     altmax_lastyear_indx(c) = altmax_indx(c)
		     altmax(c) = 0.
		     altmax_indx(c) = 0
		  endif
	       end do
	    endif
	    
	    do fc = 1,num_soilc
	       c = filter_soilc(fc)
	       
	       ! calculate alt for a given timestep
	       ! start from base of soil and search upwards for first thawed layer.
	       ! note that this will put talik in with active layer
	       ! a different way of doing this could be to keep track of how long a given layer has ben frozen for, and define ALT as the first layer that has been frozen for less than 2 years.
	       if (t_soisno(c,nlevgrnd) > SHR_CONST_TKFRZ ) then
		  alt(c) = zsoi(nlevgrnd)
		  alt_indx(c) = nlevgrnd
	       else
		  k_frz=0
		  found_thawlayer = .false.
		  do j=nlevgrnd-1,1,-1
		     if ( ( t_soisno(c,j) > SHR_CONST_TKFRZ ) .and. .not. found_thawlayer ) then
			k_frz=j
			found_thawlayer = .true.
		     endif
		  end do
		  
		  if ( k_frz .gt. 0 ) then
		     ! define active layer as the depth at which the linearly interpolated temperature line intersects with zero
		     z1 = zsoi(k_frz)
		     z2 = zsoi(k_frz+1)
		     t1 = t_soisno(c,k_frz)
		     t2 = t_soisno(c,k_frz+1)
		     alt(c) = z1 + (t1-SHR_CONST_TKFRZ)*(z2-z1)/(t1-t2)
		     alt_indx(c) = k_frz
		  else
		     alt(c)=0._r8
		     alt_indx(c) = 0
		  endif
	       endif
	       
	       
	       ! if appropriate, update maximum annual active layer thickness
	       if (alt(c) .gt. altmax(c)) then
		  altmax(c) = alt(c)
		  altmax_indx(c) = alt_indx(c)
	       endif
	       
	    end do
	    
	  end subroutine alt_calc
	  
	  
	end module ActiveLayerMod


	module CNDVEcosystemDyniniMod

	!#if (defined CNDV)

	!-----------------------------------------------------------------------
	!BOP
	!
	! !MODULE: CNDVEcosystemDyniniMod
	!
	! !DESCRIPTION:
	!
	! !USES:
	  use shr_kind_mod, only: r8 => shr_kind_r8
          use decompmod_ACASA   , only: get_proc_bounds
	!
	! !PUBLIC TYPES:
	  implicit none
	  save
	!
	! !PUBLIC MEMBER FUNCTIONS:
	  public  :: CNDVEcosystemDynini ! CNDV related initializations
	!
	! !REVISION HISTORY:
	! Created by Sam Levis following CNDVEcosystemDynMod by Mariana Vertenstein
	!
	!EOP
	!-----------------------------------------------------------------------

	contains

	!-----------------------------------------------------------------------
	!BOP
	!
	! !IROUTINE: CNDVEcosystemDynini
	!
	! !INTERFACE:
	  subroutine CNDVEcosystemDynini( )
	!
	! !DESCRIPTION:
	! CNDV related initializations
	!
	! !USES:
	    use shr_kind_mod, only: r8 => shr_kind_r8
	    use clmtype45
	!    use decompmod_ACASA    , only : get_proc_bounds, get_proc_global
	!    use shr_const_mod_ACASA, only : SHR_CONST_PI, SHR_CONST_TKFRZ
	!
	! !ARGUMENTS:
	    implicit none
	!
	! !CALLED FROM:
	! subroutine initialize in module initializeMod
	!
	! !REVISION HISTORY:
	! Author: Sam Levis (adapted from LPJ initialization subroutines)
	!         Sam Levis (adapted for CNDV coupling; eliminated redunant parameters)
	!
	!EOP
	!
	! !LOCAL VARIABLES:
	    integer  :: g,p,n           ! indices
	    integer  :: begp, endp      ! per-proc beginning and ending pft indices
	    integer  :: begc, endc      !              "                column indices
	    integer  :: begl, endl      !              "                landunit indices
	    integer  :: begg, endg      !              "                gridcell indices
	    type(gridcell_type), pointer :: gptr  ! pointer to gridcell derived subtype
	    type(pft_type)     , pointer :: pptr  ! pointer to pft derived subtype
	!KC 071814
	    real(r8) :: SHR_CONST_PI
	    real(r8) :: SHR_CONST_TKFRZ
	!-----------------------------------------------------------------------
	!setup parameters
	    SHR_CONST_TKFRZ = 273.15_R8
	    SHR_CONST_PI = 3.14159265358979323846_R8
	!KC end


	    ! Set pointers into derived type

	    gptr => clm3%g
	    pptr => clm3%g%l%c%p

	    ! ---------------------------------------------------------------
	    ! Some of the following came from LPJ subroutine initgrid
	    ! ---------------------------------------------------------------

	    call get_proc_bounds(begg, endg, begl, endl, begc, endc, begp, endp)

	    do p = begp,endp
	       pptr%pdgvs%present(p)   = .false.
	       pptr%pdgvs%crownarea(p) = 0._r8
	       pptr%pdgvs%nind(p)      = 0._r8
	       pptr%pcs%leafcmax(p)    = 0._r8
	       pptr%pdgvs%t_mo_min(p)  = 1.0e+36_r8
	    end do

	    do g = begg,endg
	       gptr%gdgvs%agdd20(g)   = 0._r8
	       gptr%gdgvs%tmomin20(g) = SHR_CONST_TKFRZ - 5._r8 !initialize this way for Phenology code
	    end do
	  end subroutine CNDVEcosystemDynini

	!#endif

	end module CNDVEcosystemDyniniMod



	module CNDVEstablishmentMod

	!#if (defined CNDV)

	!-----------------------------------------------------------------------
	!BOP
	!
	! !MODULE: CNDVEstablishmentMod
	!
	! !DESCRIPTION:
	! Calculates establishment of new pfts
	! Called once per year
	!
	! !USES:
	  use shr_kind_mod, only: r8 => shr_kind_r8
	  use abortutils  , only: endrun
	!
	! !PUBLIC TYPES:
	  implicit none
	  save
	!
	! !PUBLIC MEMBER FUNCTIONS:
	  public :: Establishment
	!
	! !REVISION HISTORY:
	! Module created by Mariana Vertenstein
	!
	!EOP
	!-----------------------------------------------------------------------

	contains

	!-----------------------------------------------------------------------
	!BOP
	!
	! !IROUTINE: Establishment
	!
	! !INTERFACE:
	  subroutine Establishment(lbg, ubg, lbp, ubp,isoi3)
	!
	! !DESCRIPTION:
	! Calculates establishment of new pfts
	! Called once per year
	!
	! !USES:
	    use clmtype45
	    use clm_varpar45   , only : numpft
	    use clm_varcon45   , only : istsoil
	!    use clm_varctl   , only : iulog
	    use pftvarcon45    , only : noveg, nc3_arctic_grass
	    use pftvarcon45    , only : slatop,dsladlai,woody,dwood
	!    use shr_const_mod_ACASA, only : SHR_CONST_CDAY, SHR_CONST_PI, SHR_CONST_TKFRZ
	!
	! !ARGUMENTS:
	    implicit none
	    integer , intent(in) :: lbg, ubg         ! gridcell bounds
	    integer , intent(in) :: lbp, ubp         ! pft bounds
	!
	! !CALLED FROM:
	! subroutine dv in module CNDVMod
	!
	! !REVISION HISTORY:
	! Author: Sam Levis (adapted from Stephen Sitch's LPJ subr. establishment)
	! 3/4/02, Peter Thornton: Migrated to new data structures.
	! 10/05 , Sam Levis: adapted to work with CN
	! 09/07 , Sam Levis: as 10/05 but with current CN
	!
	! !LOCAL VARIABLES:
	!
	! local pointers to implicit in arguments
	!
	    logical , pointer :: pftmayexist(:)   ! exclude seasonal decid pfts from tropics [1=true, 0=false]
	    integer , pointer :: plandunit(:)     ! landunit of corresponding pft
	    integer , pointer :: pgridcell(:)     ! gridcell of corresponding pft
	    integer , pointer :: ltype(:)         ! landunit type for corresponding pft
	    real(r8), pointer :: tmomin20(:)      ! 20-yr running mean of tmomin
	    real(r8), pointer :: agdd20(:)        ! 20-yr running mean of agdd
	    real(r8), pointer :: agddtw(:)        ! accumulated growing degree days above twmax
	    real(r8), pointer :: prec365(:)       ! 365-day running mean of tot. precipitation
	!    real(r8), pointer :: slatop(:)    !specific leaf area at top of canopy, projected area basis [m^2/gC]
	!    real(r8), pointer :: dsladlai(:)  !dSLA/dLAI, projected area basis [m^2/gC]
	!    real(r8), pointer :: woody(:)         ! ecophys const - woody pft or not
	    real(r8), pointer :: crownarea_max(:) ! ecophys const - tree maximum crown area [m2]
	    real(r8), pointer :: twmax(:)         ! ecophys const - upper limit of temperature of the warmest month
	    real(r8), pointer :: reinickerp(:)    ! ecophys const - parameter in allometric equation
	!    real(r8), pointer :: dwood(:)         ! ecophys const - wood density (gC/m3)
	    real(r8), pointer :: allom1(:)        ! ecophys const - parameter in allometric
	    real(r8), pointer :: tcmin(:)         ! ecophys const - minimum coldest monthly mean temperature
	    real(r8), pointer :: tcmax(:)         ! ecophys const - maximum coldest monthly mean temperature
	    real(r8), pointer :: gddmin(:)        ! ecophys const - minimum growing degree days (at or above 5 C)
	    real(r8), pointer :: leafcmax(:)      ! (gC/m2) ann max leaf C
	    real(r8), pointer :: deadstemc(:)     ! (gC/m2) dead stem C
	    real(r8), pointer :: annsum_npp(:)         ! annual sum NPP (gC/m2/yr)
	    real(r8), pointer :: annsum_litfall(:)     ! annual sum litfall (gC/m2/yr)
	!
	! local pointers to implicit in/out arguments
	!
	    integer , pointer :: ivt(:)           ! vegetation type for this pft
	    logical , pointer :: present(:)       ! true=> PFT present in patch
	    real(r8), pointer :: nind(:)          ! number of individuals (#/m**2)
	!
	! local pointers to implicit out arguments
	!
	    real(r8), pointer :: fpcgrid(:)       ! foliar projective cover on gridcell (fraction)
	    real(r8), pointer :: crownarea(:)     ! area that each individual tree takes up (m^2)
	    real(r8), pointer :: greffic(:)       ! lpj's growth efficiency
	    real(r8), pointer :: heatstress(:)
	!
	!EOP
	!
	! !OTHER LOCAL VARIABLES:
	!
	    integer  :: g,l,p,m                        ! indices
	    integer  :: fn, filterg(ubg-lbg+1)         ! local gridcell filter for error check
	!
	! gridcell level variables
	!
	    integer  :: ngrass(lbg:ubg)                ! counter
	    integer  :: npft_estab(lbg:ubg)            ! counter
	    real(r8) :: fpc_tree_total(lbg:ubg)        ! total fractional cover of trees in vegetated portion of gridcell
	    real(r8) :: fpc_total(lbg:ubg)             ! old-total fractional vegetated portion of gridcell (without bare ground)
	    real(r8) :: fpc_total_new(lbg:ubg)         ! new-total fractional vegetated portion of gridcell (without bare ground)
	!
	! pft level variables
	!
	    logical  :: survive(lbp:ubp)               ! true=>pft survives
	    logical  :: estab(lbp:ubp)                 ! true=>pft is established
	    real(r8) :: dstemc(lbp:ubp)                ! local copy of deadstemc
	!
	! local and temporary variables or parameters
	!
	    real(r8) :: taper ! ratio of height:radius_breast_height (tree allometry)
	    real(r8) :: estab_rate                     !establishment rate
	    real(r8) :: estab_grid                     !establishment rate on grid cell
	    real(r8) :: fpcgridtemp                    ! temporary
	    real(r8) :: stemdiam                       ! stem diameter
	    real(r8) :: stocking                       ! #stems / ha (stocking density)
	    real(r8) :: lai_ind                        ! LAI per individual
	    real(r8) :: lm_ind                         !leaf carbon (gC/ind)
	    real(r8) :: fpc_ind                        !individual foliage projective cover
	    real(r8):: bm_delta

	    real(r8), parameter :: ramp_agddtw = 300.0

	! minimum individual density for persistence of PFT (indiv/m2)
	!
	    real(r8), parameter :: nind_min = 1.0e-10_r8
	!
	! minimum precip. for establishment (mm/s)
	!
	    real(r8), parameter :: prec_min_estab = 100._r8/(365._r8*86400._r8)
	!
	! maximum sapling establishment rate (indiv/m2)
	!
	    real(r8), parameter :: estab_max = 0.24_r8
	!-----------------------------------------------------------------------
	!KC 071814
	    real(r8) :: SHR_CONST_PI
	    real(r8) :: SHR_CONST_TKFRZ
	    real(r8) :: SHR_CONST_CDAY
	    integer  :: isoi3
	!-----------------------------------------------------------------------
	!setup parameters
	    SHR_CONST_TKFRZ = 273.15_R8
	    SHR_CONST_PI = 3.14159265358979323846_R8
	    SHR_CONST_CDAY = 86400.0_R8
	!KC end
	    ! Assign local pointers to derived type members (gridcell-level)

	    agdd20        => clm3%g%gdgvs%agdd20
	    tmomin20      => clm3%g%gdgvs%tmomin20

	    ! Assign local pointers to derived type members (landunit-level)

	    ltype => clm3%g%l%itype

	    ! Assign local pointers to derived type members (pft-level)

	    ivt           => clm3%g%l%c%p%itype
	    pgridcell     => clm3%g%l%c%p%gridcell
	    plandunit     => clm3%g%l%c%p%landunit
	    present       => clm3%g%l%c%p%pdgvs%present
	    nind          => clm3%g%l%c%p%pdgvs%nind
	    fpcgrid       => clm3%g%l%c%p%pdgvs%fpcgrid
	    crownarea     => clm3%g%l%c%p%pdgvs%crownarea
	    greffic       => clm3%g%l%c%p%pdgvs%greffic
	    heatstress    => clm3%g%l%c%p%pdgvs%heatstress
	    annsum_npp     => clm3%g%l%c%p%pepv%annsum_npp
	    annsum_litfall => clm3%g%l%c%p%pepv%annsum_litfall
	    prec365       => clm3%g%l%c%p%pdgvs%prec365
	    agddtw        => clm3%g%l%c%p%pdgvs%agddtw
	    pftmayexist   => clm3%g%l%c%p%pdgvs%pftmayexist

	    ! Assign local pointers to derived type members (vegetation types)

	    crownarea_max => dgv_pftcon%crownarea_max
	    twmax         => dgv_pftcon%twmax
	    reinickerp    => dgv_pftcon%reinickerp
	    allom1        => dgv_pftcon%allom1
	    tcmax         => dgv_pftcon%tcmax
	    tcmin         => dgv_pftcon%tcmin
	    gddmin        => dgv_pftcon%gddmin
	    leafcmax      => clm3%g%l%c%p%pcs%leafcmax
	    deadstemc     => clm3%g%l%c%p%pcs%deadstemc
	!    slatop        => pftcon%slatop
	!    dsladlai      => pftcon%dsladlai
	!    dwood         => pftcon%dwood
	!    woody         => pftcon%woody

	    ! **********************************************************************
	    ! Slevis version of LPJ's subr. bioclim
	    ! Limits based on 20-year running averages of coldest-month mean
	    ! temperature and growing degree days (5 degree base).
	    ! For SURVIVAL, coldest month temperature and GDD should be
	    ! at least as high as PFT-specific limits.
	    ! For REGENERATION, PFT must be able to survive AND coldest month
	    ! temperature should be no higher than a PFT-specific limit.
	    ! **********************************************************************


	    taper = 200._r8 ! make a global constant as with dwood (lpj's wooddens)

	    ! Initialize gridcell-level metrics

	    do g = lbg, ubg
	       ngrass(g) = 0
	       npft_estab(g) = 0
	       fpc_tree_total(g) = 0._r8
	       fpc_total(g) = 0._r8
	       fpc_total_new(g) = 0._r8
	    end do


	    do p = lbp, ubp
	       g = pgridcell(p)

	       ! Set the presence of pft for this gridcell
	       if (nind(p) == 0._r8) present(p) = .false.
	       if (.not. present(p)) then
		  nind(p) = 0._r8
		  fpcgrid(p) = 0._r8
	       end if
	       survive(p) = .false.
	       estab(p)   = .false.
	       dstemc(p)  = deadstemc(p)
	    end do
	    ! Must go thru all 16 pfts and decide which can/cannot establish or survive
	    ! Determine present, survive, estab.  Note: Even if tmomin20>tcmax, crops
	    ! and 2nd boreal summergreen tree cannot exist (see
	    ! EcosystemDynini) because this model cannot simulate such pfts, yet.
	    ! Note - agddtw is only defined at the pft level and has now been moved
	    ! to an if-statement below to determine establishment of boreal trees
	    do p = lbp, ubp
	       g = pgridcell(p)
	       if (tmomin20(g) >= tcmin(ivt(p)) + SHR_CONST_TKFRZ ) then
		  if (tmomin20(g) <= tcmax(ivt(p)) + SHR_CONST_TKFRZ  .and. agdd20(g) >= gddmin(ivt(p))) then
		     estab(p) = .true.
		  end if
		  survive(p) = .true.
		  ! seasonal decid. pfts that would have occurred in regions without
		  ! short winter day lengths (see CNPhenology)
		  if (.not. pftmayexist(p)) then
		     survive(p) = .false.
		     estab(p) = .false.
		     pftmayexist(p) = .true.
		  end if
	       end if
	    end do


	    do p = lbp, ubp
	       g = pgridcell(p)
	       l = plandunit(p)

	       ! Case 1 -- pft ceases to exist -kill pfts not adapted to current climate

	       if (present(p) .and. (.not. survive(p) .or. nind(p)<nind_min)) then
		  present(p) = .false.
		  fpcgrid(p) = 0._r8
		  nind(p) = 0._r8

	       end if

	       ! Case 2 -- pft begins to exist - introduce newly "adapted" pfts

	!       if (ltype(l) == istsoil) then
		if (isoi3 .ne. 14) then
		  if (.not. present(p) .and. prec365(p) >= prec_min_estab .and. estab(p)) then
		     if (twmax(ivt(p)) > 999._r8 .or. agddtw(p) == 0._r8) then

			present(p) = .true.
			nind(p) = 0._r8
			! lpj starts with fpcgrid=0 and calculates
			! seed fpcgrid from the carbon of saplings;
			! with CN we need the seed fpcgrid up front
			! to scale seed leafc to lm_ind to get fpcgrid;
			! sounds circular; also seed fpcgrid depends on sla,
			! so theoretically need diff value for each pft;slevis
			fpcgrid(p) = 0.000844_r8
			if (woody(ivt(p)) < 1._r8) then
			   fpcgrid(p) = 0.05_r8
			end if

			! Seed carbon for newly established pfts
			! Equiv. to pleaf=1 & pstor=1 set in subr pftwt_cnbal (slevis)
			! ***Dangerous*** to hardwire leafcmax here; find alternative!
			! Consider just assigning nind and fpcgrid for newly
			! established pfts instead of entering the circular procedure
			! outlined in the paragraph above
			leafcmax(p) = 1._r8
			if (dstemc(p) <= 0._r8) dstemc(p) = 0.1_r8
		     end if   ! conditions required for establishment
		  end if   ! conditions required for establishment
	       end if   ! if soil

	       ! Case 3 -- some pfts continue to exist (no change) and some pfts
	       ! continue to not exist (no change). Do nothing for this case.

	    end do


	    ! Sapling and grass establishment
	    ! Calculate total woody FPC, FPC increment and grass cover (= crown area)
	    ! Calculate total woody FPC and number of woody PFTs present and able to establish
	    do p = lbp, ubp
	       g = pgridcell(p)
	       if (present(p)) then
		  if (woody(ivt(p)) == 1._r8) then
		     fpc_tree_total(g) = fpc_tree_total(g) + fpcgrid(p)
		     if (estab(p)) npft_estab(g) = npft_estab(g) + 1
		  else if (woody(ivt(p)) < 1._r8 .and. ivt(p) > noveg) then !grass
		     ngrass(g) = ngrass(g) + 1
		  end if
	       end if
	    end do

	    ! Above grid-level establishment counters are required for the next steps.
	    do p = lbp, ubp
	       g = pgridcell(p)

	       if (present(p) .and. woody(ivt(p)) == 1._r8 .and. estab(p)) then

		  ! Calculate establishment rate over available space, per tree PFT
		  ! Max establishment rate reduced by shading as tree FPC approaches 1
		  ! Total establishment rate partitioned equally among regenerating woody PFTs

		  estab_rate = estab_max * (1._r8-exp(5._r8*(fpc_tree_total(g)-1._r8))) / real(npft_estab(g))

		  ! Calculate grid-level establishment rate per woody PFT
		  ! Space available for woody PFT establishment is fraction of grid cell
		  ! not currently occupied by woody PFTs

		  estab_grid = estab_rate * (1._r8-fpc_tree_total(g))

		  ! Add new saplings to current population

		  nind(p) = nind(p) + estab_grid

		  !slevis: lpj's lm_ind was the max leaf mass for the year;
		  !now lm_ind is the max leaf mass for the year calculated in CNFire
		  !except when a pft is newly established (nind==0); then lm_ind
		  !is assigned a leafcmax above
	 
		  lm_ind = leafcmax(p) * fpcgrid(p) / nind(p) ! nind>0 for sure
		  if (fpcgrid(p) > 0._r8 .and. nind(p) > 0._r8) then
		     stocking = nind(p)/fpcgrid(p) !#ind/m2 nat veg area -> #ind/m2 pft area
		     ! stemdiam derived here from cn's formula for htop found in
		     ! CNVegStructUpdate and cn's assumption stemdiam=2*htop/taper
		     ! this derivation neglects upper htop limit enforced elsewhere
		     stemdiam = (24._r8 * dstemc(p) / (SHR_CONST_PI * stocking * dwood * taper))**(1._r8/3._r8)
		  else
		     stemdiam = 0._r8
		  end if
		  crownarea(p) = min(crownarea_max(ivt(p)), allom1(ivt(p))*stemdiam**reinickerp(ivt(p))) ! Eqn D (now also in Light; need here for 1st yr when pfts haven't established, yet)

		  ! Update LAI and FPC
		  if (crownarea(p) > 0._r8) then
		     if (dsladlai(ivt(p)) > 0._r8) then
			! make lai_ind >= 0.001 to avoid killing plants at this stage
			lai_ind = max(0.001_r8,((exp(lm_ind*dsladlai(ivt(p)) + log(slatop(ivt(p)))) - &
				      slatop(ivt(p)))/dsladlai(ivt(p))) / crownarea(p))
		     else ! currently redundant because dsladlai=0 for grasses only
			lai_ind = lm_ind * slatop(ivt(p)) / crownarea(p) ! lpj's formula
		     end if
		  else
		     lai_ind = 0._r8
		  end if

		  fpc_ind = 1._r8 - exp(-0.5_r8*lai_ind)
		  fpcgrid(p) = crownarea(p) * nind(p) * fpc_ind
	       end if   ! add new saplings block
	       if (present(p) .and. woody(ivt(p)) == 1._r8) then
		  fpc_total_new(g) = fpc_total_new(g) + fpcgrid(p)
	       end if
	    end do   ! close loop to update fpc_total_new

	    ! Adjustments- don't allow trees to exceed 95% of vegetated landunit

	    do p = lbp, ubp
	       g = pgridcell(p)
	       if (fpc_total_new(g) > 0.95_r8) then
		  if (woody(ivt(p)) == 1._r8 .and. present(p)) then
		     nind(p) = nind(p) * 0.95_r8 / fpc_total_new(g)
		     fpcgrid(p) = fpcgrid(p) * 0.95_r8 / fpc_total_new(g)
		  end if
		  fpc_total(g) = 0.95_r8

	       else
		  fpc_total(g) = fpc_total_new(g)
	       end if
	    end do
	    ! Section for grasses. Grasses can establish in non-vegetated areas

	    do p = lbp, ubp
	       g = pgridcell(p)
	       if (present(p) .and. woody(ivt(p)) < 1._r8) then
		  if (leafcmax(p) <= 0._r8 .or. fpcgrid(p) <= 0._r8 ) then
		     present(p) = .false.
		     nind(p) = 0._r8
		  else
		     nind(p) = 1._r8 ! in case these grasses just established
		     crownarea(p) = 1._r8
		     lm_ind = leafcmax(p) * fpcgrid(p) / nind(p)
		     if (dsladlai(ivt(p)) > 0._r8) then
			lai_ind = max(0.001_r8,((exp(lm_ind*dsladlai(ivt(p)) + log(slatop(ivt(p)))) - &
				      slatop(ivt(p)))/dsladlai(ivt(p))) / crownarea(p))
		     else ! 'if' is currently redundant b/c dsladlai=0 for grasses only
			lai_ind = lm_ind * slatop(ivt(p)) / crownarea(p)
		     end if
		     fpc_ind = 1._r8 - exp(-0.5_r8*lai_ind)
		     fpcgrid(p) = crownarea(p) * nind(p) * fpc_ind
		     fpc_total(g) = fpc_total(g) + fpcgrid(p)
		  end if
	       end if
	    end do   ! end of pft-loop
	    ! Adjustment of fpc_total > 1 due to grasses (ivt >= nc3_arctic_grass)

	    do p = lbp, ubp
	       g = pgridcell(p)

	       if (fpc_total(g) > 1._r8) then
		  if (ivt(p) >= nc3_arctic_grass .and. fpcgrid(p) > 0._r8) then
		     fpcgridtemp = fpcgrid(p)
		     fpcgrid(p) = max(0._r8, fpcgrid(p) - (fpc_total(g)-1._r8))
		     fpc_total(g) = fpc_total(g) - fpcgridtemp + fpcgrid(p)
		  end if
	       end if

	       ! Remove tiny fpcgrid amounts
	       if (fpcgrid(p) < 1.e-15_r8) then
		  fpc_total(g) = fpc_total(g) - fpcgrid(p)
		  fpcgrid(p) = 0._r8
		  present(p) = .false.
		  nind(p) = 0._r8
	       end if

	       ! Set the fpcgrid for bare ground if there is bare ground in
	       ! vegetated landunit and pft is bare ground so that everything
	       ! can add up to one.

	       if (fpc_total(g) < 1._r8 .and. ivt(p) == noveg) then
		  fpcgrid(p) = 1._r8 - fpc_total(g)
		  fpc_total(g) = fpc_total(g) + fpcgrid(p)
	       end if

	    end do
	    ! Annual calculations used hourly in GapMortality
	    ! Ultimately may wish to place in separate subroutine...

	    do p = lbp, ubp
	       g = pgridcell(p)

	       ! Stress mortality from lpj's subr Mortality

	       if (woody(ivt(p)) == 1._r8 .and. nind(p) > 0._r8 .and. &
		   leafcmax(p) > 0._r8 .and. fpcgrid(p) > 0._r8) then

		  if (twmax(ivt(p)) < 999._r8) then
		     heatstress(p) = max(0._r8, min(1._r8, agddtw(p) / ramp_agddtw))
		  else
		     heatstress(p) = 0._r8
		  end if

		  ! Net individual living biomass increment
		  ! NB: lpj's turnover not exactly same as cn's litfall:
		  ! lpj's sap->heartwood turnover not included in litfall (slevis)

		  bm_delta = max(0._r8, annsum_npp(p) - annsum_litfall(p))
		  lm_ind = leafcmax(p) * fpcgrid(p) / nind(p)

		  ! Growth efficiency (net biomass increment per unit leaf area)

		  if (dsladlai(ivt(p)) > 0._r8) then
		     greffic(p) = bm_delta / (max(0.001_r8,                     &
			 ( ( exp(lm_ind*dsladlai(ivt(p)) + log(slatop(ivt(p)))) &
			     - slatop(ivt(p)) ) / dsladlai(ivt(p)) )))
		  else ! currently redundant because dsladlai=0 for grasses only
		     greffic(p) = bm_delta / (lm_ind * slatop(ivt(p)))
		  end if
	       else
		  greffic(p) = 0.
		  heatstress(p) = 0.
	       end if

	    end do
	    ! Check for error in establishment
	    fn = 0
	    do g = lbg, ubg
	       if (abs(fpc_total(g) - 1._r8) > 1.e-6) then
		  fn = fn + 1
		  filterg(fn) = g
	       end if
	    end do
	    if (fn > 0) then
	       g = filterg(1)
	!       write(iulog,*) 'Error in Establishment: fpc_total =',fpc_total(g), ' at gridcell ',g
	write(*,*) 'Establishment'
	       call endrun
	    end if
	  end subroutine Establishment

	!#endif

	end module CNDVEstablishmentMod



	module CNDVLightMod

	!#if (defined CNDV)

	!-----------------------------------------------------------------------
	!BOP
	!
	! !MODULE: LightMod
	!
	! !DESCRIPTION:
	! Calculate light competition
	! Update fpc for establishment routine
	! Called once per year
	!
	! !USES:
	  use shr_kind_mod, only: r8 => shr_kind_r8
	!  use shr_const_mod_ACASA, only : SHR_CONST_PI
	!
	! !PUBLIC TYPES:
	  implicit none
	  save
	!
	! !PUBLIC MEMBER FUNCTIONS:
	  public :: Light
	!
	! !REVISION HISTORY:
	! Module created by Sam Levis following CNDVLightMod by Mariana Vertenstein
	!
	!EOP
	!-----------------------------------------------------------------------

	contains

	!-----------------------------------------------------------------------
	!BOP
	!
	! !IROUTINE: Light
	!
	! !INTERFACE:
	  subroutine Light(lbg, ubg, lbp, ubp, num_natvegp, filter_natvegp)
	!
	! !DESCRIPTION:
	! Calculate light competition
	! Update fpc for establishment routine
	! Called once per year
	!
	! !USES:
	    use clmtype45
	    use pftvarcon45, only: slatop,dsladlai,dwood,woody,tree
	!
	! !ARGUMENTS:
	    implicit none
	    integer, intent(in) :: lbg, ubg                  ! gridcell bounds
	    integer, intent(in) :: lbp, ubp                  ! pft bounds
	    integer, intent(in) :: num_natvegp               ! number of naturally-vegetated pfts in filter
	    integer, intent(in) :: filter_natvegp(ubp-lbp+1) ! pft filter for naturally-vegetated points
	!
	! !CALLED FROM:
	! subroutine dv in module CNDVMod
	!
	! !REVISION HISTORY:
	! Author: Sam Levis (adapted from Stephen Sitch's LPJ subroutine light)
	! 3/4/02, Peter Thornton: Migrated to new data structures.
	! 2005.10: Sam Levis updated to work with CN
	!
	! !LOCAL VARIABLES:
	!
	! local pointers to implicit in arguments
	!
	    integer , pointer :: ivt(:)       ! pft vegetation type
	    integer , pointer :: pgridcell(:) ! gridcell index of corresponding pft
	!    integer , pointer :: tree(:)      ! ecophys const - tree pft or not
	!    real(r8), pointer :: slatop(:)    !specific leaf area at top of canopy, projected area basis [m^2/gC]
	!    real(r8), pointer :: dsladlai(:)  !dSLA/dLAI, projected area basis [m^2/gC]
	!    real(r8), pointer :: woody(:)     ! ecophys const - woody pft or not
	    real(r8), pointer :: leafcmax(:)  ! (gC/m2) leaf C storage
	    real(r8), pointer :: deadstemc(:)     ! (gC/m2) dead stem C
	!    real(r8), pointer :: dwood(:)         ! ecophys const - wood density (gC/m3)
	    real(r8), pointer :: reinickerp(:)    ! ecophys const - parameter in allomet
	    real(r8), pointer :: crownarea_max(:) ! ecophys const - tree maximum crown a
	    real(r8), pointer :: allom1(:)        ! ecophys const - parameter in allomet

	! local pointers to implicit inout arguments
	!
	    real(r8), pointer :: crownarea(:) ! area that each individual tree takes up (m^2)
	    real(r8), pointer :: fpcgrid(:)   ! foliar projective cover on gridcell (fraction)
	    real(r8), pointer :: nind(:)      ! number of individuals
	!
	!EOP
	!
	! !OTHER LOCAL VARIABLES:
	    real(r8), parameter :: fpc_tree_max = 0.95_r8 !maximum total tree FPC
	    integer  :: p,fp, g                           ! indices
	    real(r8) :: fpc_tree_total(lbg:ubg)
	    real(r8) :: fpc_inc_tree(lbg:ubg)
	    real(r8) :: fpc_inc(lbp:ubp)                  ! foliar projective cover increment (fraction)
	    real(r8) :: fpc_grass_total(lbg:ubg)
	    real(r8) :: fpc_shrub_total(lbg:ubg)
	    real(r8) :: fpc_grass_max(lbg:ubg)
	    real(r8) :: fpc_shrub_max(lbg:ubg)
	    integer  :: numtrees(lbg:ubg)
	    real(r8) :: excess
	    real(r8) :: nind_kill
	    real(r8) :: lai_ind
	    real(r8) :: fpc_ind
	    real(r8) :: fpcgrid_old
	    real(r8) :: lm_ind                            !leaf carbon (gC/individual)
	    real(r8) :: stemdiam                          ! stem diameter
	    real(r8) :: stocking                          ! #stems / ha (stocking density)
	    real(r8) :: taper                             ! ratio of height:radius_breast_height (tree allometry)
	!-----------------------------------------------------------------------
	!KC 071814
	    real(r8) :: SHR_CONST_PI
	!-----------------------------------------------------------------------
	!setup parameters
	    SHR_CONST_PI = 3.14159265358979323846_R8
	!KC end

	    ! Assign local pointers to derived type scalar members

	    ivt           => clm3%g%l%c%p%itype
	    pgridcell     => clm3%g%l%c%p%gridcell
	    nind          => clm3%g%l%c%p%pdgvs%nind
	    fpcgrid       => clm3%g%l%c%p%pdgvs%fpcgrid
	    leafcmax      => clm3%g%l%c%p%pcs%leafcmax
	    deadstemc     => clm3%g%l%c%p%pcs%deadstemc
	    crownarea     => clm3%g%l%c%p%pdgvs%crownarea
	    crownarea_max => dgv_pftcon%crownarea_max
	    reinickerp    => dgv_pftcon%reinickerp
	    allom1        => dgv_pftcon%allom1
	!    dwood         => pftcon%dwood
	!    slatop        => pftcon%slatop
	!    dsladlai      => pftcon%dsladlai
	!    woody         => pftcon%woody
	!    tree          => pftcon%tree

	    taper = 200._r8 ! make a global constant; used in Establishment + ?

	    ! Initialize gridcell-level metrics

	    do g = lbg, ubg
	       fpc_tree_total(g) = 0._r8
	       fpc_inc_tree(g) = 0._r8
	       fpc_grass_total(g) = 0._r8
	       fpc_shrub_total(g) = 0._r8
	       numtrees(g) = 0
	    end do

	    do fp = 1,num_natvegp
	       p = filter_natvegp(fp)
	       g = pgridcell(p)

	       ! Update LAI and FPC as in the last lines of CNDVAllocation

	       if (woody(ivt(p))==1._r8) then
		  if (fpcgrid(p) > 0._r8 .and. nind(p) > 0._r8) then
		     stocking = nind(p)/fpcgrid(p) !#ind/m2 nat veg area -> #ind/m2 pft area
		     ! stemdiam derived here from cn's formula for htop found in
		     ! CNVegStructUpdate and cn's assumption stemdiam=2*htop/taper
		     ! this derivation neglects upper htop limit enforced elsewhere
		     stemdiam = (24._r8 * deadstemc(p) / (SHR_CONST_PI * stocking * dwood * taper))**(1._r8/3._r8)
		  else
		     stemdiam = 0._r8
		  end if
		  crownarea(p) = min(crownarea_max(ivt(p)), allom1(ivt(p))*stemdiam**reinickerp(ivt(p))) ! Eqn D (from Establishment)
	!      else ! crownarea is 1 and does not need updating
	       end if

	       if (crownarea(p) > 0._r8 .and. nind(p) > 0._r8) then
		  lm_ind  = leafcmax(p) * fpcgrid(p) / nind(p)
		  if (dsladlai(ivt(p)) > 0._r8) then
		     lai_ind = max(0.001_r8,((exp(lm_ind*dsladlai(ivt(p)) + log(slatop(ivt(p)))) - &
				   slatop(ivt(p)))/dsladlai(ivt(p))) / crownarea(p))
		  else
		     lai_ind = lm_ind * slatop(ivt(p)) / crownarea(p)
		  end if
	       else
		  lai_ind = 0._r8
	       end if

	       fpc_ind = 1._r8 - exp(-0.5_r8*lai_ind)
	       fpcgrid_old = fpcgrid(p)
	       fpcgrid(p) = crownarea(p) * nind(p) * fpc_ind
	       fpc_inc(p) = max(0._r8, fpcgrid(p) - fpcgrid_old)
	       if (woody(ivt(p)) == 1._r8) then
		  if (tree(ivt(p)) == 1) then
		     numtrees(g) = numtrees(g) + 1
		     fpc_tree_total(g) = fpc_tree_total(g) + fpcgrid(p)
		     fpc_inc_tree(g) = fpc_inc_tree(g) + fpc_inc(p)
		  else ! if shrubs
		     fpc_shrub_total(g) = fpc_shrub_total(g) + fpcgrid(p)
		  end if
	       else    ! if grass
		  fpc_grass_total(g) = fpc_grass_total(g) + fpcgrid(p)
	       end if
	    end do

	    do g = lbg, ubg
	       fpc_grass_max(g) = 1._r8 - min(fpc_tree_total(g), fpc_tree_max)
	       fpc_shrub_max(g) = max(0._r8, fpc_grass_max(g) - fpc_grass_total(g))
	    end do
	    ! The gridcell level metrics are now in place; continue...
	    ! slevis replaced the previous code that updated pfpcgrid
	    ! with a simpler way of doing so:
	    ! fpcgrid(p) = fpcgrid(p) - excess
	    ! Later we may wish to update this subroutine
	    ! according to Strassmann's recommendations (see relevant pdf)

	    do fp = 1,num_natvegp
	       p = filter_natvegp(fp)
	       g = pgridcell(p)

	       ! light competition

	       if (woody(ivt(p))==1._r8 .and. tree(ivt(p))==1._r8) then

		  if (fpc_tree_total(g) > fpc_tree_max) then

		     if (fpc_inc_tree(g) > 0._r8) then
			excess = (fpc_tree_total(g) - fpc_tree_max) * &
			     fpc_inc(p) / fpc_inc_tree(g)
		     else
			excess = (fpc_tree_total(g) - fpc_tree_max) / &
			     real(numtrees(g))
		     end if

		     ! Reduce individual density (and thereby gridcell-level biomass)
		     ! so that total tree FPC reduced to 'fpc_tree_max'

		     if (fpcgrid(p) > 0._r8) then
			nind_kill = nind(p) * excess / fpcgrid(p)
			nind(p) = max(0._r8, nind(p) - nind_kill)
			fpcgrid(p) = max(0._r8, fpcgrid(p) - excess)
		     else
			nind(p) = 0._r8
			fpcgrid(p) = 0._r8
		     end if

		  ! Transfer lost biomass to litter

		  end if ! if tree cover exceeds max allowed
	       else if (woody(ivt(p))==0._r8) then ! grass

		  if (fpc_grass_total(g) > fpc_grass_max(g)) then

		     ! grass competes with itself if total fpc exceeds 1

		     excess = (fpc_grass_total(g) - fpc_grass_max(g)) * fpcgrid(p) / fpc_grass_total(g)
		     fpcgrid(p) = max(0._r8, fpcgrid(p) - excess)

		  end if

	       else if (woody(ivt(p))==1._r8 .and. tree(ivt(p))==0._r8) then ! shrub

		  if (fpc_shrub_total(g) > fpc_shrub_max(g)) then

		     excess = 1._r8 - fpc_shrub_max(g) / fpc_shrub_total(g)

		     ! Reduce individual density (and thereby gridcell-level biomass)
		     ! so that total shrub FPC reduced to fpc_shrub_max(g)

		     if (fpcgrid(p) > 0._r8) then
			nind_kill = nind(p) * excess / fpcgrid(p)
			nind(p) = max(0._r8, nind(p) - nind_kill)
			fpcgrid(p) = max(0._r8, fpcgrid(p) - excess)
		     else
			nind(p) = 0._r8
			fpcgrid(p) = 0._r8
		     end if

		  end if

	       end if   ! end of if-tree
	    end do
	  end subroutine Light

	!#endif

	end module CNDVLightMod


	module CNDVMod

	!#if (defined CNDV)

	!-----------------------------------------------------------------------
	!BOP
	!
	! !MODULE: CNDVMod
	!
	! !DESCRIPTION:
	! Module containing routines to drive the annual dynamic vegetation
	! that works with CN, reset related variables,
	! and initialize/reset time invariant variables
	!
	! !USES:
	  use shr_kind_mod        , only : r8 => shr_kind_r8
	  use abortutils          , only : endrun
	  use cnvegstructupdatemod_ACASA, only : CNVegStructUpdate
	!
	! !PUBLIC TYPES:
	  implicit none
	  private
	  save
	!
	! !PUBLIC MEMBER FUNCTIONS:
	  public dv                 ! Drives the annual dynamic vegetation that
				    ! works with CN
	  public histCNDV           ! Output CNDV history file
	!
	! !REVISION HISTORY:
	! Module modified by Sam Levis from similar module CNDVMod
	! created by Mariana Vertenstein
	!
	!EOP
	!-----------------------------------------------------------------------

	contains

	!-----------------------------------------------------------------------
	!BOP
	!
	! !IROUTINE: dv
	!
	! !INTERFACE:
	  subroutine dv(lbg, ubg, lbp, ubp, num_natvegp, filter_natvegp, kyr,isoi3)
	!
	! !DESCRIPTION:
	! Drives the annual dynamic vegetation that works with CN
	!
	! !USES:
	    use clmtype45
	    use CNDVLightMod        , only : Light
	    use CNDVEstablishmentMod, only : Establishment
	!
	! !ARGUMENTS:
	    implicit none
	    integer, intent(in) :: lbg, ubg       ! gridcell bounds
	    integer, intent(in) :: lbp, ubp       ! pft bounds
	    integer, intent(inout) :: num_natvegp ! number of naturally-vegetated
						  ! pfts in filter
	    integer, intent(inout) :: filter_natvegp(ubp-lbp+1) ! filter for
						  ! naturally-vegetated pfts
	    integer, intent(in) :: kyr            ! used in routine climate20 below
	!
	! !CALLED FROM:
	!
	! !REVISION HISTORY:
	! Author: Sam Levis
	!
	! !LOCAL VARIABLES:
	!
	! local pointers to implicit in arguments
	!
	   integer , pointer :: mxy(:)         ! pft m index (for laixy(i,j,m),etc.)
	   integer , pointer :: pgridcell(:)   ! gridcell of corresponding pft
	   real(r8), pointer :: fpcgrid(:)     ! foliar projective cover on gridcell (fraction)
	   real(r8), pointer :: agdd(:)        ! accumulated growing degree days above 5
	   real(r8), pointer :: t_mo_min(:)    ! annual min of t_mo (Kelvin)
	!
	! local pointers to implicit inout arguments
	!
	   real(r8), pointer :: tmomin20(:)         ! 20-yr running mean of tmomin
	   real(r8), pointer :: agdd20(:)           ! 20-yr running mean of agdd
	!
	!EOP
	!
	! !LOCAL VARIABLES:
	    integer  :: g,p                    ! indices
	!-----------------------------------------------------------------------
	!KC 071184
	    integer  :: isoi3

	    ! Assign local pointers to derived type members (gridcell-level)

	    agdd20    => clm3%g%gdgvs%agdd20
	    tmomin20  => clm3%g%gdgvs%tmomin20

	    ! Assign local pointers to derived type members (pft-level)

	    mxy       => clm3%g%l%c%p%mxy
	    pgridcell => clm3%g%l%c%p%gridcell
	    fpcgrid   => clm3%g%l%c%p%pdgvs%fpcgrid
	    t_mo_min  => clm3%g%l%c%p%pdgvs%t_mo_min
	    agdd      => clm3%g%l%c%p%pdgvs%agdd

	    ! *************************************************************************
	    ! S. Levis version of LPJ's routine climate20: 'Returns' tmomin20 & agdd20
	    ! for use in routine bioclim, which I have placed in routine Establishment
	    ! Instead of 20-yr running mean of coldest monthly temperature,
	    ! use 20-yr running mean of minimum 10-day running mean
	    ! *************************************************************************

	    do p = lbp,ubp
	       g = pgridcell(p)
	       if (kyr == 2) then ! slevis: add ".and. start_type==arb_ic" here?
		  tmomin20(g) = t_mo_min(p) ! NO, b/c want to be able to start CNDV
		  agdd20(g) = agdd(p)       ! w/ clmi file from non-CNDV simulation
	       end if
	       tmomin20(g) = (19._r8 * tmomin20(g) + t_mo_min(p)) / 20._r8
	       agdd20(g)   = (19._r8 * agdd20(g)   + agdd(p)    ) / 20._r8
	    end do


	    ! Rebuild filter of present natually-vegetated pfts after Kill()

	    call BuildNatVegFilter(lbp, ubp, num_natvegp, filter_natvegp)

	    ! Returns fpcgrid and nind

	    call Light(lbg, ubg, lbp, ubp, num_natvegp, filter_natvegp)

	    ! Returns updated fpcgrid, nind, crownarea, and present. Due to updated
	    ! present, we do not use the natveg filter in this subroutine.

	    call Establishment(lbg, ubg, lbp, ubp,isoi3)

	    ! Reset CNDV variables needed in next yr (too few to keep subr. dvreset)

	    do p = lbp,ubp
	       clm3%g%l%c%p%pcs%leafcmax(p) = 0._r8
	       clm3%g%l%c%p%pdgvs%t_mo_min(p) = 1.0e+36_r8
	    end do
	  end subroutine dv

	!-----------------------------------------------------------------------
	!BOP
	!
	! !IROUTINE: histCNDV
	!
	! !INTERFACE:
	  subroutine histCNDV()
	!
	! !DESCRIPTION:
	! Create CNDV history file
	!
	! !USES:
	    use clmtype45
!	    use decompmod_ACASA       , only : get_proc_bounds, get_proc_global
	    use clm_varpar45      , only : maxpatch_pft
