	!    use shr_const_mod_ACASA   , only : SHR_CONST_CDAY
	!    use ncdio_pio
	!
	! !ARGUMENTS:
	    implicit none
	!
	! !CALLED FROM:
	!
	! !REVISION HISTORY:
	! Author: Sam Levis
	!
	! !LOCAL VARIABLES:
	!
	! local pointers to implicit in arguments
	!
	   logical , pointer :: ifspecial(:)        ! true=>landunit is not vegetated (landunit-level)
