          xtime=.24D+002*dble((abs(calday-dble(real(int(calday))))))
          zzen=.0D+000
!        print*,'debug 56'
          call zenith(calday,xtime,xlat,zzen)
!        print*,'debug 57'
          if (zzen > 0.0D+000) then
	    do ib = 1,2
             if ((isl .ne. 16) .and. (isl .ne. 14)) then
                inc    = max(0.11_r8-0.40_r8*sh2o(1), 0._r8)
                soilcol = soic(isl) 
                albsod(ib) = min(albsat(soilcol,ib)+inc, albdry(soilcol,ib))
                pv09g = max(albsat(soilcol,1)+inc, albdry(soilcol,1))
                pr09g = max(albsat(soilcol,2)+inc, albdry(soilcol,2))
             else if (isl .eq. 16)  then          ! land ice
                albsod(ib) = albice(ib)
             else                                 ! frozen lake, wetland
                albsod(ib) = alblak(ib)
             end if
	    enddo
	   else !use mean values applied in previous WRF-ACASA
                albsod(1) = .50D-001
                albsod(2) = .45D+000
	   endif
