		 do i=1,nsoil0
                    qsoiq_ini(i) = max(0.05,qsoiq_ini(i))
		 enddo
                 xsatv=.0D+000
                 call satv(xxx,forc_txy-.27315D+003)
                 xxx = dble(.62198*(xxx/(xpre6*100.0-.378*xxx))*1000.0) !saturation specific humidity g/kg
                 xxx = 1.05*xxx      ! super saturation
                 IF(xe6 .ge.xxx) THEN
                    xe6 = xxx
                 ELSEIF(xe6 .le. 0.0D+000) THEN
                    xe6 = .8*xxx
                 ELSE
                    xe6 = xe6
                 ENDIF
!KC end
!        print*,'debug 59'
         xo361=.18D+003         ! 'methane'
         xo362=.3D+003          ! "NO2"
         xo363=.5D+003          ! "Monoturpene"
         xo364=.12D+003         ! "OH- radicals"
         xo365=.308D+003        ! "Ozone"
! et cetera. units will track "naturally" throughout the equations.  if you start with ppb, the output will reflect
