                 emissi8=emissi
              zlatude_rad=.3141592654D+001*(xlat)/.18D+003 !pi*latitude/180 radians
              max_decl = 0.409571D+000
              if (zlatude_rad .lt. 0.D+000) max_decl = -max_decl
              temp = -(sin(zlatude_rad)*sin(max_decl))/(cos(zlatude_rad) * cos(max_decl))
              temp_var = min(1.D+000,max(-1.D+000,temp))
              max_dayl = 2.0D+000 * 13750.9871D+000 * acos(temp_var)
              zzen_rad = acos(zzen)

              temp = -(sin(zlatude_rad)*sin(declin)/(cos(zlatude_rad) * cos(declin)))
              temp_var = min(1.D+000,max(-1.D+000,temp))
              dayl = 2.0D+000 * 13750.9871D+000 * acos(temp_var)
              dayl_factor=min(1.D+000,max(0.01D+000,(dayl*dayl)/(max_dayl*max_dayl)))
        ! KC 021814, plug in CN cycle
