   lmrsun_clm(pftloop) = lmr_sun!*clm3%g%l%c%p%wtcol(filter(nc)%soilp(pftloop))
   lmrsha_clm(pftloop) = lmr_sha!*clm3%g%l%c%p%wtcol(filter(nc)%soilp(pftloop))
   tphoto_clm(pftloop) = -tphoto!*clm3%g%l%c%p%wtcol(filter(nc)%soilp(pftloop))      !notice the sign reversal
   fsun_clm(pftloop) = fsun
   t_veg_clm(pftloop) = t_veg
