     call BeginCBalance(begc, endc, filter(1)%num_soilc, filter(1)%soilc)  !cnbalancecheckmod_ACASA.F
     call BeginNBalance(begc, endc, filter(1)%num_soilc, filter(1)%soilc)  !cnbalancecheckmod_ACASA.F

