        subroutine normz(ar1,ar2,n,xscale,ifig)

!
! for output only..for ease of viewing all output on the same graph
! normalizes ar1 and outputs it as ar2, with scale factor xscale
!
        implicit none
!
        integer n,i,ifig
        double precision ar1(n),ar2(n,60),xscale(60),ar1a(n)

!
        do i=1,n
         ar1a=.0D+000
        enddo
        do i=1,n
         ar1a(i)=ar1(i)
        enddo
        xscale(ifig)=.0D+000
! schnormalize:  use the next 6 lines if you want normalized output
!       do i=2,n
!        xscale(ifig)=max(xscale(ifig),abs(ar1a(i)))
!       enddo
!       ar2(1,ifig)=.0D+000
!       do i=1,n
!        ar2(i,ifig)=ar1a(i)/(xscale(ifig)+.1D-020)
!       enddo
! do not schnormalize:  use the next 6 lines if you do not want normalized output
        do i=1,n
         xscale(ifig)=.1D+000
        enddo
        do i=1,n
         ar2(i,ifig)=ar1a(i)
        enddo
!
        return
        end subroutine
