!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!
! begin blanket 0 initialization / all between here and 'end blanket 0 initialization"
! is simply variables getting reset to 0 / keep it all clean.
!
! assign 0 values to some variables intially	
!......................................................................
!	variable			definition
!......................................................................
!
	snoh=.0D+000			! energy of snowpack phase change
	smelt=.0D+000			! rate of show phase change (m/s)
	ng=n				!#vert. layers
	pbarx=.0D+000			!Pressure gradient (mean )x-direction 
	pbary=.0D+000			!.", y-direction 
        xxxz=.0D+000			! wkg vble.
        yyyz=.0D+000			! wkg. vble.
!
	do i=1,ng !the following	are arrayed in the vertical
         fstacas(i)=.0D+000
	 dwco2a(i)=.0D+000		!Total nonanthrobiogenic co2 flux divergence component
	 dwco2b(i)=.0D+000		!Total anthropogenic co2 flux div. comp.
	 wco2b(i)=.0D+000		!Total anthro. co2 flux comp.
	 wco2a(i)=.0D+000		!Total nonanthrobiogen. co2 flux comp.
	 tstorep(i)=.0D+000		! total canopy storage flux dens. profile
	 tstorep_snow(i)=.0D+000		! total canopy snowpack pahsechange etc. storage flux dens. profile
	 tstorep_bio(i)=.0D+000		! total biogenic canopy storage flux dens. profile
	 tstorep_anthro(i)=.0D+000	! total anthropogenic-only canopy storage flux dens. profile
	 tstorep1(i)=.0D+000		! working vble / total canopy storage flux dens. profile
	 tstorep_anthro1(i)=.0D+000	! working vble / total anthro canopy storage flux dens. profile
	 tstorep_bio1(i)=.0D+000	! working vble / total bio canopy storage flux dens. profile
	 do j=1,10
	 do k=1,8
	  xlint(i,j,k)=.0D+000		!Dry/wet/snow-covered canopy element weighting fractions)
	 enddo
	 enddo
!
	 dr(i)=.0D+000			!Leaf-scale drag coefficient
	 l(i)=.0D+000			!turb. length scale
	 ld(i)=.0D+000			!Turb. Length scale
	 ldt(i)=.0D+000			!Turb. Length scale
!
!	mean microenv and
!	turbulent moments labeled minimally for brevity; 
         xxx_snoh=.0D+000
!
! UNITS:  when not listed, assume mks protocol: <wwt> has units of 
! m2Ks-2 (for co2-related moments:, this is MKS*1.E+06 each time "co2" appears in a 
! variable)
!
	 mw(i)=.0D+000			!Total mean wind speed
	 uw(i)=.0D+000			!Streamwise momentum flux dens.
	 u2(i)=.0D+000			!Streamwise wind veloc. variance
	 v2(i)=.0D+000			!Crosswise wind veloc. variance
	 w2(i)=.0D+000			!Vertical wind veloc variance
	 q(i)=.0D+000			!Square	root of TKE
	 ws(i)=.0D+000			!Total vertical gradient of mean wind speed
	 wsx(i)=.0D+000			!Vertical gradient streamwise wind
	 co2(i)=.0D+000			!carbon	dioxide	concentration
	 dco2(i)=.0D+000		!vert. gradient [co2]
	 wco2(i)=.0D+000		!total vert. co2 flux dens.
	 dwco2(i)=.0D+000		!total co2 flux dens. divergence
	 tco2(i)=.0D+000		!<tCO2>
	 dtco2(i)=.0D+000		!d/dz(<tco2>)
	 wwco2(i)=.0D+000		!<wwco2>
	 dwwco2(i)=.0D+000		!d/dz<wwco2>
	 wtco2(i)=.0D+000		!<wtco2>
	 dwtco2(i)=.0D+000		!d/dz(wtco2>
	 ttco2(i)=.0D+000		!<ttco2>
	 respl(i)=.0D+000 		! total resp. flux leaves
	 resps(i)=.0D+000 		! total resp flux stems
	enddo			
	do i=1,nsoil09
	 respr(i)=.0D+000 		! total resp flux roots
	 respm(i)=.0D+000 		! total resp flux microbes
	enddo				
!	
	do k=1,60! output profiles / all turbulence variables go into these arrays upon output
	 do i=1,n
	  zprof0(i,k)=.0D+000		! storage array for output
	  zprof(i,k)=.0D+000		! storage array for output
	 enddo
	enddo
!
!4 Barry:  initial profiles of tracer arrays are set here.  
! from here on out the turbulence set and the source/sink
! eqns should carry this all the way through.  
