	 x6(i)=.0D+000			!wkg.
	 x7(i)=.0D+000			!wkg.
	 delta(i)=.0D+000		!wkg.
	 dx(i)=.0D+000			!wkg.
	 wt(i)=.0D+000			!<wt>
	 wq(i)=.0D+000			!<wq>
	 dwt(i)=.0D+000			!d/dz<wt>
	 t2q(i)=.0D+000			!<ttq>
	 t3(i)=.0D+000			!<ttt>
	 wut(i)=.0D+000			!<wut>
	 utt(i)=.0D+000			!<utt>
	 uut(i)=.0D+000			!<uut>
	 dwq(i)=.0D+000			!d/dz<wq>
	 wwt(i)=.0D+000			!<wwt>
	 dwwq(i)=.0D+000		!d/dz<wwq>
	 dwwt(i)=.0D+000		!d/dz<wwt>
	 wwq(i)=.0D+000			!<wwq>
	 wtt(i)=.0D+000			!<wtt>
	 wtq(i)=.0D+000			!<wtq>
	 vvt(i)=.0D+000			!<vvt>
	 de(i)=.0D+000			!d/dz<q>
	 dt(i)=.0D+000			!d/dz<t>
	 tq(i)=.0D+000			!<tq>
	 t2(i)=.0D+000			!<tt>
	 ut(i)=.0D+000			!<ut>
	 e(i)	=.0D+000		!<q>
	 t(i)	=.0D+000		!<t>
	 dwwu(i)=.0D+000		!d<wwu>/dz 
	 dwwv(i)=.0D+000		!d<wwv>/dz 
	 tau(i)	=.0D+000		!turbulence timescale parameter
	 c8k(i)	=.0D+000 		!turb. parameter
	 c10k(i)=.0D+000		!turb. parameter
