        xaimin=.1D-001
        if(xlai6.lt.xaimin)xlai6=.0D+000
	xlai7=xlai6					! total green LAI / used by ACASA -- dummy to xlai7 
!        xlai7=max(xlai7,.5D+000)   changed for test April Dave and clkyu 
	standage=max(standage, .5D+000)			! keep canopy > = 0.5 m
	standage2=max(standage2, .5D+000)		! keep canopy > = 0.5 m.
	if(xlai7.le.xaimin)xlai7=.0D+000		! reset min value to 0.
        xlai2=xlai7 					! alias for xlai7
	zcan=standage					! maximum (top 1%) canopy height (m)
	if(standage2.gt.standage)zcan=standage2 	! if buildings are taller, let zcan be the bigger of the 2...
	htb=zcan					! max building height (now same as zcan)
	htb1=htb 					! alias of htb,zcan,standage 
	wthb1=.0D+000					! vestigial
	zcanopy=zcan					! alias of zcan,htb,htb1,standage
        ht=zcanopy					! alias of zcanopy,zcan,htb,htb1,standage 
!
! rdp rocktober 2011: change top 10 layers' widths to match to any arbitrary height between
! preferably 2*zcan and 10*zcan // previously had been hardwired to 2*zcan
        xxx=.11D+001*standage				!110% the canopy height
	yyy=domain_height				!
        domht=max(yyy,xxx) 				! input domain height, height of driving meteorology, meters...must be >= 110% h_canopy!!!!! 
        domain_height=domht
        d0 = .667D+000*ht				! initial zero-plane displacement ht.
!				  			  used only in turb. length scale calcs. feed in last time step's soil t, q values
        nsoil=nsoil09					! alias number of soil layers (nsoil09).
!KC
        xxx=dble(float(n-1)/float(inlyr-1))
        domht=max(domht,xxx*ht)  ! lower limit on domht; >=2*ht
!KC end
!KC, feed in last time step's soil t, q values
!
         do k=1,nsoil09
          tsoiq(k)=dble(stca(k))
          qsoiq(k)=dble(smca(k))
         enddo
!KC end
!......................................................................
! set up vertical grid spacing arrays
!......................................................................
!hardwire: 10 cm snow layers
 	deltsn=.1D+000
!
! old ggrid: set up vertical gridpoint-type  coordinates.
! RDP Rocktober 2011: made the vertical coordinate general above canopy top...
! estimates vergtical grid spacing. takes care of 
! situations when domain height more than 2x canopy height
! (domht > 2.*ht). we'll deal with domain_height < 2*zcan later...
!
        do k=1,nlyr
!  canopy is hardwired for ten equally spaced layers: keep
!  rdp 17 september 2014: ended 10-canopy and 21-layer domain 
!  hardwires both here everywhere...example: the factor multiplying ht had been 0.1.
!KC
         gg(k)=ht*.1D+001/(dble(float(nlyr-1))) 
!         gg(k)=ht*.1D+000
!KC end
        enddo
        do k=nlyr+1,n
!KC
	 gg(k)=(domht-ht)*.1D+001/(dble(float(n-nlyr)))
!         gg(k)=(domht-ht)*.1D+000
!KC end
        enddo
!
! when the height of the domain is > 2x the canopy height...
!
        k=1
        gsq(k)=gg(k)*gg(k)
        twog(k)=gg(k+1)+gg(k) 
        grad(k) = 0.4D+000*gg(k)
        do k=2,n-1
         gsq(k)=gg(k)*gg(k)
         twog(k)=gg(k+1)+gg(k-1) 
         grad(k) = 0.4D+000*gg(k)
        enddo
        k=n
        gsq(k)=gg(k)*gg(k)
        twog(k)=gg(k-1)+gg(k) 
        grad(k) = 0.4D+000*gg(k)
