	ii=1
	jj=1
	needtinf=0
	ihumid=0
        t2op=t2o6				! air temperature (K)
	xxx=dble(ffrozp) 
	if(xxx.lt..1D-009)xxx=.0D+000		! ensures noninfinitesimal values do not corrupt the snow rate...
	if(xxx.gt..1D+001)xxx=.1D+001		! ensures  this to be cogent as well...
	rain(1)=raina*(.1D+001-xxx)		!RAIN RATE (KG/DELTA-T)
	rain(2)=xxx*raina			! snow rate "
	rain(3)=.0D+000				! icepellets/graupel/hail " (turned off)
        if(rain(1).lt..1D-008)rain(1)=.0D+000	! low-end cutoff
        if(rain(2).lt..1D-008)rain(2)=.0D+000   ! low-end cutoff
        if(rain(3).lt..1D-008)rain(3)=.0D+000   ! low-end cutoff
	xee=.1D-002*xe6				! specific humidity kg kg-1
        tlux=tx6				! incoming solar radiation flux dens. (Wm-2)
        ineut=0					! neutrality flag for scala() 
        if(tlux.le..1D+002)ineut=1  		! neutral/stable conditions assumed w/ low radiation
        tinf=tf6	 			! incoming thermal-ir radiation flux dens. (Wm-2)
	xmw=mw6 					! mean wind speed (m/s)
        xpre=xpre6	 			! surface pressure (hPa)
	xco2=xco26				! CO2 concentration (umol mol-1)
	iswamp=0			! standing water (aquatic)
        fcori1=dble(sin(real(zlatude)*3.1415927/180.)*2.0*(2.0*3.1415927/86400.0))! coriolis !parameter
	nsoil=nsoil09 !zlatude
!!!!!!!!!!!!!!!!!   configuration with 'hardened parameters' !!!!!!!!!!!!!!
! vertical veg. parameter arrays set as monotonic 
! if you want to layer the canopy with different species, here's where  
! one would do it.
!!!!!!!!!!!!!!!!!   configuration with 'hardened parameters' !!!!!!!!!!!!!!
       do i=1,nsoil09
	r0r(i)=r0r9		!root basal resp. rate (umol m-2(tissue) s-1)
	r0m(i)=	r0m9		!microbe basal resp. rate (umol m-2(tissue) s-1)
	q10r(i)=q10r9		!q10 for root resp.(-)
	q10m(i)=q10m9		!q10 for microbial resp.(-) 
       enddo
!KC 122814, setup ldiam according to different PFTs
        if (ivt .ge. 12) then
        xldiam9=.01     !leaf diam, m! .5D-001 for forest, 0.01 for grass
        else
        xldiam9=.05
        endif
!KC end
       do i=1,n
	q10l(i)=q10l9		!q10 for leaf resp.(-)
	q10s(i)=q10s9		!q10 for stem respiration(-)
	drx(i)=drx9		!leaf drag coefficient (0.05 - 0.20)
	xldiam(i)=xldiam9	!mean leaf diameter (m)
	xrsmn(i)=xrsmn9		!max. (ideal) carboxylization rate (umol m-2(tissue) s-1 (values range from x < xrsmn < 400 depending on species, available soil Nitrogen content, etc.
	r0l(i)=r0l9		!leaf basal resp. rate (umol m-2(tissue) s-1)
	r0s(i)=	r0s9		!stem basal resp. rate (umol m-2(tissue) s-1)
       enddo
!KC
!        tr09=.11D+000   !mean near-IR transmissivity
!        tv09=.22D-001   !mean PAR transmissivity
!KC end
       do i=1,101!nlyr 
	pr0(i)=pr09		!near-IR leaf reflectivity(-)
	tr0(i)=tr09		!near-IR leaf transmissivity(-)
	pv0(i)=pv09		!vis leaf reflect(-)
	tv0(i)=tv09		!vis leaf transmissivity(-)
       enddo
!
        i=1
! RDP December 2012: don't alter these; keep tyhem as-is for use of observed albedoes;
!       pr0(i)=pr09g-dble(smca(1))*.2D+000 !near-IR leaf reflectivity(-)/ground surface
!       pv0(i)=pv09g-dble(smca(1))*.2D+000 !vis leaf reflect(-) / ground surface
        pr0(i)=pr09g
        pv0(i)=pv09g
        tr0(i)=.0D+000 !ground / sea ice surface is considered "totally opaque"
        tv0(i)=.0D+000 !"
!
! note: this needs a little beefing up...
! RDP 19 july 2011 set snowpack-modified reflectivities @ ground
! using the following logic:  if the snow is really cold, the labedoes are > 0.6.
! if the snow is warm, the albedo is lower.
! Ola Persson / citing Koren etc. / NOAA-FSL (using SHEBA data)  personal comm. 2000-2001
! RDP jan 2013: this obviously has to be modified for situations where the snow becomes discolored
! either by way of soot, plant droppings, or microbes.
!
!        snowater=.0D+000
!        snowater9=dble(ice_sl_can(1)) ! insitu mode
        snowater9=dble(sneqv8)
        if(snowater9.ge..1D-003)then! whiten the ground
         pv0(1)=.755D+000                                               ! fresh/or cold snow
         pr0(1)=.555D+000
         if(t_sl_snow(1).gt.270.0)then                           ! warm snow condition insitu mode
           pv0(1)=.555D+000
           pr0(1)=.455D+000
         endif
        else                                                            ! nekkid sea ice condition
          if(i7ce.gt.0)then
           pv0(1)=.655D+000
           pr0(1)=.455D+000
          endif
        endif
! RDP 30 june 2011 set lower bounds on reflectances to prevent negative (phosphorescent/light-emitting) values of reflectances.
        pr0(i)=max(pr0(1),.8D-001)
        pv0(i)=max(pv0(1),.8D-001)
!
! RDP November 2010: adjust canopy reflectivities when snow is present
!
! set up canopy to become more albacious when snow is present within it (on boughs,balconies, etc.).
! set limits = to "old snow" values...set proportions as related to 
! total amount of snow in the canopy layers.  
!
! all the enhanced inscattering of photons in a snowy canopy is handled 
! automatically via radiative transfer calcs.
! rdp 03 juno 2015 / made sure this was done correctly
! 
        
 	do i=2,nlyr
 	  if(ice_sl_can(i).gt.0.0)then		! there is snow in this canopy layer, so we/ insitu mode
 	   pr0(i)=.5D+000*(.45D+000 + pr09) 	! assume 'undersides' of leaves & snowtooped sides ate 1/2 each...
 	   pv0(i)=.5D+000*(.55D+000 + pv09) 	! ...& then average the reflectances w/ generic snow values.
          endif
        enddo
!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
! get vegetation profile---5 distributions are now used...
! canopy architecture, or lai(z), which generally cover a wide variey
! of canopy types. if you would like to specify pai(z)
! from measurements at a particular site, read it in from a 
! file here...note the number of nodes for (pai101(i); with the 
! ground surface at node 1 = 0 at all times.
!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
!
! lveg: value range & meanings:
! 1 = bottomheavy (conifer-type; boreal & alpine,  particularly)
! 2 = mid-peaked (grasses, mixed forests, young/disturbed forests; orchards)
! 3 = topheavy (older forests; usually broadleaf; vinyards or old orchards)
! 4 = multiple (older mixed forests; usually tropical rainforests)
! 5 = multiple (older mixed forests; usually temperate undisturbed / 
!	         disturbed tropical 2ndary growth)
!RDP 22 September 2012: make consistent with "no lai < 0.01" condition
! RDP 22 September 2012: low-total-area-index conditions/cosistency across all profiles.
        do i=1,nlyr ! initialize total cai21 array for vegz(...)
          cai21(i)=.0D+000
        enddo
!
        do i=1,101 ! initialize pai101 array for vegz(...)
          cai101(i)=.0D+000
          pai101(i)=.0D+000
          stei101(i,1)=.0D+000
          stei101(i,2)=.0D+000
          rai101(i)=.0D+000
          wai101(i)=.0D+000
        enddo
!
       if (xlai7 .gt. .1D-001) call vegz(lveg,pai101,xlai7,standage)      ! wall area is bottomheavy
       call vegz(lveg,pais101,xlai6,standage) !save the original canopy strucutre
!
! get full set of canopy area indices...start with totals for each
!
! Begin Part (3): ! Setting Urban Environment (sue) roof and wall area indices
! Salvatore Natale - s.natale@yahoo.com - from July 2013 to October 2014:
! settings for non-urban environments:
       xrai=.0D+000                    ! total roof area index
       xwai=.0D+000                    ! total wall area index
       suecdfb=.0D+000
       suelhfb=.0D+000
! ...while, if in a urban site:
       if(popdens.gt..1D-005)then
! use area indexes values from morphology:
        xrai=suerai                   ! total roof area index
        xwai=suewai                   ! total wall area index
! ...or use RDP proxies:
        if(suerai.lt..0D+000)xrai=min(.5D+000,popdens*.1D+003)                          !RDP proxy: xrai proportional to popdens, cut off at 50%
        if(suewai.lt..0D+000)xwai=.75D+000+(.15D+000*(popdens/.2D-002)**.3D+001)        !RDP proxy: xwai proportional to popdens^3
!
        call vegz(3,rai101,xrai,standage)      ! roof area is topheavy
        call vegz(1,wai101,xwai,standage)      ! wall area is bottomheavy
!
        if(iendo.eq.1 .and.suecb.eq.1)suecdfb=suehbf*xrai*standage2*suehep*suecp*suec2*suec3/(suelhp*suec7*suemw)       !umol m-2 s-1,
!carbon dioxide flux from buildings, peak while heating is on
        if(iendo.eq.1 .and.suelb.eq.1)suelhfb=suehbf*xrai*standage2*suehep*suewpb*suelhw/suelhp                                 !W m-2, latent heat flux
! from buildings, peak while heating is on
! Salvatore Natale - s.natale@yahoo.com - from July 2013 to October 2014:
       endif
!
! 22 September 2012 make sure min lai condition also applies to all other canopy area indices
!
       if(xrai.lt.xaimin)then
        xrai=.0D+000
        xwai=.0D+000
       endif
!
! now build the index profiles...each one is on a 101 grid
! RDP 10August2010 for WRF / ocean condition
!
! RDP 10August2010 for WRF / ocean condition
!
        xstei1=(zcan/.5D+002)*.1D+000*(xlai7)    ! total large stem s. area
        xstei2=.1D+000*xlai7                     !
        if(iocean.eq.1)then
         xstei1=.0D+000
         xstei2=.0D+000
        endif
        if(xstei1.lt..1D-002)xstei1=.0D+000
        if(xstei1.ge..1D-002)then
         do i=1,101
          arr101(i)=.0D+000
         enddo
         call vegz(6,arr101,xstei1,standage)               ! large stems use profile lveg=6: conical
         do i=1,101
          stei101(i,1)=arr101(i)
         enddo
        endif
!
        if(xstei2.lt..1D-002)xstei2=.0D+000
        if(xstei2.ge..1D-002)then
         do i=1,101
          arr101(i)=.0D+000
         enddo
         call vegz(lveg,arr101,xstei2,standage)            ! small stems use profile lveg=6: conical
         do i=1,101
          stei101(i,2)=arr101(i)
         enddo
        endif
!
	 xai=xlai7+xstei1+xstei2+xrai+xwai  		   ! xai = total canopy area index (all element types , all layers)
!
	i=1
	  pai101(i)=.0D+000	
          pais101(i)=.0D+000
	  stei101(i,1)=.0D+000	
	  stei101(i,2)=.0D+000	
	  rai101(i)=.0D+000	
	  wai101(i)=.0D+000	
!
         do i=1,101
	  pai101a(i)=pai101(i)	
	  stei101a(i)=stei101(i,1)+stei101(i,2)	!rdp 30 march 2015: + stei101(i,2) was included here
	  rai101a(i)=rai101(i)	
	  wai101a(i)=wai101(i)	
         enddo
