      xstei1=.0D+000
      xstei2=.0D+000
      xrai=.0D+000
      xwai=.0D+000
      xlyr=dble(float(nlyr))-.10D+001
      do i=2,nlyr
       pad(i)=pai(i)*xlyr/ht
       stad(i,1)=stei(i,1)*xlyr/ht
       stad(i,2)=stei(i,2)*xlyr/ht
       rfad(i)=rai(i)*xlyr/ht
