        flai(1)=.1D+001
        fstei(1,1)=.0D+000
        fstei(1,2)=.0D+000
        frai(1)=.0D+000
        fwai(1)=.0D+000
        pad(1)=.0D+000
        stad(1,1)=.0D+000
        stad(1,2)=.0D+000
        rfad(1)=.0D+000
        wad(1)=.0D+000
        pai(1)=.0D+000
        pais(1)=.0D+000
        stei(1,1)=.0D+000
        stei(1,2)=.0D+000
        rai(1)=.0D+000
        wai(1)=.0D+000
!
! now calibrate all profiles to match total area indices
!
        yyy=.1D+001
        xxx=.0D+000
        do i=2,nlyr
         xxx=xxx+pai(i)
        enddo
        yyy=xlai7/(xxx+.1D-014)
        do i=2,nlyr
         pai(i)=pai(i)*yyy
         pad(i)=pai(i)/gg(i)
        enddo
