        yyy=.1D+001
        xxx=.0D+000
        do i=2,nlyr
         xxx=xxx+pais(i)
        enddo
        yyy=xlai6/(xxx+.1D-014)
        do i=2,nlyr
         pais(i)=pais(i)*yyy
        enddo
