        do i=2,nlyr
         xxx=xxx+stei(i,1)
        enddo
        yyy=xstei1/(xxx+.1D-014)
        do i=2,nlyr
         stei(i,1)=stei(i,1)*yyy
         stad(i,1)=stei(i,1)/gg(i)
        enddo
!
        xxx=.0D+000
        do i=2,nlyr
         xxx=xxx+stei(i,2)
        enddo
        yyy=xstei2/(xxx+.1D-014)
        do i=2,nlyr
         stei(i,2)=stei(i,2)*yyy
         stad(i,2)=stei(i,2)/gg(i)
        enddo
!
        xxx=.0D+000
        do i=2,nlyr
         xxx=xxx+rai(i)
        enddo
        yyy=xrai/(xxx+.1D-014)
        do i=2,nlyr
         rai(i)=rai(i)*yyy
         rfad(i)=rai(i)/gg(i)
        enddo
!
        xxx=.0D+000
        do i=2,nlyr
         xxx=xxx+wai(i)
        enddo
        yyy=xwai/(xxx+.1D-014)
        do i=2,nlyr
         wai(i)=wai(i)*yyy
         wad(i)=wai(i)/gg(i)
        enddo
!
      xlai7 = max(xlai7,.1D-014)
      xstei = max(xstei,.1D-014)
      xrai = max(xrai,.1D-014)
      xwai = max(xwai,.1D-014)
      do i=2,nlyr ! get stem/leaf fractions
       xxx=max(pad(i)+stad(i,1)+stad(i,2)+rfad(i)+wad(i),.1D-014)
       flai(i)=pad(i)/xxx
       fstei(i,1)=stad(i,1)/xxx
       fstei(i,2)=stad(i,2)/xxx
       frai(i)=rfad(i)/xxx
       fwai(i)=.1D+001-flai(i)-fstei(i,1)-fstei(i,2)-frai(i)
      enddo

        rai(1)=rai101(1)
!after calling laictx
        pai(1)=.0D+000
        pais(1)=.0D+000
        xai=(xlai7+xstei+xrai+xwai)              ! total area index (walls are all perpendicular to ground)
!KC end

       do i=1,in
        cai101(i)=pai101(i)+stei101(i,1)+stei101(i,2)+rai101(i)+wai101(i)   ! total canopy area index 
       enddo
! get nlyr-member array for total area index for the input 101-member arrays(for canrdz27b,a,  et alia).
        k=0
        jb=int(100./float(nlyr-1))
        do j=2,nlyr
         do i=1,jb
          k=k+1
          cai21(j)=cai21(j)+cai101(k)
         enddo
        enddo
!
!!!!!!!!!!!!!!!!!!! end old laictx...all lea areas are now there...
