	do i=2,nlyr	 ! intracanopy values note: we currently put all anthro emissions at ground-level
!			   we could do this in a more vertically distributed manner / Natale,Pyles
!KC
!	 dwco2(i)=dwco2a(i)+dwco2b(i)+wco2a(i-1)+dwco2b(i-1)
        dwco2(i)=dwco2a(i)+dwco2b(i)
