!
	do i=nlyr+1,n
	 wco2(i)=wco2(nlyr)
	enddo
!
! define feeder arrays for stomatal resistances for all the k scenarios
!
      do j=1,10
       do i=1,nlyr
	rss1(i,j,1)=xrss(i,j) ! 
	rss1(i,j,2)=.0D+000! wet leaves - liquid
	rss1(i,j,3)=.0D+000! wet leaves - ice
	rss1(i,j,4)=.1D+004 ! dry building surfaces
	rss1(i,j,5)=.0D+000 ! wet building surfaces
	rss1(i,j,6)=.0D+000 ! iced building surface
	rss1(i,j,7)=min(.1D+002*xrss(i,j),.1D+004)	!dry fat stems
	rss1(i,j,8)=min(.1D+002*xrss(i,j),.1D+004)	!dry small twigs/petioles
       enddo	 
      enddo
      do k=1,8
