!  eqn 31 w/ "a" = q (humid.)
!  inverted to solve dot d/dz<q> (a.k.a. de)
! also: invert eq. 29 to get dt/dz, &
! invert eq. 30 applied to co2 to get d/dz<co2>
!
       do i=2,n
        de(i)=  wet*((-c3*wq(i)/tau(i)   + .7D+000*got*tq(i)   + dwwq(i))/max(.1D-003,w2(i)))    + omw*de(i)
        dt(i)=  wet*((-c3*wt(i)/tau(i)   + .7D+000*got*t2(i)   + dwwt(i))/max(.1D-003,w2(i)))    + omw*dt(i)
        dco2(i)=wet*((-c3*wco2(i)/tau(i) + .7D+000*got*tco2(i) + dwwco2(i))/max(.1D-003,w2(i)))  + omw*dco2(i)
       enddo
!
!KC
!......................................................................
! <ut>,<vt>,<tq>,<tco2> & derivatives dt/dz,de/dz,dco2/dz and
