!......................................................................
! a1(1) b1(1) c1(1) d1(1)
! a1(2) b1(2) c1(2) d1(2)
!
! combination of eqn 29 and 31
! this bloc coded by Ricky Burnett, 2002
!
       do i=2,n-1
        a1(1) = -.2D+001*wt(i)
        call protect(a1(1),.1D-003)
        b1(1) = -.2D+001/tau(i)
        d1(1) = dwtt(i)
        a1(2) = w2(i)
        b1(2) = -.667D+000*got
        d1(2) = dwwt(i)-c3*wt(i)/tau(i)
        a1(1) = a1(1)*b1(2) - b1(1)*a1(2)
        d1(1) = d1(1)*b1(2) - b1(1)*d1(2)
        call protect(a1(1),.1D-001)
        c1(1) = d1(1)/a1(1)
        c1(2) = (-c1(1)*a1(2)+d1(2))/b1(2)
!        dt(i) = wet*c1(1) + omw*dt(i)
        t2(i) = wet*c1(2) + omw*t2(i)
!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
! combination of eqn 30 and 31
!
        a1(1) = -wt(i)
        call protect(a1(1),.1D-003)
        b1(1) = -.2D+001/tau(i)
        d1(1) = wq(i)*dt(i) + dwtq(i)
        a1(2) = w2(i)
        b1(2) = -.667D+000*got
        d1(2) = dwwq(i)-c3*wq(i)/tau(i)
        a1(1) = a1(1)*b1(2) - b1(1)*a1(2)
        d1(1) = d1(1)*b1(2) - b1(1)*d1(2)
        call protect(a1(1),.1D-001)
        c1(1) = d1(1)/a1(1)
        c1(2) = (-c1(1)*a1(2)+d1(2))/b1(2)
        tq(i) = wet*c1(2) + omw*tq(i)
       enddo
!......................................................................
! 2c. 2nd order terms ut and vt; tco2, to3, dco2, do3
!
!......................................................................
!   invert eqn. 28 applied to x,y dimensions
!
        zzz=.0D+000
      do i=2,n-1
        b1(1)= c3/tau(i)
        d1(1)=-uw(i)*dt(i)-(.1D+001-ct)*wsx(i)*wt(i)-dwut(i)
        ut(i) = wet*(d1(1)/b1(1))+omw*ut(i)
      enddo
!

! now invert eqn. 28 for co2

      do i=2,n-1
       a1(2)=max(w2(i),.1D-003)
       a1(1) = -wt(i)
       b1(1) = -.2D+001/tau(i)
       d1(1) = wco2(i)*dt(i) +dwtco2(i)
       b1(2) = -.667D+000*got
       d1(2) = -dwwco2(i)-c3*wco2(i)/tau(i)
! cat
       a1(1) = a1(1)*b1(2) - b1(1)*a1(2)
       d1(1) = d1(1)*b1(2) - b1(1)*d1(2)
       call protect(a1(1),sss1)
       c1(1) = d1(1)/a1(1)
       c1(2) = (-c1(1)*a1(2)+d1(2))/b1(2)
!       dco2(i) = wet*c1(1) + omw*dco2(i)
       tco2(i) = wet*c1(2) + omw*tco2(i)
       enddo
!KC end
! invert eq. 30 applied to o3(i,j) arrays  to get d/dz<o3> (tracers) !
!
        i=1
