        if(ihi.ge.2)then  ! do multiple tracer arrays
         do j=2,ihi
          do i=2,n
           do3(i,j)=wet*((-c3*wo3(i,j)/tau(i) + .7D+000*got*to3(i,j) + dwwo3(i,j))/w2(i)) + omw*do3(i,j)
          enddo
         enddo
        else		! only one "d03(i)"
         j=1
         do i=2,n
          do3(i,j)=wet*((-c3*wo3(i,j)/tau(i) + .7D+000*got*to3(i,j) + dwwo3(i,j))/w2(i)) + omw*do3(i,j)
         enddo
        endif
