! integrate using cubic spline (as is done with wsx(i) == d<U>/dz)
!KC
        call integrate3(.0D+000,.1D+001,dt,t,gg,n)
        call integrate3(.0D+000,.1D+001,de,e,gg,n)
        call integrate3(.0D+000,.1D+001,dco2,co2,gg,n)
!        call integrate1(dt,t,gg,n)
!        call integrate1(de,e,gg,n)
!        call integrate1(dco2,co2,gg,n)
!KC end
!KC, protection
             xsatv=.1D+001
             call satv(xsatv,t(n))
        do i=2,n-1
           t(i) = max(t(i),t(n)-10.0D+000)
           t(i) = min(t(i),t(n)+10.0D+000)
           e(i) = min(e(i),xsatv)
           e(i)=max(e(i),.1D+000*e(n))!allow only subtle drawdowns in e/ good for WRF. etc..
        enddo
