!        call integrate1(de,e,gg,n)
!        call integrate1(dco2,co2,gg,n)
!KC end
!KC 
!!!!!!!!!!!!!!!!!!!!!!!!!!!! Rem cum Rea facit !!!!!!!!!!!!!!!!!!!!!!
!                           (an attempt at least)
! realizability constraints are about to be imposed on t,e,co2 profiles.
! these are:
!
! 1) no negative or totally saturated humidity
! 2) no > +/- 50 degree temperature swings
! 3) 300 <= co2(i) <= 1000
!
!
! quasi-Andre type realizability constraints
!
       call smth(ut,n)
       call smth(t2,n)
       call smth(tq,n)
       call smth(tco2,n)
        i=n
         ut(i)=.2D+001*ut(i-1)-ut(i-2)
         t2(i)=.2D+001*t2(i-1)-t2(i-2)
         tq(i)=.2D+001*tq(i-1)-tq(i-2)
         tco2(i)=.2D+001*tco2(i-1)-tco2(i-2)
!
! help out t2...
! flip negative variances to 0.1x in the positive
        do i=1,n
         if(t2(i).lt..0D+000)t2(i)=.336D+000*abs(t2(i))
        enddo
        call deriv(dt2,t2,gg,n)
        call deriv(dtq,tq,gg,n)
        call deriv(dut,ut,gg,n)
        call deriv(dtco2,tco2,gg,n)
!KC end
!
! now do the same for the passive tracers "o3"
!
        do j=1,ihi
         do i=1,n
          arrq(i)=do3(i,j)
          arrq1(i)=o3(i,j)
         enddo
!KC
         call integrate3(.0D+000,.1D+001,arrq,arrq1,gg,n)
!         call integrate1(arrq,arrq1,gg,n)
!KC end
         do i=1,n
          o3(i,j)=arrq1(i)
         enddo
        enddo
!
! end Meyers/Meyers Paw U bloc for calculating dt, de, dco2 - original sub scalae
!KC, add length3&length2 section here to make it consistent with J13
        wet=.51D+000
        omw=.1D+001-wet
        xxx=ht
        al7=.23053D+002*.41D+000*(domain_height-d0)/l(n)
        al7 = min(al7,.135D+003)
        al7=max(al7,-.7D+001)
        ld(2)=l(2)*al7
        tau(2)=wet*ld(2)/q(2) + omw*tau(2)
        x(2)=tau(2)/(.2D+001*c8)
        c8k(2)=.1D+001/x(2)
        tau(1)=.1D+001
        nm1=n-1 ! rdp 12 december 2014: this was not defined yet here oops!
        do i=2,nm1
         ld(i+1)=l(i+1)*al7
         tau(i+1)=wet*ld(i+1)/q(i+1)+omw*tau(i+1)
         x(i+1)=tau(i+1)/(.2D+001*c8)
         c8k(i+1)=.1D+001/x(i+1)
         c10k(i)=c10*.2D+001/tau(i)
         yy1=gg(i+1)/(gg(i+1)+gg(i-1))
         yy2=.1D+001-yy1
         xxx1=yy1*(x(i+1)-x(i))/gg(i+1)
         xxx2=yy2*(x(i)-x(i-1))/gg(i-1)
         dx(i)=xxx1+xxx2
         x1(i)=x(i)*w2(i)/gsq(i)
         x2(i)=(x(i)*dw2(i)+dx(i)*w2(i))/twog(i)
        enddo
        c10k(ng) =c10*.2D+001/tau(ng)
! rdp 29 apri 2014: had to include these due to lack of definition previously...
        i=n
        dx(i)=(x(i)-x(i-1))/gg(i)
        x1(i)=x(i)*w2(i)/gsq(i)
        x2(i)=(x(i)*dw2(i)+dx(i)*w2(i))/twog(i)
!
! old length2
!
       dife = .4D+000*(domain_height-d0-l(nlyr))/dble(float(n-nlyr))
       do i=nlyr+1,n
        l(i)=l(i-1)+dife
        ld(i)=l(i)*alcan
       enddo
