! end vestigial variable section.
!
!
	if(xai.lt.xaimin)go to 7331	! do not do any canopy evaporation/sublimation / abblation because there is no canopy!
!
! this formula is from BINTANJA, R.  1998:  The interaction between drifting snow and atmospheric turbulence .
!! Annals of Glaciology, International Glaciological Society (26) pp 167-173
! ustar = sqrt momentum flux density / kinematic (no factor of density neded in denom.)  * time * area with snow.
! let's assume the same rate applies to water as it does snow in the canopy.
!        ablation_glacia(i) =  .843D-001*(abs(uw(i))**.637D+000)*deltat1*xwgt(i,j,3)
!        ablation_acqua(i) =  .843D-001*(abs(uw(i))**.637D+000)*deltat1*xwgt(i,j,2)
! "critical friction velocity to initiate blowing snow / saltation " hs=0.0843*u*^ 1.27...u* = sqrt(uw(i)/rho(i))...therefore hs = .843D-001*(xxx)**.637D+000
! 
!! wind ablation / use "first principles" (momentum transfer) to blow water off the leaves....
! rendered empirically by using momentum flux directly as a driver of sblowing snow (empirical findings)
!! blowing snow  (kg) = ".0843 * ustar^1.27"
!!
!
!! evaporation/condensation contribution to canopy stored water content and/or 
!       rain and/or snow that is blown off the canopy by the wind in the current timestep (kg m-2 timestep-1)             $
!!!     the proportion of TKE which removes the snow is, of course, also proportional to the area 
!       of leaves covered by water &/or ice
! 
! rdp 8 january 2016: checked & corrected  the following to ensure proper storage and reklease of canopy water and ice due to 
! sublimation/evaporation; liquid water condensation/ice condensation, & wind ablation of both liquid water and ice        
! note: canopy precip sequestration & the temperature-based capacity of the 
! canopy to hold snow is already done in interception section.
! right now it assumes all throughfall (here & for precip)  reaches the ground.
!KC, test the canopy area partition
!       do k=2,5,3              						! water on leaves or buildings
!        do j=1,10
!         do i=2,nlyr
!          xxx=dwqs(i,j,k)*gg(i)*deltat1
!          rcan(i,j,k)=rcan(i,j,k)-xxx					! evaporative drawdown or increase 
!          rcan(i,j,k)=max(rcan(i,j,k),.0D+000)                             	! rcan >= 0
!          qqq=.0D+000
!          if(rcan(i,j,k).gt.xrcan(i,j,k))then				! drip from dew formation
!           qqq=(rcan(i,j,k)-xrcan(i,j,k))*xwgt(i,j,k)
!           rcan(i,j,k)=xrcan(i,j,k)
!          endif
! add ablative drip to rain that eventually reaches the surface
!          zzz= .843D-001*(ustar**.127D+001)*deltat1*xwgt(i,j,k)     	! wind ablation factor
!          yyy=rcan(i,j,k)*xwgt(i,j,k)					! actual mass ablation rate
!          zzz=min(zzz,yyy)						! mre can';t blow off than is there!
!          if(zzz.lt..1D-012)zzz=.0D+000                          	! if it's less than 1 ug per timestep..treat it as 0.
!          rain(1) = rain(1) + zzz +qqq  	                        ! add ablation & drip from dew overloading to precip reaching the ground
!          h2o_sl_can(i,j,k)=real(rcan(i,j,k))				! update storage term for next timestep RDP 16 December 2015
!         enddo
!        enddo
!       enddo
! 
!! sublimation/ice condensation adjustments to canopy stored snow/ice
!
!       do k=3,6,3              						! snow/ice on leaves or buildings
!        do j=1,10
!         do i=2,nlyr
!          xxx=dwqs(i,j,k)*gg(i)*deltat1
!          rcan1(i,j,k)=rcan1(i,j,k)-xxx					! evaporative drawdown or increase 
!          rcan1(i,j,k)=max(rcan1(i,j,k),.0D+000)                             	! rcan >= 0
!          qqq=.0D+000
!          if(rcan1(i,j,k).gt.xrcan1(i,j,k))then				! drip from rime formation
!           qqq=(rcan1(i,j,k)-xrcan1(i,j,k))*xwgt(i,j,k)
!           rcan1(i,j,k)=xrcan1(i,j,k)
!          endif
! add ablative drip to rain that eventually reaches the surface
!          zzz= .843D-001*(ustar**.127D+001)*deltat1*xwgt(i,j,k)     	! wind ablation factor
!          yyy=rcan1(i,j,k)*xwgt(i,j,k)					! actual mass ablation rate
!          zzz=min(zzz,yyy)						! mre can';t blow off than is there!
!          if(zzz.lt..1D-012)zzz=.0D+000                          	! if it's less than 1 ug per timestep..treat it as 0.
!          rain(2) = rain(2) + zzz +qqq   		                ! add ablation and rime overload to precip reaching the ground
!          ice_sl_can(i,j,k)=real(rcan1(i,j,k))				! update storage term for next timestep RDP 16 December 2015
!         enddo
!        enddo
!       enddo
!
! store canopy stored water for next time step
!
!KC,Inplement the old code from J13
!KC, use wq instead of dwqs without bias correction 
       k=2              !water
       do j=1,10
        do i=2,nlyr
! evaporation/condensation
!         xxx=xwgt(i,j,k)*dwqs(i,j,k)*gg(i)*deltat1                      ! free evap/condens.
         xxx=dwqs(i,j,k)*gg(i)*deltat1
         yyy=rcan(i,j) - xxx  !- zzz                                    ! rcan diminishes through evaporation
         rcan(i,j)=max(yyy,.0D+000)                                     ! rcan >= 0
        enddo
       enddo
       k=3              !ice
       do j=1,10
        do i=2,nlyr
! sublimation/condensation
!         xxx=xwgt(i,j,k)*dwqs(i,j,k)*gg(i)*deltat1                      ! free subl./condens.
         xxx=dwqs(i,j,k)*gg(i)*deltat1
         yyy=rcan1(i,j) - xxx  !- zzz                                   ! rcan1 diminishes through evaporation
         rcan1(i,j)=max(yyy,.0D+000)                                    ! rcan >= 0
        enddo
       enddo
! evaporation/condensation
!        do i=2,nlyr
!           xxx=wq(i)
!           if (tsssa(i).gt.0.0D+000) then
!        do j=1,10
!           yyy=rcan(i,j) - xxx*.1D+000  !- zzz                                    ! rcan diminishes through evaporation
!           rcan(i,j)=max(yyy,.0D+000)
!        enddo
!           else
!        do j=1,10
!           yyy=rcan1(i,j) - xxx*.1D+000  !- zzz                                    ! rcan diminishes through evaporation
!           rcan1(i,j)=max(yyy,.0D+000)
!        enddo
!           endif
!        enddo
!KC end
!
! store canopy stored water for next time step
!
! for WRF add up all stored water in proportion to leaf angle occurrences
! reset working arrays to 0.
!
        do i=1,nlyr
         h2o_sl_can(i)=0.0
         ice_sl_can(i)=0.0
        enddo
!
       do j=1,10
        do i=2,nlyr
         h2o_sl_can(i)=h2o_sl_can(i)+rcan(i,j)
         ice_sl_can(i)=ice_sl_can(i)+rcan1(i,j)
        enddo
       enddo
!KC end
 7331   continue
	if(iocean.ne.0)go to 733	! do not do any conduction for this point
!
!!!!!!!!!!!!!!!!!! CONDUCTION MODULE...FOR GROUND SURFACE AND BLDG SURFACES
! redone w/ additional streamlining and consistency /  rdpyles 15 juno 2015.
! 1) SOIL COLUMN (W/ SNOWPACK IF PRESENT)
!    (hydrology is turned ON & soil types are nontrivial)
!
! storex(1,10,1) = ground / snow surface heat flux density, G, in the storex(i,j,k) array
! update soil & snow thermal, hydrological states & storage flux densities
! for soil and soil w/ snow on top conditions. its layered!
!!!!!!!!!!!!!!!!!! BEGIN thermal & hydrological CONDUCTION MODULE !!!!!!!!!!!!!!!!!!!!!!!!!!
!!!!!!!!!!!!!!!!!! BEGIN thermal & hydrological CONDUCTION MODULE !!!!!!!!!!!!!!!!!!!!!!!!!!
!!!!!!!!!!!!!!!!!! BEGIN thermal & hydrological CONDUCTION MODULE !!!!!!!!!!!!!!!!!!!!!!!!!!
! the followuing are the thermal diffusion cores (from NOAHLSM subroutines soil123, tqcan) 
! but are now generalized to do (1) soil, (2) snow as if it were soil, (3) large stems, and (4) buildings
! note: this will run off of mean building temperature (t_sl_bldgs(i,k)=t_sl_all(i,j,4-6,nsoil09): i=[2,11]; k=[1,nsoil09])
! storex(i55,j55,h55) = conductive surface heat flux density will be applied to k=5,6 
! equally as k=4...
!
	aca_runoff1=0.
	aca_runoff2=0.
	aca_infil=0.
!
! rdp 22 December 2014...when snow is initialized over a water point in the cohorting of pixels...
! we have a probelm as snow is handled in the conduction modeule, which is not called over water, etc.
! until this is handled better it is best to have no "ice-9"!   
!
        if(iocean.gt.0)then ! open water; keep the snow gone unless the surface is covered with ice.
         snowater9=.0D+000
         SNOWHk=0.0          ! snowpack height =  0
         SNEQV8=0.0          ! update snow water equivalent = 0
         goto 733           ! skip conduction calcs.
        endif
! 
!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
! this is for the trsnpioration root loss only !
!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
!
        do k=1,nsoil09
         xroot(k)=.0D+000		! transpiration extraction (via roots)  	(kg m-2 s-1)
         xroot1(k)=.0D+000		! transpiration extraction (via roots)  	(kg m-2 s-1)
        enddo
        if(xai.gt.xaimin)then	! transpiiration can occur; calculate amount to extract from root zone.
         do i=1,n
          swqfrac1(i)=.0D+000                                                          ! this array was found to be uninitialized (Liyi Xu, March 2008)
         enddo
! calculate the total transpiration rate (=water that is pulled by roots from the soil).
! rdp 24 june 2015: added in stem transpiration terms...k=7,8 are stems ("always 'dry')
         xxx=.0D+000
         do j=1,10
          do i=2,nlyr
           xxx=xxx + (dwqs(i,j,1)*xwgt(i,j,1) + dwqs(i,j,7)*xwgt(i,j,7) + dwqs(i,j,8)*xwgt(i,j,8))*gg(i)
          enddo
         enddo
! this extra factor of (.1D-002 = 1/1000) multiplying swqfrac is to convert from (kg_h2o m-2 s-1) intto [Mg_h2o m-2 s-1] for the soil moisture calculations
         swqfrac=.1D-002*max(xxx,.0D+000)
         xroot(1)=.0D+000
         do i=2,nsoil09
          if(q_sl_all(i).gt.0.0)then  !                                   ! root extraction of water is taking place
!          if(qsoiq(i).gt.0.0)then  !                                   ! root extraction of water is taking place
           xroot(i)=rweight(i)*swqfrac
          else                                                                         ! soil is too dry; roots cannot extract moisture
           xroot(i)=.0D+000
          endif
         enddo
         do i=1,nsoil09                                                                 ! prevent root water "downtake"
          xroot(i)=-max(xroot(i),.0D+000)
         enddo
        endif
!
!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
! rdp iulia 2015: major overhaul of the architecture of the conduction section (soil, snow, thermal storage & conduction through stems, 
! buildings, etc.
!
! the usage of the NOAHLSM soil-core is kept, but is applied via a more streamlined structure that is more modular 
! (less orphaned calculations, more straight-forward logic, etc...and fewer bugs....)
!
! the latest implementation now approaches the standards applied throughout the rest of this model (YAY!!!)
!
! the application of this scheme differs from NOAHLSM in that soil123 is used for snow itself, and the boundary conditions & forcings
! are appplied to each location that can conduct heat (plus moisture) within the canopy architecture (in other words, 
! instead of calling NOAHLSM rotuines (soil123a & tqcan) for a "single surface", here soil123a & tqcan are also applied 
! to multiple solid systems in the surface layer, including large stems, walls, and the soil & snow that can remain on each.
!
! do <i,j,k> is the main triple-nested loop for calling hydrological and/or thermal state & conduction. use storex(i,j,k) for input S(i,j,k) 
! (storage / conduction heat flux) from last time step. use t_sl_all(i,j,k) & t_sl_snow(i,j,k) for interior temperatures. 
! do same for interior water conents (frozen & liquid).
!
! define: iconduction(n,10,8),ihyd(n,10,8), isnowy(n,10,8) to signal when conduction & possibly 
! hydrology, and whether to allow a snowpack to persist at a given element(i,j,k).

        DO K=1,8		
         DO J=1,10
          DO I=1,NLYR
           iconduction(i,j,k)=0
           ihyd(i,j,k)=0
           isnowy(i,j,k)=0
          enddo
         enddo
        enddo
!
! ground surface /// hydro, thermo conduction, both for soil & snow 
!
        i=1
        j=10
        k=1
        if(iocean.eq.0)then
         iconduction(i,j,k)=1		! there is conduction here even when there is no snow present.
         ihyd(i,j,k)=1			! do hydrological transport calculations 
         isnowy(i,j,k)=1		! this surface can maintain a snowpack (snow is always assumed to be hydrologically active) (automatically does conduction)
        endif
!
        if(xai.ge.xaimin)then		! there is a canopy of some sort; set up flag arrays
         K=7				! large stems; "always dry" (no snow)
         DO J=1,10
          DO I=2,NLYR
           iconduction(i,j,k)=1   ! enough fat stems are present for conduction
          enddo
         enddo
        endif
!
        if(xrai.ge.xaimin)then		! there is a building canopy of some sort; set up flag arrays
         DO K=4,6			! allow for dry, wet, & snow covered building surfaces
          DO J=1,10
           DO I=2,NLYR
            iconduction(i,j,k)=1	! do conduction through roofs, walls
           enddo
          enddo
         enddo
         K=6				! allow for snow covered building surfaces
         DO J=1,10
          DO I=2,NLYR
	   isnowy(i,j,k)=1	! do conduction through roofs, walls
          enddo
         enddo
        endif
!
         K=3				! allow for snow covered foliage
         DO J=1,10
          DO I=2,NLYR
            isnowy(i,j,k)=1		! snow can accumulate here.; hydrology is assumed active
            iconduction(i,j,k)=0	! assume leaves are not conducting media
          enddo
         enddo  
!
!
! conduction & hydro parameters for soil, large stems, walls, and also snow...anything that stores & 
! conducts heat (and also dynamic liquid water or ice).
!
        smcdry_snow=0.01			! input: air-dry evporative cutoff value of substrate
        smcref_snow=0.283			! input: reference soil moisture
        psisat_snow=0.218			! input: saturation hydraulic conductivity
        bexp_snow=4.90				! input: clapp-hornberger 'b' expoenti
        dksat_snow=3.47E-05			! input: saturation thermal conductivity
        smcmax_snow=0.435			! input: max water content (total).  also equals maximum snowpack density
!
        smcdry_bldgs=0.004		! input: air-dry evporative cutoff value of substrate
        smcref_bldgs=0.17		! input: reference soil moisture
        psisat_bldgs=0.121		! input: saturation hydraulic conductivity
        bexp_bldgs=4.05			! input: clapp-hornberger 'b' expoenti
        dksat_bldgs=1.41E-07		! input: saturation thermal conductivity
        smcmax_bldgs=0.200		! input: max water content
!
        smcdry_stems= 0.078		! input: air-dry evporative cutoff value of substrate
        smcref_stems= 0.329		! input: reference soil moisture
        psisat_stems=0.478		! input: saturation hydraulic conductivity
        bexp_stems=5.39			! input: clapp-hornberger 'b' expoenti
        dksat_stems=6.95E-07		! input: saturation thermal conductivity
        smcmax_stems=0.451		! input: max water content
! 
!
!KC, adapt soil subroutines from J13KC
!        snweold=snowater9
!        xxxrain=rain(1)+RAIN(2)!for snowmip
        xxx=deltat1
        runoff11=.0D+000
        runoff22=.0D+000
        snowmelt=.0D+000! RDP 11/3/2009; this needed a value

        h55=1   ! 1=soil/snow sfc
        i55=1   ! ith node = 1
        j55=10  ! jth angle class = 10 (default)
! fgacas0 = last time step's value of G
!
        if(snowater9.gt..0)then
         do i=1,n
          tessa(i)=tsss(1,10,1) ! here, tessa(i)==ground surface (skin temperature)
         enddo
        else
         do i=1,n
          tessa(i)=t(2) ! here, tessa(i)==air temperature
         enddo
        endif
        aca_runoff1=0.
        aca_runoff2=0.
        aca_infil=0.
!
        ssoil1=.0D+000
!        ithispoint=0
        iisnow=1
!KC, input T_sl_snow from last time step
        do i=1,num_snow_layers
         soilt22(i)=dble(T_sl_snow(i))
        enddo
! RDP 6/12/2023: initialize qsoiq,tsoiq for soil call...
        do i=1,nsoil09
         tsoiq(i)=dble(T_sl_all(i))
         qsoiq(i)=dble(Q_sl_all(i))
        enddo
!KC end
        call grnd1(h55,i55,j55,fgacas0,rnswf11, &
         tessa,sb,rlwd,rnswi11,emit,rlwu,rai,xxx,e,ra,t,rain,rsl,rho, &
         wt,wq,pai,xlai7,popdens,xlint,gg,dwq,i7ce,nlyr,iocean,soiltype, &
         xai,xstei,zmoi,xstei1,dwqs,xwgt,eosx,dwts,nsnow,schcanlyrs,in,ihi,inlyr,nsoil09,nstem, &
         m,iminit,deltsn,zs1,rweight,smcdry_soil,smcref_soil,psisat_soil,bexp_soil,dksat_soil,smcmax_soil, &
         XSNODEP,SOILT22,RUNOFF11,RUNOFF22,SNOWDENS,SNOWATER9, &
         SNOWMELT,QSOIQ,TSOIQ,STOREX,SNOH,SMELT,SNOWMIP1,ssoil1,iisnow,etal,etaf,fracas(1),fsacas(1),flacas(1))
         aca_runoff2=real(runoff22)             !acasa subsurface runoff
         aca_runoff1=real(runoff11)             !acasa surface runoff
         aca_infil=real(rain(1))-aca_runoff1   !acasa rain hitting the ground surface
         do i=1,num_snow_layers
            T_sl_snow(i)=real(soilt22(i))
         enddo

        if(i7ce.eq.1)then! update here
         do k=1,nroot1
          tsoiq(k)=min(tsoiq(k),.27165D+003)    !sea ice melts at ~1.5 C.
          qsoiq(k)=.1D+001
         enddo
         do k=nroot1+1,nsoil09 ! nrrot for sea ice reps the depth of the sea ice itself./ set to sub-ice ocean temperature: default = -1.5 C.
          tsoiq(k)=max(tsoiq(k),.27165D+003)
         enddo
        endif
!        % chnaged for test Apirl Dave and clkyu
!         qsoiq(1) = .5D-001
!         qsoiq(2) = .5D-001
           do k=1,nsoil09! urban: update building/wall states all the way to interior$
              T_sl_all(k)=real(tsoiq(k))
              Q_sl_all(k)=real(qsoiq(k))
           enddo
!                                 used only in turb. length scale calcs.
! feed in last time step's soil t, q values
!
!        if(i7ce.eq.1.or.soiltype.eq.16)then! update here
!         do k=1,nroot1
!          tsoiq(k)=min(tsoiq(k),.27165D+003)    !sea ice melts at ~1.5 C.
!          qsoiq(k)=.1D+001
!         enddo
!         do k=nroot1+1,nsoil09 ! nrrot for sea ice reps the depth of the sea ice itself./ set to sub-ice ocean temperature: default = -1.5 C.
!          tsoiq(k)=max(tsoiq(k),.27165D+003)
!         enddo
!        endif
!
         do k=1,nsoil09
          stca(k)=real(tsoiq(k))
          smca(k)=real(qsoiq(k))
          sh2o1a(k)=smca(k)
         enddo
!
        fgacas=ssoil1
!        storex(1,10,1) = fgacas
!        s_sl_all(1,10,1) = real(storex(1,10,1))
        SSOIL=real(fgacas)
        snwenew=snowater9
!KC, update temperature
!        tsss(1,10,1) = tsoiq(1)-.27315D+003
!        do j=1,9
!           do k=2,8
!              t_sl_all(1,j,k,:) = t_sl_all(1,10,1,:)
!           enddo
!        enddo
!KC end
!        snwenew=snowater
!
!!!!!!!!!!!!!!!!!!!!!!!!!!! begin aboveground conduction zona!!!!!!!!!!!!!!!!!!!!!!
! 2) ABOVEGROUND CONDUCTION:  BUILDINGS, ETC...
! will run off of mean building temperature (t_sl_bldgs(i,k): i=[2,11]; k=[1,nsoil0])
! storex(i55,j55,h55) = conductive surface heat flux density will be applied to k=5,6
! equally as k=4...
!
! build mean building, large stem, and small leaves& stems mean temps withi each layer...
!
        if(xrai.gt.xaimin)then!urban canopy to figure in to storage fluxes
! set tessa(z) = building temperature_surface(skin)_average(z)
         do i=1,n
          tessa(i)=.0D+000
         enddo
!!
         do k=4,6
          do j=1,9
           do i=2,nlyr
            tessa(i)=tessa(i)+lf11(j)*fsl11(i)*xlint(i,j,k)*tsss(i,j,k)
           enddo
          enddo
          j=10
          do i=2,nlyr
           tessa(i)=tessa(i)+(.1D+001-fsl11(i))*xlint(i,j,k)*tsss(i,j,k)
          enddo
         enddo
!         k=4
!         do j=1,9
!          do i=2,nlyr
!           tessa(i)=tessa(i)+lf11(j)*fsl11(i)*tsss(i,j,k)
!          enddo
!         enddo
!         j=10
!         do i=2,nlyr
!          tessa(i)=tessa(i)+(.1D+001-fsl11(i))*tsss(i,j,k)
!         enddo

!         xxxrain=.0D+000
         xxx=deltat1
!!these are dummy values...they don't apply here...
         runoff11u=.0D+000
         runoff22u=.0D+000
         do k=1,nsnow
          soilt22u(k)=.27315D+003
         enddo
         do k=1,100
          snowmip1u(k)=.1D+001
         enddo

         h55=4
         j55=1

          do i55=2,nlyr ! ith node
! rainu,tsoiqu,qsoiqu,rslu,isoi3u change to urban values...
! isoi3u = 15 (bedrock)
! rslu = 800 sm-1
! qsoiqu=0.05 (dry bldgs)
! tsoiqu = building temperature
!
           do k=1,nsoil09
            qsoiqu(k)=.5D-001 ! building walls are all assumed to be <= 5% water.
            tsoiqu(k)=dble(T_sl_all(k))
           enddo
           isoi3u=15!bedrock for now...streets & sidewalks...
           rslu=rsl
           do k=1,3
            rainu(k)=.0D+000
           enddo
!!
!! fgacas0 = last time step's value of G
         fgacas01=storex(i55,j55,h55)! urban: dry building surface
!! all walls are 0.25m thick per layer
        do k=1,nsoil09
         zs01(k)=dble(float(k-1))*.25D+000
        enddo
!!
        ssoil2=.0D+000
        idummy=0
!
        call grnd1(h55,i55,j55,fgacas01,rnswf11, &
         tessa,sb,rlwd,rnswi11,emit,rlwu,rai,xxx,e,ra,t,rain,rsl,rho, &
         wt,wq,pai,xlai7,popdens,xlint,gg,dwq,i7ce,nlyr,iocean,soiltype, &
         xai,xstei,zmoi,xstei1,dwqs,xwgt,eosx,dwts,nsnow,schcanlyrs,in,ihi,inlyr,nsoil09,nstem, &
         m,iminit,deltsn,zs1,rweight,smcdry_soil,smcref_soil,psisat_soil,bexp_soil,dksat_soil,smcmax_soil, &
         .0D+000,SOILT22U,RUNOFF11U,RUNOFF22U,.3D+003,.0D+000, &
         .0D+000,QSOIQU,TSOIQU,STOREX,.0D+000,.0D+000,SNOWMIP1U,ssoil2,idummy,etalu,etafu,fracas(1),fsacas(1),flacas(1))
!           do k=1,nsoil09! urban: update building/wall states all the way to interior$
!              T_sl_all(i55,j55,h55,k)=real(tsoiqu(k))
!              Q_sl_all(i55,j55,h55,k)=real(qsoiqu(k))
!           enddo
! this was used in the preliminary (s-less) version
! insert building values to be stored here.
!          if(iendo.eq.0)then
!           do k=1,nsoil09! urban: update building/wall states all the way to int$
!              T_sl_all(i55,j55,h55,k)=real(tsoiqu(k))
!           enddo
!          else
!!!!!!!            :k=1,nsoil0/2! urban: update building/wall states all the way to interior$
