!
! rdp 05 october 2015: xxx=dble(stca(1)) - - .27315D+003.  typo that rendered ocean values of Q1 bogus. 
!
        if(iocean.eq.1)then
	 xxx=dble(stca(1)) - .27315D+003 ! aaargh!tsoiq(1)-.27315D+003 ! !t(1) rdp 15 november 2014: make sure this is the sst/sfc temp prescribed by wrf.					! T1 (oC)
         xsatv=.1D+001						! initialize sat. vapor pressure
         call satv(xsatv,xxx)					! get xsatv
         xxx=xsatv*.622D+000/pres				! convert xsatv into mixing ratio (kg kg-1)
        else
	 xxx=t(2)					! T1 (oC)
         xsatv=.1D+001						! initialize sat. vapor pressure
         call satv(xsatv,xxx)					! get xsatv
         xxx=xsatv*.622D+000/pres				! convert xsatv into mixing ratio (kg kg-1)
        endif
	q_sl_air(1)=real(xxx)					! Q1 output for WRF
	Q1 = q_sl_air(1)					! what WRF actually uses Q1 / kg kg-1
	t_sl_air(1)=T1						! aliases...
	q_sl_air(1)=Q1						!"
	t1acasa =dble (T1) ! aaaargh!skintemperature					!"
        q1acasa=dble(q1)					!"
        xxx=flacas(nlyr)						! latent heat flux density  (Wm-2)    ! 
        ETA=real(xxx)	
        yyy=.2491265D+007-.2374029D+004*(t2o6-273.15D+000)			! latent heat of vap. @ temperature 
        if(t2o6.lt..27315D+003)yyy=yyy+.3345D+006		! latent heat of h2o-vap. + -fusion (latent heat)
        ETA_kinematic=ETA/real(yyy)				! <w'q'> (kg m-2 s-1)
        SHEAT=real(fsacas(nlyr))            			! H (Wm-2)
        ifail=0
        if(sheat.lt.-500.)ifail=1
        if(SHEAT.GT.1500.)ifail=1
        if(ETA.lt.-200.)ifail=1
        if(ETA.gt.1500.)ifail=1
        if(abs(SSOIL).gt.350.0)ifail=1
        ustaracasa=real(ustar88)				! u* (ms-1)
!
! 10m wind speed & direction for WRF output / California
! iitwo here = "iiten"
        xxx=.0D+000 
        iitwo=n-1
        i=n
        do i=2,n
         xxx=xxx+gg(i)
         if(xxx.gt..1D+002)then
          iitwo=i-1
          go to 5661
         endif
        enddo
 5661   continue
        iitwo=max(iitwo,2)
        U10mm=real(mw(iitwo))  ! crude but is nearest to 10m ; (xxx*mw(im1)+yyy*mw(i))/(xxx+yyy)
!
! 2m temperature, specific humidity for WRF output / California
!
        xxx=.0D+000 
        iitwo=n-1
        do i=2,n
         xxx=xxx+gg(i)
         if(xxx.gt..2D+001)then
          iitwo = i-1
          go to 5662
         endif
        enddo
 5662   continue
        iitwo=max(iitwo,2)
        t2mm = real(t(iitwo)) +273.15    		! "2m" temperature (K)
        q2mm = real(e(iitwo)) 				! "2m" specific humidity (kg kg-1)                
!
        if(isoi3.eq.1)ssoil=0.      				! infinite reservoir/surface  /G ==>0
!
! (hey...wasn't this eta the same eta as in the eta model (~1995)?...)
! runoffs are cumulants...keep bounded...
! rdp 25 july 2014: moved snow state vbles to nearer where thwe were calculated...
	do j=1,60
	 xscale(j)=.0D+000
	enddo
        do i=1,n! p0=1000mb=100000Pa--unit conversion error fixed 9/17/2008
         thetavir(i)=(.1D+001+.61D+000*e(i))*((t(i)+.27315D+003)*(.1D+006/pres)**rocp) ! virtual potential temperature for bulk richardson # calcs...used for PBL above theACASA domain.
        enddo
	izz7=2
	if(xai.ge.xaimin)then
	 izz7=int(real(.1D+002*d0/ht))+1		! node closest to zero-plane displacement height / center of momentum
	 izz7=max(izz7,2)
	 izz7=min(izz7,nlyr)
	endif
        xxx=mw(n)-mw(izz7) 				!
        call protect(xxx,.1D+000)
        bracasa1=got*(thetavir(n)-thetavir(izz7))*(domht-d0)/xxx 		!bulk richardson number
	if(wt(n).gt..0D+000)then
	 bracasa1 = -abs(bracasa1) ! make sure positive heat fluxes do not blow the sign of br
	else
	 bracasa1 = abs(bracasa1) ! make sure neg/0 heat fluxes do not blow the sign of br 
	endif							
	xxx=abs(bracasa1)				! up "faux-stabilizing" the atmosphere.
	if(xxx.lt..1D-001)bracasa1=.0D+000		!neutrality
        bracasa1=max(bracasa1,-.1D+003)
        bracasa1=min(bracasa1,.1D+003)
        BR88=bracasa1					! bulk richardson #
        evaporation_soil8=real(rho(2)*wq(1))		!soil/snow/ice/water surface evaporation
        resp_stems_leaves8= real(tresps+trespl)
	if(abs(resp_stems_leaves8).lt.1.0E-15)resp_stems_leaves8=0.0
	resp_anthro8=0.0
        if(popdens.gt..1D-005)resp_anthro8 = real(wco2b(1))
        resp_soil_microbia8= real(trespm)
	if(abs(resp_soil_microbia8).lt.1.0E-15)resp_soil_microbia8=0.0
        resp_roots8 =real(trespr)
	if(abs(resp_roots8).lt.1.0E-15)resp_roots8=0.0
        canopy_resist_blk8= real(rssx)
	if(iocean.eq.1)canopy_resist_blk8=2500.		!flag
	if(xai.lt.xaimin)canopy_resist_blk8=2500.		!flag
        dnaught_blk8 =real(d0)
	xxx=.0D+000
	if(iocean.eq.1)xxx = fracas(n) - flacas(n) -fsacas(n)	!storage flux into water is residual of Rn-H-LE
        s_total_ocean8= real(xxx)
	xxx=.0D+000
	if(snowhk .gt.0.00)THEN
         xxx = fracas(1) - flacas(1) - fsacas(1) - storex(1,10,1)	!storage flux into water is residual of Rn-H-LE at surface
         s_total_snow8 = real(xxx)
        endif
	if(i7ce.eq.1)THEN
         xxx = fracas(1) - flacas(1) - fsacas(1) - storex(1,10,1)	!storage flux into water is residual of Rn-H-LE at surface
         s_total_snow8 = real(xxx)
        endif
        s_total_bio8 = real(xsbio)
        s_total_anthro8 = real(xsanthro)
	if(abs(s_total_snow8).lt.1.0E-15)s_total_snow8=0.0
	if(abs(s_total_bio8).lt.1.0E-15)s_total_bio8=0.0
	if(abs(s_total_anthro8).lt.1.0E-15)s_total_anthro8=0.0
	t1acasa =skintemperature
        xsatv=.1D+001
	xxx=t1acasa-.27315D+003
        call satv(xsatv,xxx)
        q1acasa=xsatv*.622D+000/pres
        rnetflx=real(fracas(n))				! total net absorbed (thermal+solar) radiation flux density (Wm-2)
!KC, update snowpack depth
        snowhk = real(xsnodep)
        SNEQV8=real(snowater9)                            ! update snow water equivalent (kg m-3)
        SNDENS1 = real(SNOWDENS)                         ! density of snowpack
        FLX3=aca_infil                                  ! rainfall hitting the ground / infiltration rate
!KC end
! 
!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
! the energy balance is not forced closed.  therefore, the residual is a measure of model coherence...or "internal" processes such as 
! the artificial heating/cooling of buildings, snow phase changes, &/or fuxes carried by snowfall/rainfall.
! this is the true energy budget residual..if all is going well, it should integrate to < a few % of the total 
! incoming energy over time...will usually be 0 to several Wm-2 individually. 
!!! NOTA BENE: these are artifically set to 0...to keep "infinite-reservoir" and phase change storages for open water and snow, ice, respectively
! this should eventually be handled explicity.....but for now, keep as-is. --RDP
         do i=1,nlyr
          if(abs(error_sebp(i)).lt.1.0E-6)then
           error_sebp(i)=0.0               ! infinitesimalia.
           error_sebp_norm(i)=0.0               ! infinitesimalia.
           error_seb=0.0               ! infinitesimalia.
          endif
         enddo
!
! diagnostic output
!
         Rn_KC = fracas(n)
         H_KC = fsacas(n)!-tstore_sensible
         LE_KC = flacas(n)!-tstore_latent
         ET_KC = ETA_KINEMATIC
         NEE_KC= fco2nee-tstore_co2
         s1_KC = fstacas(1)
         s2_KC = xsbio
         s3_KC = xsanthro
         total_resp_KC = fco2respl+fco2resps+fco2respr+fco2respm
         NPP_KC= -(tphoto+total_resp_KC)
         ustar_KC = ustar
         NPP_KC= fco2npp
         rlwu_top = rlwu(n)
         Ttop  = t(n)
         QSFC  = E(n)
         photo_KC=tphoto
         GPP_KC= fco2npp-(fco2respl+fco2resps+fco2respr+fco2respm)

       if(raina.eq..0D+000)then
        prc33=.0D+000
        prc34=.0D+000
       endif
! 
!heat flux from rain ; estimate / (dM/dt)*cp_aq*(fall_temp - skintemp) = flux
       hfx_rain= real((rain1(1)+rain1(2)+rain1(3))*(t2op-skintemperature))*4.186E+04
       if(rain1(1)+rain1(2)+rain1(3).lt..1D-006)hfx_rain=.0
!
       i=n         
!
! nota: we need to refine this a bit more.
! rdp 17 December 2015: these lines are bogus....
!         xxx=.0D+000
!         if(ice_sl_can(1,10,1).gt.0.0001)then ! wrf mode
!          i=nlyr
!          fstacas(i) = fracas(i)-flacas(i)-fsacas(i) !dble(error_seb)
!          error_seb=.0
!         endif
!
       xxx=.0D+000
       if(snowater9.gt..1D-003)then
        xxx=fracas(i)-fsacas(i)-flacas(i)-tstorep(i) 
        error_seb=0.0
       endif
!
       i=nlyr
!
!
 7792    format(f24.18,i4,80f24.18)
 779    format(80f18.6)
 7791    format(30f12.6)

!! label fields.  units are all MKS-standard unless otherwise specified
!! gets big...100 MB for every 100 days or so @ 30-minute intervals.
!!
!!to file, unit=61, file='ACASA_Output_profiles.txt'
!!
 778    format(30f9.2)
!
!!to file, unit=62, file='ACASA_Output_profilesG.txt'
!!
!	 if(itimestep.eq.1)then ! label fields
!          write(62,528)'zsoil(m),Tsoil,z(m)qsoil,snowaterequivalent(m)'
!          write(62,528)'units: meters, K, volumetric, K'
!          write(62,*)'  '
!          write(67,528)'zs1_snow(m),Tsnow(zs1_snow),snowaterequivalent(m)'
!          write(67,528)'units: meters, K, mm'
!          write(67,*)'  '
!	 else			! output
!	   do k=1,nsnow
!	    write(67,523) -zs1_snow(k),t_sl_snow(k),ice_sl_can(1) !tsoiq(k),qsoiq(k)
!	   enddo
!	   write(67,*)'  '
!	   do k=1,nsoil09
!!	    write(62,523) -zs1(k),t_sl_all(1,10,1,k),q_sl_all(1,10,1,k) 
!	   enddo
!	   write(62,*)'  '
!	 endif
 523     format(160E18.8)
 528     format(158a24)
 355     format(70E18.8)


!! mean wind, scalar 'zeroth order' gradients, each solved for independently...
!! ~i~ indicates the quantity is independently calculated
!! ~a~ indicates quantites are derived directly from the corresponding ~i~ quantity
!! currently the output profiles are nonnormalized.
!!ccccccccccccccccccccccccccccc
!! output to SCREEN / files / applications
!!ccccccccccccccccccccccccccccc output for diagnostics
!!ccccccccccccccccccccccccccccccccccccccccccccccccc 
!! mean wind, scalar 'zeroth order' gradients, each solved for independently...
!!
!! ~i~ indicates the quantity is independently calculated
!! ~a~ indicates quantites are derived directly from the corresponding ~i~ quantity
!!
!! currently the output profiles are nonnormalized.
!! 3 8 9 36 37
!! order zero
!!
!
	call normz(mw,zprof,n,xscale,1)		! <U> 
	call normz(t,zprof,n,xscale,2)		! <T> 
	call normz(e,zprof,n,xscale,3)		! <E> 
	call normz(co2,zprof,n,xscale,4)	! <[CO2]>
!
	call normz(wsx,zprof,n,xscale,5)	! d<U>/dz 
	call normz(duw,zprof,n,xscale,6)	! d<uw>/dz
	call normz(dt,zprof,n,xscale,7)		! dT/dz 
	call normz(de,zprof,n,xscale,8)		! dq/z 	!
	call normz(dco2,zprof,n,xscale,9)	! d[co2]/dz 
	call normz(uw,zprof,n,xscale,10)	! <u'w'>
	call normz(u2,zprof,n,xscale,11)	! <u'u'>
	call normz(v2,zprof,n,xscale,12)	! <v'v'>
	call normz(w2,zprof,n,xscale,13)	! <w'w'>
	call normz(qs,zprof,n,xscale,14)	! <TKE> 
	call normz(wt,zprof,n,xscale,15)	! <w't'>
	call normz(dwt,zprof,n,xscale,16)	! d<w't'>/dz
	call normz(wq,zprof,n,xscale,17)	! <w'q'>
	call normz(dwq,zprof,n,xscale,18)	! d<w'q'>/dz
	call normz(wco2,zprof,n,xscale,19)	! <w'co2'>
	call normz(dwco2,zprof,n,xscale,20)	! d<w'co2'>/dz
	call normz(ut,zprof,n,xscale,21)	! <u't'>
	call normz(t2,zprof,n,xscale,22)	! <t't'>
	call normz(tq,zprof,n,xscale,23)	! <t'q'>
	call normz(tco2,zprof,n,xscale,24)	! <t'co2'>
	call normz(t3,zprof,n,xscale,25)	! <t't't'>
	call normz(wtt,zprof,n,xscale,26)	! <w't't'>
	call normz(wwt,zprof,n,xscale,27)	! <w'w't'>
	call normz(w3,zprof,n,xscale,28)	! <w'w'w'>
	call normz(wwq,zprof,n,xscale,29)	! <w'w'q'>
	call normz(wtq,zprof,n,xscale,30)	! <w't'q'>
	call normz(t2q,zprof,n,xscale,31)	! <t't'q'>
	call normz(utt,zprof,n,xscale,32)	! <u't't'>
	call normz(wut,zprof,n,xscale,33)	! <w'u't'>
	call normz(uut,zprof,n,xscale,34)	! <u'u't'>
	call normz(wwu,zprof,n,xscale,35)	! <w'w'u'>
	call normz(wuu,zprof,n,xscale,36)	! <w'u'u'>
	call normz(wvv,zprof,n,xscale,37)	! <w'v'v'>
	call normz(wwv,zprof,n,xscale,38)	! <w'w'v>
	call normz(vvt,zprof,n,xscale,39)	! <v'v't'>
	call normz(vtt,zprof,n,xscale,40)	! <v't't'>
	call normz(wwco2,zprof,n,xscale,41)	! <w'w'co2'>
	call normz(wtco2,zprof,n,xscale,42)	! <w't'co2'>
	call normz(ttco2,zprof,n,xscale,43)	! <t't'co2'>
!
	vname(1)=' <U> '
	vname(2)=' <T> '
	vname(3)=' <q> '
	vname(4)=' <co2> '		
	vname(5)=' d<U>/dz '

	vname(6)=' d<uw>/dz '
	vname(7)=' d<T>/dz '
	vname(8)=' d<q>/dz '
	vname(9)=' d<co2>/dz '
	vname(10)=' <uw> '
	vname(11)=' <uu> '
	vname(12)=' <vv> '
	vname(13)=' <ww> '
	vname(14)=' <TKE> '
	vname(15)=' <wt> '
	vname(16)=' d<wt>/dz '
	vname(17)=' <wq> '
	vname(18)=' d<wq>/dz '
	vname(19)=' <wco2> '
	vname(20)=' d<wco2>/dz '
	vname(21)=' <ut> '
	vname(22)=' <tt> '
	vname(23)=' <tq> '
	vname(24)=' <tco2> '
	vname(25)=' <ttt> '
	vname(26)=' <wtt> '
	vname(27)=' <wwt> '
	vname(28)=' <www> '
	vname(29)=' <wwq> '
	vname(30)=' <wtq> '
	vname(31)=' <ttq> '
	vname(32)=' <utt> '
	vname(33)=' <wut> '
	vname(34)=' <uut> '
	vname(35)=' <wwu> '
	vname(36)=' <wuu> '
	vname(37)=' <wvv> '
	vname(38)=' <wwv> '
	vname(39)=' <vvt> '
	vname(40)=' <vtt> '
	vname(41)=' <wwco2> '
	vname(42)=' <wtco2> '
	vname(43)=' <ttco2> '
!!
	if(iprint7.eq.0)go to 677		!iprint7 is set in morphology.txt
!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
!! now output all of these to a file. multiply all x1(i) by scale1
!! and all x2(i)*scale2 --> x73(i)*scale73 to restore profiles to nonnormalized forms.
!! the normalization was necessary to standardize the output as well as
!! provide an easy way to compare all profiles' variations in z together
!! (such a feature accelerates troubleshooting!)
!!
!! the format is:  
!! 
!! date
!! vname1, vname2,    ...vname73
!! scale1,scale2,     ...scale73
!! x1(1)norm,x2(1)norm...x73(1)norm
!! x1(2)norm,x2(2)norm...x73(2)norm
!! ...      ...       ...
!! :        :         :
!! x1(n)norm,x2(n)norm...x73(n)norm
!! 
!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
!
!
!!!!!!!!!!!!!!!!!!!!! begin acasa non-STANDARD output to files....!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
!
 677 continue
!!!
!!!!!!!!!!!!!!!!!!!!! begin acasa output to files....!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
! end standard output
!!!!!!!!!!!!!!!!!!!!!!!!!!
!
!!

!!!!!!!!!!!!!!!!!!!!! begin acasa output to files....!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
! end standard output
!!!!!!!!!!!!!!!!!!!!!!!!!!
!
       return
      end subroutine acasa

