  401.0  /
!
!
! Introducing Dayligth Saving Time:	
       if(suedst.eq.1)then
        if(xday.ge..90083D+002.and.xday.lt..30007D+003)then	!exact for utc+1 time zone (Italy) for 2008; valid within 5 days for all other years,
! in any UE country
!~ xday=xday+.1d+001/.24d+002 		!this produces an error: after the 47th half-hour produces the 48th half hour, instead 
!of 0th half-hour
         xday=xday+0.41667D-001				!this is correct (just calculate 1/24 and make it a bit bigger)
        endif
       endif
!
!
! Calculating day of week:
! This calendar is valid from jan 1, 1905 to dec 31, 2100:
       iweekday=mod(nint(xyear-xyear0)*365+nint(xyear-xyear0)/4+int(xday)-nint(xday0),7) 	!we started with january 1st, 1905, which was 
!a sunday; so if an exact multiple of 7 days has passed since then, we are in sunday again; if remainder is 1, we are in monday.
! So if iweekday=0=sun, 1=mon, ..., 6=sat
       iweek=1								!workdays
       if(iweekday.eq.6)iweek=2					!saturday
       if(iweekday.eq.0)then ; iweek=3 ; iweekday=7 ; endif 	!sunday 
!
!
! Modulating traffic along the year:
       xxx=.1D+001									!flat mean traffic during year
       if(suetay.eq.2)then
        if(xday.ge..182D+003.and.xday.lt..244D+003)xxx=.8D+000 	!invoke 20% reduction in july and august
       endif
       if(suetay.eq.3)then							!another formulation following Christen 2001:
        if(xday.lt..320D+002)xxx=.94D+000					!january
        if(xday.ge..152D+003.and.xday.lt..182D+003)xxx=.104D+001	!june
       endif
       if(suetay.eq.4)then 							!valid for Helsinki 2008-2009 (Jarvi et al 2012, fig.3a) considering
!that ndjfm average is very close to 900 vehicle timestep-1, and this is equal to 1 in the following table:
        if(xday.ge..010D+002.and.xday.lt..320D+002)xxx=.940D+000 	!jan
        if(xday.ge..320D+002.and.xday.lt..600D+002)xxx=.100D+001 	!feb
        if(xday.ge..600D+002.and.xday.lt..910D+002)xxx=.100D+001	!mar
        if(xday.ge..910D+002.and.xday.lt..121D+003)xxx=.111D+001 	!apr
        if(xday.ge..121D+003.and.xday.lt..152D+003)xxx=.111D+001 	!may
        if(xday.ge..152D+003.and.xday.lt..182D+003)xxx=.100D+001	!jun
        if(xday.ge..182D+003.and.xday.lt..213D+003)xxx=.740D+000 	!jul
        if(xday.ge..213D+003.and.xday.lt..244D+003)xxx=.100D+001 	!aug
        if(xday.ge..244D+003.and.xday.lt..274D+003)xxx=.111D+001	!sep
        if(xday.ge..274D+003.and.xday.lt..305D+003)xxx=.111D+001	!oct
        if(xday.ge..305D+003.and.xday.lt..335D+003)xxx=.107D+001 	!nov
        if(xday.ge..335D+003.and.xday.lt..367D+003)xxx=.940D+000 	!dec
       endif
!
!
! Obtaining vehicle density:	
!rdp 19 october 2015:        ihour=nint(.48D+002*(xday-int(xday)))  ! identified using gnu fortran (gfortran -ffree-form -Wconversion
!       ihour=nint(.48D+002*(xday-int(xday)))
!                                    1
!Warning: Conversion from INTEGER(4) to REAL(8) at (1)

       ihour=nint(.48D+002*(xday-dble(real(int(real(xday))))))
       vehicled_fake=xxx*dble(vehicle_proxy_day(ihour+1,iweek))*popdens/.27D-002 	! generalize from Helsinki popdens (0.0027 people m-2)  to 'any'
!
!
       return
       end subroutine
!
!!!!!!!!!!!!!!!!!!! /-\ < /-\ S /-\ !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
!       
        subroutine physiology(pres,tleaf,tair,ahumid,shumid,co2c, &
         caq1, &
         parc,ares,sresn,rhs1,gsw1,an1, &
         xai,photosynth,qsoil,respl,yrsmn,t_enviro_mean)
!
! physiological driver program: sets up calls to photos and conduct. 
!
! tleaf in c, tair in c
! ahumid in kg/kg, shumid in kg/kg
! co2c is co2 concentration molar fraction
! ares is the input leaf boundary layer resistance
! sresn is the updated value of stomatal resistance
! rhs1, an1, and gsw1 are all to be initialized with the first iteration in
! acasa.
! 	
	implicit none
      DOUBLE PRECISION pres,tleaf,tair,ahumid,shumid,co2c,parc,ares
      DOUBLE PRECISION sresn,rhs1,gsw1,an1,gb0,xxx,t_enviro_mean
      DOUBLE PRECISION xai,caq1,gsw1a
      DOUBLE PRECISION photosynth,qsoil,respl,yrsmn
      DOUBLE PRECISION wuey
	gb0 = pres/(.8314D+001*(tair+.27315D+003)*ares)
!    an1 - net co2 assimilation rate [umol.m-2.s-1]
!    gb0 - leaf boundary layer conductance [mol.m-2.s-1]
!    co2c - mole fraction co2 in ambient air [umol.mol-1]
!    tleaf - leaf temperature in celsius [c]
!    rhs1 - relative humidity at leaf surface (0<=rhs<=1.)
!    parc - absorbed photosynthetic active radiation irradiance [w.m-2]
!     yrsmn = max ideal carboxylization rate (umol m-2(tissue) s-1)
!
! 	call photos(an1,gb0,co2c,tleaf,rhs1,parc, &
!        xai,photosynth,respl,yrsmn,t_enviro_mean)
        call photos_J13(an1,gb0,co2c,tleaf,rhs1,parc, &
        xai,photosynth,respl,yrsmn)
!    gsw1 - stomatal conductance to water vapor [mol.m-2.s-1]
!    an1 - net co2 assimilation rate [mol.m-2.s-1]
!    ahumid - specific humidity in ambient air [kg.kg-1]
!    shumid - saturated specific humidity at leaf temperature [kg.kg-1]
!    co2c - mole fraction co2 in ambient air [umol.mol-1]
!    gb0 - boundary layer conductance [mol.m-2.s-1]
!
        call conduct(gsw1,an1,ahumid,shumid,co2c,caq1,gb0, &
         gsw1a)
!        wuey = .1D+001
!        call conduct_J13(gsw1,an1,ahumid,shumid,co2c,caq1,gb0, &
!         gsw1a,wuey)
!
! co2 enriched; water use efficiency goes up; conductance less
! 
! J. D. Lewis, M. Lucash, D. M. Olszyk & D. T. Tingey, 2002:
! Stomatal responses of Douglas-fir seedlings to elevated carbon dioxide 
! and temperature during the third and fourth years of exposure
! Plant, Cell & Environment, 25(11),1411.
!
	xxx=.1D+001
        gsw1=gsw1a*xxx
!
	sresn = min(pres/(.8314D+001*(tair+.27315D+003)*gsw1),.2D+004)
!
	return
	END SUBROUTINE
!
!!!!!!!!!!!!!!!!!!! /-\ < /-\ S /-\ !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
!
	subroutine photos(an,gb,caq,tlc,rhs,par, &
        xai,photosynth,respl,yrsmn,t_enviro_mean)
!......................................................................
!  list of variables in subroutine photosynthesis
!    an - net co2 assimilation rate [mol.m-2.s-1]
!    ag - gross co2 assimilation rate [mol.m-2.s-1], ag is not used explicitly
!    ar - rubisco activity limit of ag mol.m-2.s-1]
!    ae - electron transport & rup2 regeneration limit of ag [mol.m-2.s-1]
!    rd - "day respiration" or mitochondrial respiration rate [umol.m-2.s-1]
!    ca - mole fraction co2 in ambient air [mol.mol-1]
!    oi - mole fraction o2 in intercellular air space [mol.mol-1]
!    gamma - co2 compensation point when rd=0 [umol.mol-1]
!    vcmax - maximum rate of carboxylation with non-limiting rup2 and co2 and
!	     full activation of rubisco [umol.m-2.s-1]
!    kc, ko - michaelis-menten constants for co2 and o2 [umol.mol-1]
!    j - potential electron transport rate [umol.m-2.s-1]
!    aj, bj, cj - coefficients of transition quadratic equation of j
!    jmax - maximum j determined by leaf temperature [umol.m-2.s-1]
!    pfd - photon flux density [umol.m-2.s-1]
!    iqe - intrinsic quantum efficiency (iqe=(1-f)/2) where f is the
!	   fraction of pfd absorbed by other than the chloroplast lamellae
!    theta - curvature factor of light and co2 response curve (0<=theta<=1)
!    tlc - leaf temperature in celsius [c]
!    tlk - leaf temperature in kelvin [k]
!    tck - conversion constant between celsius and kelvin of temperature
!    vcmax25 - vcmax at 25c [umol.m-2.s-1] -- max carb. at ideal temperature, etc.
!    kc25 - kc at 25c [umol.mol-1]
!    ko25 - ko at 25c [umol.mol-1]
!    gamma25 - gamma at 25c [umol.mol-1]
!    ekc, eko - activation energies for kc and ko [j.mol-1]
!    rgas - universal gas constant [j.k-1.mol-1]
!    t0c - reference temperature in celsius [c]
!    t0k - reference temperature in kelvin [k]
!    zjmax0 - coefficient for temperature dependence of jmax [umol.m-2.s-1]
!        (it is likened to the max ideal carboxylization rate vcmax25, but is 217/90 greater)
!    ejamx - coefficient for temperature dependence of jmax [j.mol-1]
!    sjamx - coefficient for temperature dependence of jmax [j.mol-1.k-1]
!    hjmax - coefficient for temperature dependence of jmax [j.mol-1]
!    par - absorbed photosynthetic active radiation irradiance [w.m-2]
!    cpfd - conversion coefficient from par to pfd
!    aa,bb,dd,ee - coefficients in formula ==> an={aa*(ci-dd)}/{ee*ci+bb}-rd
!    rhs - relative humidity at leaf surface (0<=rhs<=1.)
!    gb - leaf boundary layer conductance [mol.m-2.s-1]
!    can3, can2, can1, can0 - coefficients in cubic equation of an
!    acan,bcan,gcan,tcan - intermediate coefficients to calculate can3,...can0
!    dwdc - ratio of molecular diffusivity of water vapor to that of co2
!    cm - slope of ball-berry linear gsw empirical formula (unitless)
!    cb - intercept of ball-berry linear gsw empirical formula [mol.m^-2.s^-1]
!    bbb,ccc,ddd - coefficients of cubic equation of x=an
!    ppp,qqq - coefficients of reduced cubic equation of z=x+bbb/3.
!......................................................................
!  note (1): unit for ci, oi, kc, ko and gamma should be consistent, it could
!	     be either [mol.mol-1] or [umol.mol-1] or partial pressure [bar]
!	     where 1 bar = 1.e5 pa.
      implicit none

      DOUBLE PRECISION kc,kc25,ko,ko25,jmax,zjmax0,j,iqe,can0,power3,t_enviro_mean
      DOUBLE PRECISION an,ag,ar,ae,acan,bcan,gcan,tcan,can3,can2,can1
      DOUBLE PRECISION aj,bj,cj,delta,bbb,ccc,ddd,ppp,qqq,rrr,ttt,theta0
      DOUBLE PRECISION ejmax,hjmax
      DOUBLE PRECISION yyy,respl
      DOUBLE PRECISION gb,caq,tlc,rhs,par
      DOUBLE PRECISION theta,oi,vcmax25,xxx
      DOUBLE PRECISION gamma25,ekc,eko,rgas,t0c,tck,sjmax,cpfd,dwdc,cb
      DOUBLE PRECISION cm,pi,ca,dtl,t0k,tlk,rd,vcmax,gamma,pfd,aa
      DOUBLE PRECISION dd,ee,bb,qqn,xyz,xai,dtl1,photosynth
      DOUBLE PRECISION qsoil,yrsmn
      double precision xb7,xb8,xb9,xb10,xb11,xb12,xxb,xyb,xzb
      parameter(theta=.5D+000,oi=.209D+000,iqe=.405D+000)
      parameter(kc25=.310D+003,ko25=.396000D+006)
      parameter(gamma25=.447D+002,ekc=.59430D+005)
      parameter(eko=.36000D+005,rgas=.8314D+001)
      parameter(tck=.27315D+003)
      parameter(sjmax=.710D+003,ejmax=.37000D+005)
      parameter(cpfd=.46D+001,hjmax=.220000D+006)
      parameter(dwdc=.1647D+001,cb=.8D-002,cm=.929D+001)
! 
      vcmax25=yrsmn
!
!yrsmn*(.217D+003/.90D+002)! this ratio exists from preset values from the field (well-fertilized soybeans, grapes)
!
      zjmax0=vcmax25*.24111D+001   !(.217D+003/.90D+002) ! this ratio exists from preset values from the field (well-fertilized soybeans, grapes)
      t0c=t_enviro_mean-.27315D+003  ! rdp 22 july 2014: this was set to 25..hence the lack of T-related variations in photosynthetic uptake!!!
!		.25D+002 !....t0c is a reference temperature only; is NOT a phys parameter 9/22/2008 RDP
      theta0=theta
      pi=.3141592654D+001
      power3=.1D+001/.3D+001
      ca=caq
!......................................................................
!  leaf temperature dependencies
!......................................................................
      dtl=(tlc-t0c)
      xxx=tlc-.1D+002
      dtl1=dtl
      t0k=t0c+tck
      tlk=tlc+tck
! 
      rd=-.1D-005*respl ! input respiration rate w/ sign reversal to fit convention
      dtl=tlc-t0c
      vcmax=vcmax25*(.1D+001+.505D-001*dtl- &
        .248D-003*dtl*dtl-.809D-004*dtl*dtl*dtl)

      if(tlk.le..28315D+003)then! use the Falge et al (1996, 2005) adjustments
!	vcmax=vcmax25*(EXP(xb7*(xb12-xb8)/(xb9*xb12*xb8))* &
! 	((.1D+001+EXP((xb10*xb8-xb11)/(xb9*xb8)))))) / &
!	(.1D+001+EXP((xb10*xb12-xb11)/(xb9*xb12)))
! where...
! xb7=delHa=200000 (J mol-1)
! xb8=Tref=298.15 (K)
! xb9=Rgas=8.31 (J mol-1 K-1) 
! xb10=delS=655 (J mol-1 K-1)
! xb11=delHd=200000 (J mol-1)
! xb12=tl(K)=any (K)
!
	xb7=.2D+006
	xb8=.29815D+003
	xb9=.831D+002
	xb10=.655D+003
	xb11=.2D+006
	xb12=tlk
!
	xxb=xb7*(xb12-xb8)/(xb9*xb12*xb8)
	xyb=(xb10*xb8-xb11)/(xb9*xb8)
	xzb=(xb10*xb12-xb11)/(xb9*xb12)

!	vcmax=vcmax25*((EXP(xb7*(xb12-xb8)/(xb9*xb12*xb8))*
!	((1+EXP((xb10*xb8-xb11)/(xb9*xb8))))))/
!	(1+EXP((xb10*xb12-xb11)/(xb9*xb12)))

	vcmax=vcmax25*EXP(xxb)*(.1D+001+EXP(xyb))/(.1D+001+EXP(xzb))

      endif

      kc=kc25*exp(ekc/(rgas*t0k)*(.1D+001-t0k/tlk))
      ko=ko25*exp(eko/(rgas*t0k)*(.1D+001-t0k/tlk))
      call protect(kc,.1D-014)
      call protect(ko,.1D-014)
      gamma=gamma25*(.1D+001+.4206D-001*dtl+.805D-003*dtl*dtl)
      jmax=zjmax0*exp(ejmax/(rgas*t0k)*(.1D+001-t0k/tlk)) &
     	   /(.1D+001+exp((sjmax-hjmax/tlk)/rgas))
!......................................................................
!  when par=0, ag=0 and an=-rd
!......................................................................
      pfd=par*cpfd
      if(pfd.eq..0D+000) then
	an=.0D+000
	goto 100
      endif
!......................................................................
!  convert [umol] into [mol]
!......................................................................
      vcmax=vcmax*.1D-005
      kc=kc*.1D-005
      ko=ko*.1D-005
      gamma=gamma*.1D-005
!......................................................................
!  solve for ar
!......................................................................
      aa=vcmax
      dd=gamma
      ee=.1D+001
      bb=kc*(.1D+001+oi/ko)
      acan=dwdc+cb/gb-cm*rhs
      call protect(acan,.1D-024)
      bcan=ca*(gb*cm*rhs-.2D+001*cb-gb*dwdc)
      gcan=ca*ca*cb*gb
      tcan=gb*cm*rhs-cb
!......................................................................
!  can3*an^3+can2*an^2+can1*an+can0=0, where an=ar-rd
!......................................................................
      can3=ee*acan
      call protect(can3,.1D-024)
      can2=ee*(bcan+acan*rd)+bb*tcan-aa*acan
      can1=gcan*(ee+bb/ca)+bcan*(ee*rd-aa)+tcan*(aa*dd+bb*rd)
      can0=gcan*(ee*rd-aa+(aa*dd+bb*rd)/ca)
!......................................................................
!  x^3+bbb*x^2+ccc*x+ddd=0, where x=an=ar-rd
!......................................................................
      bbb=can2/can3
      ccc=can1/can3
      ddd=can0/can3
!......................................................................
!  z^3+ppp*z+qqq=0, where x=z-bbb/3
!......................................................................
      ppp=(bbb*bbb/.9D+001-ccc/.3D+001)
      qqq=(ddd-bbb*ccc/.3D+001+.2D+001*bbb*bbb*bbb/.27D+002)
      ppp=abs(ppp)
      rrr=ppp**.15D+001
      rrr=max(rrr,.1D-019)
      qqn=.1D+001
      if(qqq.lt..0D+000)qqn=-.1D+001
      xyz=qqn*qqq/(.2D+001*rrr)
      xyz=min(xyz,.1D+001)
      xyz=max(xyz,-.1D+001)
      ttt=acos(xyz)+.4D+001*pi
      ar=.2D+001*rrr**power3*cos(ttt/.3D+001)-bbb/.3D+001
      ar=ar+rd
!......................................................................
!  aj*j^2+bj*j+cj=0
!......................................................................
      aj=theta
      bj=-pfd*iqe-jmax
      cj=pfd*iqe*jmax
      delta=bj*bj-.4D+001*aj*cj
      call protect(aj,.1D-014)
      j=(-bj-sqrt(delta))/(.2D+001*aj)
      j=j*.1D-005
!......................................................................
!  solve for ae
!......................................................................
      aa=j
      dd=gamma
      ee=.45D+001
      bb=.105D+002*gamma
      acan=dwdc+cb/gb-cm*rhs
      call protect(acan,.1D-014)
      bcan=ca*(gb*cm*rhs-.2D+001*cb-gb*dwdc)
      gcan=ca*ca*cb*gb
      tcan=gb*cm*rhs-cb
!......................................................................
!  can3*an^3+can2*an^2+can1*an+can0=0, where an=ae-rd
!......................................................................
      can3=ee*acan
      can2=ee*(bcan+acan*rd)+bb*tcan-aa*acan
      can1=gcan*(ee+bb/ca)+bcan*(ee*rd-aa)+tcan*(aa*dd+bb*rd)
      can0=gcan*(ee*rd-aa+(aa*dd+bb*rd)/ca)
      call protect(can3,.1D-014)
!......................................................................
!  x^3+bbb*x^2+ccc*x+ddd=0, where x=an=ae-rd
!......................................................................
      bbb=can2/can3
      ccc=can1/can3
      ddd=can0/can3
!......................................................................
!  z^3+ppp*z+qqq=0, where x=z-bbb/3
!......................................................................
      ppp=(bbb*bbb/.9D+001-ccc/.3D+001)
      qqq=ddd-bbb*ccc/.3D+001+.2D+001*bbb*bbb*bbb/.27D+002
      ppp=abs(ppp)
      rrr=ppp**.15D+001
      rrr=max(rrr,.1D-019)
      qqn=.1D+001
      if(qqq.lt..0D+000)qqn=-.1D+001
      xyz=qqn*qqq/(.2D+001*rrr)
      xyz=min(xyz,.1D+001)
      xyz=max(xyz,-1.1D+001)
      ttt=acos(xyz)+.4D+001*pi
      ae=.2D+001*rrr**power3*cos(ttt/.3D+001)-bbb/.3D+001
      ae=ae+rd
!......................................................................
!  ag=min(ar,ae) and an=ag-rd
!......................................................................
      if(ae.ge.ar) then
	ag=ar
      else
	ag=ae
      endif
      ag=max(ag,.0D+000)
      an=ag-rd 
      photosynth=-ag
 100  continue
      return
	END SUBROUTINE
!
!!!!!!!!!!!!!!!!!!! /-\ < /-\ S /-\ !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
!
      subroutine conduct(gsw,an,qax,qsm,caq,caq1,gb,gsw1a)
!......................................................................
!  ball-berry leaf stomatal conductance model is adopted here.
!......................................................................
!  list of variables in subroutine conductance
!    cm - slope of ball-berry linear gsw empirical formula (unitless)
!    cb - intercept of ball-berry linear gsw empirical formula [mol.m-2.s-1]
!    wa - mole fraction water vapor in ambient air [mol.mol-1]
!    wi - intercelluar mole fraction water vapor (saturated) [mol.mol-1]
!    wawi = wa/wi = qa/qs, which is used instead of wa and wi
!    qa - specific humidity in ambient air [kg.kg-1]
!    qs - saturated specific humidity at leaf temperature [kg.kg-1]
!    gb - boundary layer conductance [mol.m-2.s-1]
!    gsw - stomatal conductance to water vapor [mol.m-2.s-1]
!    an - net co2 assimilation rate [mol.m-2.s-1]
!    ca - mole fraction co2 in ambient air [mol.mol-1]
!    agsw, bgsw, cgsw - coefficients of quadratic equation of gsw
!......................................................................
      implicit none
      DOUBLE PRECISION gsw,an,qax,qsm,caq,gb,cb,cm,qa,qs
      DOUBLE PRECISION ca,wawi,agsw,bgsw,cgsw,delta,ca1,caq1,gsw1a

      parameter(cb=.8D-002)
      cm=.929D+001
      qa=qax
      qs=qsm
      ca=caq
      ca1=caq
      if(an.lt..0D+000) then
	gsw=cb
	goto 10
      endif
      wawi=qa/qs
      agsw=ca1-an/gb! ca up agsw up
      bgsw=agsw*(gb-cb)-cm*an ! 
      cgsw=-(cm*an*wawi+cb*agsw)*gb! goes neg as ca up
      if(agsw.le..0D+000) then
	gsw=cb
	goto 10
      endif
      delta=bgsw*bgsw-.4D+001*agsw*cgsw
      if(delta.lt..0D+000) then
	gsw=cb
	goto 10
      endif
!     
      gsw=(((-bgsw+sqrt(delta))/(.2D+001*agsw)))
      gsw1a=gsw
 10   return
!
	END SUBROUTINE
!
!!!!!!!!!!!!!!!!!!! /-\ < /-\ S /-\ !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
!
        subroutine deriv3(omw,wet,df,f,gg,n)
        implicit none
        integer n,i
        double precision df(n),f(n),gg(n),omw,wet
!
!       "centered difference method" 1st-order differentiation. 
!       upper b.c. uses 'backward one-step' differentiation.
!       this algorithm must be at least as old as the abacus.
!
!
         df(1)=.0D+000
         do i=2,n-1
! RDP 17 December 2015:  allows integration for when gg(i) =/= gg(i+1), etc.
          df(i)=(f(i+1)-f(i-1))/(gg(i+1)+gg(i-1)) ! nixed "2*gg(i")
         enddo
         i=n
         df(i)=(f(i)-f(i-1))/(gg(i))
!
        return
        end SUBROUTINE deriv3
!
!!!!!!!!!!!!!!!!!!! /-\ < /-\ S /-\ !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
!
        subroutine deriv4(omw,wet,df,f,gg,n)
        implicit none
        integer n,i
        double precision df(n),f(n),gg(n),omw,wet
!
!       "forward" difference method. 
!       this algorithm is really ancient.
!
        i=1
        df(i)=.0D+000
        do i=2,n
! RDP 17 December 2015:  major typo here eliminated: 1/dz = 1/gg(i) was missing! 
         df(i)=omw*df(i)+wet*(f(i)-f(i-1))/gg(i)	
        enddo
!
        return
        end SUBROUTINE deriv4
!
!!!!!!!!!!!!!!!!!!! /-\ < /-\ S /-\ !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
!
        subroutine protect(x,s)
        implicit none
        DOUBLE PRECISION x,s
!
! make sure x doesnt get closer than s to 0.
!
	if(x.lt..0D+000.and.x.gt.-s)x=-s
	if(x.ge..0D+000.and.x.lt.s)x=s

	return
	END SUBROUTINE
!
!!!!!!!!!!!!!!!!!!! /-\ < /-\ S /-\ !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
!
        subroutine protecta(x,s)
        implicit none
        DOUBLE PRECISION x,s
!
! make sure x doesnt get closer than s to 0.
!
	if(x.lt..0D+000.and.x.gt.-s)x=x-s
	if(x.ge..0D+000.and.x.lt.s)x=x+s

	return
	END SUBROUTINE
!
!!!!!!!!!!!!!!!!!!! /-\ < /-\ S /-\ !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
