! subroutine satv
!
      	sb=.567D-007
      	cp=.10046685D+004
	sb1=(sb)
	cp1=(cp)
	em1=(em)
!
! coeff for satv(T)
!
	eee=(ee)
	tazz=(ta)
	ra1=(ra)
	rs1=(rs)
	pres1=(pres)
	rns1=(rns)
	rnl1=(rnl)
	stor1=(store)
! KC change  AKHA = .0D+000 to  AKHA = Tair
        AKHA = .0D+000
!        AKHA = ta+.27315D+003
        AKHS = AKHA*AKHA
        tax1=(tazz+.27315D+003)

        ik=max(int(tax1-.17315D+003)+1,1)
        ik=min(ik,200)

        ama = ama8(ik)
        sa = sa8(ik)
        tha = tha8(ik)
        aaa = aaa8(ik)
        za = za8(ik)
!
      	TSE = .2D+001*sb1*em1
        VSE = TSE
        EA = EEE*pres1/.622D+000
        GAM = cp*.101325D+006/(.622D+000*.4187D+004*(.595D+003-.567D+000*tazz))
        rho1=pres1/(.28704D+003*((tazz+.27315D+003)*(.1D+001+.6D+000*eee)))
        rho=(rho1)
! 
	ts=.0D+000
        HTAE = .2D+001*rho1*cp/ra1
        HE = .2D+001*rho1*cp/(GAM*(ra1+rs1))
        AKA = TSE+HE*AMA
        AA = (.4D+001*TSE*AKHA + SA*HE)/AKA
        BA = (.6D+001*TSE*AKHS + THA*HE)/AKA
        CA = (.4D+001*TSE*AKHS*AKHA + AAA*HE +HTAE)/AKA
        DA =(-rns1-rnl1+stor1+TSE*AKHS*AKHS+HE* &
          ZA-HE*EA-HTAE*(tazz+.27315D+003))/AKA
         call ATEX1(ts,AA,BA,CA,DA)
! KC 092313, test the temperature solution
!         xxx=.0D+000
!         call satv(xxx,ta)
!         call slav(ta,yyy)
! linear temperature solution
!        ts = ((rns1+rnl1-stor1-HE*(xxx-EA)-sb1*((ta+.27315D+003)**4))/(HTAE+HE*(yyy)+4*sb1*((ta+.27315D+003)**3)))+(ta+.27315D+003)
! constant temperature difference from ATEX1
	ts=ts-.27315D+003
! KC 092313, set the temperature range from ta-15<ts<ta+15 to ta-3<ts<ta+3
	if(ts.lt.ta-.15D+002)ts=ta-.15D+002
	if(ts.gt.ta+.15D+002)ts=ta+.15D+002
!       if((rns1+rnl1).le.0.000 .and. ts.lt.ta-.1D+001)ts=ta-.1D+001
!       if((rns1+rnl1).le.0.000 .and. ts.gt.ta+.1D+001)ts=ta+.1D+001
!       if(ts.lt.ta-.5D+001)ts=ta-.5D+001
!       if(ts.gt.ta+.5D+001)ts=ta+.5D+001
	return
      end subroutine
