! 
! subroutine surfacet1
!	
        tax1=(tax+.27315D+003)
        taxs = tax1*tax1

        ik=max(int(tax1-.17315D+003)+1,1)
        ik=min(ik,200)
!
        ama1 = ama8(ik)
        sa1 = sa8(ik)
        tha1 = tha8(ik)
        aaa1 = aaa8(ik)
        za1 = za8(ik)
        xsatv=(za1+aaa1*tax1+tha1*taxs+sa1*taxs*tax1 &
         +ama1*taxs*taxs)

      return
      end subroutine
!
!!!!!!!!!!!!!!!!!!! /-\ < /-\ S /-\ !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
!
!
      subroutine atex1(atex2,aa,ba,ca,da)
!
!...computes surface temperature given all this energy coming and going
!
      implicit none
      DOUBLE PRECISION xx,xxx,ts,atex0,zzz,atex2
      double precision aa,ba,ca,da
      double precision pow,al,bl,cac,dum,ac,bc,y,rz,r,e

      pow = .1D+001/.3D+001
      al = aa*ca -.4D+001*da -ba*ba/.3D+001
      bl = -.2D+001*ba*ba*ba/.27D+002+ba*(aa*ca &
         -.4D+001*da)/.3D+001-aa*aa*da+.4D+001*ba*da-ca*ca
      cac = abs((bl*bl*.25D+000 + al*al*al/.27D+002))
      dum = sqrt(cac)
      ac = -.5D+000*bl + dum
      xx=ac/(.1D-029+abs(ac))
      ac=xx*(abs(ac)**pow)
      bc = -.5D+000*bl - dum
      xx=bc/(.1D-029+abs(bc))
      bc=xx*(abs(bc)**pow)
      y = ac + bc + ba/.3D+001
      rz = abs((aa*aa*.25D+000 - ba + y))
      r = sqrt(rz)
      call protect1(r,.1D-021)
      e = abs((.75D+000*aa*aa-rz-.2D+001* &
          ba-(.4D+001*aa*ba-.8D+001*ca-aa*aa*aa)/(.4D+001*r)))
      e = sqrt(e)
! KC 092313, test the atex solution, comment the following line
      atex2 = (.5D+000*((e)-.5D+000*(aa)-(r)))
! T=T+2
!      atex2 = atex2+.2D+001
! KC end
!
      return
        END SUBROUTINE
!
!!!!!!!!!!!!!!!!!!! /-\ < /-\ S /-\ !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
!
        subroutine smth(arr,n)

        implicit none
        integer n,i
        DOUBLE PRECISION arr(n),arr1(n)
!
! mild smoothing (quasi-gaussian)
!                                x(i-1):x(i):x(i+1)
!                                  19  : 62 : 19
        do i=1,n
         arr1(i)=.0D+000
        enddo
!        arr(n)=arr(n-1)
        arr1(n)=arr(n)
        arr1(1)=arr(1)
        do i=2,n-1      !       apply gaussian smoothing filter
         arr1(i)=.620D+000*arr(i)+.190D+000*arr(i-1)+.190D+000*arr(i+1)
        enddo
        do i=2,n
         arr(i)=arr1(i)
        enddo
!
        return
        END SUBROUTINE
!
!!!!!!!!!!!!!!!!!!! /-\ < /-\ S /-\ !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
!
	subroutine znowpack(deltat1,nsnow,iisnow,rain1,tacasa1,tacasa2,surface_energy,wq1,tsoiltop,zsoil2,rhcs,  &
         zs1_snow,snowdepth,rhosnow,tsnow,snowater,storexsnow,smelt,snoh1a)
!
! DOES ACCUMULATION, DENSITY & PHASE-CHANGE THERMODYNAMICS BEFORE SNOWPACK(S) ARE SUBMITTED TO CALLS TO SOIL123 & TQCAN FOR
! THERMAQL DIFFUSION & HYDROLOGICAL TRANSPORT. THESE CALCULATIONS ARE FROM NOAHLSM SNOWPACK CALCULATIONS
!
! ORIGINAL CODE CORE IS FROM SMIRNOVA, ET AL (2000) , SCHLOSSER ET AL (2000,2001) SUBROUTINE SOILSNOW IN NOAHLSM.
! BUT NOW HAS BEEN GENERALIZED (RDP JUNE 2015) FOR ANY NUMBER OF SNOW LAYERS & REPRODUCIBLE FOR SEPARATE SNOWPACKS ON GROUND, THE CANOPIY, OR ON ROOFTPOPS.
! updates snowpack depth, density (averages) and temperature column (array of length nsnaow) (maximum number of active snow layers)
! 
! INPUTS 
!
! INPUT	deltat1			time step length(s)
! INPUT	nsnow			number of snow layers (total memory allocation) 	(-)
! INPUT	rain1			precip rate 						(kg(h2o) s-1)
! INPUT	tacasa1			skin temperature of surface 				(K)
! INPUT	tacasa2			temperature of infalling snow/ice 			(K)
! INPUT	surface_energy 		total energy balance at surface (nonconductive)		(Wm-2)
! INPUT/OUTPUT	tsoiltop	soil surface temperature (when underneath snow, use for lower b.c. & update value by bootystrapping the interface)		
! INPUT	zsoil2			depth of 1st interior soil layer (-m)
! INPUT		rhosnow		snowpack density (z)					(kg m-3)
! INPUT		rhocs		soil heat capacity (uppermost layer)			J kg K-1
!
! INPUT/OUTPUT: THESE REQUIRE INITIALIZATION OUTSIDE OF SUBROUTINE CALL; VALUES BOTH STORED & UPDATED FOR FURTHER USE BETWEEN TIMESTEPS
!
! INPUT/OUTPUT	zs1_snow	snow layer depths 					(-m)
! INPUT/OUTPUT  snowdepth	snowpack depth						(m)
! INPUT/OUTPUT	tsnow		snowpack temperature (includes upper and lower b.c.'s)	(K)
! INPUT/OUTPUT	snowater	total snow water equivalent				(m)
! INPUT/OUTPUT	storex_snow   	"G" (conductive heat flux density) snow-air interface	(Wm-2)
!
! OUTPUT: ONLY NEEDED FOR DIAGNOSTIC OUTPUT (ENERGY BALANCE CALCULATIONS)
!
! OUTPUT	smelt		amount of meltwater available to soil column		(kg m-2 s-1)
! OUTPUT	snoh,snoh1a   	snowpack omnibus energy flux density (S_snow = s_conduction + s_fusion + s_precip + etc.)
!
! calculates snowpack growth &/or decay due to precip &/or melting.
! sets up temperature array for thermal diffusion via SOIL123A(...) but adjusted for: lower b.c. = uppermost soil T
! upper b.c. is the snowpack skin temperature (tacASA1) WHEN NO NEWSNOW, =TACASA2 WHEN SNOW IS FALLING.
!
        implicit none
         INTEGER KK,nsnow,ll,jj,llq,iisnow
         double precision xxx,yyy,array(nsnow),array_1(nsnow),epdt, &
	  tacasa1,tacasa2,rhonewsnow,newsnow,deltat1,rhonewsn, &
	  wq1,soilhf,surface_energy,xfreeze,tsnav,rsm,tsoiltop,rhcs, &
          zsoil2,rhocsn,snohgnew,snowdepth_new,snowdepth_old,snowdepth1
!
! rdpyles 17 june 2015: new snowpack calculations.
! snowpack accumulation, density, and adjustment of snow column to accomodate new snow.
! also calculation of bottom-layer storage & phase-change heat fluxes
! based on the theoretical core of NOAHLSM but now is adapted to snowpack pixels within and beneath canopy
! also note usage of SOIL123A(...) for snowpack as well
!cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
! inside loo, to b edone when snowater > 0.001 m.
!
         double precision zs19_snow,rain1(3),cvw,snowater1
         double precision rhosnow,tsnow(nsnow),zs1_snow(nsnow)
         double precision snowater,snowdepth,storexsnow,SNOH,SNOH1a,SMELTG,SMELT,SMELTz,SNOHG,SNODIF
!
! initialize snow arrays
!
           SNOH=.0D+000
           SNOH1a=.0D+000
           SMELTG=.0D+000
           SMELT=.0D+000
           SNOHG=.0D+000
           SNODIF=.0D+000
!
!	now that the latest estimates of snowdepth are done,, 
!       set up snowpack vertical grids & calculate old and fresh snow density (t > -15 C, else min value)
!       (eqn. 10 from Koren et al. (1999).
!
! note: this is to get the ball rolling...will be adjusted after snowpack is updated...
        zs19_snow=.5D-001						! default snow layer depths = 0.05 m.
        iisnow=1							! 0 snow layers (default)
!        xxx=dble(float(nsnow-1))*zs19_snow
        xxx=dble(float(iisnow-1))*zs19_snow
	if(zs19_snow.le.snowdepth.and.snowdepth.le.xxx)then		! snow is between 0.05 and (nsoil-1)*.05 (here, 0.5 m) depth
         iisnow=1+min(int(real(snowdepth/zs19_snow)),nsnow)		! the number of active snow layers, each of which are zs19_snow thick
        endif
        xxx=zs19_snow*dble(float(nsnow-1))				! structurally: "really deep snow" = when it is more than (nsoil-1)*zs19_snow
	if(snowdepth.gt.xxx)then
         zs19_snow=snowdepth/dble(float(nsnow-1))			! width of active snow layers when snow is "really deep"
         iisnow=nsnow							! "really deep"
        endif
!
        do kk=1,nsnow							! snow layer depth array for when snow is moderately deep
         zs1_snow(kk)=-zs19_snow*dble(float(kk-1))			! set up the -z array
        enddo
!
! snow layers default to 1 for really shallow snow; dz assumed = 0.05 even though the layer might be very thin.  will address this -rdp
        if(snowater.ge..1D-003.and.snowdepth.le..5D-001)iisnow=2	! "really shallow snow"
        if(snowater.lt..1D-003)iisnow=2				! "no snow."
        iisnow=max(iisnow,2)		
! 
! do new snow accumulations
!        
         snowdepth_old = snowdepth 		! old snowepack depth (m)
         snowdepth_new=.0D+000			! set newsnow depth to 0 by default
	 snowdepth1=snowdepth			! alias
!
         if(snowdepth.gt..0D+000)rhosnow = .1D+004*snowater/snowdepth 
!
         IF(rain1(2)+rain1(3).gt..0D+000)THEN 				!say "freshsnow". "shsn".  lizzid. frozen precip is happening!
! density of falling snow is based on the same temperature function (Koren et al 1999):
! nota! mednow/mudnow...it's just like '82-'83 but weirder!
          xxx = .1D+004*(.5D-001+.17D-002*(tacasa2- .273150D+003 + .15D+002)**.150D+001)
          xxx=min(xxx,.45D+003)
          xxx=max(xxx,.5D+002)
          rhonewsnow=xxx	! assume that all new snow falling per timestep is at const. temperature (= t(n), input value)
!
! get newsnow and total snow water estimate (=last timestep's value + newsnow)
          NEWSNOW=(rain1(2)+rain1(3))*deltat1 	! amount of new (fresh) snow that is falling currently
          snowater = snowater + newsnow		! add newsnow to total snow water equivalent (pre- undermining or surface melt) (m)
          snowdepth_new =newsnow*(.1D+004/rhonewsnow) ! depth of new snow (m)
          rhosnow=(rhosnow*snowdepth_new + rhonewsnow*snowdepth)/(snowdepth_new+snowdepth) ! calculate new snowpack density (average)
!take tsnow(kk), rhosnow(kk), and zs1_snow(kk)  and adjust each to reflect the presence of new snow layers.  this is a bit of a trick ;)
!
!          do kk=1,nsnow
          do kk=1,iisnow
           array(kk)=tsnow(kk)						! temporary storage array for tsnow
           array_1(kk)=rhosnow					! temporary storage array for tsnow
          enddo
          if(iisnow.lt.nsnow)then		! fill in 'blank' snow layers 
           do kk=iisnow+1,nsnow
            array(kk)=tsnow(iisnow)						! temporary storage array for tsnow
            array_1(kk)=rhosnow					! temporary storage array for tsnow
           enddo
          endif

! recaulculate zs1_snow etc. here before melt is figured in.
!
          snowdepth1=snowdepth_old+snowdepth_new
          zs19_snow=.5D-001						! default snow layer depths = 0.05 m.
          iisnow=0							! 0 snow layers (default)
          xxx=dble(float(nsnow-1))*zs19_snow
  	  if(zs19_snow.le.snowdepth1.and.snowdepth1.le.xxx)then		! snow is between 0.05 and (nsoil-1)*.05 (here, 0.5 m) depth
           iisnow=1+min(int(real(snowdepth/zs19_snow)),nsnow)		! the number of active snow layers, each of which are zs19_snow thick
          endif
          xxx=zs19_snow*dble(float(nsnow-1))				! structurally: "really deep snow" = when it is more than (nsoil-1)*zs19_snow
	  if(snowdepth.gt.xxx)then					! the snow is "really deep"
           zs19_snow=snowdepth1/dble(float(nsnow-1))			! width of active snow layers when snow is "really deep"
           iisnow=nsnow !-1
          endif
!
         do kk=1,nsnow							! snow layer depth array for when snow is moderately deep
           zs1_snow(kk)=-zs19_snow*dble(float(kk-1))			! set up the -z array
          enddo
!
! snow layers default to 1 for really shallow snow; dz assumed = 0.05 even though the layer might be very thin.  will address this -rdp
          if(snowater.ge..1D-003.and.snowdepth1.le..5D-001)iisnow=1	! "really shallow snow"
          if(snowater.lt..1D-003)iisnow=1				! "no snow."
          iisnow=max(iisnow,2) 
         ENDIF					! end new snow situation
!
! udate snowdepth
!fuuck
!         if(snowdepth_new.eq..0D+000.and.snowdepth1.gt.snowdepth_old)then       
!          snowdepth=snowdepth_old
!         else
!          snowdepth=snowdepth1
!         endif
!
! the temperature changed such that the formula for determining snowpack depth is degenerate.
! don't make snowpack any fluffier if it just gets colder thgan last time.
! if its ~ melting, make it denser until max density is reached.
!
!  check if all snow can evaporate during DT
         EPDT = .1D-002*wq1*DELTAT1 			! total surface evaporation (sublimation)
         IF(snowater.LT.EPDT)THEN
           snowater=.0D+000
           snowdepth=.0D+000
         Endif
! "soh" => "storex_snow" snow surface heat flux density
!	this is the G_snow_total; includes:      
!
! 		1) air-to-surface flux density Wm-2
! 		2) newsnow flux dens. Wm-2
! 		3) change in internal heat (thermal) flux dens Wm-2
! 		4) rain-introduced energy flux dens. Wm-2; 
!
!-- SNOH is energy flux of snow phase change(melt only)
!
        cvw = .4186D+007                   ! CVW -  water specific heat capacity (J Mg-1 K-1)
        SNOH=max(.0D+000,surface_energy  &
        + .209D+004*NEWSNOW/DELTAT1*(min(tacasa2-.273150D+003,.0D+000)) &	
        -storexsnow &							
        +CVW*.10D-002*rain1(1)*(tacasa2-.273150D+003)) 			         
!										 
!-- SNOH1a is energy flux of snow phase change (all)
!
        SNOH1a=surface_energy & 	
        +.209D+004*NEWSNOW/DELTAT1*(tacasa2-.273150D+003) &			
        -storexsnow &							
        +CVW*.10D-002*rain1(1)*(tacasa2-.273150D+003) 				
!
! smelt, smeltz = mass flux from melting (actual and potential)		
!
        SMELT= .1D-002*SNOH/.3335D+006
        SMELTz= .1D-002*SNOH1a/.3335D+006
!
! snowpack water refreezing section...
!
! from Koren et al. (1999) 13% of snow melt stays in snow pack
! multiply this concept with xfreeze, the fraction of existing 
! water that can freeze which can vary depending upon 
! thermodynamic state of the snowpack.  (by extension the 87% leftover 
! meltwater goes out of snowpack before refreezing takes place
! and ends up as runoff and/or soil water &/or ice
!
        xfreeze=.0D+000   						! xfreeze = fraction snowpack water that can refreeze
	xxx=.0D+000
	yyy=.0D+000
        if(smelt.gt..0D+000)then					! melt!
         xxx=.10D+004*.130D+000*smelt*.3335D+006*deltat1 +.1D-009	! Korens 13% rule
! tsnav = t_average_snowpck)
         yyy=min(tsnav-.273150D+003,.0D+000)*.2090D+004*snowater ! refreezing fraction if snowpack goes cool
         xfreeze=abs(yyy/xxx)
        endif
        xfreeze=min(xfreeze,.1D+001)					! cant do more than 100%
        xfreeze=max(xfreeze,.0D+000)					! no less than zero
        rsm=xfreeze*smelt*deltat1					! reverse (< 0) snow melt amount
        smelt=smelt-rsm/deltat1						! adjust snow melt rate (it can go to 0!)!	
	smeltz=smeltz-rsm/deltat1
	snoh1a=SMELTz*.3335D+006*.10D+004				!(fusion) heat flux density
!
! surface component is done...
! now adjust snow water equivalent due to above melt rate plus evaporation
!
        snowater1=snowater - SMELT*DELTAT1       
        snowater=max(snowater1,.0D+000)
!
        if(snowater.lT..1D-003)then
         smelt=smelt+rsm/deltat1
         rsm=.0D+000! no refreezing back into snow possible if all snow melts...
        endif
!
!        xxx=.333D+000 ! assume when snow is melting, that the density is 0.333 Mg m-3
!
!        if(smelt.gt..0D+000)then
!          snowdepth= snowdepth - smelt*deltat1/.333D+000  ! surface melt loss from snowpack height...
!          rhosnow=.33D+003	! kg m-3
!        endif
!
!--  Snow melt from the top is done. But if ground surface temperature is above freezing snow can melt from the bottom. The following
!--  piece of code will check if bottom melting is possible.
! tsoiltop = lower boundary conduition for snowpack temperature 
! zsoil2 is the depth of the 1st soil layer (beneath snowpack) 
! rhocsn = rhosnow(bottom-layer)*.209D+004*.1D-002  				! (rho*cp)_snow (kJ kg-1 K-1)
        
        RHOCSN=.209D+004*.1D-002*rhosnow		
!	it's definition here corresponds to the snowpack layer closest to the soil surface; OK
        IF(tsoiltop.GE..273150D+003.AND.snowater.gT..1D-003) THEN		! undermining of snowpack can proceed. use soil temperatures...
         SNOHG=(tsoiltop-.273150D+003)*(RHCS*zsoil2*.5D+000 + RHOCSN*.50D+000*zs19_snow)/DELTAT1  ! snow-ground heat flux dens (Wm-2)
         SMELTG=SNOHG/.3335D+006*.1D-002					! soil/substrate's contrubution to snow melt mass flux (*meters* of h2o)(m-2 s-1)
         SMELTG=MIN(SMELTG,snowater/DELTAT1)					! can't do more than what's there
         if(smeltg.gt..0D+000)then
          rhosnow=.33D+003	! kg m-3
         endif

         SNOHGNEW=SMELTG*.3335D+006*.10D-002					! recalculate snow melt mass flux mass flux m m-2 s-1
         SNODIF=MAX(.0D+000,SNOHG-SNOHGNEW)					! remove 'excess flux' if melting exceeds snowpack mass 
         tsoiltop=SNODIF*DELTAT1/(RHCS*zsoil2+RHOCSN*.50D+000*zs19_snow)+.273150D+003	! new value of soil surface (skin) temperature 
         snowater = MAX(.0D+000,snowater-SMELTG*DELTAT1)				! update snow water equivalent (m)
         snowdepth=snowater*.1D+002/.1D+004 !nota.  until snow density calms down, use 1:10 ratio here.
!
!        if(snowater.gt..0D+000.and.snowater.lt..15D-002)snowdepth=.5D-001	! the 1.5 mm snowater, 5cm snowpack limit...
!        if(snowater.gt..0D+000.and.snowater.lt..15D-005)snowdepth=.5D-001	! the 1.5 mm snowater, 5cm snowpack limit...
        if(snowater.eq..0D+000)then						! the snowpack has disappeared; 
          snowdepth=.0D+000 !
          iisnow=2
          do kk=1,nsnow							! snow layer depth array for when snow is moderately deep
           zs1_snow(kk)=-zs19_snow*dble(float(kk-1))			! set up the -z array / so not = 0
          enddo
          return
        endif
!
         SMELT=SMELT+SMELTG							! adjust snow melt rate to TOTAL m m-2 s-1
         SNOH=SNOH+SNOHGNEW							! adjust snow phase change heat flux Wm-2
!
! final calculation of vertical grids and of the number of active snow layers.
!
         zs19_snow=.5D-001						! default snow layer depths = 0.05 m.
         iisnow=0							! 0 snow layers (default)
         xxx=dble(float(nsnow-1))*zs19_snow
	 if(zs19_snow.le.snowdepth.and.snowdepth.le.xxx)then		! snow is between 0.05 and (nsoil-1)*.05 (here, 0.5 m) depth
          iisnow=1+min(int(real(snowdepth/zs19_snow)),nsnow)		! the number of active snow layers, each of which are zs19_snow thick
         endif
         xxx=zs19_snow*dble(float(nsnow-1))				! structurally: "really deep snow" = when it is more than (nsoil-1)*zs19_snow
 	 if(snowdepth.gt.xxx)then
          zs19_snow=snowdepth/dble(float(nsnow-1))			! width of active snow layers when snow is "really deep"
          iisnow=nsnow							! "really deep"
         endif
         iisnow=max(iisnow,2)
!
         do kk=1,nsnow							! snow layer depth array for when snow is moderately deep
          zs1_snow(kk)=-zs19_snow*dble(float(kk-1))			! set up the -z array
         enddo

        ELSE
         SNOHG=.0D+000
         SMELTG=.0D+000
         SNOHGNEW=SMELTG
         SNODIF=.0D+000					! remove 'excess flux' if melting exceeds snowpack mass 
!         tsoiltop unchanged
!         snowater unchanged
!         SMELT unchanged
!         SNOH unchanged
        ENDIF

! RDP 7 January 2016: 
! snowdepth = garbage until we can get a good snow density calcualtion going.  
!c otherwise this is all garbly.  best to keep with 1:5 ratios until further notice .
          snowdepth=snowater*.5D+001*.1D-002			
        RETURN
!
        END SUBROUTINE ZNOWPACK
!
!!!!!!!!!!!!!!!!!!! /-\ < /-\ S /-\ !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
!
!
      subroutine bowen(wq,wt,dwq,dwt,rnswi11,rnlw,tstorep,n,inlyr,rho,gg,t,cp)
!
! RDP mayday 2012:  allow negative bowen ratios
! removed vestigial lines. only acts within canopies.
!
      implicit none
      integer n,inlyr,i,j,k,iq2
      double precision dwq(n),dwt(n),rnswi11(n),gg(n),xxx,t(n),wq(n),wt(n),yyy,zzz,ppp
      double precision rnlw(n),tstorep(n),rho(n),derr(n),derr0(n),cp,switch
      double precision drsw(n),dstore(n),drlw(n),dh(n),dle(n),fracas(n),fstacas(n)
!  KTPU ADDITION 130808
!
!      double precision dhrat,dlerat
!
!       end KTPU ADDITION 130808
        double precision bow
!
        do i=1,n
         drsw(i)=.0D+000
         drlw(i)=.0D+000
         dh(i)=.0D+000
         dle(i)=.0D+000
         dstore(i)=.0D+000
         derr(i)=.0D+000
         derr0(i)=.0D+000
        enddo
!
        drsw(1)=rnswi11(1)
        do i=2,inlyr+1
         drsw(i)=(rnswi11(i)-rnswi11(i-1))/gg(i)
        enddo
!
        drlw(1)=rnlw(1)
        do i=2,inlyr+1
         drlw(i)=(rnlw(i)-rnlw(i-1))/gg(i)
        enddo
!
        call deriv(dstore,tstorep,gg,n)
!
        drsw(1)=rnswi11(1)
        drlw(1)=rnlw(1)
        dstore(1)=tstorep(1)

        xxx=.0D+000
        dstore(1)=tstorep(1)
!
! RDP 2000s; jaunary 2013: restored the 'add-the-residual-in-using-bowen-ratio' method instead of partitioning all dAE/dz to the fractions
! canopy flux divergences in this manner ensure energy conservation as derr(i) is the trua avialable energy flux divergence
! doing it by way of addition to existing estimates are best because it will allow for more negative bowen ratio solutions for when energetics suggest it.
        do i=1,inlyr
         ppp=(.2491265D+007-.2374029D+004*t(i))
         if(t(i).lt..0D+000)ppp=ppp+.3345D+006
         dH(i)=dwt(i)*rho(i)*cp ! dH/dz
         dLE(i)=dwq(i)*rho(i)*ppp ! dLE/dz
         derr(i)=drsw(i)+drlw(i)-dstore(i)              ! derr(i)= total available energy flux density for sens, latent....
         derr0(i)=dH(i)+dLE(i)                          ! what dH and dLE add up to. derr and derr0 should converge.
! KC add convergence criteria for derr&derr0
         k=0
!         do while (abs(derr(i)-derr0(i)) .gt. 1.0D-001/gg(i))
      if((abs(dh(i))+abs(dle(i))) .gt. derr(i)) then
         if (i .ne. 1) then
            bow=abs(dH(i)*gg(i))/(abs(dle(i)*gg(i)))
           else
            bow=abs(dH(i))/(abs(dle(i)))
         endif
         bow=max(bow,.1D-001)! no less than .01% goes to H.
         bow=min(bow,.1D+003)! no more than 99.99% goes to H.
         xxx=bow/(.1D+001+bow)
         yyy=.1D+001/(.1D+001+bow)
         zzz=derr(i)
         dwt(i)=(xxx*zzz)/(rho(i)*cp)
         dwq(i)=(yyy*zzz)/(rho(i)*ppp)
       else
         do while (abs(derr(i)-derr0(i)) .gt. 0.1D-004)
         dH(i)=dwt(i)*rho(i)*cp ! dH/dz
         dLE(i)=dwq(i)*rho(i)*ppp ! dLE/dz
         derr0(i)=dH(i)+dLE(i)                          ! what dH and dLE add up to. derr and derr0 should converge.
      if (i .ne. 1) then
         bow=abs(dH(i)*gg(i))/(abs(dle(i)*gg(i)))
        else
         bow=abs(dH(i))/(abs(dle(i)))
      endif
         bow=max(bow,.1D-001)! no less than .01% goes to H.
         bow=min(bow,.1D+003)! no more than 99.99% goes to H.
         xxx=bow/(.1D+001+bow)
         yyy=.1D+001/(.1D+001+bow)

! apportioning to each dH(i)/dz and dLE(i)/dz in this manner is more numerically stable...and it comes with no b.s.
         zzz=derr(i)-derr0(i)
         dwt(i)=(dH(i) + xxx*zzz)/(rho(i)*cp)
         dwq(i)=(dLE(i) + yyy*zzz)/(rho(i)*ppp)
        k = k+1
      enddo
!KC 071814, set wt(1) & wq(1) into the balanced values
      endif
      enddo
      wt(1) = dwt(1)
      wq(1) = dwq(1)
! KC end


        return
        end subroutine

        subroutine deriv(df,f,gg,n)
        implicit none
        integer n,i
        double precision df(n),f(n),gg(n)

! uses centered difference

        do i=2,n-1
         df(i)=(f(i+1)-f(i-1))/(gg(i+1)+gg(i-1))
        enddo
!KC, modify node 1&n
!        df(1)=df(2)
!        df(n)=df(n-1)
         df(n)=(f(n)-f(n-1))/(gg(n))
         df(1)=(f(2)-f(1))/(gg(1))

        return
        end SUBROUTINE

        subroutine protect1(x,s)
!
! make sure x doesnt get closer than s to 0.
! use double precision
!
        implicit none
        double precision x,s
        if(x.lt..0D+000.and.x.gt.-s)x=-s
        if(x.ge..0D+000.and.x.lt.s)x=s

        return
        END SUBROUTINE
!
        subroutine lwradiation(t4s,rlwd,rlwu,emit,nlyr,xwgt2,xai,pai,stei,wai,rai, &
!        nsnow,n,in,ihi,inlyr,nsoil0,nstem,m,iminit,deltsn,zs1,rweight,lf11)
        nsnow,n,in,ihi,inlyr,nsoil0,nstem,lf11)
!
! passed-in (only used, not updated)
!
! t4s = thermal emission source (each layer) Wm-2
! id11a, mid11a = prob. diffuse penetration (from sw-radiation), 1-prob...
! emit = thermal emissivity Wm-2 K-4
!
! passed-in and updated
! rlwu = thermal lw up Wm-2
! rlwu = thermal lw down Wm-2
!
        implicit none
        integer nsnow,n,in,ihi,inlyr,nsoil0,nstem,m,iminit
        DOUBLE PRECISION deltsn,zs1(nsoil0),rweight(nsoil0)
!

        integer i,k,imm,nlyr

        DOUBLE PRECISION t4s(n),rlwd(n),rlwu(n),id11a(n)
        DOUBLE PRECISION mid11a(n),emit(n),yyy,xwgt2(n,10,8)
! local vbles (not passed

        integer j
!
        double precision alpha,zen,beta,kxm,zzz,xxx,theta,xxcc1,kxz,emissi7(nlyr)
        double precision kxdir(nlyr),lf11(9),x1(nlyr),pi,ar11a(nlyr)
        double precision tr11a(nlyr),pr11a(nlyr)
        double precision z1,z2,z3,xai,pai(n),stei(n,2),rai(n),wai(n)
!
!!!!!!!!!!!!!!!!!!!!! begin thermal longwave calculations !!!!!!!!!!!
! longwave flux section: recalculates using 2-stream greybody approx
! all diffuse using emissivities & spherical symmetry.
! emissiion fluxes included in transfer equations.
! iterates to solution within this bloc
!
        do i=1,nlyr
         x1(i)=.0D+000
         kxdir(i)=.0D+000
        enddo
        pi=dble(acos(-1.0))
!......................................................................
! computation of extinction coefficient. this works just like for SW radiation
! but with the reflectivities being 1-emissivity and the transmissivities 0;
!......................................................................
        alpha=.0D+000
        beta=pi/.36D+002
        kxm = .0D+000!
        do i=1,nlyr
         x1(i)=sin(alpha)*cos(alpha)
         kxdir(i)=.0D+000
         beta = pi/.36D+002
         do j=1,9
          if(alpha.ge.beta) then
           kxz = cos(beta)
          else
           xxcc1=1.
           call ton(xxcc1,beta)
           yyy=xxcc1
           call protect(yyy,.1D-009)
           call ton(xxcc1,alpha)
           xxx=max(xxcc1/yyy,-.1D+001)
           xxx=min(xxx,.1D+001)
           zzz=max(xxcc1/yyy,-.1D+001)
           zzz=min(zzz,.1D+001)
           theta = acos(zzz)
           call ton(xxcc1,alpha)
           kxz = cos(beta)*(.1D+001 + .63661D+000*(xxcc1-theta))
          endif
           kxdir(i)=kxdir(i)+kxz*lf11(j)
           beta = beta + pi/.18D+002
         enddo
         alpha=alpha+pi/.2D+002
        enddo
!......................................................................
! compute mean emissivity in each layer.
!......................................................................
        emissi7(1)=emit(1)
        do i=1,nlyr
         xxx=.0D+000
         do k=1,8
          do j=1,10
           xxx=xxx+emit(i)*xwgt2(i,j,k)
          enddo
         enddo
        emissi7(i)=xxx
        enddo
!......................................................................
! compute (diffuse)thermal  radiation penetration function (id(.) and a (r up/r down)
!......................................................................
        tr11a(1)=.0D+000
        pr11a(1)=.1D+001-emissi7(1)
        do i=2,nlyr
         tr11a(i)=.0D+000
         pr11a(i)=.1D+001-emissi7(i)
        enddo
!
        i=1
!
! rdp mc 15 april 2012 ...lower b.c. was not defined...oops!
! lower b.c.s for id, mid also needed to be moved here from down below to satisfy these equations.
!
        id11a(i)=.0D+000
        mid11a(i)=.1D+001
         ar11a(i)=id11a(i)+ pr11a(i)*mid11a(i)
        do i=2,nlyr
         id11a(i)=.0D+000
         z1=.0D+000
         k=1
         do j=1,5
            xxx=(stei(i,1)+stei(i,2)+pai(i)+rai(i)+wai(i))
            z2=exp(-xxx*kxdir(k+1))*x1(k+1)
            z3=exp(-xxx*kxdir(k+2))*x1(k+2)
            id11a(i)=id11a(i)+pi*(z1+.4D+001*z2+z3)/(.6D+002)
            z1=z3
            k=k+2
         enddo
         id11a(i)=id11a(i)*.2D+001
         if(xai.le..1D-003)id11a(i)=.1D+001
         id11a(i)=min(id11a(i),.1D+001)
         mid11a(i)=.1D+001 - id11a(i)
         ar11a(i)=ar11a(i-1)*(tr11a(i)*mid11a(i)+id11a(i))*(tr11a(i)*mid11a(i)+id11a(i))/ &
         (.1D+001 - ar11a(i-1)*pr11a(i)*mid11a(i))      + pr11a(i)*mid11a(i)
        enddo
!
!
        do k=nlyr-1, 1, -1
         rlwd(k)=rlwd(nlyr)             ! downward-longwave_radiation_flux_density(i)=sky_value initially.
        enddo
        rlwu(1)=t4s(1)                  ! = emiss*sigma*Tsss(i,j,k)**4 / updated with each master (turbulence) iteration
        do k=2, nlyr                    ! = upward-longwave_radiation_flux_density(i)=ground value intiially
         rlwu(k)=rlwu(1)
        enddo
!
! iterate this little squitty 'till we get numerical convergence; usually a few; so go 10.
!
! rlwd = downward thermal infrared flux density (Wm-2) at level k
! rlwd(k) = rlwd(k+1)*(noleaf(k+1))+ backreflec(k+1)*leaf(k+1) + emission(k+1)*leaf(k+1)
! rlwu = upward thermal infrared flux density (Wm-2) at level k
! rlwu(k) = rlwu(i-1)*noleaf(i)+ backreflec(i)*leaf(i) + emission(i)*leaf(i)
! assumed all is diffuse; use same probabilities for diffuse sw radiation & add thermal emissions & reflexions
!
        do imm=1,10
         do i=1,nlyr-1
          k = nlyr - i
          xxx=.1D+001-emissi7(i) ! garg emissi7
          rlwd(k)=rlwd(k+1)*(id11a(k+1))+t4s(k+1)*mid11a(k+1)
         enddo
         do i=2,nlyr
          xxx=.1D+001-emissi7(i)!garg emissi7
          rlwu(i)=rlwu(i-1)*id11a(i)+t4s(i)*mid11a(i)
         enddo
        enddo
!
! abovecanopy: nlyr+1 -> n
!
        do i=nlyr+1,n
         rlwu(i)=rlwu(nlyr)
         rlwd(i)=rlwd(nlyr)
        enddo
!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
!end thermal longwave calculations
!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
        return
        END SUBROUTINE lwradiation

        subroutine expand(arrs,arrl,ns,nl)
!
! expands a ns-layer array (arrs) into a nl-layer one (arrl).
!
        implicit none
! rdp 15 june 2012 reverse order of the following 2 lines...fortran semsntics...
        integer i,k,ns,nl
        double precision arrs(ns),arrl(nl)
!
        arrl(1)=arrs(1)
        arrl(nl)=arrs(ns)
        do i=2,nl
         k=2+int(float(i-1)/10.)
         arrl(i)=arrs(k)
        enddo
        return
        end subroutine expand
!!!!!!!!!!!!!!!!!!! /-\ < /-\ S /-\ !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!

        subroutine grnd1(h55,i55,j55,fgacas0,rnswf11, &
         tessa,sb,rlwd,rnswi11,emit,rlwu,rai,deltat1,e,ra,t,rain,rsl,rho, &
         wt,wq,pai,xlai,popdens,xlint,gg,dwq,i7ce,nlyr,iocean,isoi3, &
         xai,xstei,zmoi,xstei1,dwqs,xwgt,eosx,dwts,nsnow,n,in,ihi,inlyr,nsoil0,nstem, &
         m,iminit,deltsn,zs1,rweight,smcdry,smcref,psisat,bexp,dksat,smcmax, &
         XSNODEP,SOILT22,RUNOFF11,RUNOFF22,SNOWDENS,SNOWATER, &
         SNOWMELT,QSOIQ,TSOIQ,STOREX,SNOH,SMELT,SNOWMIP1,ssoil1,iisnow,etal,etaf,fracas,fsacas,flacas)

!......................................................................
! computes energy budget at ground surface
! and does soil/snow temps, moisture
!......................................................................
!
      implicit none
        integer h55,i55,j55,ido,idoo,iisnow
        integer nsnow,n,in,ihi,inlyr,nsoil0,nstem,m,iminit
        DOUBLE PRECISION deltsn,zs1(nsoil0),rweight(nsoil0),xxx,ssoil1
        REAL SMCDRY, SMCREF, PSISAT,BEXP,DKSAT, SMCMAX


        DOUBLE PRECISION tessa(n),sb,rlwd(n),rnswi11(n)
        DOUBLE PRECISION emit(n),rlwu(n),rai(n),deltat1,e(n)
      DOUBLE PRECISION ra(n,10,8),t(n),rain(3),rsl,rho(n),wt(n)
        DOUBLE PRECISION pai(n),xlai,xsnodep,rnswf11(n,9)
      DOUBLE PRECISION soilt22(nsnow),xstei
      DOUBLE PRECISION runoff11,runoff22,snowdens,popdens,xsnodep0
        DOUBLE PRECISION storex(n,10,8),yyy
      DOUBLE PRECISION snowater,snowmelt,xlint(n,10,8),gg(n),dwq(n)
        DOUBLE PRECISION snoh,smelt,snowmip1(100),dwqs(n,10,8)
        DOUBLE PRECISION xwgt(n,10,8)
        integer i7ce,nlyr,iocean,isoi3,k,i,j,lk
        DOUBLE PRECISION wq(n),qsoiq(nsoil0),tsoiq(nsoil0),xai,zmoi,xstei1
      DOUBLE PRECISION eosx(n,10,8),fgacas0
      DOUBLE PRECISION dwts(n,10,8)
!
! not passed
!
        DOUBLE PRECISION tk1,rlwu1,rnlw1,rndum1,potwq,pote1,wq1
        DOUBLE PRECISION tk2,rlwu2,rnlw2,tdelst,rain1(3),soilhf,epp
        DOUBLE PRECISION stdiam
        DOUBLE PRECISION etal(nsoil0),etaf(nsoil0),tdelt
        DOUBLE PRECISION fracas,fsacas,flacas
!
! begin thermal longwave partitioning
!
      tk1=tessa(1)+.27315D+003

      rlwu1=(emit(i55)*sb*(tk1)**.4D+001)
      rnlw1=rlwd(i55) -rlwu1
      if(xai.le..1D-004)then
        rnlw1=rlwd(n)-rlwu1
      endif
      rndum1=rnswi11(i55)+rnlw1
      if(i55.gt.1)then
        if(j55.lt.10)then
         rndum1=rnswf11(i55,j55)+rnlw1  ! sunlit
        else
         rndum1=rnswi11(i55)+rnlw1      ! shaded
        endif
      else
       rndum1=rnswi11(i55)+rnlw1        ! ground surface/sun+shaded
      endif
!
!......................................................................
! soil model interface:
! calculates heat and moisture fluxes from soil surface, updates
! soil temperature and moisture profiles
!......................................................................

!
! first get potential evaporative surface temperature
!
!.....................................................................
! call soil model for ground
!.....................................................................
        idoo=1!3
        do ido=1,idoo
        xxx=dble(float(idoo))   !attenuate deltat1 to allow loops; keepingrain1(i)'s cogent.
        tdelt=deltat1/xxx       ! deltat1
      if(iocean.eq.0)then       ! no wet galoshes
        rain1(1)=.0D+000
        rain1(2)=.0D+000
        rain1(3)=.0D+000
        soilhf=.0D+000
        rain1(1)=.0D+000
        rain1(2)=.0D+000
        rain1(3)=.0D+000
        rain1(1)=rain(1)/tdelt          ! convert rain rate from kg m-2 timestep-1 to kg m-2 s-1...
        rain1(2)=rain(2)/tdelt
        rain1(3)=rain(3)/tdelt
!
! initialize these guys
!
         epp=.0D+000
         do i=1,nsoil0
          etaf(i)=qsoiq(i)
          etal(i)=qsoiq(i)
         enddo
         runoff11=.0D+000
         runoff22=.0D+000
         soilhf=fgacas0
         wq1=.0D+000
         xsnodep0=xsnodep
         snowmip1(50)=.0D+000
         if(h55.gt.1)then
           xsnodep0=.0D+000
           do i=1,3
            rain1(i)=.0D+000! assume rain does not leak into buildings pro nunc.
           enddo
         endif
!
         call soilmodel(i55,j55,h55,t,e,rain1, &
          epp,ra,rsl,rndum1,rho,wt,isoi3,wq, &
          pai,xlai,soilhf,wq1,tdelt, &
          qsoiq,tsoiq,xsnodep,soilt22, &
          runoff11,runoff22,snowdens,i7ce,snowater, &
          etaf,etal,snowmelt,xlint,nlyr,gg,dwq,zmoi, &
          snoh,smelt,snowmip1,tessa,dwqs,xwgt,eosx,dwts, &
          nsnow,n,in,ihi,inlyr,nsoil0,nstem,m,iminit,deltsn,zs1,rweight, &
          SMCDRY, SMCREF, PSISAT,BEXP,DKSAT, SMCMAX,iisnow)
!
!
         do k=1,nsoil0
          qsoiq(k)=max(qsoiq(k),.5D-001)! a minimum of 5% moisture content in soil
         enddo
!
!
! update ground heat flux
!
!KC 031615
        soilhf=max(soilhf,-.1D+003)
        soilhf=min(soilhf,.1D+003)
!       soilhf=max(soilhf,-.5D+002)
!       soilhf=min(soilhf,.5D+002)
!KC end
! ground heat flux and transient math =/= steady-state
! turbulence math...hence...large changes can destabilize the soil t, q
! solutions...the shovel implied below is to allow trillions of calls
! without one weird call trashing the whole time series.
!
!KC 031615
!        if(abs(soilhf).eq..5D+003)then  !you may want to get a shovel...
        if(abs(soilhf).eq..1D+003)then  !you may want to get a shovel...
!KC end
!         soilhf=.0D+000         !do not carry junk G values into next time step.
         soilhf=fracas-fsacas-flacas
        endif
!KC
        storex(i55,j55,h55)=(storex(i55,j55,h55)+soilhf)*.5D+000
!        storex(i55,j55,h55)=soilhf
!KC end
        ssoil1=storex(i55,j55,h55)
       else! ocean
        storex(i55,j55,h55)=.0D+000
        wq1=-.1D-005
       endif
! store into keeper array
! nix all but shaded possibility
! only storex(1,10,1) has soilhf as a value for now
!
        enddo
        if(i55.eq.1)then! only one kind of surface on ground for now
         do k=1,8
          do j=1,9
           storex(i55,j,k)=.0D+000
          enddo
         enddo
         do k=2,8
          j=10
          storex(i55,j,k)=.0D+000
         enddo
        endif
! end soil model interface
      return
        END SUBROUTINE
!
!!!!!!!!!!!!!!!!!!! /-\ < /-\ S /-\ !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
!
        subroutine soilmodel(i55,j55,h55,t,e,rain1, &
         epp,ra,rsl,rndum1,rho,wt,isoi3,wq, &
         pai,xlai,soilhf,wq1,tdelt, &
         qsoiq,tsoiq,xsnodep,soilt22, &
         runoff11,runoff22,snowdens,i7ce,snowater, &
         etaf,etal,snowmelt,xlint,nlyr,gg,dwq,zmoi, &
         snoh,smelt,snowmip1,tessa,dwqs,xwgt,eosx,dwts, &
         nsnow,n,in,ihi,inlyr,nsoil0,nstem,m,iminit,deltsn,zs1,rweight, &
         SMCDRY, SMCREF, PSISAT,BEXP,DKSAT, SMCMAX,iisnow)



      implicit none
        integer nsnow,n,in,ihi,inlyr,nsoil0,nstem,m,iminit,i55,j55,h55,iisnow
        DOUBLE PRECISION deltsn,zs1(nsoil0),rweight(nsoil0)
        REAL SMCDRY, SMCREF, PSISAT,BEXP,DKSAT, SMCMAX


      integer inx,jnx
      integer i7ce
      integer jsoil,i
      DOUBLE PRECISION tdelt,runoff11,runoff22,xlint(n,10,8)
      DOUBLE PRECISION snowdens,rrho,swqfraq,snowater,xxx
      DOUBLE PRECISION tacasa1,tacasa2,eacasa1,eacasa2,snoh,smelt
      DOUBLE PRECISION potwq1,xlai,wq1,snowmelt
      DOUBLE PRECISION qsoref,qso0,rn1acasa,h1acasa,le1acasa,soilhf
      DOUBLE PRECISION xsnodep,xsnomelt,snowmip1(100),tessa(n)
        DOUBLE PRECISION gg(n),dwq(n),t(n)
        DOUBLE PRECISION e(n),wt(n),wq(n)
        DOUBLE PRECISION dwqs(n,10,8),xwgt(n,10,8)
        integer nlyr,j
      INTEGER MIq,MJq,MKq,IDEBUG,NSEGP,NSPGX,NSPGD
      INTEGER KX,KXP1,MIqM,MJqM,MKqM,NZS,NZSP
      INTEGER miqv,mjqv,mkqv
      PARAMETER (MIq=1,MJq=1,MKq=1,IDEBUG=0)
      PARAMETER(NSEGP=5,NSPGX=6,NSPGD=6)
      PARAMETER (KX=MKq,KXP1=MKq+1)
      parameter(miqm=1,mjqm=1,mkqm=1)
      parameter(miqv=1,mjqv=1,mkqv=1)
      PARAMETER (NZSP=7)! 15::nsoil0!!!! bugus if you want to hange # soil layers
      parameter(inx=miq,jnx=mjq)
      DOUBLE PRECISION ETAF(nsoil0),ETAL(nsoil0)
      DOUBLE PRECISION xroot(nsoil0),rain1(3),epp,rsl,ra(n)
      DOUBLE PRECISION rndum1,rho(n)
      DOUBLE PRECISION dwts(n,10,8)
      DOUBLE PRECISION swqfrac1(n),pai(n),qsoiq(nsoil0)
      DOUBLE PRECISION swqfrac,tsoiq(nsoil0),zmoi,eosx(n,10,8)
      integer isoi3,i56
      DOUBLE PRECISION soilt22(nsnow),t_bc
!
        nzs=nsoil0
        i56=max(i55,2)
        tacasa1=tessa(i55)! T of soil/snow, stems, &/or bldg surfaces
        t_bc = tessa(1)
        if(i55.eq.1.and.snowater.gt..1D-004)tacasa1=min(tacasa1,.0D+000)
        if(rain1(2).gt..0D+000)tacasa1=min(tacasa1,.0D+000)
        tacasa2=t(n)    ! fall temp for precip fluxing energy
        if(rain1(2).gt..0D+000)tacasa2=min(tacasa2,.0D+000)
!        eacasa2=e(i56)         ! air spechum (kg kg-1)
! gankball for WRF
        rrho=rho(i56)             ! air density kg m-3
        eacasa1=eosx(i55,j55,h55) ! aveeosx(1,10,1)    ! surface sat. spechum (kg kg-1)
        eacasa2=eosx(i55,j55,h55) ! aveeosx(1,10,1)    ! surface sat. spechum (kg kg-1)
        rn1acasa=rndum1         ! absorbed Rn at surface (w/m2)
        potwq1=dwqs(i55,j55,h55)     ! surface evap. rate (kg s-1)
        h1acasa=rho(i56)*.100468550D+004*dwts(1,10,1)! sens. heat flux dens. at ground surf (w/m2)
        xxx=.24912650D+007-.23740290D+004*tessa(1) ! latent heat of vap.
        if(tessa(1).lt..0D+000)xxx=xxx+.3335D+006!"
        le1acasa=dwqs(i55,j55,h55)*rho(i56)*xxx! latent heat flux density @ ground surf (w/m2)
        jsoil=isoi3             ! soil type (1-11 usda)
        if(i7ce.eq.1)then       ! sea ice condition
         jsoil=1
        endif
        qso0=.50D-002           ! minimum limit for vol. soil moisture (for numerical purposes)
        qsoref=.20D+000         ! not used
!
! transpirational root extraction...
!
! wqfrac is the net evaporation from one level to the next.
! swqfrac is the contribution to the total evaporation which is due
! solely to transpiration (excludes free evaporation from leaves)
! weight fraction to that lai which has no free water to evaporate.
!
      do i=1,nsoil0
       xroot(i)=.0D+000
      enddo
!
      swqfraq=.0D+000
      do i=1,n
       swqfrac1(i)=.0D+000! uninitialized array found by Liyi Xu, March 2008
      enddo
      xxx=.0D+000
      do j=1,10
      do i=2,nlyr
        xxx=xxx+dwqs(i,j,h55)*gg(i)*xwgt(i,j,h55)
      enddo
      enddo
      swqfrac=.1D-002*max(xxx,.0D+000)

      do i=1,nsoil0
       if(qsoiq(i).gt..5D-001.and.h55.eq.1)then ! root extraction taking place
        xroot(i)=rweight(i)*swqfrac
       else! soil is too dry; roots cannot extract moisture
        xroot(i)=.0D+000
       endif
      enddo
!
!gankball (for WRF)
!
!       xroot(1)=.3333D+000*swqfrac
!       xroot(2)=xroot(1)
!       xroot(3)=xroot(2)
!       xroot(4)=.0D+000
!
      do i=1,nsoil0 ! prevent root water "downtake"
       xroot(i)=max(xroot(i),.0D+000)
      enddo
! pass int tsoiq,qsoiq to have uptaded w/ tso,eta internally
! also pass out soil/snow heat flux and snow phase change storage, and
! soil surface evap
!
      xsnomelt=.0D+000
      call grnd2(i55,jsoil,tacasa1,tacasa2,eacasa1,eacasa2,xroot, &
      potwq1,wq1,snowmelt,rain1,qsoref,qso0, &
      rn1acasa,h1acasa,le1acasa,soilhf,xsnodep,xsnomelt, &
      rrho,runoff11,runoff22,tdelt,qsoiq,tsoiq,soilt22, &
      snowdens,i7ce,snowater,etaf,etal,zmoi,snoh,smelt,snowmip1, &
        nsnow,n,in,ihi,inlyr,nsoil0,nstem,m,iminit,deltsn,zs1,rweight, &
          SMCDRY, SMCREF, PSISAT,BEXP,DKSAT, SMCMAX,xlai,iisnow,t_bc)
       return
        END SUBROUTINE
!
!!!!!!!!!!!!!!!!!!! /-\ < /-\ S /-\ !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
!
      subroutine grnd2(i55,jsoil,tacasa1,tacasa2,eacasa1,eacasa2,xroot, &
      potwq1,wq1,snowmelt,rain1,qsoref,qso0, &
      rn1acasa,h1acasa,le1acasa,soilhf,xsnodep,xsnomelt, &
      rrho,runoff11,runoff22,tdelt,qsoiq,tsoiq,soilt22, &
      snowdens,i7ce,snowater,etaf,etal,zmoi,snoh,smelt,snowmip1, &
        nsnow,n,in,ihi,inlyr,nsoil0,nstem,m,iminit,deltsn,zs1,rweight, &
          SMCDRY, SMCREF, PSISAT,BEXP,DKSAT, SMCMAX,xlai,iisnow,t_bc)

!
! original code written by Dr. Tatiana Smirnova (NOAA FSL < 2000 to 2006+?)
! the original author of the soil/snow/diffusion heat flux modules
! (particularly the snow sections)
! which have since been generalized to handle urban surfaces
! as well modified to handle lots of snow layers
! for when it gets deep
! and to do sea ice situations, etc.
!
        implicit none
      integer j
      DOUBLE PRECISION runoff11,runoff22,tdelt,snowdens
      DOUBLE PRECISION runoffz,vt
        integer nsnow,n,in,ihi,inlyr,nsoil0,nstem,m,iminit
        DOUBLE PRECISION deltsn,zs1(nsoil0),rweight(nsoil0)
        REAL SMCDRY, SMCREF, PSISAT,BEXP,DKSAT, SMCMAX

      INTEGER MIq,MJq,MKq,IDEBUG,NSEGP,NSPGX,NSPGD,i55
      integer KX,KXP1,MIqM,MJqM,MKqM,NZS,NZSP,iisnow
      integer miqv,mjqv,mkqv,ikq
      PARAMETER (MIq=1,MJq=1,MKq=1,IDEBUG=0)
      PARAMETER(NSEGP=5,NSPGX=6,NSPGD=6)
      PARAMETER (KX=MKq,KXP1=MKq+1)
      parameter(miqm=1,mjqm=1,mkqm=1)
      parameter(miqv=1,mjqv=1,mkqv=1)
      PARAMETER (NZSP=7)

      DOUBLE PRECISION TSO(nsoil0),ETA(nsoil0)
      DOUBLE PRECISION F,snowater
      DOUBLE PRECISION SNWE,yyy,xlai
      DOUBLE PRECISION CAP(nsoil0),HK(nsoil0),QMIN
      DOUBLE PRECISION DQM,PC,REF,WILT
      DOUBLE PRECISION RHOCS,PSIS,snowmip1(100)
      DOUBLE PRECISION BCLH,KSAT,SOILTYP
      DOUBLE PRECISION ETAF(nsoil0),ETAL(nsoil0),CN,SAT,CW,RAS,FQ,RHOSN
      DOUBLE PRECISION DDZS(2*(nsoil0-2)),ddzsnow(2*(nsnow-1)),DSDZ1(nsoil0)
      DOUBLE PRECISION TWST(nsoil0),TSQ1(nsoil0),TSQ2(nsoil0),BES(nsoil0),RTS(nsoil0)
      DOUBLE PRECISION BEQ(nsoil0),RQS(nsoil0),TRANSP(nsoil0),SOILT
      DOUBLE PRECISION RHO,S,zmoi
      DOUBLE PRECISION RUNOFF1,RUNOFF2
      DOUBLE PRECISION SNHEI,SNOH
      DOUBLE PRECISION SMELT,ETASN,SOILT1(nsnow)
      DOUBLE PRECISION soilt22(nsnow),xxx
      DOUBLE PRECISION tacasa1,tacasa2,eacasa1,eacasa2
      DOUBLE PRECISION xroot(nsoil0),potwq1,wq1,snowmelt,rain1(3)
      DOUBLE PRECISION qsoref,qso0,rn1acasa,h1acasa,le1acasa,soilhf
      DOUBLE PRECISION xsnodep,xsnomelt,qsoiq(nsoil0),tsoiq(nsoil0)
      DOUBLE PRECISION zs2(nsoil0),zsnow2(nsnow+1),zsnow1(nsnow+1)
        INTEGER I7CE,K,I,jsoil
        DOUBLE PRECISION DT
       DOUBLE PRECISION setab,setaf,ssqfx,etadif,sqfxdt
       DOUBLE PRECISION rrho,t_bc
!
        nzs=nsoil0
        i=1
        j=1
        rho=rrho
       DT=tdelt
!*** feed in soil, veg parameters
        snhei=xsnodep
        snwe=snowater
        DQM=.0D+000
        RHOCS=.0D+000
        RAS=.0D+000
        REF=.0D+000
        WILT=.0D+000
        PSIS=.0D+000
        BCLH=.0D+000
        KSAT=.0D+000
        CW=.0D+000
        QMIN=.3D+000
        RHOSN=.0D+000
        if(snowater.gt..1D-004)then
         rhosn=.1D+004*(snhei/snwe)
        else
         rhosn=.3D+003
        endif
!
! the following arrays initialized by R. Pyles and L. Xu / 2008
!
        do i=1,2*(nzs-2)
         DDZS(i)=.0D+000
        enddo
        do i=1,2*(nsnow-1)
         ddzsnow(i)=.0D+000
        enddo
        do i=1,nzs
         DSDZ1(i)=.0D+000
         zs2(i)=.0D+000
        enddo
!
! replace constants here with deltsn...were hardwired to 0.25 m here / now deltsn alone determines the zsnow1,zsnow2.
        do i=1,nsnow+1
         zsnow2(i)=deltsn*dble(float(i-1))
         zsnow1(i)=deltsn*dble(float(i-1))
        enddo
!
       call soivegini(DT,DQM,RHOCS,DDZS,ddzsnow,DSDZ1,RAS, &
      REF,WILT,PSIS,BCLH,KSAT,CW,QMIN,RHOSN,jsoil, &
      i7ce,zs2,zsnow2,zsnow1,snhei,zmoi, &
        nsnow,n,in,ihi,inlyr,nsoil0,nstem,m,iminit,deltsn,zs1,&
          SMCDRY, SMCREF, PSISAT,BEXP,DKSAT, SMCMAX)
        runoffz=.0D+000
!
! feed in soil temp, moist, snow depth & all that
!
      do k=1,nzs
       tso(k)=tsoiq(k)
       eta(k)=qsoiq(k)
      enddo
      do k=1,nsnow
       soilt1(k)=min(soilt22(k),.27315D+003)
      enddo
      soilt=tacasa1+.273150D+003
       ikq=1
! rdp initialization 2008
        j=1
        i=1
        f=.0D+000
        cn=.0D+000
        sat=.0D+000
        fq=.0D+000
        vt=.0D+000
        do i=1,nzs
         cap(i)=.0D+000
         hk(i)=.0D+000
         twst(i)=.0D+000
         tsq1(i)=.0D+000
         tsq2(i)=.0D+000
         bes(i)=.0D+000
         rts(i)=.0D+000
         beq(i)=.0D+000
         rqs(i)=.0D+000
         transp(i)=.0D+000
        enddo
        pc=.0D+000
        soiltyp=1
        s=.0D+000
        runoff1=.0D+000
        runoff2=.0D+000
        etasn=.0D+000
        setab=.0D+000
        setaf=.0D+000
        ssqfx=.0D+000
        etadif=.0D+000
        sqfxdt=.0D+000

      CALL surfacexx(i55,DT,J,i,SNWE, &
       RHOSN,TSO,ETA,F,xlai,CN,SAT,CW,fq,VT,CAP,DDZS,ddzsnow, &
       DSDZ1,DQM,PC,REF,QMIN,RHOCS,PSIS,BCLH, &
       KSAT,TWST,TSQ1,TSQ2,BES,RTS,BEQ,RQS,TRANSP, &
       SOILTYP,ETAF,ETAL,SOILT,S,RUNOFF1, &
       RUNOFF2,SNHEI,SNOH,ETASN,SMELT,SOILT1, &
       setab,setaf,ssqfx,etadif,sqfxdt,tacasa2, &
       eacasa1,eacasa2,xroot,potwq1,wq1, &
       snowmelt,rain1,qsoref,qso0,rn1acasa,h1acasa,le1acasa,soilhf, &
       xsnodep,xsnomelt,runoffz,i7ce,soilt22, &
       snowater,snowdens,rho,zs2,zsnow2,zsnow1,snowmip1, &
       nsnow,n,in,ihi,inlyr,nsoil0,nstem,m,iminit,deltsn,zs1,iisnow)
!
!KC 011716, testing TSO threshold
          tso(1) = max(2.6315D+002,tso(1))
       if (xsnodep .gt. 0.0D+000) then
          tso(1) = min(2.7315D+002,tso(1))
       endif
          DO K=2,NZS
            TSO(K)=min(TSO(K),TSO(K-1)+5D+000)
            TSO(K)=max(TSO(K),TSO(K-1)-5D+000)
          END DO
        do k=1,nzs
         tsoiq(k)=tso(k)
         qsoiq(k)=max(eta(k),.5D-001)
        enddo
!KC 070714, fix the runoff typo & units
!         runoff22=runoff2*.1D+004*dt! mm per timestep
!         runoff11=runoff11*.1D+004*dt! mm per timestep
         runoff22=runoff2*(zs1(nsoil0)-zs1(2))*1000.0*dt! mm
         runoff11=runoff1*(zs1(2)-zs1(1))*1000.0*dt! mm
!KC end
!
        xxx=.0D+000
        if(snowater.gt..1D-004)then
         do k=1,int(snowmip1(6))
          xxx=xxx+(soilt1(k)-soilt22(k)) &
           *rhosn*snowater*deltsn*.3335D+006/tdelt
         enddo
         snowmip1(60)=xxx! snowpack thermal storage change Wm-2
        endif
        if(snowater.lt..1D-004.and.xsnodep.gt..1D-014)xsnodep=.0D+000
!       if(xsnodep.lt..1D-005)snowater=.0D+000
!         snowdens=rhosn
!RDP 20 July 2011: restore broken link updating snowpack temperature
              do k=1,nsnow
               soilt22(k)=min(soilt1(k),.27315D+003)
              enddo
      return
        END SUBROUTINE

      subroutine soivegini(DT,DQM,RHOCS,DDZS,ddzsnow,DSDZ1,RAS, &
      REF,WILT,PSIS,BCLH,KSAT,CW,QMIN,RHOSN,jsoil, &
      i7ce,zs2,zsnow2,zsnow1,snhei,zmoi, &
        nsnow,n,in,ihi,inlyr,nsoil0,nstem,m,iminit,deltsn,zs1, &
          SMCDRY, SMCREF, PSISAT,BEXP,DKSAT, SMCMAX)


        implicit none
        integer nsnow,n,in,ihi,inlyr,nsoil0,nstem,m,iminit
        DOUBLE PRECISION deltsn,zs1(nsoil0)
!

! uncomment/comment out when switching to offline mode
! so as to be able to key in with jsoil / isoi3
! as wrf feeds the soil params in directly
!      integer nzs,nzsp,ikk
!      PARAMETER (NZSP=7)
      integer nzs,nzsp,ikk,nstyp
      PARAMETER (NZSP=7,nstyp=19)
      INTEGER nzs1,k2,kp,km,k1,jsoil,i7ce,k

      REAL SMCDRY, SMCREF, PSISAT,BEXP,DKSAT, SMCMAX

      DOUBLE PRECISION RHOCS,RAS,CW,RHOSN,ksat

      DOUBLE PRECISION DDZS(2*(nsoil0-2)),DSDZ1(nsoil0),dqm,psis,qmin,bclh
      DOUBLE PRECISION wilt,ref,zmoi
      DOUBLE PRECISION a,b,c,d,e,f,g,dt,x,ddzsnow(2*(nsnow-1))
      DOUBLE PRECISION zs2(nsoil0),zsnow2(nsnow+1),zsnow1(nsnow+1),snhei
      DOUBLE PRECISION satkt4y(nstyp),b4y(nstyp),satpsi4y(nstyp)
      DOUBLE PRECISION qsat4y(nstyp),qminn(nstyp),qqref(nstyp)
!  soil type (=jsoil): -2 = open water w/ vegetation-1=permanent ice; 0=water;
! NOTE: soil types < 1 this routine is not called. also avoid having jsoil = 14.
! its all taken care of in ACASA.
!
!             1          SAND                  SAND
!             2          LOAMY SAND            LOAMY SAND
!             3          SANDY LOAM            SANDY LOAM
!             4          SILT LOAM             SILTY LOAM
!             5          SILT                  SILTY LOAM
!             6          LOAM                  LOAM
!             7          SANDY CLAY LOAM       SANDY CLAY LOAM
!             8          SILTY CLAY LOAM       SILTY CLAY LOAM
!             9          CLAY LOAM             CLAY LOAM
!            10          SANDY CLAY            SANDY CLAY
!            11          SILTY CLAY            SILTY CLAY
!            12          CLAY                  LIGHT CLAY
!            13          ORGANIC MATERIALS     LOAM
!            14          WATER
!            15          BEDROCK
!            16          OTHER (land-ice)
!--- REF values seem too high for many soil types
! Residual soil moisture is from Rawls et al(1982), missing soil types
! are from Carcel and Parrish (1988)
!
! qsat4y                 LQMA     Max. soil moisture content (porosity)
! qqref                  LREF     Field capacity soil moisture content
!                        LWIL     Wilting point soil moisture content
! qminn                  LQMI     Air dry soil moisture content limits
! satpsi4y               LPSI     Saturation soil potential
! satkt4y                LKAS     Saturation soil conductivity
! b4y                    LBCL     Exponent b for Clapp-Hornb. equations
! clapp and hornberger b value
!
        data b4y /2.79, 4.26, 4.74, 5.33, 5.33, 5.25, 6.66, 8.72, &
                  8.17,10.73,10.39,11.55, 5.25, 0.0,  2.79, 4.26, &
                                11.55, 2.79, 2.79 /
!-------------------------------------------------------------------------
! saturation psi value(thermal conductivity)
        DATA satpsi4y /0.069,0.036,0.141,0.759,0.759, 0.355, 0.135, &
! KC 102913, fix the original typo with SOILPARM.TBL
!       0.1617, 0.1763, 0.098, 0.324, 0.468, 0.355, 0.0, 0.069, 0.036, &     !old
       0.617, 0.263, 0.098, 0.324, 0.468, 0.355, 0.0, 0.069, 0.036, &      !new
! end
         0.468, 0.069, 0.069/
!-------------------------------------------------------------------------
!-------------------------------------------------------------------------
! maximum (saturated) hydraulic conductivity
! Maruyama/flooded rice/isoi3=1        data satkt4y/1.07D-7, 1.41D-5, 5.23D-6, 2.81D-6,2.81D-6, &
        data satkt4y/1.07D-6, 1.41D-5, 5.23D-6, 2.81D-6,2.81D-6, &
                3.38D-6,4.45D-6, 2.04D-6, 2.45D-6, 7.22D-6,1.34D-6, &
                9.74D-7, 3.38D-6, 0.0, 1.41D-4, 1.41D-5, &
                9.74D-7, 1.41D-4, 1.07D-6 /
!-------------------------------------------------------------------------
! maximum soil moisture content: WRF
! Maruyama/flooded rice/isoi3=1         DATA qsat4y/0.999,0.421,0.434,0.476,0.476,0.439,0.404,0.464, &
                DATA qsat4y/0.339,0.421,0.434,0.476,0.476,0.439,0.404,0.464, &
                0.465,0.406,0.468,0.468,0.439,1.0,0.2,0.421,0.468,0.2,0.339/
!-------------------------------------------------------------------------
! air dry soil moisture content limits : new from WRF
        DATA qminn /0.01,0.028,0.047,0.084,0.084,0.066,0.067,0.12, &
                0.103,0.1,0.126,0.138,0.066,0.0,0.006,0.028,0.03,0.006,0.01/
!-------------------------------------------------------------------------
! reference soil moisture (field capacity): WRF
! Maruyama/flooded rice/isoi3=1   DATA qqREF /0.996,0.383,0.383,0.36,0.383,0.329,0.314,0.387, &
          DATA qqREF /0.236,0.383,0.383,0.36,0.383,0.329,0.314,0.387, &
                0.382,0.338,0.404,0.412,0.329,0.0,0.17,0.283,0.454,0.17,0.236/

!-------------------------------------------------------------------------
! constnts.
        nzs=nsoil0
        cw=.4186D+007        ! CW -  water specific heat capacity (J Mg-1 K-1)
        rhocs=.2D+007      ! Volumetric Dry soil heat capacity for VALDAI(J m-3 K-1)
!
        f=.115D+000           ! WILT - wilting value of volumetric soil moisture content 2d
!
        c=qminn(jsoil)          ! qqMIN - residual (air dry) value of soil moisture
        g=qqref(jsoil)          ! qREF - reference value of volumetric soil moisture content
        b=-satpsi4y(jsoil)*100. ! PSI - Soil moisture potential atsaturation (-cm)
        d=b4y(jsoil)            ! Clapp and Hornberger B parameter
        e=2.*satkt4y(jsoil)     ! KSAT - maximum hydraulic conductivity (m/s)
        a=qsat4y(jsoil)-0.005   ! DQM = QMAX - QMIN  for soil type
!
! if fed in from WRF...turned off for now; soil parameters all stored
! internally and keyed in by jsoil
!        c= dble(SMCDRY)         ! qqMIN - residual (air dry) value of soil moisture
!        g= dble(SMCREF)          ! qREF - reference value of volumetric soil moisture content
!        b=-DBLE(PSISAT)*100. ! PSI - Soil moisture potential atsaturation (-cm)
!        d= DBLE(BEXP)            ! Clapp and Hornberger B parameter
!        e=.2D+001* DBLE(DKSAT)        ! KSAT - maximum hydraulic conductivity (m/s)
!        a= DBLE(SMCMAX) -.5D-002    ! DQM = QMAX - QMIN  for soil type
!
! sea ice values
!
        if(i7ce.eq.1)then
         b=-.86D+001          ! PSI - Soil moisture potential at saturation (cm)
         d=.712D+001           ! Clapp and Hornberger B parameter 2d
         e=.2D-014         ! KSAT - maximum hydraulic conductivity (m/s) 2d
         a=.9D+003           ! DQM = QMAX - QMIN  for soil type
        endif

        dqm=a
        psis=b
! change this
        qmin=.3D+000 ! formerly < qmin=c > but this gets numerically unstable for low
!               values; not to worry: surface evaporation is already
!               moisture-regulated (via rsl)..and as for kjpl(k)=f(qsoiq)...
!               (thermal conductivity)...well...we do what we can.
!
        bclh=d
        ksat=e
        wilt=f
        ref=g
!
        zs2(1)=.0D+000
        do k=2,nzs
         zs2(k)=.5D+000*(zs1(k-1)+zs1(k))
        enddo
!
        if(float(nsnow)*deltsn.ge.snhei)then ! snow <= than nsnow*deltsn
         do k=2,nsnow+1
          if(zsnow1(k-1).lt.snhei-deltsn)then
           zsnow1(k)=deltsn*float(k-1)
          else
           zsnow1(k)=snhei
           ikk=k
           go to 86
          endif
         enddo
 86      continue
         k=min(k,nsnow+1)
         do k=ikk,nsnow+1
          zsnow1(k)=zsnow1(k-1)+deltsn
         enddo
        else                      ! snow is deeper than nsnow*deltsn
         zsnow1(1)=.0D+000
         do k=2,nsnow
          zsnow1(k)=deltsn*float(k-1)
         enddo
         zsnow1(nsnow+1)=snhei
        endif
!
        zsnow2(1)=0.
        do k=2,nsnow+1
         zsnow2(k)=.5D+000*(zsnow1(k-1)+zsnow1(k))
        enddo
!
        NZS1=NZS-1
        DO  K=2,NZS1
         K1=2*K-3
         KM=K-1
         K2=K1+1
         KP=K+1
         X=DT/.2D+000/(ZS2(KP)-ZS2(K))
         DDZS(K1)=X/(ZS1(K)-ZS1(KM))
         DSDZ1(KM)=X
         DDZS(K2)=X/(ZS1(KP)-ZS1(K))
        END DO


! now for snow layers
        if(snhei.gt..1D-015)then
         DO  K=2,nsnow
          K1=2*K-3
          KM=K-1
          K2=K1+1
          KP=K+1
          X=DT/.2D+000/(ZSnow2(KP)-ZSnow2(K))
          DDZsnow(K1)=X/(ZSnow1(K)-ZSnow1(KM))
          DDZSnow(K2)=X/(ZSnow1(KP)-ZSnow1(K))
         END DO
        else
         DO  K=2,nsnow
          K1=2*K-3
          K2=K1+1
          X=DT/.1D+000
          DDZsnow(K1)=X/.5D-001
          DDZSnow(K2)=X/.5D-001
         END DO
        endif
        RETURN
        END SUBROUTINE
subroutine surfacexx(i55,DT,J,i,SNWE, &
      RHOSN,TSO,ETA,F,xlai,CN,SAT,CW,fq,VT,CAP,DDZS,ddzsnow, &
      DSDZ1,DQM,PC,REF,QMIN,RHOCS,PSIS,BCLH, &
      KSAT,TWST,TSQ1,TSQ2,BES,RTS,BEQ,RQS,TRANSP, &
      SOILTYP,ETAF,ETAL,SOILT,S,RUNOFF1, &
      RUNOFF2,SNHEI,SNOH,ETASN,SMELT,SOILT1, &
      setab,setaf,ssqfx,etadif,sqfxdt,tacasa2, &
      eacasa1,eacasa2,xroot,potwq1,wq1,  &
      snowmelt,rain1,qsoref,qso0,rn1acasa,h1acasa,le1acasa,soilhf, &
      xsnodep,xsnomelt,runoffz,i7ce,soilt22, &
      snowater,snowdens,rho,zs2,zsnow2,zsnow1,snowmip1, &
      nsnow,n,in,ihi,inlyr,nsoil0,nstem,m,iminit,deltsn,zs1,iisnow)
    
      implicit none
     
      INTEGER nsnow,n,in,ihi,inlyr,nstem,m,iminit
      INTEGER NSOIL0, NZSP, I,J,ikk,k,iisnow,i55, i7ce
      
      DOUBLE PRECISION xlai,tsnav, rhonewsn,xsn,snowater,rho
      DOUBLE PRECISION dt,vt,runoffz, deltsn,zs1(nsoil0)
      DOUBLE PRECISION soilt22(nsnow), SNWE, TSO(nsoil0),ETA(nsoil0),F
      DOUBLE PRECISION CAP(nsoil0),QMIN,DQM,PC,REF
      DOUBLE PRECISION RHOCS,PSIS,rainflux,BCLH,KSAT,SOILTYP
      DOUBLE PRECISION ETAF(nsoil0),ETAL(nsoil0),CN,SAT,CW,FQ
      DOUBLE PRECISION DDZS(2*(nsoil0-2)),DSDZ1(nsoil0),RHOSN
      DOUBLE PRECISION TWST(nsoil0),TSQ1(nsoil0),TSQ2(nsoil0),BES(nsoil0),RTS(nsoil0)
      DOUBLE PRECISION BEQ(nsoil0),RQS(nsoil0),TRANSP(nsoil0) 
      DOUBLE PRECISION SOILT,p , S,ddzsnow(2*(nsnow-1)) 
      DOUBLE PRECISION RUNOFF1,RUNOFF2,snwepr1, SNHEI,SNOH
      DOUBLE PRECISION SMELT,ETASN,SOILT1(nsnow),snowmip1(100)
      DOUBLE PRECISION tacasa2,eacasa1,eacasa2, xsnodep,xsnomelt
      DOUBLE PRECISION xroot(nsoil0),potwq1,wq1,snowmelt,rain1(3)
      DOUBLE PRECISION qsoref,qso0,rn1acasa,h1acasa,le1acasa,soilhf
      DOUBLE PRECISION setab,setaf,ssqfx,etadif,sqfxdt
      DOUBLE PRECISION c1sn,c2sn,BSN,snowdens,xxx
      DOUBLE PRECISION zs2(nsoil0),zsnow2(nsnow+1),zsnow1(nsnow+1)
      DOUBLE PRECISION cp,T2ABS,NEWSNOW,  DELT 
!adding for snowdensity adjustment below REAL:: adj1, adjrhosn,smelt1
      DOUBLE PRECISION adj1, adjrhosn, smelt11, tswe
!initialize etc .lem.
	cp=.100468550D+004
        K=1
        delt=dt
	rho=.120D+001   !called in soilsnow,soil123 .lem.
	p=.0D+000 	!called in soil123 .lem.
        NEWSNOW=.0D+000
        rhosn=snowdens

! get mean snow temperature
!## tsnav is also used in soilsnow .lem.
        T2ABS=tacasa2+.273150D+003
	ikk=1
	tsnav=.00D+000
        if(snhei.gt..1D-003)then
	 ikk=max(int(snhei/deltsn),1)! # snow layers to average over)
		!rdp cm 15 june 1021: nsnow max = 11 not 101!!! 
	 ikk=min(ikk,11) ! # snow layers to average over)
         do i=1,ikk! assume constant density within snowpack
          tsnav=tsnav+soilt22(i)! allows for using tsnav instead of integrating after the calc.
	 enddo			! tsnav is used in snowpack phase change clacs...
	 tsnav=tsnav/float(ikk)
        else
         tsnav=.273150D+003! default (missing) value)
        endif    

!cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
       IF(rain1(2)+rain1(3).gt..0D+000)THEN ! frozen precip is happening

	!calculate fresh snow density (t > -15 C, else min value)  eqn. 10 from Koren et al. (1999)
        if(t2abs.lt..258150D+003)then
	  rhonewsn=.5D+002
        else
         ! rhonewsn=.1D+004* &
         ! max((.5D-001+0.0017* &
          ! (min(t2abs-.273150D+003,.0D+000)+.15D+002)**.150D+001),.5D-001)
          !rhonewsn=min(rhonewsn,.333D+003)
!double precision everywhere lem.12.10.14
        
rhonewsn=.1D+004* &
          max((.5D-001+.17D-002* &
           (min(t2abs-.273150D+003,.0D+000)+.15D+002)**.150D+001),.5D-001)
          rhonewsn=min(rhonewsn,.333D+003)

!rhonewsn=rhonewsn*1.5D+000!LEM TEST feb2 	2016
!rhonewsn=rhonewsn*.5D+000!LEM TEST dec  13	
!testing other newsnow densities
!lem 12.14.14
!MAKE SURE THAT THEY ARE ALL USING TS2ABS?!
!!!!!!temp for precip flux e? in celsius
!!!!ALSO PUT IN ALL THE MAX/MIN FUNCTIONS I HAVE LEFT OUT HERE. 

!. FOUR
!boone, brown, hesdstrom
! if (t2abs.lt.27315D+003) then
!rhonewsn=.6792D+003+.5125D+002*EXP((t2abs-.27315D+003)/.259D+001)
!else! if (t2abs.ge.27315D+003) then!the temperature is at or equal to ? 273
!rhonewsn=.11917D+003+.20D+002*(t2abs-.27315D+003)


endif


                
!. TWO
!Dourville perhaps the best at higher temperatures since the others are
!making the snow too dense
!rhonewsn=0.1D+003


!. THREE
!Boone/Lehing from Essery
!rhonewsn=max((.109D+003+.6D+001*(t2abs-.27315D+003)+.26D+002*(.15D+001**0.5D+000)),.5D+002)
!rhonewsn=max((.109D+003+.6D+001*(t2abs-.27315D+003)+.26D+002*(vt*0.5D+000)),.5D+002)
!where 1.5 is acutally wind speed

!. FIVE
!rhonewsn=.8D+002 


	newsnow=.0D+000 
        NEWSNOW=(rain1(2)+rain1(3))*DELT 
!KC
!        snwepr1=snowater
!        snwe=snowater+.1D-002*newsnow
!        snhei=snwe*.1D+004/rhosn
!KC end
!lem 10/14
       if (snwe.lt.1D-004.or.snhei.lt.1D-003) then
!KC
         snhei=.0D+000
         snwe=.0D+000
         snwepr1=.0D+000
         rhosn=.350D+003
!KC end
        !snwei!=newsnow/1000.
 !!  ! SNHEI=newsnow/RHOSN
!write(*,*)"L13781 my change"

!        snhei= swe/333.0
!else
end if 
	END IF 
!## previously density was calculated only if frozen precip happening .lem.
!## moved it so desnity of snow is always recalculated .lem. 
!## perhaps create it so that it is only if snow on ground of certain amount .lem.

!     rhosn=rhonewsn!.333D+003 !## initilaziation nec for calc below. use this? what does koren do? .lem. 
!rhosn=.333D+003
  !lem12.10.14  ! get lots of nan values in output when i do this, and my snow denisty values go back to being zero

!test feb 2
!rhosn=rhonewsn ! this needs to be replaced by rhosnlast soon 12.10 not here but in the equation below
	if(snwe.gt..1D-004)then ! correct snow density for current temperature (Koren et al. 1999)
         c1sn=.266D-001! cm-1 h-1 Koren prefers 0.01
         c2sn=.2D+002 ! cm-3 g
         BSN=delt/.36D+004* &
         c1sn*exp(.8D-001*(tsnav-.27315D+003)-c2sn*rhosn*.1D-002)
         xsn=rhosn*(exp(bsn*snwe*.1D+003)-.1D+001)/(bsn*snwe*.1D+003)
         rhosn=min(xsn,.5D+003)  !keep rhosn to w/in 1/2 that of liquid wate
!write(*,*) "firstpartif"
        else
        !!rhosn=.333D+003		! keep this as default value
!write(*,*)"2nd"        
endif


!rhosn=rhonewsn ! this needs to be replaced by rhosnlast soon 12.10 not here but in the equation below
!        if(snwe.gt..1D-004)then ! correct snow density for current temperature (Koren et al. 1999)
!         c1sn=.266D-001! cm-1 h-1 Koren prefers 0.01
!         c2sn=.2D+002 ! cm-3 g
!         BSN=delt/.36D+004* &
!         c1sn*exp(.8D-001*(tsnav-.27315D+003)-c2sn*oldrhosn*.1D-002)
!         xsn=oldrhosn*(exp(bsn*snwe*.1D+003)-.1D+001)/(bsn*snwe*.1D+003)
!         rhosn=min(xsn,.5D+003)  !keep rhosn to w/in 1/2 that of liquid water
!        else
!        rhosn=.333D+003         ! keep this as default value
!        endif
!oldrhosn=rhosn
!this shouldn't matter if it just used rhosn like previously it should be fine.


! rhosn=rhosn+1
! WILL PUT THE ADJUSTMENT TO SNOW DENSITY IN HERE FROM KOREN. WORKING ON IT NOW. 
! 12.10.14
!REAL:: adj1, adjrhosn,smelt1

!!!!SMELT=SMELT1 IS NOT RIGHT JUST USING IT RIGHT NOW TO TEST BEFORE I FIGURE OUT HOW TO GET SMELT1 
!MIGHT JUST STORE IT IN SNOWMIP1. EASY. 

!smelt11=0.00D+1!smelt
!
!for the below i need smelt1 from vtsfluxds. so figure out how to input get variable name chagne here. 
!ASS SOON AS I UNCOMMMENT THE ABOVE I GET 0 VALUES IF THOUGH ADJ1 ODESN'T GO ANYWERHE RIGHT NOW...
!somewhere after rhosn below i get an error that causes errors everywhere 
!adj1     = rhosn!*snwe!*(snwe-.8D+000*smelt11) + 0.13D+000*.1D+003*smelt11 + rhonewsn*newsnow
!Adj1     = .1D+001*adj1
!adjrhosn = adj1 / (snwe+.13D+000*smelt11+newsnow)!*.1D+003
! KOREN UNITS FOR THE ABOVE ARE FRACTION AND NOT PERCENT TO ADJUST ACCORDINGLY 
!!!ALSO SET SMELT TO 0 AND SEE WHAT HAPEPNS
!rhosn    = min(adjrhosn,.4D+003) 
!
!need to create a last density variable to go into koren equation above. at the end of the adjustment


!rhosnlast=rhosn BUT THIS WON'T HELP WITH TIMESTEP NEED FIRST TIMESTEP TO BE =333?
!use snowmip1 to store a timestep number to use in the equaiton above?

 
!testing my own adjustment scheme
!Tswe=snwe+newsnow*.1D-002 !THIS HAS TO HAVE BEEN DONE ELSE WHERE
!rhosn=rhosn*(snwe/Tswe)+rhonewsn*(newsnow*.1D-002/Tswe)

!look like they adjust snwe and height for the new snow but not the density...
! what are the implications of this? MORE SNWE per same density. is increased height...but not thright...
! with my adjustment above it should be fine now... 
        snwe=snowater+.1D-002*newsnow
        snhei=snwe*.1D+004/rhosn
        !snhei=snwe*.1D+004/rhosn !not necessary and not used in this sub. just feed in snhei.
	! lem aug 2015


!IF (ITIMESTEP.lt.2) snhei=0.05!lem 12/8/2014
!we don't know timestep here. 
!lem 10/14 think this sequential order caused no new snow to form. commenting out to see the rresults.
!newly commented is !!!
!!!	if(snhei.lt..1D-003)then
	! snhei=.0D+000i ! lem aug 2015
!!!	 snwe=.0D+000
	 !snwepr1=.0D+000
!## 10_24lem	 rhosn=.350D+003
!!!	endif

!---  Incorporate soil model call here, bypassing the old sfc energy budget
!      calculation.  This is now done in soil123.
!rhosn=.333 lem 12/9/14
      IF(SNHEI.GT..0D+000) THEN	
        call soilsnow (i55,NEWSNOW,DELT,J,I, &
       TSO,ETA,F,SNWE,CN,SAT,CW,CAP,xlai, &
       DDZS,ddzsnow,DSDZ1,DQM,PC,REF,QMIN,RHOCS,PSIS, &
       BCLH,KSAT,TWST,TSQ1,TSQ2,BES,RTS,BEQ,RQS,TRANSP,RHOSN, &
       ETAF,ETAL,SOILT,RHO,S,RUNOFF1,RUNOFF2, &
       SNHEI,SNOH,ETASN,SMELT,SOILT1, &
       eacasa1,eacasa2,xroot,potwq1,wq1, &
       snowmelt,rain1,qsoref,qso0,rn1acasa,h1acasa, &
       le1acasa,soilhf,xsnodep,xsnomelt,runoffz,tsnav,i7ce, &
       soilt22,t2abs,zs2,zsnow2,zsnow1,snowmip1,snwepr1, &
       nsnow,n,in,ihi,inlyr,nsoil0,nstem,m,iminit,deltsn,zs1,iisnow)
!
        snowater=snwe
        xsnodep=snhei
        snowdens=rhosn
	if(xsnodep.lt..1D-004)snowater=.0D+000
        if(snowater.lt..1D-004)xsnodep=.0D+000
      
      ELSE 
        snwe=.0D+000
        snhei=.0D+000
        xsnomelt=.0D+000
	rainflux=.0D+000

       call soil123 (DELT,J,I,P,xlai, &
       TSO,ETA,F,SAT,CW,CAP,DDZS,ddzsnow, &
       DSDZ1,DQM,PC,REF,QMIN,RHOCS,PSIS,BCLH,KSAT, &
       TWST,TSQ1,TSQ2,BES,RTS,BEQ,RQS,TRANSP,ETAF,ETAL, &
       SOILT,RHO,RUNOFF1,RUNOFF2, &
       eacasa1,eacasa2,xroot,potwq1,wq1, &
       rain1,qsoref,qso0,runoffz,i7ce,s,soiltyp, &
       soilhf,zs2,zsnow2,zsnow1,snowmip1, &
       nsnow,n,in,ihi,inlyr,nsoil0,nstem,m,iminit,deltsn,zs1,rainflux)

    ENDIF

      RETURN
END SUBROUTINE

!!!!!!!!!!!!!!!!!!! /-\ < /-\ S /-\ !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
!
       subroutine soilsnow (i55,NEWSNOW,DELT,J,I, &
       TSO,ETA,F,SNWE,CN,SAT,CW,CAP,xlai, &
       DDZS,ddzsnow,DSDZ1,DQM,PC,REF,QMIN,RHOCS,PSIS, &
       BCLH,KSAT,TWST,TSQ1,TSQ2,BES,RTS,BEQ,RQS,TRANSP,RHOSN, &
       ETAF,ETAL,SOILT,RHO,S,RUNOFF1,RUNOFF2, &
       SNHEI,SNOH,ETASN,SMELT,SOILT1, &
       eacasa1,eacasa2,xroot,potwq1,wq1, &
       snowmelt,rain1,qsoref,qso0,rn1acasa,h1acasa, &
       le1acasa,soilhf,xsnodep,xsnomelt,runoffz,tsnav,i7ce, &
       soilt22,t2abs,zs2,zsnow2,zsnow1,snowmip1,snwepr1, &
        nsnow,n,in,ihi,inlyr,nsoil0,nstem,m,iminit,deltsn,zs1,iisnow)
     
        implicit none

	INTEGER nsnow,n,in,ihi,inlyr,nsoil0,nstem,m,iminit
        INTEGER K,K1,KN,KK, iisnow, I,J   ,i55
        INTEGER i7ce,ikk,  kday

        common /pphleck/rsm,kday

      DOUBLE PRECISION deltsn,zs1(nsoil0) 
      DOUBLE PRECISION runoffz,tsnav,epot,xxx,xfreeze
      DOUBLE PRECISION TSO(nsoil0),ETA(nsoil0), F, xlai, rsm     
      DOUBLE PRECISION SNWE,zs2(nsoil0),zsnow2(nsnow+1),zsnow1(nsnow+1)
      DOUBLE PRECISION CAP(nsoil0),QMIN,DQM,PC,REF,RHOCS,PSIS
      DOUBLE PRECISION ETAF(nsoil0),ETAL(nsoil0), BCLH,KSAT,yyy
      DOUBLE PRECISION CN,SAT,CW,ddzsnow(2*(nsnow-1))
      DOUBLE PRECISION DDZS(2*(nsoil0-2)),DSDZ1(nsoil0),RHOSN
      DOUBLE PRECISION TWST(nsoil0),TSQ1(nsoil0),TSQ2(nsoil0),BES(nsoil0),RTS(nsoil0)
      DOUBLE PRECISION BEQ(nsoil0),RQS(nsoil0),TRANSP(nsoil0)
      DOUBLE PRECISION SOILT,RHO,S,RUNOFF1,RUNOFF2, SMELT,ETASN,SOILT1(nsnow)   
      DOUBLE PRECISION SNHEI,SNOH,snoh1,soilt22(nsnow),snowmip1(100)
      DOUBLE PRECISION eacasa1,eacasa2
      DOUBLE PRECISION xroot(nsoil0),potwq1,wq1,snowmelt,rain1(3)
      DOUBLE PRECISION qsoref,qso0,rn1acasa,h1acasa,le1acasa,soilhf
      DOUBLE PRECISION X2,FT,ZN,Q2,tthresh, DDZSN,ddzsn1,ddzsn2
      DOUBLE PRECISION XLMELT,RHOICE,SNWEPR,RHOCSN,TWSTSN,xsnodep,xsnomelt 
      DOUBLE PRECISION SOH , SNOHG,SNOHGNEW, SMELTG, SNODIF, TN,xxsn, H
      DOUBLE PRECISION DID,ETAM(nsoil0),RHCS, T2ABS,X, snwepr1   
      DOUBLE PRECISION INFMAX ,PRCIP, NEWSNOW, RIW, TAV(nsoil0)
      DOUBLE PRECISION DELT, tsob, tavln,XSN1,xsn2
      DOUBLE PRECISION DETAL(nsoil0),CI, besplus(101),rtsplus(101)
      DOUBLE PRECISION A,ETAMF(nsoil0),ETAML(nsoil0),WS,FACH,FACD
!Variables eg constants added for clarity lem aug 2015
      DOUBLE PRECISION c_snw, lfw
           !specific heat of snow in J kg-1 C-1i
           !lfw=latent heat of fusion for water 333500 J kg -1

!-- for non-linear root distribution
!-- for Johansen thermal conductivity
      DOUBLE PRECISION kqwrtz,qwrtz,kzero,gamd,kdry,kas,x5,sr,ke
      DOUBLE PRECISION kasat(nsoil0), kjpl(nsoil0), kice,kwt
      DOUBLE PRECISION CP,X4,Q4,X1,DSDZ2

!ADDITIONAL VARIABLES FOR OLD TQSNOW SUBROUTINE
        DOUBLE PRECISION RUNOFF, D14NEW, INFMAX1,DDT,PX
        DOUBLE PRECISION F1MAX,F2MAX,F1,F2,FD,KDT,VAL
        DOUBLE PRECISION DWILT,D3,D4,D12,D13,D14,DZS,D16,QQ

!variables for my test lem 12.15.14
	DOUBLE PRECISION SMELT27, SMAX7, SMIN7, xday7


!!! ! lem 10/14/2015     if (snwe.lt.1D-004.or.snhei.lt.1D-003) then
 ! !!      snwe=newsnow.
 !   !!SNHEI=newsnow/RHOSN

!        snhei= swe/333.0
!!else
!!end if
    c_snw=.209D+004 !specific heat of snow in J kg-1 C-1
	 Lfw=0.3335D+006 !lfw=latent heat of fusion for water 333500 J kg -1 previously !XLMELT=.3335D+006

        epot=potwq1*.1D-002 
!-- the next line calculates heat of sublimation of water vapor
        CP=.10046855D+004
!-- Constants for Johansen (1975) thermal conductivity
        kqwrtz=.77D+001      
        kice  =.22D+001   
        kwt   =.57D+000
        qwrtz =.6D+000      ! for sandy loam1        
	kzero =.2D+001       
! if qwrtz > 0.2
     
!*** zsnow is the depth of the top layer of snow where
!*** there is a temperature gradient, the rest of the snow layer
!*** is considered to have constant temperature
        do k=1,nsoil0
	 bes(k)=.0D+000
	 rts(k)=.0D+000
	enddo
	do k=1,101
         besplus(k)=.0D+000
	 rtsplus(k)=.0D+000
	enddo
!
        RHOICE=.90D+003
        CI=RHOICE*.210D+004!Specific heat ice - 2.108 kJ/kgK so that is J/kg K lem aug 2011
        SOH=.0D+000
        SMELTG=.0D+000
        SMELT=.0D+000
        SNOHG=.0D+000
        SNODIF=.0D+000
        DSDZ2=.10D+001/(ZS1(2)-ZS1(1))
        DO K=1,NSOIL0  
          TRANSP(K)=.0D+000
          DETAL (k)=.0D+000
          etaf  (k)=.0D+000
          etamf (k)=.0D+000
          kasat (k)=.0D+000
          kjpl  (k)=.0D+000
        ENDDO
        
!----- THE CALCULATION OF THERMAL DIFFUSIVITY, DIFFUSIONAL AND ---
!----- HYDRAULIC CONDUCTIVITY (SMIRNOVA ET AL. 1996? EQ.2,5,6) ---
!tgs - the following loop is added to define the amount of frozen
!tgs - water in soil if ther is any
         DO K=1,(NSOIL0-1)
         tav(k)=.50D+000*(tso(k)+tso(k+1))
         etam(k)=.50D+000*(eta(k)+eta(k+1))
         tavln=log(tav(k)/.273150D+003)
         if((log(tso(k)/.273150D+003)).lt..0D+000) then
           etal(k)=(dqm+qmin)*(.3352D+008* &
        (tso(k)-.273150D+003)/tso(k)/.9806650D+001/psis) &
         **(-.10D+000/bclh)-qmin
           etal(k)=max(.1D-014,etal(k))
           etal(k)=min(etal(k),eta(k))
           etaf(k)=(eta(k)-etal(k))*.10D+004/rhoice
         else
           etaf(k)=.0D+000
           etal(k)=eta(k)
         endif
         if(tavln.lt..0D+000) then
           etaml(k)=(dqm+qmin)*(.33520D+008* &
        (tav(k)-.273150D+003)/tav(k)/.9806650D+001/psis) &
         **(-.10D+001/bclh)-qmin
!rdp 21 July 2011           etaml(k)=max(.1D-014,etaml(k))
           etaml(k)=max(.5D-001,etaml(k))
           etaml(k)=min(etaml(k), etam(k))
           etamf(k)=(etam(k)-etaml(k))*.10D+004/rhoice
         else
           etamf(k)=.0D+000
           etaml(k)=etam(k)
         endif
         ENDDO
         
        etal(nsoil0)=eta(nsoil0)
	         
!--- Calculation of thermal conductivity and volumetric
!--- heat capacity
           ws=DQM+QMIN
           RIW=rhoice*.1D-002
           X1=lfw/(.9806650D+001*PSIS)!XLMELT/(.9806650D+001*PSIS)
           X2=X1/BCLH*(DQM+QMIN)
           X4=(BCLH+.10D+001)/BCLH
!--- Next 3 lines are for Johansen thermal conduct.
           gamd=(.10D+001-ws)*.270D+004
           xxx=.270D+004-.9470D+000*gamd
           call protect(xxx,.1D-014)
           kdry=(.135D+000*gamd+.6470D+002)/(xxx)
           kas=kqwrtz**qwrtz*kzero**(.10D+001-qwrtz)
         DO K=1,(NSOIL0-1)
           TN=TAV(K) - .273150D+003
           IF(ETAMF(k).NE..0D+000.AND.TN.LT.-.1D-003) then
            DETAL(K)=.27315D+003*X2/(TAV(K)*TAV(K))* &
                    (TAV(K)/(X1*TN))**X4
           endif
!
!--- Next 10 lines calculate Johansen thermal conductivity KJPL
           kasat(k)=kas**(.1D+001-ws)*kice**(riw*etamf(k)) &
                   *kwt**(etaml(k)+qmin) &
                   *.260D-001**(dqm-etam(k))
           X5=(etam(k)+qmin)/ws
         if(etamf(k).eq..0D+000) then
           sr=max(.101D+000,x5)
           ke=log10(sr)+.10D+001
!--- next 2 lines - for coarse soils
!           sr=max(.501D-001,x5)
!           ke=.7D+000*log10(sr)+.1D+001
         else
           ke=x5
         endif
	xxx=.1D+001
           kjpl(k)=xxx*(ke*(kasat(k)-kdry)+kdry)
!
!--- CAP -volumetric heat capacity
!KC
         CAP(K)=xxx*((.1D+001-DQM-QMIN)*RHOCS+(ETAML(K)+qmin)*(CW*.1D+004) &
                 + ETAMF(K)*CI- DETAL(K)*.1D+004*lfw)!xlmelt)
!         CAP(K)=xxx*((.1D+001-DQM-QMIN)*RHOCS+(ETAML(K)+qmin)*(CW) &
!                 + ETAMF(K)*CI- DETAL(K)*.1D+004*lfw)!xlmelt)
!KC end
!cw times 1000 to match previous units!
        if(i7ce.eq.1)then !sea ice thermal cond. and vol. heat capacity
         cap(k)=.196D+007   
         kjpl(k)=.250D+001 ! for sea ice
        endif
!--- Calculation of hydraulic and diffusional conductivities
        if((ws-riw*etamf(k)).lt..12D+000) then
           TSQ2(K)=.0D+000
           TSQ1(K)=.0D+000
        else   
           a=RIW*ETAMF(K)
           xxx=dqm-a
           call protect(xxx,.1D-004)
           H=max(.0D+000,ETAML(K)/(xxx))
           fach=.1D+001
           facd=.1D+001
          if(etaf(k).ne..0D+000)fach=.1D+001-riw*etaf(k)/eta(k)
          if(a.ne..0D+000) facd=.10D+001-a/(etam(K)+.1D-020)
          TSQ2(K)=KSAT/(dqm-riw*etaf(k))*(ETAL(K)/ &
                 (abs(dqm-riw*etaf(k)))+.1D-020)**(.2D+001*BCLH+.2D+001)* fach
          TSQ1(K)=-BCLH*KSAT*PSIS*.1D+001/ &
                (dqm-riw*etamf(k))* &
                (abs(dqm/(dqm-riw*etamf(k)))+.1D-020)**.3D+000 &
                *H**(BCLH+.2D+001)*facd
        endif

         
!--- TWST - thermal diffusivity
!           TWST(K)=HK(K)/CAP(K)
!--- Use thermal conductivity from Johansen (1975)
            TWST(K)=KJPL(K)/CAP(K)
           
         END DO
         wq1=potwq1
       TSQ2(nsoil0)=KSAT/DQM*(ETA(nsoil0)/DQM)**(.2D+001*BCLH+.2D+001)
       INFMAX=.999D+003
       if((ws-riw*etamf(1)).lt..12D+000) INFMAX=.0D+000
!
        RHCS=CAP(1)
        TN=SOILT-.27315D+003
        RHOCSN=c_snw* RHOSN
        TWSTSN= .280D+000/rhocsn
        SMELT=.0D+000
        H=.10D+000

! facasa after d3 = 1.-d29 
        do k=1,nsoil0
         transp(k)=-xroot(k)
        enddo 
! facasa
!  check if all snow can evaporate during DT
        SNHEI=SNWE*.10D+004/RHOSN
        !SNWEPR=SNWE

!  check if all snow can evaporate during DT
        IF(SNWE.LE.(EPOT*DELT+.1D-024))THEN ! IF(SNWEPR.LE.(EPOT*DELT+.1D-024))THEN
         !   SNWE=.0D+000
           
 SNHEI=.0D+000
         Endif
!C******************************************************************************
!       COEFFICIENTS FOR THOMAS ALGORITHM FOR TSO
!******************************************************************************
        BES(1)=.0D+000
        RTS(1)=TSO(nsoil0)
        DO  K=1,(NSOIL0-2)
          KN=NSOIL0-K  
          K1=2*KN-3
          X1=DDZS(K1)*TWST(KN-1)
          X2=DDZS(K1+1)*TWST(KN)
          FT=TSO(KN)+X1*(TSO(KN-1)-TSO(KN))-X2*(TSO(KN)-TSO(KN+1))
          ZN=.10D+001+X1+X2-X2*BES(K)
          call protect(zn,.1D-004)
          BES(K+1)=X1/ZN
          RTS(K+1)=(FT+X2*RTS(K))/ZN
	END DO
 !  33  CONTINUE 
! do snow temps before solving for soil/ice temps       
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
! snowsnowsnowsnowsnowsnowsnowsnowsnowsnowsnowsnowsnowsnowsnowsnowsnow
! svensvensvensvensvensvensvensvensvensvensvensvensvensvensvensvenaven
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
! THE NZS element in BES and RTS will be for snow
! There will be 2 layers in snow if it is deeper than zsnow1(i)+SNTH
	do i=1,nsnow+1
	 zsnow1(i)=.5D-001*dble(float(i-1))	
         zsnow2(i)=.5D-001*dble(float(i-1))	
	enddo
!
	iisnow=1!feck
       IF(SNHEI.gt..1D-014) then
        if(snhei.le.zsnow1(2)) then
	iisnow=1!feck
!
!-- 1-layer snow model for shallow snowpack
!
!lem 9.18.15	 snowmip1(6)=.10D+001
         IF(SNHEI.GT..1D-014)then
          XSN1 = DELT/.20D+001/(ZS2(2)+.50D+000*SNHEI)
          DDZSN = XSN1 / SNHEI
          X1 = DDZSN * TWSTSN
          X2 = DDZS(1)*TWST(1)
          FT = TSO(1)+X1*(SOILT-TSO(1)) &
             -X2*(TSO(1)-TSO(2))
          ZN = .10D+001 + X1 + X2 -X2*BES((NSOIL0-1))
          call protect(zn,.1D-014)
         call protect(zn,.1D+000)
          BES(nsoil0)=X1/ZN
          RTS(nsoil0)=(FT+X2*RTS((NSOIL0-1)))/ZN
         else
          XSN1 = DELT/2.0D+001/(ZS2(2)+.50D+000*SNHEI)
          DDZSN = XSN1 / (.2D-001)	!(SNHEI+.1D-011)
          X1 = DDZSN * TWSTSN
          X2 = DDZS(1)*TWST(1) 
          FT = TSO(1)+X1*(SOILT-TSO(1)) &
             -X2*(TSO(1)-TSO(2))   
          ZN = .10D+001 + X1 + X2 -X2*BES((NSOIL0-1))
         call protect(zn,.1D-003)
          BES(nsoil0)=X1/ZN
          RTS(nsoil0)=(FT+X2*RTS((NSOIL0-1)))/ZN
         endif
          besplus(1)=bes(nsoil0)
          rtsplus(1)=RTS(nsoil0)
          besplus(2)=bes(nsoil0)   
          rtsplus(2)=RTS(nsoil0)
        endif
!
!-- 2 layers in snow for slightly heavier snowpacks
!
        if(zsnow1(2).lt.snhei)then
	iisnow=2!feck
         if(nsnow.gt.2)then
          if(snhei.gt.zsnow1(3))go to 888
         endif
!lem 9.18.15	 snowmip1(6)=.20D+001
         XSN1 = DELT/.20D+001/(.50D+000*SNHEI)
         XSN2= DELT/.20D+001/(ZS2(2)+.50D+000*(SNHEI-zsnow1(2)))
         DDZSN1 = XSN1 / zsnow1(2)
         DDZSN2 = XSN2 / (max(SNHEI-zsnow1(2),.2D-001))
         Xsn1 = DDZSN1 * TWSTSN
         Xsn2 = DDZSN2 * TWSTSN   
         X2 = DDZS(1)*TWST(1)
         FT = TSO(1)+XSN2*(SOILT1(1)-TSO(1)) &
             -X2*(TSO(1)-TSO(2))         
	 ZN = .10D+001 + xsn2 + X2 - X2*BES((NSOIL0-1))
         call protect(zn,.1D-003)
         BES(nsoil0)=XSN2/ZN   
         RTS(nsoil0)=(FT+X2*RTS((NSOIL0-1)))/ZN
         FT = SOILT1(1)+XSN1*(SOILT-SOILT1(1)) &
              -XSN1*(SOILT1(1)-TSO(1))
         ZN = .10D+001 + XSN1 + XSN2 - XSN2*BES(nsoil0)
         call protect(zn,.1D-003)
         BESPLUS(1)=XSN1/ZN  
         RTSPLUS(1)=(FT+XSN2*RTS(nsoil0))/ZN
        endif
!
!-- 3 to 100 layers in snow; depending on snowpack depth and
! choice of zsnow1 values. these next lines perform the implicit
! solution (thomas) for diffusion equation
!
 888    continue
	if(nsnow.eq.2)go to 669
        if(zsnow1(3).lt.snhei)then ! possibility for multiple snow layers
!
! set iisnow for multiple snow layers; iisnow is for looping the
! thermal diffusion equation for snow
!
         iisnow=3

         do ikk=3,nsnow-1
          if(zsnow1(ikk).lt.snhei.and.snhei.le.zsnow1(ikk+1)) &
          iisnow=ikk
         enddo
         if(zsnow1(nsnow).lt.snhei)iisnow=nsnow
!lem 9.18.15	 snowmip1(6)=float(iisnow)
!
! the uppermost soil(ice)/lowermost snow layer:
!
         k1=1
         xsn1=ddzsnow(k1)*twstsn
         xsn2=ddzsnow(k1+1)*twstsn
         X2 = DDZS(1)*TWST(1)
         FT = TSO(1)+Xsn2*(SOILT1(iisnow)-TSO(1)) &
             -X2*(TSO(1)-TSO(2))
         ZN = .10D+001 + XSN2 + X2 - X2*BES((NSOIL0-1))
         call protect(zn,.1D-003)
         BES(nsoil0)=XSN2/ZN
         RTS(nsoil0)=(FT+X2*RTS((NSOIL0-1)))/ZN
         FT = soilt1(iisnow)+XSN1* &
             (SOILT1(iisnow-1)-soilt1(iisnow)) &
             -XSN2*(soilt1(iisnow)-TSO(1))
         ZN = .10D+001 + XSN1 + XSN2 - XSN2*BES(nsoil0)
         call protect(zn,.1D-003)
         BESPLUS(1)=XSN1/ZN
         RTSPLUS(1)=(FT+XSN2*RTS(nsoil0))/ZN
!
! now the internal layers
! 
! check value of twstsn; eventually want to vary snowpack density w/ height
!
         do k=1,iisnow-2
          kn=iisnow-k
          k1=2*kn-3
          x1=ddzsnow(k1)*twstsn
          x2=ddzsnow(k1+1)*twstsn
          FT=soilt1(KN)+X1*(soilt1(KN-1)-soilt1(KN)) &
            -X2*(soilt1(KN)-soilt1(KN+1))
          ZN=.10D+001+X1+X2-X2*besplus(K)
          call protect(zn,.1D-014)
          besplus(K+1)=X1/ZN
          rtsplus(K+1)=(FT+X2*rtsplus(K))/ZN

         enddo
!
! the uppermost snow layer
!
         kn=iisnow-1
         k1=2*kn-3
         x1=ddzsnow(k1)*twstsn
         x2=ddzsnow(k1+1)*twstsn
         FT=SOILT1(1)+x1*(SOILT-SOILT1(1)) &
              -x2*(SOILT1(1)-soilt1(2))
         ZN=.10D+001 + x1 + x2 - x2*BESPLUS(iisnow-1)
         call protect(zn,.1D-014)
         BESPLUS(iisnow)=X1/ZN
         RTSPLUS(iisnow)=(FT+X2*RTSPLUS(iisnow-1))/ZN
!
        endif         
 669   continue
!
! now solve for snow layer temperatures
!-- up to nsnow-layer snow model; iisnow layers are active
!
        if(nsnow.lt.3)go to 671
         if(zsnow1(3).lt.snhei)then ! multiple snow layers
!---- Final calculation for snow t
          DO K=2,iisnow ! or just nsnow
            KK=IISNOW-K+1
            soilt1(K)=rtsplus(KK)+besplus(KK)*soilt1(K-1)
          ENDDO
          SOILT1(1)=RTSPLUS(iisnow)+BESPLUS(iisnow)*SOILT
! rdp january 2013: setting soil surface temperature tso(1) to the bottom snowpack temperature soilt22(bottom) 
!    to allow for proper diffusion across the snow-ice interface. 
          TSO(1)=soilt1(iisnow)  
          tsob=soilt1(1)
          if(iisnow.lt.nsnow)then
           do k=iisnow+1,nsnow
            soilt1(k)=soilt1(iisnow)
           enddo
          endif
         endif
 671     continue
!
          SOILT1(1)=RTSPLUS(1)+BESPLUS(1)*SOILT
          TSO(1)=soilt1(iisnow)  
! rdp january 2013: setting soil surface temperature tso(1) to the bottom snowpack temperature soilt22(bottom) 
!    to allow for proper diffusion across the snow-ice interface. 
          tsob=soilt1(1)
        if(nsnow.eq.2.and.zsnow1(2).lt.snhei) then
!-- 2-layer snow model; all layers active
          iisnow=2
          SOILT1(1)=RTSPLUS(1)+BESPLUS(1)*SOILT
! rdp january 2013: setting soil surface temperature tso(1) to the bottom snowpack temperature soilt22(bottom) 
!    to allow for proper diffusion across the snow-ice interface. 
          TSO(1)=soilt1(iisnow)  
          tsob=soilt1(1)
          do k=iisnow,nsnow
           soilt1(k)=soilt1(iisnow-1)
          enddo
        endif

        if(snhei.le.zsnow1(2)) then
!-- 1 layer in snow
          iisnow=1
! rdp january 2013: setting soil surface temperature tso(1) to the bottom snowpack temperature soilt22(bottom) 
!    to allow for proper diffusion across the snow-ice interface. 
          TSO(1)=soilt1(iisnow)  
          SOILT1(1)=TSO(1)
          tsob=tso(1)
          do k=iisnow,nsnow
           soilt1(k)=soilt1(1)
          enddo
        endif
       ELSE
	do k=1,nsnow
	 soilt1(k)=min(soilt1(k),.27315D+003)
	enddo
!-- no snow
         iisnow=1
         TSO(1)=SOILT
         do k=1,nsnow
          SOILT1(k)=.27315D+003! set snowpack temperature array to default value
         enddo
       ENDIF
!
!C************************************************************************

!lem aug 2015
!IF(SNHEI.GT..1D-014) xxx=max(snhei-zsnow1(2),.2D-001)! no effect because x is recaculated below.
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
! snowsnowsnowsnowsnowsnowsnowsnowsnowsnowsnowsnowsnowsnowsnowsnowsnow
! svensvensvensvensvensvensvensvensvensvensvensvensvensvensvensvenaven
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!---- Final calculation for TSO
          DO K=2,NSOIL0
            KK=NSOIL0-K+1
            TSO(K)=RTS(KK)+BES(KK)*TSO(K-1)  
          END DO

!-- recalculating of frozen water in soil
         DO K=1,NSOIL0
         if((log(tso(k)/.273150D+003)).lt..0D+000) then
           etal(k)=(dqm+qmin)*(.33520D+008* &
        (tso(k)-.273150D+003)/tso(k)/.9806650D+001/psis) &
         **(-.10D+001/bclh)-qmin
           etal(k)=max(.0D+000,etal(k))
           etal(k)=min(etal(k),eta(k))
           etaf(k)=(eta(k)-etal(k))*.10D+004/rhoice
         else
           etaf(k)=.0D+000
           etal(k)=eta(k)
         endif
         ENDDO
!calculate SNOH, latent heat flux density (fusion) of snow phase change Wm-2
         xxx=max(snhei-zsnow1(2),.2D-001)
         SOH=TWSTSN*RHOCSN*(.273150D+003-TSOB)/xxx! change in stored heat (thermal)
         X= .0D+000! X is replaced with -h1acasa-le1acasa
!
!-- SNOH is energy flux of snow phase change(melt only)
!
!!TEST LEM 11.6        SNOH=max(.0D+000,(rn1acasa-h1acasa-le1acasa) & 			!air-to-surface flux density Wm-2
        SNOH=((rn1acasa-h1acasa-le1acasa) &                  !air-to-surface flux density Wm-2
        +c_snw*NEWSNOW/DELT*(min(T2ABS-.273150D+003,.0D+000)) &	!newsnow flux dens. Wm-2
        -SOH &								!change in internal heat (thermal) flux dens Wm-2
        +CW*rain1(1)*(t2abs-.273150D+003)) 			! rain-introduced energy flux dens. Wm-2; like snoh but includes includes refreezing potential & surface
!write(*,*)snoh
snowmip1(78)=snoh
! rdp 2 november 2012: snoh, which acts at the surface,  is only gonna melt the snow when the snowpack surface is at the melting point!!!
! rdp revisited this january 2013 and found there to be trouble unless i55 was passed through. i55=1 --> ground surface specific.
!
	tthresh=.273D+003					! melt point / snow over land -0.15 K
	if(i7ce.eq.1)tthresh=.272D+003				! melt point depression, snow over sea ice; 272.
!
	if(i55.eq.1.and.soilt22(1).lt.tthresh)snoh=.0D+000	! allow snow to melt if T_snowsurface > = 271.65 K
	if(i55.eq.1.and.soilt22(1).lt.tthresh)snoh=.0D+000	! allow snow to melt if T_snowsurface > = 271.65 K
!-- SMELT is speed of melting in M/S
        SMELT=.1D-002*(SNOH)/lfw!XLMELT
!lem 9.18.15!snowmip1(78)=smelt
!
! snowpack water refreezing section...
!
! from Koren et al. (1999) 13% of snow melt stays in snow pack
! multiply this concept with xfreeze, the fraction of existing 
! water that can freeze which can vary depending upon 
! thermodynamic state of the snowpack.  (by extension the 87% leftover 
! meltwater goes out of snowpack before refreezing takes place
! and ends up as runoff and/or soil water &/or ice
!
        xfreeze=.0D+000   			! fraction snowpack water that can refreeze
	xxx=.0D+000
	yyy=.0D+000
        if(smelt.gt..0D+000)then		! melt!
         xxx=.10D+004*.130D+000*smelt*lfw*delt!xlmelt*delt	! Korens 13% rule
         call protect(xxx,.1D-009)
         yyy=min(tsnav-.273150D+003,.0D+000)*c_snw*snwe! refreezing fraction if snowpack goes cool
         xfreeze=abs(yyy/xxx)
        endif
        xfreeze=min(xfreeze,.1D+001)	! cant do more than 100%
        xfreeze=max(xfreeze,.0D+000)	! no less than zero
        rsm=xfreeze*smelt*delt		! reverse (< 0) snow melt amount
        smelt=smelt-rsm/delt		! adjust snow melt rate (it can go to 0!)
!test feb 2
!smelt=smelt*1.5        
SNOH=SMELT*lfw*.10D+004!XLMELT*.10D+004		! final snow latent 
!
! surface component is done...
!
! adjust snow water equivalent due to above melt rate plus evaporation
  !!!!  !   Epot=epot*.25 
        SNWE=max(SNWE-(SMELT+EPOT)*DELT,.0D+000) !max(SNWEPR-(SMELT+EPOT)*DELT,.0D+000)
!SNWE=max(SNWEPR-(SMELT+EPOT)*DELT,.0D+000)
!write(*,*)"ground smelt, epot", smelt, epot

!
        if(snwe.le..1D-014)then
         smelt=smelt+rsm/delt
         rsm=.0D+000! no refreezing back into snow possible if all snow melts...
        endif

!--  Snow melt from the top is done. But if ground surface temperature
!--  is above freezing snow can melt from the bottom. The following
!--  piece of code will check if bottom melting is possible.
! 
	smeltg=.0D+000
	snohg=.0D+000
	snohgnew=.0D+000
	snodif=.0D+000
	xxx=snhei
	yyy=.10D+001
!
	if(snhei.gt.deltsn)xxx=deltsn
        IF(TSO(1).GE..273150D+003.AND.SNWE.Gt..1D-014) THEN
        SNOHG=(TSO(1)-.273150D+003)*(RHCS*ZS2(2)+RHOCSN*.50D+000*xxx) &
             /DELT! snow-ground heat flux dens (Wm-2)
        SMELTG=SNOHG/lfw*.1D-002!XLMELT*.1D-002!mass flux (*meters* of h2o)(m-2 s-1)
        SMELTG=MIN(SMELTG,SNWE/DELT)!cant do more than whats there
        SNOHGNEW=SMELTG*lfw*.10D+004!XLMELT*.10D+004!recalculate mass flux m m-2 s-1
        SNODIF=MAX(.0D+000,SNOHG-SNOHGNEW)
        TSO(1)=SNODIF*DELT/(RHCS*ZS2(2)+RHOCSN*.50D+000*xxx) &
                  +.273150D+003
        SNWE = MAX(.0D+000,SNWE-SMELTG*DELT)!*.5
      SMELT=(SMELT+SMELTG)! adjust snow melt rate m m-2 s-1
        SNOH=SNOH+SNOHGNEW! adjust snow phase change heat flux Wm-2
       ENDIF
!	snwe=.02
! snow-ground heat flux dens (Wm-2)
! correct snow density from effect of snow melt refreezing portion
!## LEM.10.24
!lem 12/9/14 inteserted this back in ....
!	if(delt.lt..20D+001)then
!         SNWE = SNWEPR
!	endif


!the below never went here, just using it chnage smelt and try some things out
!lem 12.15.14
SMAX7=.2605D+001
SMIN7=.255D+001
!9.18.15 xday7=snowmip1(27)

!all of the below is wrong, good to knwo snowmip can be used to carry across vars
!initial units are mm/day/C so divide by 24*60*60 then account for timestep
!SMELT27=(SMAX7+SMIN7)/.2D+001+SIN(xday7-0.81D+002/0.5809D+002)*((SMAX7-SMIN7)/.2D+001)
!smelt26=smelt27/.86400D+5/delt*.1d+002

!smelt27=.37D+001*(t2abs-.27315D+003)*.29398D-008
!
! SNWE=max(SNWEPR-(SMELT27+EPOT)*DELT,.0D+000)
!when i do this here i don't get the right snow height and snow densites around 200
!THE PLACEMENT HERE MAKES ALSO THE SNOW DISAPPEAR FIGURE IT OUT. OR JUST MEANS SMELT IS TOO LARGE
!write(6,*) "smelt", smelt
!write(6,*) "smelt27", smelt27
!write(6,*) xday7


        IF(SNWE.gt..1D-014) THEN
         xxsn=(rhosn*(snwe-rsm)+.1D+004*rsm)/snwe! refreezing water stays in as 1:1 ice
!         rhosn=min(xxsn,.350D+003) 
         rhocsn=c_snw*rhosn
         twstsn=.280D+000/rhocsn
!         snwe=max(snwe,.0D+000)
!         SNHEI=SNWE*.10D+004/RHOSN
         xsnodep=snhei
         !xsnomelt=smelt
       endif

!!!!!putting the above section back in only made minor changes to rhosn swe and epth but might be important for later claculations...
!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!

  !      snowmelt=smelt26     		! snow melt rate in m/s


!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
! end snowsnowsnowsnowsnowsnowsnowsnowsnowsnowsnowsnowsnowsnowsnowsnowsnow
!       COEFFICIENTS FOR THOMAS ALGORITHM FOR ETA
!******************************************************************************

        DID=(ZS1(nsoil0)-ZS2(nsoil0))*.20D+001 
        X1=ZS1(nsoil0)-ZS1((NSOIL0-1))
        ZN=(.10D+001+TSQ1((nsoil0-1))/X1/DID*DELT+TSQ2(nsoil0)/(.20D+001*DID)*DELT)
        call protect(zn,.1D-003)
        BEQ(1)=DELT*(TSQ1((nsoil0-1))/DID/X1 +TSQ2((NSOIL0-1))/.20D+001/DID)/ZN
        RQS(1)=(ETA(nsoil0)+TRANSP(nsoil0)*DELT/DID)/ZN
        
        DO K=1,(NSOIL0-2)   
          KN=NSOIL0-K
          K1=2*KN-3
          X4=.20D+001*DDZS(K1)*TSQ1(KN-1)
          X2=.20D+001*DDZS(K1+1)*TSQ1(KN)
          Q4=X4+TSQ2(KN-1)*DSDZ1(KN-1)
          Q2=X2-TSQ2(KN+1)*DSDZ1(KN-1)
          ZN=.10D+001+X2+X4-Q2*BEQ(K)
          call protect(zn,.1D-003)
          BEQ(K+1)=Q4/ZN   
      RQS(K+1)=(ETA(KN)+Q2*RQS(K) &
                  +TRANSP(KN) &
                  /(ZS2(KN+1)-ZS2(KN)) &
                  *DELT)/ZN
end do

!*************************************************************************
!--- tqcan FOR SOLUTION OF MOISTURE BALANCE EQ.22,28 AND TSO,ETA PROFILES
!   moisture balance equation is solving here and
!   final calculation for heat and moisture transfer equations
!!**************************************************************************************
!        SUBROUTINE tqsnow(BEQ,RQS,TSQ1,TSQ2,DELT,ETA, &

          RUNOFF=.0D+000
          RUNOFF2=.0D+000
          DZS=ZS1(2)
          X1=TSQ1(1)/DZS
          D12=X1+TSQ2(1)*.50D+000
          D13=X1-TSQ2(2)*.50D+000
!tgs D8=0. because there is no evaporation from snow_soil interface.
!tgs soil moisture. Transpiration may still effect the soil moisture
!tgs if the canopy is not saturated.
          D14=-rain1(1)*.10D+002-SMELT
!-- SCHAAKE/KOREN EXPRESSION for calculation of max infiltration
         DWILT=DQM-.5D+000*.9D+000*(etaf(1)+etaf(2))
         call protect(dwilt,.1D-019)
         F1MAX=DWILT*ZS2(2)
         F2MAX=DWILT*(ZS2(3)-ZS2(2))
         F1=F1MAX*(.1D+001-(ETA(1)-.9D+000*etaf(1))/DWILT)
         F2=F2MAX*(.1D+001-(ETA(2)-.9D+000*etaf(2))/DWILT)
         FD=F1+F2
         KDT=.1*KSAT/(.34341D-005)
         VAL=(.1D+001-EXP(-KDT*SQRT(DELT/.865)))
         DDT = FD*VAL
         PX=-D14 * DELT
         IF(PX.LT..0D+000) PX = .0D+000
         IF(px.eq..0D+000.or.ddt.eq..0D+000) then
            infmax1=.0D+000   
         else
            xxx=px+ddt
            call protect(xxx,.1D-014)
            INFMAX1 = (PX*(DDT/(xxx)))/DELT
            INFMAX1 = MIN(INFMAX1, KSAT)
        endif
         INFMAX = MIN(INFMAX,INFMAX1)
          IF (-D14.GE.INFMAX)THEN 
            RUNOFF=-D14-INFMAX
            D14=-INFMAX
          ENDIF
! PRCIP is total infiltration flux in M/S
          PRCIP=D14
          D12=D12+(.50D+000*DZS/DELT)
          D14=D14-ETA(1)*(.50D+000*DZS/DELT)
          Q2=eacasa2
          D16=TRANSp(1)
          xxx=d12-BEQ(nsoil0-1)*d13
          call protect(xxx,.1D-014)
          QQ=(RQS(nsoil0-1)*D13-D14+D16)/(xxx)
          D14NEW=-DQM*(xxx)+D13*RQS(nsoil0-1)+D16 
          IF(QQ.LT..0D+000) THEN
              ETA(1)=.5D-001
             ELSE IF(QQ.GT.DQM) THEN
             ETA(1)=max(DQM,.5D-001)
            RUNOFF=RUNOFF+(D14NEW-D14)  
            ELSE
            ETA(1)=QQ
          END IF

!--- FINAL SOLUTION FOR ETA
          DO K=2,nsoil0
            KK=nsoil0-K+1
            QQ=BEQ(KK)*ETA(K-1)+RQS(KK)
           IF (QQ.LT..0D+000) THEN
              ETA(K)=.50D-001
           ELSE IF(QQ.GT.DQM) THEN
             ETA(K)=max(DQM,.5D-001)
             IF(K.EQ.nsoil0)THEN
                RUNOFF2=RUNOFF2+(QQ-DQM)*(ZS1(K)-ZS2(K))
               ELSE
                RUNOFF2=RUNOFF2+(QQ-DQM)*(ZS2(K+1)-ZS2(K))
             ENDIF 
           ELSE
            ETA(K)= max(QQ,.5D-001)
           END IF
          END DO
          runoffz=runoff



!           RETURN
! 	END SUBROUTINE

        s=(TWST(1)*RHCS*DSDZ2)*(tso(1)-tso(2))! always interpret G as the same even when snow is on top of 
        if(iisnow.lt.2)then
!
! RDP january 2013: make sure G is G no matter what is on the ground. not doing this made G get replaced with "sub-surface G"
! which just won't do.
! s --> s_snow (for g is at the blank-air interface.  s_surface, which is s nonsnow and s_snow when snow is present...
	 s=(TWST(1)*RHCS*DSDZ2)*(soilt22(1)-tso(1))! always interpret G as the same even when snow is on top of 
        else
	 s=(TWST(1)*RHCS*DSDZ2)*(soilt22(1)-soilt22(2))! always interpret G as the same even when snow is on top of 
	endif

!	soil...those energy dynamics are handled elsewhere (in subroutine soilsnow)
!       transmation:  G flows from the ground into (+) or from (-) the snow.
!
        soilhf=s		! soilhf is G...G is now always located at the surface-air boundary, where it affects the energy budget at 
!				"node 1".
      RETURN
	END SUBROUTINE

!!!!!!!!!!!!!!!!!!! /-\ < /-\ S /-\ !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
!!!!!!!!!!!!!!!!!!! /-\ < /-\ S /-\ !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
!!!!!!!!!!!!!!!!!!! /-\ < /-\ S /-\ !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
       subroutine soil123 (DELT,J,I,P,xlai, &
      TSO,ETA,F,SAT,CW,CAP,DDZS,ddzsnow, &
      DSDZ1,DQM,PC,REF,QMIN,RHOCS,PSIS,BCLH,KSAT, &
       TWST,TSQ1,TSQ2,BES,RTS,BEQ,RQS,TRANSP,ETAF,ETAL, &
      SOILT,RHO,RUNOFF1,RUNOFF2, &
      eacasa1,eacasa2,xroot,potwq1,wq1, &
      rain1,qsoref,qso0,runoffz,i7ce,s,soiltyp, &
      soilhf,zs2,zsnow2,zsnow1,snowmip1, &
        nsnow,n,in,ihi,inlyr,nsoil0,nstem,m,iminit,deltsn,zs1,rainflux)
           
      implicit none
      INTEGER nsnow,n,in,ihi,inlyr,nsoil0,nstem,m,iminit
      DOUBLE PRECISION deltsn,zs1(nsoil0)
!

      DOUBLE PRECISION runoffz,soilhf,xxx ,rainflux 

!             
      INTEGER K,K1,KN, i7ce
      INTEGER I,J,ITEST,JTEST,KK
!
      DOUBLE PRECISION P,TSO(nsoil0),ETA(nsoil0), F,soiltyp,s,xlai
      DOUBLE PRECISION CAP(nsoil0),QMIN,DQM,PC,REF,RHOCS,PSIS
      DOUBLE PRECISION BCLH,KSAT,ETAF(nsoil0),ETAL(nsoil0)
      DOUBLE PRECISION SAT,CW,DDZS(2*(nsoil0-2)),DSDZ1(nsoil0)
      DOUBLE PRECISION TWST(nsoil0),TSQ1(nsoil0),TSQ2(nsoil0),BES(nsoil0),RTS(nsoil0) 
      DOUBLE PRECISION BEQ(nsoil0),RQS(nsoil0),TRANSP(nsoil0)
      DOUBLE PRECISION SOILT,ddzsnow(2*(nsnow-1)),RHO,RUNOFF1,RUNOFF2
      DOUBLE PRECISION zs2(nsoil0),zsnow2(nsnow+1),zsnow1(nsnow+1)
      DOUBLE PRECISION eacasa1,eacasa2
      DOUBLE PRECISION xroot(nsoil0),potwq1,wq1,rain1(3),qsoref,qso0
      DOUBLE PRECISION CP,X4,Q4,X1,DSDZ2,X2,FT,ZN,Q2
      DOUBLE PRECISION  TN,D9,H,snowmip1(100)
      DOUBLE PRECISION  DID,ETAM(nsoil0),RHCS  
      DOUBLE PRECISION INFMAX ,PRCIP,DELT, RIW, TAV(nsoil0) 
      DOUBLE PRECISION XLMELT,RHOICE, DETAL(nsoil0),lfw
      DOUBLE PRECISION ci,tln,etaml(nsoil0),etamf(nsoil0),ws
      DOUBLE PRECISION facd,fach,a, tavln
!lfw=latent heat of fusion for water 333500 J kg -3

!-- for non-linear root distribution
      DOUBLE PRECISION part(nsoil0)
!-- for Johansen thermal conductivity
      DOUBLE PRECISION kqwrtz,qwrtz,kzero,gamd,kdry,kas,x5,sr,ke,kice,kwt
      DOUBLE PRECISION kasat(nsoil0), kjpl(nsoil0)
        DATA ITEST/61/,JTEST/10/

        CP=.100468550D+004
        RHOICE=.90D+003
        CI=RHOICE*.210D+004
        lfw=.3335D+006!
        XLMELT=.3335D+006
!-- Constants for Johansen (1975) thermal conductivity
        kqwrtz=.770D+001
        kice  =.220D+001
        kwt   =.570D+000 
        qwrtz =.60D+000      ! for sandy loam
        kzero =.20D+001       ! if qwrtz > 0.2
        
! SOILTYP = 10 is water where soil model is not applied
          SOILTYP=.80D+001
       IF(SOILTYP.EQ.10) GOTO 222 ! 
          
        DSDZ2=.10D+001/(ZS1(2)-ZS1(1))
          DO k=1,NSOIL0
            TRANSP(K)=.0D+000
            DETAL (k)=.0D+000
            etaf  (k)=.0D+000
            etamf (k)=.0D+000
            kasat (k)=.0D+000
            kjpl  (k)=.0D+000
            part  (k)=.0D+000
          ENDDO
        



          etal(nsoil0)=eta(nsoil0)
         
           WS=DQM+QMIN
           RIW=rhoice*.1D-002
           X1=lfw/(.9806650D+001*PSIS)!XLMELT/(.9806650D+001*PSIS)
           X2=X1/BCLH*WS
           X4=(BCLH+.10D+001)/BCLH
!--- Next 3 lines are for Johansen thermal conduct.
           gamd=(.10D+001-ws)*.270D+004
           kdry=(.1350D+000*gamd+.6470D+002)/(.270D+004-.9470D+000*gamd)
           kas=kqwrtz**qwrtz*kzero**(.10D+001-qwrtz) 



!----- THE CACULATION OF THERMAL DIFFUSIVITY, DIFFUSIONAL AND ---
!----- HYDRAULIC CONDUCTIVITY (SMIRNOVA ET AL. 1997 EQ.2,5,6) ---
!tgs - the following loop is added to define the amount of frozen
!tgs - water in soil if ther is any




         DO K=1,(NSOIL0-1)
         tav(k)=.50D+000*(tso(k)+tso(k+1))
         etam(k)=.50D+000*(eta(k)+eta(k+1))

         tln=log(tso(k)/.273150D+003)
         tavln=log(tav(k)/.273150D+003)

         if(tln.lt..0D+000) then
           etal(k)=(dqm+qmin)*(.33520D+008* &
        (tso(k)-.273150D+003)/tso(k)/.9806650D+001/psis)**(-.10D+001/bclh)-qmin
           etal(k)=max(.0D+000,etal(k))
           etal(k)=min(etal(k),eta(k))
           etaf(k)=(eta(k)-etal(k))*1.e3/rhoice
         else
           etaf(k)=.0D+000
           etal(k)=eta(k)
         endif

         if(tavln.lt..0D+000) then
           etaml(k)=(dqm+qmin)*(.33520D+008* &
        (tav(k)-.273150D+003)/tav(k)/.9806650D+001/psis) &
         **(-.10D+001/bclh)-qmin
           etaml(k)=min(etaml(k), etam(k))
           etamf(k)=(etam(k)-etaml(k))*.10D+004/rhoice
         else
           etamf(k)=.0D+000
           etaml(k)=etam(k)
         endif


           TN=TAV(K) - .273150D+003
         
           IF(ETAMF(k).NE..0D+000.AND.TN.LT.-.1D-003) then
            DETAL(K)=.273150D+003*X2/(TAV(K)*TAV(K))* &
                    (TAV(K)/(X1*TN))**X4
           endif
!--- Next 10 lines calculate Johansen thermal conductivity KJPL
!           kasat(k)=kas**(.10D+001-ws)*kice**(dqm-etaml(k))
           kasat(k)=kas**(.10D+001-ws)*kice**(riw*etamf(k)) &
                   *kwt**(etaml(k)+qmin) &
                   *.260D-001**(dqm-etam(k))
           X5=(etam(k)+qmin)/ws
         if(etamf(k).eq..0D+000) then
           sr=max(1101D-000,x5)
           ke=log10(sr)+.10D+001
!--- next 2 lines - for coarse soils
!          sr=max(.505D-001,x5)
!          ke=.70D+000*log10(sr)+.10D+001   
         else
           ke=x5
        endif           
        xxx=.10D+001
           kjpl(k)=xxx*(ke*(kasat(k)-kdry)+kdry)
!--- CAP -volumetric heat capacity
!            CAP(K)=xxx*((.10D+000-DQM-QMIN)*RHOCS &
!                 + (ETAML(K)+qmin)*CW*(0.1D+004) & 
!                 + ETAMF(K)*CI &
!           - DETAL(K)*.10D+004*lfw)!xlmelt)
            CAP(K)=xxx*((.10D+000-DQM-QMIN)*RHOCS &
                 + (ETAML(K)+qmin)*CW &
                 + ETAMF(K)*CI &
           - DETAL(K)*.10D+004*xlmelt)
!cw*1000 to match previous units
! 
        if(i7ce.eq.1)then !sea ice thermal cond. and vol. heat capacity
         cap(k)=.196D+007  
         kjpl(k)=.250D+001
        endif
!          
        if((ws-riw*etamf(k)).lt..120D+000) then           
           TSQ2(K)=.0D+000
           TSQ1(K)=.0D+000
        else
           a=riw*ETAMF(K)
           xxx=dqm-a
           call protect(xxx,.1D-014)
           H=max(.0D+000,(ETAM(K)-a)/(xxx))
           fach=.10D+001
           facd=.10D+001
	if(etaf(k).ne..0D+000) &
           fach=.10D+001-riw*etaf(k)/eta(k)
          if(a.ne..0D+000) &
           facd=.10D+001-a/etam(k)
	  
!
!--- TSQ2 - hydraulic conductivity
          TSQ2(K)=KSAT/(dqm-riw*etaf(k))* &
                 (ETAL(K)/ &
                 (dqm-riw*etaf(k)))**(.20D+001*BCLH+.20D+001) &
                 * fach
         
!--- TSQ1 - diffusional conductivity
          TSQ1(K)=-BCLH*KSAT*PSIS*.10D-001/ &
                 (dqm-riw*etamf(k))* &
                 (dqm/(dqm-riw*etamf(k)))**.30D+001 &
                *H**(BCLH+.20D+001)*facd
        
        endif
!        endif
           
!--- TWST - thermal diffusivity
!           TWST(K)=HK(K)/CAP(K)
!--- Use thermal conductivity from Johansen (1975)
            TWST(K)=KJPL(K)/CAP(K) 
         END DO
           TSQ2(nsoil0)=KSAT/DQM*(ETA(nsoil0)/DQM) &
                     **(.20D+001*BCLH+.20D+001)
!
       INFMAX=.9990D+003
       if((ws-riw*etamf(1)).lt..120D+000) INFMAX=.0D+000
!********************************************************************
        RHCS=CAP(1)
        TN=SOILT-.273150D+003
        do k=1,nsoil0
         transp(k)=-xroot(k)
        enddo 

! facasa
           
!C******************************************************************************
!       COEFFICIENTS FOR THOMAS ALGORITHM FOR TSO
!******************************************************************************
        BES(1)=.0D+000
        RTS(1)=TSO(nsoil0)
        DO 33 K=1,(NSOIL0-2)
          KN=NSOIL0-K
          K1=2*KN-3
          X1=DDZS(K1)*TWST(KN-1)
          X2=DDZS(K1+1)*TWST(KN)
          FT=TSO(KN)+X1*(TSO(KN-1)-TSO(KN)) &
            -X2*(TSO(KN)-TSO(KN+1))
          ZN=.10D+001+X1+X2-X2*BES(K)
          call protect(zn,.1D-014)
          BES(K+1)=X1/ZN   
          RTS(K+1)=(FT+X2*RTS(K))/ZN
   33  CONTINUE
!C************************************************************************
!--- THE HEAT BALANCE EQUATION (EQ. 21,26) now defunct
! facasa 3 after 90
!--- SOILT - skin temperature
        tso(1)=soilt
! facasa   

!---- Final solution for soil temperature - TSO  
          DO K=2,NSOIL0
            KK=NSOIL0-K+1
            TSO(K)=RTS(KK)+BES(KK)*TSO(K-1)
          END DO
          
!-- Recalculating of frozen water in soil
         DO K=1,NSOIL0
         tln=log(tso(k)/.273150D+003) 
         if(tln.lt..0D+000) then
           etal(k)=(dqm+qmin)*(.33520D+008* &
        (tso(k)-.273150D+003)/tso(k)/.9806650D+001/psis) &
         **(-.10D+001/bclh)-qmin
           etal(k)=max(.0D+000,etal(k))
           etal(k)=min(etal(k),eta(k))
           etaf(k)=(eta(k)-etal(k))*0.1D+004/rhoice
         else
           etaf(k)=.0D+000
           etal(k)=eta(k)
         endif
         ENDDO
!C******************************************************************************
!       COEFFICIENTS FOR THOMAS ALGORITHM FOR ETA
!******************************************************************************
        DID=(ZS1(nsoil0)-ZS2(nsoil0))*.20D+001
        X1=ZS1(nsoil0)-ZS1((NSOIL0-1))

        ZN=(.10D+001+TSQ1((nsoil0-1))/X1/DID*DELT+TSQ2(nsoil0)/(.20D+001*DID)*DELT)
        call protect(zn,.1D-014)
        BEQ(1)=DELT*(TSQ1((nsoil0-1))/DID/X1 &
                   +TSQ2((NSOIL0-1))/.20D+001/DID)/ZN
        RQS(1)=(ETA(nsoil0)+TRANSP(nsoil0)*DELT/ &
              DID)/ZN
          
        DO 330 K=1,(NSOIL0-2)
          KN=NSOIL0-K 
          K1=2*KN-3
          X4=.20D+001*DDZS(K1)*TSQ1(KN-1)
          X2=.20D+001*DDZS(K1+1)*TSQ1(KN)
          Q4=X4+TSQ2(KN-1)*DSDZ1(KN-1)
          Q2=X2-TSQ2(KN+1)*DSDZ1(KN-1)
          ZN=.10D+001+X2+X4-Q2*BEQ(K)   
          call protect(zn,.1D-014)
          BEQ(K+1)=Q4/ZN
 330      RQS(K+1)=(ETA(KN)+Q2*RQS(K) &
                  +TRANSP(KN) &
                  /(ZS2(KN+1)-ZS2(KN)) &
                  *DELT)/ZN
!*************************************************************************
!--- tqcan FOR SOLUTION OF MOISTURE BALANCE EQ.22,28 AND ETA PROFILES
!*************************************************************************
          CALL tqcan (BEQ,RQS,TSQ1,TSQ2,DELT,ETA, &
       DQM,QMIN,TRANSP,  &
       RUNOFF1,REF,rain1, &
       KSAT,INFMAX,PRCIP,RUNOFF2,I,J,etaf, &
       runoffz,potwq1,eacasa2,eacasa1,zs2,zsnow2,zsnow1, &
       snowmip1, &
        nsnow,n,in,ihi,inlyr,nsoil0,nstem,m,iminit,deltsn,zs1)
        D9=(TWST(1)*RHCS*DSDZ2)
        S=D9*(tso(1)-tso(2))
        soilhf=s

 222    CONTINUE
      RETURN
	END SUBROUTINE
!
!!!!!!!!!!!!!!!!!!! /-\ < /-\ S /-\ !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
!
        SUBROUTINE tqcan (BEQ,RQS,TSQ1,TSQ2,DELT,ETA, &
      DQM,QMIN,TRANSp,RUNOFF,REF,rain1, &
      KSAT,INFMAX,PRCIP,RUNOFF2,I,J,ETAF,runoffz,potwq1, &
      eacasa2,eacasa1,zs2,zsnow2,zsnow1,snowmip1, &
        nsnow,n,in,ihi,inlyr,nsoil0,nstem,m,iminit,deltsn,zs1)
          
!********************************************************************************
!   moisture balance equation is solving here and
!   final solution for moisture transfer equations
!**************************************************************************************
        implicit none
        DOUBLE PRECISION potwq1,xxx,yyy,rain1(3)
        INTEGER I,J
	integer nsnow,n,in,ihi,inlyr,nsoil0,nstem,m,iminit
	DOUBLE PRECISION deltsn,zs1(nsoil0)

        DOUBLE PRECISION runoffz,eacasa2,eacasa1
        DOUBLE PRECISION BEQ(nsoil0),RQS(nsoil0),TSQ1(nsoil0),TSQ2(nsoil0),ETAF(nsoil0)
        DOUBLE PRECISION ETA(nsoil0),Q2,DQM,snowmip1(100)
        DOUBLE PRECISION QMIN,RUNOFF,TRANSp(nsoil0),REF , KSAT
        DOUBLE PRECISION INFMAX,PRCIP,RUNOFF2,D14NEW
        DOUBLE PRECISION F1MAX,F2MAX,F1,F2,FD,KDT,VAL
        DOUBLE PRECISION DWILT,d20,DDT,PX,zsnow1(nsnow+1)
        DOUBLE PRECISION INFMAX1,zs2(nsoil0),zsnow2(nsnow+1)
        DOUBLE PRECISION D3,D4,D8,X1,D12,D13,D14,DZS,DELT,R21,D16,QQ
        INTEGER K,KK
! --- MOISTURE BALANCE BEGINS HERE
         RUNOFF=.0D+000
         RUNOFF2=.0D+000
         DZS=ZS1(2)
         D3=BEQ((NSOIL0-1))
         D4= RQS((NSOIL0-1))
         X1=TSQ1(1)/DZS
         D12=X1+TSQ2(1)*.50D+000
         D13=X1-TSQ2(2)*.50D+000
! facasa
!
!         D8=potwq1*.10D-002 ! acasa units needed here (was FQ*RAS)    unit issue before   Dave
         D8=potwq1 ! clkyu change back, original one is correct
         D14=-rain1(1)*.10D-002
!
!-- SCHAAKE/KOREN EXPRESSION for calculation of max infiltration
!
         DWILT=DQM-.50D+000*.90D+000*(etaf(1)+etaf(2))
         F1MAX=DWILT*ZS2(2)
         F2MAX=DWILT*(ZS2(3)-ZS2(2))
         call protect(dwilt,.1D-014)
         F1=F1MAX*(.10D+001-(ETA(1)-.90D+000*etaf(1))/DWILT)
         F2=F2MAX*(.10D+001-(ETA(2)-.90D+000*etaf(2))/DWILT)
         FD=F1+F2   
         KDT=(.30D+001)*KSAT/(.34341D-005)

         VAL=(.10D+001-EXP(-KDT*SQRT(DELT/.8640D+005)))
         DDT = FD*VAL
         PX=-D14 * DELT
         IF(PX.LT..0D+000) PX = .0D+000
       if(px.eq..0D+000.or.ddt.eq..0D+000) then
         infmax1=.0D+000
        else
         xxx=px+ddt   
         call protect(xxx,.1D-014)
         INFMAX1 = (PX*(DDT/(xxx)))/DELT
         INFMAX1 = MIN(INFMAX1, KSAT)
        endif
         INFMAX = MIN(INFMAX,INFMAX1)
!----

          IF (-D14.GE.INFMAX)THEN
            RUNOFF=-D14-INFMAX
            D14=-INFMAX
          ENDIF
! PRCIP is total infiltration flux in M/S
          PRCIP=D14
          R21=.50D+000*DZS/DELT  
          D12=D12+R21
          D14=D14-ETA(1)*R21
          D16=transp(1)
          Q2=eacasa2
          D20=Q2-eacasa1
          IF(D20.LE..0D+000) THEN
            xxx=ref-qmin
          call protect(xxx,.1D-014)
             yyy=D12-D13*D3-D20*D8/(xxx)
          call protect(yyy,.1D-014)
             QQ=(D13*D4-D14+D16)/yyy
!            QQ=(D13*D4-D14+D16)/(D12-D13*D3-D20*D8/(xxx))
            D14NEW=-DQM*(D12-D13*D3-D20*D8/(xxx))+D13*D4+D16
          ELSE
          xxx=d12-d3*d13
          call protect(xxx,.1D-014)   
            QQ=(D4*D13-D14+D8*(Q2-eacasa1)+D16)/(xxx)
          D14NEW=-DQM*(D12-D3*D13)+D4*D13+D8*(Q2-eacasa1)+D16
          END IF

          IF(QQ.LT..0D+000) THEN
            ETA(1)=.10D-001
          ELSE IF(QQ.GT.DQM) THEN
            ETA(1)=max(DQM,.1D-001)
            RUNOFF=RUNOFF+(D14NEW-D14)
          ELSE  
            ETA(1)=QQ
          END IF

          
!--- FINAL SOLUTION FOR ETA
          DO K=2,NSOIL0
            KK=NSOIL0-K+1  
            QQ=BEQ(KK)*ETA(K-1)+RQS(KK)
             
           IF (QQ.LT..0D+000) THEN
            ETA(K)=.5D-001
           ELSE IF(QQ.GT.DQM) THEN
            ETA(K)=max(DQM,.5D-001)
             IF(K.EQ.NSOIL0)THEN 
               RUNOFF2=RUNOFF2+(QQ-DQM)*(ZS1(K)-ZS2(K))
             ELSE
               RUNOFF2=RUNOFF2+(QQ-DQM)*(ZS2(K+1)-ZS2(K))
             ENDIF
           ELSE
            ETA(K)= max(QQ,.5D-001)
           END IF
          END DO
          runoffz=runoff
          RETURN
	END SUBROUTINE
        subroutine photos_J13(an,gb,caq,tlc,rhs,par, &
        xai,photosynth,respl,yrsmn)
!......................................................................
!  list of variables in subroutine photosynthesis
!    an - net co2 assimilation rate [mol.m-2.s-1]
!    ag - gross co2 assimilation rate [mol.m-2.s-1], ag is not used explicitly
!    ar - rubisco activity limit of ag mol.m-2.s-1]
!    ae - electron transport & rup2 regeneration limit of ag [mol.m-2.s-1]
!    rd - "day respiration" or mitochondrial respiration rate [umol.m-2.s-1]
!    ca - mole fraction co2 in ambient air [mol.mol-1]
!    oi - mole fraction o2 in intercellular air space [mol.mol-1]
!    gamma - co2 compensation point when rd=0 [umol.mol-1]
!    vcmax - maximum rate of carboxylation with non-limiting rup2 and co2 and
!            full activation of rubisco [umol.m-2.s-1]
!    kc, ko - michaelis-menten constants for co2 and o2 [umol.mol-1]
!    j - potential electron transport rate [umol.m-2.s-1]
!    aj, bj, cj - coefficients of transition quadratic equation of j
!    jmax - maximum j determined by leaf temperature [umol.m-2.s-1]
!    pfd - photon flux density [umol.m-2.s-1]
!    iqe - intrinsic quantum efficiency (iqe=(1-f)/2) where f is the
!          fraction of pfd absorbed by other than the chloroplast lamellae
!    theta - curvature factor of light and co2 response curve (0<=theta<=1)
!    tlc - leaf temperature in celsius [c]
!    tlk - leaf temperature in kelvin [k]
!    tck - conversion constant between celsius and kelvin of temperature
!    vcmax25 - vcmax at 25c [umol.m-2.s-1] -- max carb. at ideal temperature, etc.
!    kc25 - kc at 25c [umol.mol-1]
!    ko25 - ko at 25c [umol.mol-1]
!    gamma25 - gamma at 25c [umol.mol-1]
!    ekc, eko - activation energies for kc and ko [j.mol-1]
!    rgas - universal gas constant [j.k-1.mol-1]
!    t0c - reference temperature in celsius [c]
!    t0k - reference temperature in kelvin [k]
!    jmax0 - coefficient for temperature dependence of jmax [umol.m-2.s-1]
!        (it is likened to the max ideal carboxylization rate vcmax25, but is 217/90 greater)
!    ejamx - coefficient for temperature dependence of jmax [j.mol-1]
!    sjamx - coefficient for temperature dependence of jmax [j.mol-1.k-1]
!    hjmax - coefficient for temperature dependence of jmax [j.mol-1]
!    par - absorbed photosynthetic active radiation irradiance [w.m-2]
!    cpfd - conversion coefficient from par to pfd
!    aa,bb,dd,ee - coefficients in formula ==> an={aa*(ci-dd)}/{ee*ci+bb}-rd
!    rhs - relative humidity at leaf surface (0<=rhs<=1.)
!    gb - leaf boundary layer conductance [mol.m-2.s-1]
!    can3, can2, can1, can0 - coefficients in cubic equation of an
!    acan,bcan,gcan,tcan - intermediate coefficients to calculate can3,...can0
!    dwdc - ratio of molecular diffusivity of water vapor to that of co2
!    cm - slope of ball-berry linear gsw empirical formula (unitless)
!    cb - intercept of ball-berry linear gsw empirical formula [mol.m^-2.s^-1]
!    bbb,ccc,ddd - coefficients of cubic equation of x=an
!    ppp,qqq - coefficients of reduced cubic equation of z=x+bbb/3.
!......................................................................
!  note (1): unit for ci, oi, kc, ko and gamma should be consistent, it could
!            be either [mol.mol-1] or [umol.mol-1] or partial pressure [bar]
!            where 1 bar = 1.e5 pa.
      implicit none

      DOUBLE PRECISION kc,kc25,ko,ko25,jmax,jmax0,j,iqe,can0,power3
      DOUBLE PRECISION an,ag,ar,ae,acan,bcan,gcan,tcan,can3,can2,can1
      DOUBLE PRECISION aj,bj,cj,delta,bbb,ccc,ddd,ppp,qqq,rrr,ttt,theta0
      DOUBLE PRECISION ejmax,hjmax
      DOUBLE PRECISION yyy,respl
      DOUBLE PRECISION gb,caq,tlc,rhs,par
      DOUBLE PRECISION theta,oi,vcmax25,xxx
      DOUBLE PRECISION gamma25,ekc,eko,rgas,t0c,tck,sjmax,cpfd,dwdc,cb
      DOUBLE PRECISION cm,pi,ca,dtl,t0k,tlk,rd,vcmax,gamma,pfd,aa
      DOUBLE PRECISION dd,ee,bb,qqn,xyz,xai,dtl1,photosynth
      DOUBLE PRECISION qsoil,yrsmn
        double precision xb7,xb8,xb9,xb10,xb11,xb12,xxb,xyb,xzb

!      parameter(theta=0.5,oi=.209,vcmax25=90.,iqe=.405)
      parameter(theta=.5D+000,oi=.209D+000,iqe=.405D+000)
        parameter(kc25=.310D+003,ko25=.396000D+006)
        parameter(gamma25=.447D+002,ekc=.59430D+005)
      parameter(eko=.36000D+005,rgas=.8314D+001)
      parameter(tck=.27315D+003)
      parameter(sjmax=.710D+003,ejmax=.37000D+005)
      parameter(cpfd=.46D+001,hjmax=.220000D+006)
      parameter(dwdc=.1647D+001,cb=.8D-002,cm=.929D+001)
!
      vcmax25=yrsmn
!
!yrsmn*(.217D+003/.90D+002)! this ratio exists from preset values from the field (well-fertilized soybeans, grapes)
!
      jmax0=vcmax25*(.217D+003/.90D+002)! this ratio exists from preset values from the field (well-fertilized soybeans, grapes)
      t0c=.25D+002!....t0c is a reference temperature only; is NOT a phys parameter 9/22/2008 RDP
      theta0=theta
      pi=.3141592654D+001
      power3=.1D+001/.3D+001
      ca=caq
!......................................................................
!  leaf temperature dependencies
!......................................................................
      dtl=(tlc-t0c)
      xxx=tlc-.1+002
      dtl1=dtl
      t0k=t0c+tck
      tlk=tlc+tck
!
      rd=-.1D-005*respl! input respiration rate w/ sign reversal to fit convention
      dtl=tlc-t0c
      vcmax=vcmax25*(.1D+001+.505D-001*dtl- &
        .248D-003*dtl*dtl-.809D-004*dtl*dtl*dtl)

      if(tlk.le..28315D+003)then! use the Falge et al (1996, 2005) adjustments
!       vcmax=vcmax25*(EXP(xb7*(xb12-xb8)/(xb9*xb12*xb8))* &
!       ((.1D+001+EXP((xb10*xb8-xb11)/(xb9*xb8)))))) / &
!       (.1D+001+EXP((xb10*xb12-xb11)/(xb9*xb12)))
! where...
! xb7=delHa=200000 (J mol-1)
! xb8=Tref=298.15 (K)
! xb9=Rgas=8.31 (J mol-1 K-1)
! xb10=delS=655 (J mol-1 K-1)
! xb11=delHd=200000 (J mol-1)
! xb12=tl(K)=any (K)
!
        xb7=.2D+006
        xb8=.29815D+003
        xb9=.831D+002
        xb10=.655D+003
        xb11=.2D+006
        xb12=tlk
!
        xxb=xb7*(xb12-xb8)/(xb9*xb12*xb8)
        xyb=(xb10*xb8-xb11)/(xb9*xb8)
        xzb=(xb10*xb12-xb11)/(xb9*xb12)

!       vcmax=vcmax25*((EXP(xb7*(xb12-xb8)/(xb9*xb12*xb8))*
!       ((1+EXP((xb10*xb8-xb11)/(xb9*xb8))))))/
!       (1+EXP((xb10*xb12-xb11)/(xb9*xb12)))

        vcmax=vcmax25*EXP(xxb)*(.1D+001+EXP(xyb))/(.1D+001+EXP(xzb))

      endif

      kc=kc25*exp(ekc/(rgas*t0k)*(.1D+001-t0k/tlk))
      ko=ko25*exp(eko/(rgas*t0k)*(.1D+001-t0k/tlk))
      call protect(kc,.1D-014)
      call protect(ko,.1D-014)
      gamma=gamma25*(.1D+001+.4206D-001*dtl+.805D-003*dtl*dtl)
      jmax=(jmax0)*exp(ejmax/(rgas*t0k)*(.1D+001-t0k/tlk)) &
           /(.1D+001+exp((sjmax-hjmax/tlk)/rgas))
!......................................................................
!  when par=0, ag=0 and an=-rd
!......................................................................
      pfd=par*cpfd
      if(pfd.eq..0D+000) then
        an=.0D+000
        goto 100
      endif
!......................................................................
!  convert [umol] into [mol]
!......................................................................
      vcmax=vcmax*.1D-005
      kc=kc*.1D-005
      ko=ko*.1D-005
      gamma=gamma*.1D-005
!......................................................................
!  solve for ar
!......................................................................
      aa=vcmax
      dd=gamma
      ee=.1D+001
      bb=kc*(.1D+001+oi/ko)
      acan=dwdc+cb/gb-cm*rhs
      call protect(acan,.1D-024)
      bcan=ca*(gb*cm*rhs-.2D+001*cb-gb*dwdc)
      gcan=ca*ca*cb*gb
      tcan=gb*cm*rhs-cb
!......................................................................
!  can3*an^3+can2*an^2+can1*an+can0=0, where an=ar-rd
!......................................................................
      can3=ee*acan
      call protect(can3,.1D-024)
      can2=ee*(bcan+acan*rd)+bb*tcan-aa*acan
      can1=gcan*(ee+bb/ca)+bcan*(ee*rd-aa)+tcan*(aa*dd+bb*rd)
      can0=gcan*(ee*rd-aa+(aa*dd+bb*rd)/ca)
!......................................................................
!  x^3+bbb*x^2+ccc*x+ddd=0, where x=an=ar-rd
!......................................................................
      bbb=can2/can3
      ccc=can1/can3
      ddd=can0/can3
!......................................................................
!  z^3+ppp*z+qqq=0, where x=z-bbb/3
!......................................................................
      ppp=(bbb*bbb/.9D+001-ccc/.3D+001)
      qqq=(ddd-bbb*ccc/.3D+001+.2D+001*bbb*bbb*bbb/.27D+002)
      ppp=abs(ppp)
      rrr=ppp**.15D+001
      rrr=max(rrr,.1D-019)
      qqn=.1D+001
      if(qqq.lt..0D+000)qqn=-.1D+001
      xyz=qqn*qqq/(.2D+001*rrr)
      xyz=min(xyz,.1D+001)
      xyz=max(xyz,-.1D+001)
      ttt=acos(xyz)+.4D+001*pi
      ar=.2D+001*rrr**power3*cos(ttt/.3D+001)-bbb/.3D+001
      ar=ar+rd
!......................................................................
!  aj*j^2+bj*j+cj=0
!......................................................................
      aj=theta
      bj=-pfd*iqe-jmax
      cj=pfd*iqe*jmax
      delta=bj*bj-.4D+001*aj*cj
      call protect(aj,.1D-014)
      j=(-bj-sqrt(delta))/(.2D+001*aj)
      j=j*.1D-005
!......................................................................
!  solve for ae
!......................................................................
      aa=j
      dd=gamma
      ee=.45D+001
      bb=.105D+002*gamma
      acan=dwdc+cb/gb-cm*rhs
      call protect(acan,.1D-014)
      bcan=ca*(gb*cm*rhs-.2D+001*cb-gb*dwdc)
      gcan=ca*ca*cb*gb
      tcan=gb*cm*rhs-cb
!......................................................................
!  can3*an^3+can2*an^2+can1*an+can0=0, where an=ae-rd
!......................................................................
      can3=ee*acan
      can2=ee*(bcan+acan*rd)+bb*tcan-aa*acan
      can1=gcan*(ee+bb/ca)+bcan*(ee*rd-aa)+tcan*(aa*dd+bb*rd)
      can0=gcan*(ee*rd-aa+(aa*dd+bb*rd)/ca)
      call protect(can3,.1D-014)
!......................................................................
!  x^3+bbb*x^2+ccc*x+ddd=0, where x=an=ae-rd
!......................................................................
      bbb=can2/can3
      ccc=can1/can3
      ddd=can0/can3
!......................................................................
!  z^3+ppp*z+qqq=0, where x=z-bbb/3
!......................................................................
      ppp=(bbb*bbb/.9D+001-ccc/.3D+001)
      qqq=ddd-bbb*ccc/.3D+001+.2D+001*bbb*bbb*bbb/.27D+002
      ppp=abs(ppp)
      rrr=ppp**.15D+001
      rrr=max(rrr,.1D-019)
      qqn=.1D+001
      if(qqq.lt..0D+000)qqn=-.1D+001
      xyz=qqn*qqq/(.2D+001*rrr)
      xyz=min(xyz,.1D+001)
      xyz=max(xyz,-1.1D+001)
      ttt=acos(xyz)+.4D+001*pi
      ae=.2D+001*rrr**power3*cos(ttt/.3D+001)-bbb/.3D+001
      ae=ae+rd
!......................................................................
!  ag=min(ar,ae) and an=ag-rd
!......................................................................
      if(ae.ge.ar) then
        ag=ar
      else
        ag=ae
      endif
      ag=max(ag,.0D+000)
      an=ag-rd
      photosynth=-ag
 100  continue
      return
        END SUBROUTINE
!
!!!!!!!!!!!!!!!!!!! /-\ < /-\ S /-\ !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
!
      subroutine conduct_J13(gsw,an,qax,qsm,caq,caq1,gb,gsw1a,wuey)
!......................................................................
!  ball-berry leaf stomatal conductance model is adopted here.
!......................................................................
!  list of variables in subroutine conductance
!    cm - slope of ball-berry linear gsw empirical formula (unitless)
!    cb - intercept of ball-berry linear gsw empirical formula [mol.m-2.s-1]
!    wa - mole fraction water vapor in ambient air [mol.mol-1]
!    wi - intercelluar mole fraction water vapor (saturated) [mol.mol-1]
!    wawi = wa/wi = qa/qs, which is used instead of wa and wi
!    wuey = water use efficiency; modifies gsw multiplicitavely with jmax0/217.
!    qa - specific humidity in ambient air [kg.kg-1]
!    qs - saturated specific humidity at leaf temperature [kg.kg-1]
!    gb - boundary layer conductance [mol.m-2.s-1]
!    gsw - stomatal conductance to water vapor [mol.m-2.s-1]
!    an - net co2 assimilation rate [mol.m-2.s-1]
!    ca - mole fraction co2 in ambient air [mol.mol-1]
!    agsw, bgsw, cgsw - coefficients of quadratic equation of gsw
!......................................................................
      implicit none
      DOUBLE PRECISION gsw,an,qax,qsm,caq,gb,cb,cm,qa,qs,wuey
      DOUBLE PRECISION ca,wawi,agsw,bgsw,cgsw,delta,ca1,caq1,gsw1a

      parameter(cb=.8D-002)
      cm=.929D+001
      qa=qax
      qs=qsm
      ca=caq
      ca1=caq
      if(an.lt..0D+000) then
        gsw=cb/wuey
        goto 10
      endif
      wawi=qa/qs
      agsw=ca1-an/gb! ca up agsw up
      bgsw=agsw*(gb-cb)-cm*an !
      cgsw=-(cm*an*wawi+cb*agsw)*gb! goes neg as ca up
      if(agsw.le..0D+000) then
        gsw=cb/wuey
        goto 10
      endif
      delta=bgsw*bgsw-4.*agsw*cgsw
      if(delta.lt..0D+000) then
        gsw=cb/wuey
        goto 10
      endif
!
      gsw=(((-bgsw+sqrt(delta))/(.2D+001*agsw)))/wuey
      gsw1a=gsw
 10   return
!
        END SUBROUTINE

        subroutine respire_J13(r0,xxx,t,q10,q,qw,aco2,itiss)
! arguments:
! xxx   =       output respiration flux (umol m-2 s-1 per m2 of tissue)
! t     =       input tissue temperature (C)
! q10   =       q10 respiration value
! q     =       soil moisure
! qw    =       wilting point soil moisture
! eai   =       element area index
! aco2  =       ambient co2 concentration (umol mol)
! itiss =       flag for tissue: 1,2,3,4:leaves/stems/roots/microbes
! r0 =     basal respiration rate (per m2 of tissue) umol m-2 s-1; varies with species and soil nutrition
!
! The equation here is similar to that developed by a one Svante
! August Arrhenius.
!
        implicit none
        integer itiss
        DOUBLE PRECISION xxx,t,a,t0,r,yyy,y,s,zzz,q,qw,b,q10
        DOUBLE PRECISION r0,eai,q0,aco2
!
! r0 is basal respiration rate (1-sided)
!
        xxx=min(t,.420D+002)! 42 degree limiting...43=crash
        yyy=r0*(exp(.1D+000*(log(q10))*xxx)) ! umol m-2(of tissue) s-1
        zzz=.1D+001
        xxx=yyy
!
        return
        END SUBROUTINE
!
!!!!!!!!!!!!!!!!!!! /-\ < /-\ S /-\ !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
!       
        subroutine integrate1(df,f,gg,n)
!
! integrates df and returns f; upper b.c. downwards through all air layers
!
        implicit none
        integer i,n
        DOUBLE PRECISION f(n),df(n),gg(n)
!
! top-down integration
!
        do i=n-1,2,-1
         f(i)=f(i+1)-df(i)*gg(i)
        enddo
!        f(n)=f(n-1)+df(n)*gg(n) -> upper BC
        f(1)=f(2)-df(1)*gg(1)
        return
        END SUBROUTINE
