	subroutine trip1(xmw,ngg,n,c10k,c8k,c11,got,dt,dwt,dt2,w2, &
         dw2,gg,omw,wet,mw,t,t2, &
         DWWT,WWT,DWTT,WTT,DW3,W3,T3,wt)
! 
! computes all third moments	
!##                                                ##   ##    ##   ##    ##	
!# mat1(1)     mat2(1) ...             ... matn(1)  #   # d(1) #   # f(1) #	
!# mat1(2)     mat2(2) ...             ... matn(2)  #   # d(2) #   # f(2) #
!# ...                 ...             ...          # X # ...  # = # ...  #
!# mat1(n)     mat2(n) ...             ... matn(n)  #   # d(n) #   # f(n) #
!##                                                ##   ##    ##   ##    ##
! n is 4: 4 moments and 3 gradients caculated directly from them
!***********

        implicit none
	double precision sss1,sss
	double precision mat1(4),mat2(4),mat3(4),mat4(4),d(4),f(4)
	integer i,ngg,n,ij
	double precision c10k(n),dt(n),dwt(n),dt2(n),c11,got
	double precision c8k(n),w2(n),dw2(n),omw,wet,gg(n)
        double precision dwwt(n),wwt(n),dwtt(n),wtt(n),dw3(n),w3(n)
	double precision t3(n),t2(n),xmw,wt(n)
	double precision xxx,yyy,zzz,ppp,qqq,mw(n),t(n)
!
!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!

! initialize working vbles...

       do i=2,ngg			
	do ij=1,4
	 mat1(ij)=.0D+000
	 mat2(ij)=.0D+000
	 mat3(ij)=.0D+000
	 mat4(ij)=.0D+000
	 d(ij)=.0D+000
	 f(ij)=.0D+000
	enddo
!**************************
! compute t3, wtt, w3, wwt
!**************************

	 mat1(1) = (c10k(i))  ! 0.01
         mat2(1) = (.3D+001*dt(i))
         f(1) = (-.2D+001*dwt(i)*dt2(i) -dwt(i)*dwt(i))
         mat1(2) = ((.1D+001-c11)*got)
         mat2(2) = (c8k(i)+c10k(i))   ! 0.01
         mat3(2) = (.2D+001*dt(i))
         f(2) = (-w2(i)*dt2(i) -.2D+001*dwt(i)*dwt(i))


         mat2(3) = (-got*(.2D+001-c11*.8D+001/.3D+001))
         mat3(3) = (c8k(i)+c10k(i))!0.01
         mat4(3) = (-dt(i))
         f(3) = (-dwt(i)*dw2(i) -.2D+001*w2(i)*dwt(i))
         mat3(4) = (-.3D+001*(.1D+000-c11)*got)
         mat4(4) = (.2D+001*c10k(i)+c8k(i))! 0.01
         f(4) = (-.3D+001*w2(i)*dw2(i))
         
! reduce matrix
         
         mat3(3) = mat4(4)*mat3(3) -mat3(4)*mat4(3)
         mat2(3) = mat4(4)*mat2(3)
         f(3) = mat4(4)*f(3) -f(4)*mat4(3)
         mat2(2) = mat3(3)*mat2(2) -mat2(3)*mat3(2)
         mat1(2) = mat3(3)*mat1(2)
         f(2) = mat3(3)*f(2) -f(3)*mat3(2)
         mat1(1) = mat2(2)*mat1(1) -mat1(2)*mat2(1)
         f(1) = mat2(2)*f(1) -f(2)*mat2(1)
!
! solve matrix
!
	xxx=mat1(1)
	call protect(xxx,.1D-004)
         d(1) = f(1)/mat1(1)   
	xxx=mat2(2)
	call protect(xxx,.1D-004)
         d(2) = (-d(1)*mat1(2) + f(2))/mat2(2)
	xxx=mat3(3)
	call protect(xxx,.1D-004)
         d(3) = (-d(2)*mat2(3) + f(3))/mat3(3)
	xxx=mat4(4)
	call protect(xxx,.1D-004)
         d(4) = (-d(3)*mat3(4) + f(4))/mat4(4)
! assign values  	        
         t3(i)=omw*t3(i)+wet*d(1)   
         wtt(i)=omw*wtt(i)+wet*d(2)
         w3(i)=omw*w3(i)+wet*d(3) 
         wwt(i)=omw*wwt(i)+wet*d(4)
	enddo
!
! quasi-Andre type realizability constraints
!
	sss=min(.1D-001*mw(n)*mw(n)*mw(n),.1D+002)
	call cap(w3,sss,n)
	sss=.1D+000*abs(wt(n)*wt(n)*wt(n))/(mw(n)*mw(n)*mw(n))
	call cap(t3,sss,n)
	sss=.1D-001*abs(wt(n))*mw(n)
	call cap(wwt,sss,n)
	sss=.1D-000*(wt(n)**2)/mw(n)
	call cap(wtt,sss,n)
!
	do i=1,10
         call smth(w3,n)
         call smth(t3,n)
         call smth(wtt,n)
         call smth(wwt,n)
	enddo
!
        call deriv(dwwt,wwt,gg,n)
        call deriv(dwtt,wtt,gg,n)
        call deriv(dw3,w3,gg,n)
!
	return
	END SUBROUTINE
!
!!!!!!!!!!!!!!!!!!! /-\ < /-\ S /-\ !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
!
	subroutine trip2(xmw,ngg,n,c10k,c8k,c11,got,w3,de,wq,dw2,w2,dwq, &
         dt,wwt,dtq,wt,dwt,wtt,dt2,omw,wet,gg,mw,t,t2,e, &
	 T2Q,WWQ,DWWQ,WTQ,DWTQ)
! 
! computes all third moments	
!##                                                ##   ##    ##   ##    ##	
!# mat1(1)     mat2(1) ...             ... matn(1)  #   # d(1) #   # f(1) #	
!# mat1(2)     mat2(2) ...             ... matn(2)  #   # d(2) #   # f(2) #
!# ...                 ...             ...          # X # ...  # = # ...  #
!# mat1(n)     mat2(n) ...             ... matn(n)  #   # d(n) #   # f(n) #
!##                                                ##   ##    ##   ##    ##
!n is 3: 3 moments and 2 gradients caculated directly from them
!***********

        implicit none
	double precision sss1,sss
	double precision mat1(4),mat2(4),mat3(4),mat4(4),d(4),f(4)
	integer i,ngg,n,ij
	double precision c10k(n),c11,got,xmw
	double precision c8k(n),omw,wet,gg(n),t2(n)
        double precision w3(n),de(n),wq(n),dw2(n),w2(n),dwq(n)
	double precision dt(n),wwt(n),dtq(n),wt(n),dwt(n),wtt(n),dt2(n),t2q(n)
	double precision dwwq(n),dwtq(n),wwq(n),wtq(n)
	double precision xxx,yyy,zzz,ppp,qqq,mw(n),t(n),e(n)
!
!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
!
! initialize working vbles...

	do ij=1,4
	 mat1(ij)=.0D+000
	 mat2(ij)=.0D+000
	 mat3(ij)=.0D+000
	 mat4(ij)=.0D+000
	 d(ij)=.0D+000
	 f(ij)=.0D+000
	enddo
!**************************
! compute wwq, wtq, t2q
!**************************
         do i=2,ngg

	 do ij=1,4
	  mat1(ij)=.0D+000
	  mat2(ij)=.0D+000
	  mat3(ij)=.0D+000
	  mat4(ij)=.0D+000
	  d(ij)=.0D+000
	  f(ij)=.0D+000
	  enddo
! assigning entries into matrix
         
         mat1(1) = (c8k(i)+c10k(i))
         mat2(1) = (-got*(.2D+001-c11*.8D+001/.3D+001))
         f(1) = (w3(i)*de(i) -wq(i)*dw2(i)-.2D+001*w2(i)*dwq(i))
         mat1(2) = (dt(i))
         mat2(2) = (c8k(i)+c10k(i))
         mat3(2) = (-(.1D+001-c11)*got)

         f(2)=(-wwt(i)*de(i)-w2(i)*dtq(i)-wt(i)*dwq(i)-wq(i)*dwt(i))  
         mat2(3) = .2D+001*dt(i)
         mat3(3) = (c10k(i))

         f(3) = (-wtt(i)*de(i)-wq(i)*dt2(i)-wt(i)*dtq(i) -wt(i)*dwt(i))


! reduce matrix

         mat2(2) = mat3(3)*mat2(2) -mat2(3)*mat3(2)

         mat1(2) = mat3(3)*mat1(2)
         f(2) = mat3(3)*f(2) -f(3)*mat3(2)

         mat1(1) = mat2(2)*mat1(1) -mat1(2)*mat2(1)

         f(1) = mat2(2)*f(1) -f(2)*mat2(1)
!         
! solve matrix
!         
	xxx=mat1(1)
	call protect(xxx,.1D-004)
         d(1) = f(1)/mat1(1)
	xxx=mat2(2)
	call protect(xxx,.1D-004)
         d(2) = (-d(1)*mat1(2) + f(2))/mat2(2)
	xxx=mat3(3)
	call protect(xxx,.1D-004)
         d(3) = (-d(2)*mat2(3) + f(3))/mat3(3)

! assign...
          wwq(i)=omw*wwq(i)+wet*d(1)
          wtq(i)=omw*wtq(i)+wet*d(2)
          t2q(i)=omw*t2q(i)+wet*d(3)
       enddo
!
! quasi-Andre type realizability constraints
!
	xxx=.1D+000*abs(wq(n))*mw(n)
	call cap(wwq,xxx,n)
	xxx=.1D+000*abs(wq(n)*wt(n))/(mw(n))
	call cap(wtq,xxx,n)
	xxx=.1D+000*(wt(n)**2)*abs(wq(n))/(mw(n)*mw(n)*mw(n))
	call cap(t2q,xxx,n)

	do i=1,10
         call smth(wwq,n)
         call smth(wtq,n)
         call smth(t2q,n)
	enddo
!
        call deriv(dwwq,wwq,gg,n)
        call deriv(dwtq,wtq,gg,n)
!

	return
	END SUBROUTINE
! 
!!!!!!!!!!!!!!!!!!! /-\ < /-\ S /-\ !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
!
      SUBROUTINE trip3(iter, &
	n,nm1,gg,got,c11,omw,wet,c10k,dt,wt,dt2,c8k,w2,dwt,dw2, &
	ws,de,dtq,dwq,wq,dv2,uw,w3,wvv,wtt,dut,duw,wwt,mw,x, &
	drag,alph0,du2,alph1,alph2,UTT,WUT,WWU,UUT,WUU,DWUU,DWVV,DWWU,DWUT)

	implicit none
	integer n,nm1,i,j,ll,iter
	double precision got,c11,alph1,alph2,aww,k1,k2,k,den,omw,wet,awk,alph0
	double precision c10k(n),dt(n),wt(n),dt2(n),c8k(n),w2(n),dwt(n),dw2(n)
	double precision ws(n),de(n),dtq(n),dwq(n),wq(n),dv2(n),wuu(n),wvv(n)
	double precision a(5),b(5),c(5),d(5),e(5),f(5),tom(5),x(n),vvt(n),wtt(n)
	double precision uw(n),dut(n),duw(n),wwt(n),mw(n),drag(n),du2(n),dwvv(n)
	double precision utt(n),wut(n),wwu(n),uut(n),w3(n),denom
	double precision dwuu(n),dwwu(n),dwut(n),gg(n),sss
!
	sss=.1D-021
!
! vvt, calculated in trip3, is used to estimate wvv....and is used nowhere else.
!
       DO I=2,N
!1214END
!880126E
	 DENOM=(.1D+001/X(I) + X(I)*GOT*(.1D+001-C11)*DT(I))
	 CALL PROTECT(DENOM,SSS)
	 AWK = DT(I)*W2(I)*DV2(I)+WUU(I)*.133D+001*ALPH1*WS(I)
	 VVT(I)=(X(I)*AWK-WT(I)*DV2(I)+C11*.67D+000*GOT*WTT(I))/DENOM
	 WVV(I)=-X(I)*(W2(I)*DV2(I)-VVT(I)*(.1D+001-C11)*GOT)
	ENDDO
!
      DO I=2,N
	B(1)=-C8K(I)
	C(1)=-.2D+001*DT(I)
	D(1)=WTT(I)*WS(I)+UW(I)*DT2(I)+.2D+001*WT(I)*DUT(I)
	A(2)=GOT*(.1D+001-C11)
	B(2)=-C8K(I)
	C(2)=-DT(I)
	D(2)=WT(I)*DUW(I)+UW(I)*DWT(I)+WWT(I)*WS(I)+W2(I)*DUT(I)
	A(3)=.2D+001*GOT*(.1D+001-C11)
	B(3)=-C8K(I)
	C(3)=.0D+000
	D(3)=W3(I)*WS(I)+.2D+001*W2(I)*DUW(I)+UW(I)*DW2(I)-W2(I)*MW(I)* &
      	     MW(I)*drag(i)-(ALPH1-ALPH2)*WUU(I)*WS(I)- &
      	     (ALPH0-.667D+000*ALPH1)*(WUU(I)+WVV(I)+W3(I))*WS(I)
	A(4)=-.2D+001*WS(I)
	A(4)=-(.2D+001-.667D+000*ALPH1-.2D+001*ALPH2)*WS(I)
	B(4)=GOT*(.1D+001-C11)
	C(4)=-C8K(I)
	D(5)=WT(I)*DU2(I)+.2D+001*UW(I)*DUT(I)-.2D+001*GOT*C11*WTT(I)/.3D+001
	A(5)=-C8K(I)
	B(5)=-DT(I)
	D(4)=W2(I)*DU2(I)+.2D+001*UW(I)*DUW(I)-.2D+001* &
         UW(I)*MW(I)*MW(I)*DRag(i)
	K=-A(4)/A(3)
	K1=B(3)*K
	D(5)=D(5)+D(3)*K
	K = B(3)/A(3)
	A(5)=A(5)+B(4)*K
	B(5)=B(5)+C(4)*K
	D(5)=D(5)+D(4)*K
 	F(1)=C(1)/B(1)
	D(1)=D(1)/B(1)
	sss=.1D-003
	DO J=2,5
	   DEN=-A(J)*F(J-1)+B(J)
	   call protect(den,sss)
	   D(J)=(-A(J)*D(J-1)+D(J))/DEN
	   if(j.gt.4)goto 50
	   F(J)=C(J)/DEN
 50	ENDDO
	TOM(5)=D(5)
	DO J=1,4
	   LL=5-J
	   TOM(LL)=D(LL)-F(LL)*TOM(LL+1)
	ENDDO
!
	UTT(I)=OMW*UTT(I)+WET*TOM(1)
	WUT(I)=OMW*WUT(I)+WET*TOM(2)
	WWU(I)=OMW*WWU(I)+WET*TOM(3)
	WUU(I)=OMW*WUU(I)+WET*TOM(5)
	UUT(I)=OMW*UUT(I)+WET*TOM(4)

        ENDDO
!
! quasi-Andre type realizability constraints
!
	sss=.1D+000*(wt(n)**2)/mw(n)
	call cap(utt,sss,n)
	sss=.1D+000*mw(n)*abs(wt(n))
	call cap(wut,sss,n)
	call cap(uut,sss,n)
	sss=.1D-001*mw(n)*mw(n)*mw(n)
	call cap(wwu,sss,n)
	call cap(wuu,sss,n)
	call cap(wvv,sss,n)
! 
	do i=1,10
         call smth(uut,n)
         call smth(utt,n)
         call smth(wut,n)
         call smth(wuu,n)
         call smth(wvv,n)
         call smth(wwu,n)
	enddo
!
        call deriv(dwuu,wwu,gg,n)
        call deriv(dwvv,wwu,gg,n)
        call deriv(dwwu,wuu,gg,n)
        call deriv(dwut,wut,gg,n)
!
 471    continue
	RETURN
	END subroutine
!
!!!!!!!!!!!!!!!!!!! /-\ < /-\ S /-\ !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
!
       subroutine trip4(xmw,n,ihi,ngg,x,w3,dco2,dw2,w2,dwco2,dt,wwt,dtco2, &
          wco2,wt,dwt,wtt,dt2,c10k,gg,omw,wet,do3,dwo3,dto3,wo3,mw,t,co2, &
	  WWCO2,DWWCO2,WTCO2,DWTCO2,TTCO2,WWO3,DWWO3,WTO3,DWTO3,TTO3)

	implicit none
	integer n,ngg
	integer i,ihi
	double precision wwco2(n),x(n),w3(n),dco2(n),dw2(n),w2(n),dwco2(n)
	double precision wtco2(n),dt(n),wwt(n),dtco2(n),wco2(n)
	double precision wt(n),dwt(n),ttco2(n),wtt(n),dt2(n),dwwco2(n)
	double precision c10k(n),gg(n),omw,wet,dwto3(n,ihi)
	double precision wwo3(n,ihi),do3(n,ihi),dwo3(n,ihi)
	double precision wto3(n,ihi),dto3(n,ihi),dwtco2(n)
	double precision wo3(n,ihi),tto3(n,ihi),dwwo3(n,ihi)
	double precision xxx,yyy,zzz,ppp,qqq,mw(n),t(n),co2(n)
	double precision yy1,yy2,xxx1,xxx2,xmw,sss
	integer jk
!
!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
!......................................................................
! computes triple correl. for co2 (ttco2,wtco2,wwco2)
! these equations are solved explicitly and are genaerally rather tame.
! 	co2 and the o3 series are passive tracers and dont figure into the
! 	buoyancy and other things that affect
! 	the velocity terms.  although co2 should do this, the concentrations
! 	are so small that the effects are negligible.  hence the numerics appear more stable.
!......................................................................
       do i=2,ngg
        wwco2(i)=omw*wwco2(i)+ &
         wet*(x(i)*(-w3(i)*dco2(i)-wco2(i)*dw2(i)-.2D+001*w2(i)*dwco2(i)))
        wtco2(i)=omw*wtco2(i)+ &
         wet*(x(i)*(-wwco2(i)*dt(i)-wwt(i)*dco2(i)-w2(i)*dtco2(i)- &
         wt(i)*dwco2(i)-wco2(i)*dwt(i)))
        ttco2(i)=omw*ttco2(i)+ &
         wet*((-wtt(i)*dco2(i)-2.*wtco2(i)*dt(i)-wco2(i)*dt2(i)- &
         .2D+001*wt(i)*dtco2(i))/c10k(i))
       enddo

      do jk=1,ihi
       do i=2,ngg
        wwo3(i,jk)=omw*wwo3(i,jk)+ &
        wet*(x(i)*(-w3(i)*do3(i,jk)-wo3(i,jk)*dw2(i)- &
        .2D+001*w2(i)*dwo3(i,jk))) 

        wto3(i,jk)=omw*wto3(i,jk)+ &
       wet*(x(i)*(-wwo3(i,jk)*dt(i)-wwt(i)*do3(i,jk)- &
        w2(i)*dto3(i,jk)- &
        wt(i)*dwo3(i,jk)-wo3(i,jk)*dwt(i)))

        tto3(i,jk)=omw*tto3(i,jk)+ &
        wet*((-wtt(i)*do3(i,jk)-.2D+001*wto3(i,jk)*dt(i)- &
        wo3(i,jk)*dt2(i)- &
        .2D+001*wt(i)*dto3(i,jk))/c10k(i))

       enddo
      enddo

!......................................................................
! now the derivatives of all <w.?.?.> terms.
!......................................................................
      do jk=1,ihi
        do i=2,ngg-1
         yy1=gg(i+1)/(gg(i+1)+gg(i-1))
         yy2=.1D+001-yy1
         xxx1=yy1*(dwwo3(i+1,jk)-dwwo3(i,jk))/gg(i+1)
         xxx2=yy2*(dwwo3(i,jk)-dwwo3(i-1,jk))/gg(i-1)
         dwwo3(i,jk)=wet*(xxx1+xxx2)+ omw*dwwo3(i,jk)
        enddo
      enddo
!
!
! quasi-Andre type realizability constraints
!
	sss=.1D+000*mw(n)*abs(wco2(n))
	call cap(wwco2,sss,n)
	sss=.1D+000*abs(wt(n)*wco2(n))/mw(n)
	call cap(wtco2,sss,n)
	sss=.1D+000*abs(wt(i)*wt(n)*wco2(n))/(mw(n)*mw(n)*mw(n))
	call cap(ttco2,sss,n)

	do i=1,10
         call smth(wwco2,n)
         call smth(wtco2,n)
         call smth(ttco2,n)
	enddo
!
        call deriv(dwwco2,wwco2,gg,n)
        call deriv(dwtco2,wtco2,gg,n)
!
! call deriv(dwto3) fix this when doing 03 or other tracer studies...
!
	return
	END SUBROUTINE
!!!!!!!!!!!!!!!!!!! /-\ < /-\ S /-\ !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
!
        subroutine cap(arr,xxx,n)
        implicit none
! caps values to +/-x
        integer n,i
        double precision arr(n),xxx
        do i=2,n
         arr(i)=min(arr(i),xxx)
         arr(i)=max(arr(i),-xxx)
        enddo
        return
        end subroutine
!
!
!!!!!!!!!!!!!!!!!!! /-\ < /-\ S /-\ !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
       subroutine zenith(xday,xtime,zlatude,zzen)
        implicit none
        double precision xtime,xday,xxx,yyy,zzz,zzen,zlatude,zenhour
!
! ACAS version 1 Dave Pyles Apr 29 1998
! ACASA version Bridge/EU-CMCC /R. David Pyles Augusta 18 2009
!
!
        xxx=.3141592654D+001*(zlatude)/.18D+003 !pi*latitude/180 radians
        yyy=.235D+002*.3141592654D+001*cos((.85D+001+xday)* &
            .3141592654D+001/.1825D+003)/.18D+003 ! season ang. (w/ solstice offset)
        zzz=cos(xxx+yyy) ! cos noon zenith ang
        zenhour=max(-cos(xtime*.3141592654D+001/.12D+002),.0D+000) ! hour fact.
        zzen=zenhour*zzz ! cos zenith angle
        zzen=max(zzen,.1D-000)  ! RDP 22 September 2012: zzen has to be "not too small"
        return
        end
!
!!!!!!!!!!!!!!!!!!! /-\ < /-\ S /-\ !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
!
      subroutine ton(xxcc1,x)
! does inverse tangent w/out blowing up
        implicit none
        DOUBLE PRECISION y,x,xxcc1
        y=cos(x)
        call protect(y,.1D-009)
        xxcc1=sin(x)/y
        xxcc1=max(xxcc1,-.1D+009)
        xxcc1=min(xxcc1,.1D+009)
        call protect(xxcc1,.1D-009)
      return
        END SUBROUTINE

       subroutine swradiation(tlux,zen,i7ce,popdens, &
         pai101,stei101,tr0,pr0,pv0,tv0, &
         id11,mid11,rnsw11,rnswi11, &
         fsl11,rnswf11,lf11, &
         xai, &
         xlai2,xlai,rai101,wai101,xstei1,xstei2,xwai,xrai,pr09g,pv09g, &
         n,nlyr,xlint101,rnswad11,forc_solad,forc_solai)
!
! 2-stream approximation comment 39.2    includes reflection & transmission of beam and 
! diffuse visible ( < 0.7 um) and near-infrared (0.7 -2.0 um)
! (will soon allow for varying albedoes according to tissue/building type and species.
! currently does a crude linear averaging of optics for snow in canopy. stay tuned)
!
	implicit none
	integer n,inlyr
	DOUBLE PRECISION popdens
!
       integer nlyr,nq,i7ce,ng,jb,ik
       parameter(nq=101)
!
      integer kh
      integer i,j,k,mm,nlayer,iter
!
      DOUBLE PRECISION rt,zen,fir,fird,fvd,rbr(nq),rbv(nq),pi
      DOUBLE PRECISION alpha,beta,kxm,lf(9),ib(nq),mib(nq),av(nq),ar(nq),kxz
      DOUBLE PRECISION x1(nq),kxd(nq),id(nq),mid(nq),z1,z2,z3,rird(nq)
      DOUBLE PRECISION rvd(nq),rvu(nq),riru(nq),orvu,oird,ckvu,ckrd,cpai,totird
      DOUBLE PRECISION rnswi(nq),tsw11,xlai
      DOUBLE PRECISION totvd,totsw(nq),prcnt,abv,abir,rnsw(nq),rnswf(nq,9)
      DOUBLE PRECISION rbsf(nq,9),fsl(nq),rnswad(nq),rnswa(nq),theta
      DOUBLE PRECISION ib11(nlyr),mib11(nlyr),rird11(nlyr),xai
      DOUBLE PRECISION rvu11(nlyr),riru11(nlyr),xstei1,xstei2,xrai,xwai
      DOUBLE PRECISION rbr11(nlyr),rai101(101),wai101(101),xlint101(nq,8)
	  DOUBLE PRECISION rswddd11(nlyr)!snowmip
	  DOUBLE PRECISION rswuuu11(nlyr)!snowmip
      DOUBLE PRECISION pai101(101),stei101(101,2)
      DOUBLE PRECISION tr0(101),pr0(101),pv0(101),tv0(101),snowd1
      DOUBLE PRECISION id11(nlyr),mid11(nlyr),rnsw11(nlyr),rvd11(nlyr)
      DOUBLE PRECISION rbv11(nlyr),rnswi11(nlyr),xlai2,pr09g,pv09g
      DOUBLE PRECISION fsl11(nlyr),rnswad11(nlyr),rnswa11(nlyr)
      DOUBLE PRECISION rnswf11(nlyr,9),kxx11(9),lf11(9)
      DOUBLE PRECISION tlux,zen1,xxx,tird11,tvd11,rbsf11
      DOUBLE PRECISION xrnswd1,xrnswa1,xrbemra,xrdifra,xrnstot
      DOUBLE PRECISION yyy,zzz,xxcc1,xxcc2
      DOUBLE PRECISION tr(nq),pr(nq),tv(nq),pv(nq),ssq(n)
      DOUBLE PRECISION forc_solad,forc_solai
      data nlayer/101/
      data pi/.314159D+001/,alpha/.0D+000/,beta/.0D+000/
      data kxm/.0D+000/,kxz/.0D+000/
      data z1/.0D+000/,z2/.0D+000/,z3/.0D+000/,orvu/.0D+000/
      data oird/.0D+000/,ckvu/.0D+000/,ckrd/.0D+000/
      data cpai/.0D+000/,totird/.0D+000/,abv/.0D+000/
      data prcnt/.0D+000/,abir/.0D+000/,totvd/.0D+000/
      data lf/.174D+000,.168D+000,.158D+000,.143D+000, &
        .123D+000,.1D+000,.737D-001,.451D-001,.152D-001/
! 
!......................................................................
! new relations for fraction of diffuse vis and near-IR based on zen ang.
!......................................................................

	fir=0.54D+000
	zen1=max(zen,.1D-003)
	xxx=.1D+001/zen1
!
! get fraction of incident SW radiation that is diffuse...
! if radiative intensity is < 50% of what it should be given zzen
! then asume it is all diffuse...turned off for now...
!
        yyy=max(.1D+004*zen1,.1D+001)
        zzz=max((yyy-tlux)/yyy,.0D+000)
        zzz=min(zzz,.1D+001)
!
	fvd=zzz
	fird=zzz
!
! new formula apes "cloud activity" plus zenith angle effects
!......................................................................
! initialize working vbles 
!......................................................................
!	nlyr=11
	inlyr=nlyr
      ng=nq
      rt=tlux
      do k =1,n
	 ssq(k)=0.68D+000
      enddo
      do k =1,ng
	 rbr(k)=.0D+000
	 rbv(k)=.0D+000
	 ib(k)=.0D+000
	 mib(k)=.0D+000
	 av(k)=.0D+000
	 ar(k)=.0D+000
	 id(k)=.0D+000
	 mid(k)=.0D+000
	 rird(k)=.0D+000
	 rvd(k)=.0D+000
	 rvu(k)=.0D+000
	 riru(k)=.0D+000
	 rnswi(k)=.0D+000
	 totsw(k)=.0D+000
	 rnsw(k)=.0D+000
	 fsl(k)=.0D+000
	 rnswad(k)=.0D+000
	 rnswa(k)=.0D+000
	 do j=1,9
	    rnswf(k,j)=.0D+000
	    rbsf(k,j)=.0D+000
	 enddo
	enddo
      do k =1,inlyr
	 rbr11(k)=.0D+000
	 rbv11(k)=.0D+000
	 ib11(k)=.0D+000
	 mib11(k)=.0D+000
	 id11(k)=.0D+000
	 mid11(k)=.0D+000
	 rird11(k)=.0D+000
	 rvd11(k)=.0D+000
	 rvu11(k)=.0D+000
	 riru11(k)=.0D+000
	 rnswi11(k)=.0D+000
	 rnsw11(k)=.0D+000
	 fsl11(k)=.0D+000
	 rnswad11(k)=.0D+000
	 rnswa11(k)=.0D+000
	 rbsf11=.0D+000
	 do j=1,9
	    rnswf11(k,j)=.0D+000
	 enddo
	enddo

        do i=1,nq
	 x1(i)=.0D+000
	 kxd(i)=.0D+000
	enddo

       pi=dble(acos(-1.))
!......................................................................
! set fraction of total that is beam radiation and then separate into into ir and visible components
!......................................................................
      rbr(nlayer)=rt*fir*(.1D+001-fird)
      rbv(nlayer)=rt*(.1D+001-fir)*(.1D+001-fvd)
!......................................................................
! computation of extinction coefficient
!......................................................................
      alpha=pi/.2D+001 - dble(acos(real(zen)))
      beta=pi/.36D+002
      kxm = .0D+000
!
      do 8 i=1,9
       if(alpha.ge.beta)kxx11(i) = cos(beta)
       if(alpha.lt.beta)then
	xxcc1=.1D+001
	xxcc2=.1D+001
	 call ton(xxcc1,alpha)
	 call ton(xxcc2,beta)
	xxx=min(xxcc1/xxcc2,.1D+001)
	xxx=max(xxx,-.1D+001)
        theta = acos(xxx)
	call ton(xxcc1,theta)
        kxx11(i)=cos(beta)*(.1D+001 + .63661D+000*(xxcc1 - theta))
       endif
       kxm = kxm + lf(i)*kxx11(i)
       beta = beta + pi/.18D+002
 8    continue
!......................................................................
! compute probability function for penetration of the beam component
! includes effects of clumping by taking
! xlai2/xlai; apparent lai / actual lai...if all the info you
! have is one lai value, take the fraction of the ground that is shaded and use that
!......................................................................
         do i=1,nlayer-1
	  k=nlayer - i
! apparent.lai/actual.lai
	  xxx=(rai101(k+1)+wai101(k+1)+pai101(k+1)+  &
           stei101(k+1,1)+stei101(k+1,2))!stems distributed as-is
	  ib(k+1)=exp(-kxm*xxx*xlai2/xlai)! probability of beam penetration
	  if(xai.le..1D-003)ib(k+1)=.1D+001
	  ib(k+1)=min(ib(k+1),.1D+001)
	  mib(k+1)=.1D+001 - ib(k+1)
          rbr(k)=rbr(k+1)*ib(k+1)
	  rbv(k)=rbv(k+1)*ib(k+1)
         enddo

!
! get soil visible and ir albedo...also
! get blended values based on varying optics for leaves, stems, walls, roofs; hydrologic condition...etc.
!......................................................................
!
! get total vis&nir reflectances&transmittance arrays : all i and surface types & conditions.
! get total blended values of pv,pr,tv,tr (vis&nir reflectances&transmittances, resp.) 
! based on occurrences(i) for each.
!
       call zalbedo(pv0,tv0,pr0,tr0,pai101,stei101,rai101,wai101,xlint101, &
        xlai,xstei1,xstei2,xrai,xwai,xai,nq,pv09g,pr09g, &
        pv,tv,pr,tr)
!nix passing the kii's for now            pv,pvk,tv,tvk,pr,prk,tr,trk)
!
!......................................................................
! initialize downward diffuse components of vis and ir above the canopy
!......................................................................
! rdp jauary 2013--cleaned up this section...
! set surface reflectances and albedoes to those already configured for this point.
!
      pv(1)=pv0(1)
      pr(1)=pr0(1)
      av(1)=pv(1) 
      ar(1)=pr(1) 
      tv(1)=.0D+000
      tr(1)=.0D+000
!......................................................................
! loop for computing oftenly used factors
!......................................................................
!
	alpha=.0D+000!
      do 5 i=1,nq
         x1(i)=sin(alpha)*cos(alpha)
	 kxd(i)=.0D+000
	 beta = pi/.36D+002
	 do 6 j=1,9
            if(alpha.ge.beta) then
	        kxz = cos(beta)
	    else
		xxcc1=1.
         	 call ton(xxcc1,beta)
		yyy=xxcc1
		call protect(yyy,.1D-009)
         	 call ton(xxcc1,alpha)
	        xxx=max(xxcc1/yyy,-.1D+001)
	        xxx=min(xxx,.1D+001)
		zzz=max(xxcc1/yyy,-.1D+001)
		zzz=min(zzz,.1D+001)
		theta = acos(zzz)
         	 call ton(xxcc1,alpha)
		kxz = cos(beta)*(.1D+001 + .63661D+000*(xxcc1-theta))
	    end if
	    kxd(i)=kxd(i)+kxz*lf(j)
	    beta = beta + pi/.18D+002
 6	 continue
         alpha=alpha+pi/.2D+002
  5    continue
!......................................................................
! compute diffuse radiation penetration function (id(.) and a (r up/r down)
!......................................................................
       do 10 i=2,nlayer
	 id(i)=.0D+000
	 z1=.0D+000
	 k=1
	 do 20 j=1,5
!	    xxx=xlai2*(stei101(i,1)+stei101(i,2)+pai101(i))/xlai
	    xxx=xlai2*(stei101(i,1)+stei101(i,2)+pai101(i)+ &
               rai101(i)+wai101(i))/xlai
	    z2=exp(-xxx*kxd(k+1))*x1(k+1)
	    z3=exp(-xxx*kxd(k+2))*x1(k+2)
            id(i)=id(i)+pi*(z1+.4D+001*z2+z3)/(.6D+002)
            z1=z3
	    k=k+2
  20	 continue
	 id(i)=id(i)*.2D+001
	 if(xai.le..1D-003)id(i)=.1D+001
	 id(i)=min(id(i),.1D+001)
	 mid(i)=.1D+001 - id(i)
	 av(i)=av(i-1)*(tv(i)*mid(i)+id(i))*(tv(i)*mid(i)+id(i))/ &
     	 (.1D+001 - av(i-1)*pv(i)*mid(i)) + pv(i)*mid(i)
	 ar(i)=ar(i-1)*(tr(i)*mid(i)+id(i))*(tr(i)*mid(i)+id(i))/ &
     	 (.1D+001 - ar(i-1)*pr(i)*mid(i))	+ pr(i)*mid(i)
  10   continue
 533  format(500f12.2)
!......................................................................
! initialize downward diffuse components of vis and ir above the canopy
!......................................................................
       rvd(nlayer)=rt*fvd*(.1D+001 - fir)
       rird(nlayer)=rt*fird*fir
!......................................................................
! compute downward diffuse radiation at each level	
!......................................................................
       do 30 i=1,nlayer-1
	 k=nlayer-i
	 rvd(k)=rvd(k+1)*(tv(k+1)*mid(k+1)+id(k+1))/ &
               (.1D+001-av(k)*pv(k)*mid(k+1))
	 rird(k)=rird(k+1)*(tr(k+1)*mid(k+1)+id(k+1))/ &
                (.1D+001-ar(k)*pr(k)*mid(k+1))
  30   continue
!......................................................................
! compute upward diffuse fluxes using the soil/snow albedo	
!......................................................................
       rvu(1)=av(1)*(rvd(1)+rbv(1))
       riru(1)=ar(1)*(rird(1)+rbr(1))
       do 40 i=2,nlayer
	  rvu(i)=rvu(i-1)*(tv(i)*mid(i)+id(i))*av(i)/ &
                (av(i)+pv(i)*mid(i))
	  riru(i)=riru(i-1)*(tr(i)*mid(i)+id(i))*ar(i)/ &
                (ar(i)-pr(i)*mid(i))
  40   continue
!......................................................................
! start main loop for iterations	
!......................................................................
       orvu=.0D+000
       oird=.0D+000
       iter=0
       do 60 mm=1,100
        iter=iter + 1
        do 50 i=1,nlayer-1
	  k = nlayer - i
	  rvd(k)=rvd(k+1)*(tv(k+1)*mid(k+1)+id(k+1))+rvu(k)* &
                pv(k+1)*mid(k+1)+rbv(k+1)*mib(k+1)*tv(k+1)
	  rird(k)=rird(k+1)*(tr(k+1)*mid(k+1)+id(k+1))+ &
                riru(k)*pr(k+1)*mid(k+1)+rbr(k+1)*mib(k+1)*tr(k+1)
 50     continue
        rvu(1)=av(1)*(rvd(1)+rbv(1))
        riru(1)=ar(1)*(rird(1)+rbr(1))
!......................................................................
! compute the upward diffuse fluxes for the vis and ir wavelengths	
!......................................................................
	do 70 i=2,nlayer
	  rvu(i)=rvu(i-1)*(tv(i)*mid(i)+id(i))+rvd(i)*pv(i)*mid(i)+ &
     	  rbv(i)*mib(i)*pv(i)
	  riru(i)=riru(i-1)*(tr(i)* &
           mid(i)+id(i))+rird(i)*pr(i)*mid(i)+rbr(i)*mib(i)*pr(i)
 70     continue
!
        ckvu=abs(rvu(10)-orvu)
        ckrd=abs(rird(10)-oird)
!......................................................................
! check for convergence of values. criteria for convergence: difference between
! the old and new values at the tenth level changes by no more than 0.1 Wm-2
!......................................................................
        if((ckvu.le..1D+000).and.(ckrd.le..1D+000)) go to 100
        orvu=rvu(10)
        oird=rird(10)
 60    continue
!
 100   continue
! 105  format('1',2x,'iter = ',i3, 5x, 'kxm = ',f5.3)
      cpai=.0D+000
	 do 120 i=1,nlayer
	    k=nlayer+1-i
	    cpai=cpai+(pai101(k)+stei101(k,1)+stei101(k,2)+rai101(k)+wai101(k))
	    totird=rird(k)+rbr(k)
	    totvd=rbv(k)+rvd(k)
	    totsw(k)=totvd+totird
	    rnswi(k)=totsw(k)-rvu(k)-riru(k)
	    prcnt=totsw(k)/rt
            if(xai.le..1D-003)then
 	     fsl(k)=.1D+001
	    else
	     fsl(k)=exp(-kxm*(cpai-(pai101(k)+ &
              stei101(k,1)+stei101(k,2)+rai101(k)+wai101(k))*0.5D+000))
            endif
 120	 continue
!c
      mid(1)=.0D+000
      id(1)=.0D+000
!
      do 180 i=1,9
        lf11(i)=lf(i)
  180 continue
!......................................................................
! computation of absorbed net shortwave (vis + ir) diffuse fluxes	
! (rnsw) and contribution from the beam component in accordance with the leaf normal
! done as the 11 layer output.
!......................................................................
	jb=100/float(nlyr-1)
	do 1000 i = 2,nlyr
          ib11(i)=.1D+001
          id11(i)=.1D+001
          fsl11(i)=.1D+001
	if(i.gt.2)then
          do ik=1,jb
	   ib11(i) = ib11(i)*ib(jb*(i-2)+ik)
	   id11(i) = id11(i)*id(jb*(i-2)+ik)
   	   fsl11(i) = fsl11(i)*fsl(jb*(i-2)+ik)
          enddo
	else
          do ik=2,jb! avoid node 1
	   ib11(i) = ib11(i)*ib(jb*(i-2)+ik)
	   id11(i) = id11(i)*id(jb*(i-2)+ik)
   	   fsl11(i) = fsl11(i)*fsl(jb*(i-2)+ik)
          enddo
	endif
	  mib11(i) = .1D+001 - ib11(i)
	  mid11(i) = .1D+001 - id11(i)
!
	  rbr11(i-1) = rbr(jb*i-2*jb+1)
	  rbv11(i-1) = rbv(jb*i-2*jb+1)
	  rvd11(i-1) = rvd(jb*i-2*jb+1)
	  rird11(i-1) = rird(jb*i-2*jb+1)
	  rvu11(i-1) = rvu(jb*i-2*jb+1)
	  riru11(i-1) = riru(jb*i-2*jb+1)
	  fsl11(i) = fsl11(i)**(.1D+001/float(jb))
 1000	continue
	  fsl11(1) = fsl(1)
!
	  rbr11(nlyr)=rt*fir*(.1D+001-fird)
	  rbv11(nlyr)=rt*(.1D+001-fir)*(.1D+001-fvd)
	  rvd11(nlyr)=rt*fvd*(.1D+001 - fir)
	  rird11(nlyr)=rt*fird*fir
	  riru11(nlyr)=riru(nlayer)
	  rvu11(nlyr)=rvu(nlayer)
!
	do 1200 i = 1,nlyr
	  tird11 = rird11(i) + rbr11(i)
	  tvd11 = rvd11(i) + rbv11(i)
	  tsw11 = tvd11 + tird11
	  rnswi11(i) = tsw11 - rvu11(i) - riru11(i)
	  rswddd11(i) = tsw11
	  rswuuu11(i)= rvu11(i)+riru11(i)
 1200	continue
!
!      abv=.1D+001 - tv - pv
!      abir=.1D+001 - tr - pr
!
      do 1400 i=1,nlyr-1
	   k=nlyr+1 - i
!
      abv=.1D+001 - tv(k) - pv(k)
      abir=.1D+001 - tr(k) - pr(k)
	 rnsw11(k)=((rird11(k)+rird11(k-1))*.5D+000+ &
              (riru11(k)+riru11(k-1)) &
     	       *.5D+000)*abir+((rvd11(k)+rvd11(k-1))*.5D+000+(rvu11(k)+ &
     	       rvu11(k-1))*.5D+000)*abv
!970225 ktpu changes below
             xrnswd1 = (rird11(k)+riru11(k-1))* &
             .5D+000*abir + (rvd11(k) &
            +rvu11(k-1))*.5D+000*abv
	     xrnswa1 = rbr(k)*abir + rbv(k)*abv
	     xrbemra = xrnswa1/(xrnswa1+xrnswd1)
	     xrdifra = xrnswd1/(xrnswa1+xrnswd1)
	     xrnstot=((rird11(k)-riru11(k))- &
               (rird11(k-1)-riru11(k-1)))+ &
     		(rvd11(k)-rvu11(k)) - (rvd11(k-1)-rvu11(k-1)) + &
     		(rbr11(k)-rbr11(k-1)) +(rbv11(k)-rbv11(k-1))
	     rnswad11(k) = xrdifra*xrnstot
	     rnswa11(k) =  xrbemra*xrnstot

	     do 1500 j=1,9
	      rbsf11=(rbv(nlayer)*abv+ rbr(nlayer)*abir)*kxx11(j)
	      rnswf11(k,j)=rnswad11(k) + rbsf11
 1500	     continue

 1400 continue

      rnsw11(1)=(rird11(1)+rbr11(1))*(.1D+001-ar(1))+(rvd11(1) &
      +rbv11(1))*(.1D+001-av(1))
      rnswad11(1)=rird11(1)*(.1D+001-ar(1)) +rvd11(1)*(.1D+001-av(1))
      rnswa11(1)=rbr11(1)*(.1D+001-ar(1)) + rbv11(1)*(.1D+001-av(1))

      mid11(1) = .0D+000
      id11(1) = .1D+001
      ib11(1) = .0D+000
!
!	do i=nlyr+1,n
!	 rnswi11(i)=rnswi11(nlyr)
!	enddo
!KC 062714, output SW variables for CNDV module
      forc_solad = rswddd11(nlyr)-rvd11(nlyr)
      forc_solai = rvd11(nlyr)-rvu11(nlyr)
!KC end
      return
	END SUBROUTINE
!
!!!!!!!!!!!!!!!!!!! /-\ < /-\ S /-\ !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
!
       subroutine zalbedo(pv0,tv0,pr0,tr0,pai101,stei101,rai101,wai101,xlint101, &
        xlai,xstei1,xstei2,xrai,xwai,xai,nq,pv09g,pr09g, &
        pv,tv,pr,tr)
!nix passing the kii's for now        pv,pvk,tv,tvk,pr,prk,tr,trk)
!
! sets individual element reflectances, transmissivities, albedoes...
! also calculates mean(blended) values of each.
!
	implicit none

	integer nq,i,j,k,kii
	double precision xxx,yyy
!
	double precision prk(nq,8),trk(nq,8),pvk(nq,8),tvk(nq,8) !individual optics
	double precision pv(nq),tv(nq),pr(nq),tr(nq)		 !blended optics
	double precision pv0(nq),tv0(nq),pr0(nq),tr0(nq)	 !fed in from morph
	double precision xlint101(nq,8)
! 
	double precision pai101(nq),stei101(nq,2),rai101(nq),wai101(nq)
	double precision xstei1,xstei2,xrai,xwai,xai,xlai,pv09g,pr09g
	integer ii
!
! indiv.-ground/
!
      i=1
      do k=1,8
       pvk(i,k)=pv0(i)
       prk(i,k)=pr0(i)
       tvk(i,k)=tv0(i)
       trk(i,k)=tr0(i)
      enddo
!
! dry leaves only:
!
      k=1
      do i=2,nq
       pvk(i,k)=pv0(i)
       prk(i,k)=pr0(i)
       trk(i,k)=tr0(i)
       tvk(i,k)=tv0(i)
      enddo
!
! wet leaves only:
!
      k=2
      do i=2,nq
       pvk(i,k)=pv0(i)+.5D-001
       prk(i,k)=pr0(i)+.5D-001
       trk(i,k)=tr0(i)
       tvk(i,k)=tv0(i)
      enddo
!
! snowy leaves only:
!
      k=3
      do i=2,nq
       pvk(i,k)=.55D+000
       prk(i,k)=.45D+000
       trk(i,k)=.0D+000
       tvk(i,k)=.0D+000
      enddo
!
! building surfaces
!
      k=4
      do i=2,nq
       pvk(i,k)=pv09g
       prk(i,k)=pr09g
       trk(i,k)=.0D+000
       tvk(i,k)=.0D+000
      enddo
!
! wet building surfaces
!
      k=5
      do i=2,nq
       pvk(i,k)=pv09g-.5D-001
       prk(i,k)=pr09g-.5D-001
       trk(i,k)=.0D+000
       tvk(i,k)=.0D+000
      enddo
!
! snowy building surfaces
!
      k=6
      do i=2,nq
       pvk(i,k)=.55D+000
       prk(i,k)=.45D+000
       trk(i,k)=.0D+000
       tvk(i,k)=.0D+000
      enddo
!
! stems
!
      do k=7,8
       do i=2,nq
        pvk(i,k)=.25D+000
        prk(i,k)=.35D+000
        trk(i,k)=.0D+000
        tvk(i,k)=.0D+000
       enddo
      enddo
!
! calculate blended values
!
! blended-ground/
!
      i=1
      pv(i)=pv0(i)
      pr(i)=pr0(i)
      tv(i)=.0D+000
      tr(i)=.0D+000
!
! canopy.
!

       do i=2,nq
        xxx=(pai101(i)+stei101(i,1)+stei101(i,2)+rai101(i)+wai101(i))
!
        yyy=pai101(i)*pvk(i,1)*xlint101(i,1)+pai101(i)*pvk(i,2)*xlint101(i,2)+pai101(i)*pvk(i,3)*xlint101(i,3) + &
          stei101(i,1)*pvk(i,7)+stei101(i,2)*pvk(i,8)+wai101(i)*pvk(i,4) + & 	
          rai101(i)*pvk(i,4)*xlint101(i,4)+rai101(i)*pvk(i,5)*xlint101(i,5)+rai101(i)*pvk(i,6)*xlint101(i,6)
	pv(i)=yyy/(xxx+.1D-015)
        yyy=pai101(i)*prk(i,1)*xlint101(i,1)+pai101(i)*prk(i,2)*xlint101(i,2)+pai101(i)*prk(i,3)*xlint101(i,3) + &
          stei101(i,1)*prk(i,7)+stei101(i,2)*prk(i,8)+wai101(i)*prk(i,4) + & 	
          rai101(i)*prk(i,4)*xlint101(i,4)+rai101(i)*prk(i,5)*xlint101(i,5)+rai101(i)*prk(i,6)*xlint101(i,6)
	pr(i)=yyy/(xxx+.1D-015)

        yyy=pai101(i)*tvk(i,1)*xlint101(i,1)+pai101(i)*tvk(i,2)*xlint101(i,2)+pai101(i)*tvk(i,3)*xlint101(i,3) + &
          stei101(i,1)*tvk(i,7)+stei101(i,2)*tvk(i,8)+wai101(i)*tvk(i,4) + & 	
          rai101(i)*tvk(i,4)*xlint101(i,4)+rai101(i)*tvk(i,5)*xlint101(i,5)+rai101(i)*tvk(i,6)*xlint101(i,6)
	tv(i)=yyy/(xxx+.1D-015)

        yyy=pai101(i)*trk(i,1)*xlint101(i,1)+pai101(i)*trk(i,2)*xlint101(i,2)+pai101(i)*trk(i,3)*xlint101(i,3) + &
          stei101(i,1)*trk(i,7)+stei101(i,2)*trk(i,8)+wai101(i)*trk(i,4) + & 	
          rai101(i)*trk(i,4)*xlint101(i,4)+rai101(i)*trk(i,5)*xlint101(i,5)+rai101(i)*trk(i,6)*xlint101(i,6)
	tr(i)=yyy/(xxx+.1D-015)

	enddo

	i=nq
	j=nq-1
	pv(i)=pv(j)
	pr(i)=pr(j)
	do kii=1,8
	 pvk(i,kii)=pvk(j,kii)
	 prk(i,kii)=prk(j,kii)
	enddo
!
      return
!
      end subroutine zalbedo
!
!!!!!!!!!!!!!!!!!!! /-\ < /-\ S /-\ !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
!

